import React, { useState, useEffect, useMemo } from 'react';
import { collection, addDoc, serverTimestamp, doc, updateDoc, increment, getDoc, setDoc, query, where, getDocs, deleteDoc } from 'firebase/firestore';
import { db, storage } from '../firebase';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { useAuth } from '../context/AuthContext';
import { Loader2, X, Image as ImageIcon, MapPin as MapPinIcon, Lock, Trash2 } from 'lucide-react';
import { PlaceSearch } from './PlaceSearch';
import { PlaceService, type PlaceResult, transformToLegacyPlace } from '../services/PlaceService';
import { ListSearch } from './ListSearch';

interface AddReviewFormProps {
    listId: string | null;
    onListChange?: (id: string) => void;
    prefillPlaceId?: string;
    prefillItemName?: string;
    editReviewId?: string;
    lockList?: boolean;
    onClose: () => void;
    onSuccess: () => void;
    suggestedListIds?: string[]; // IDs of lists where this place is already present
}

export const AddReviewForm: React.FC<AddReviewFormProps> = ({ listId, onListChange, prefillPlaceId, prefillItemName, editReviewId, lockList = false, onClose, onSuccess, suggestedListIds }) => {
    const { user } = useAuth();

    // Core Data
    // Core Data
    const [itemName, setItemName] = useState(prefillItemName || '');
    const [selectedPlace, setSelectedPlace] = useState<PlaceResult | null>(null);

    const [comment, setComment] = useState('');
    const [overallRating, setOverallRating] = useState(5);

    // Changed: Store full definition list to preserve ORDER
    const [criteriaList, setCriteriaList] = useState<any[]>([]);
    const [criteriaScores, setCriteriaScores] = useState<Record<string, number>>({});

    // Extras
    const [_imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const [customTags, setCustomTags] = useState<string[]>([]);
    const [listAvailableTags, setListAvailableTags] = useState<string[]>([]);

    const [initLoading, setInitLoading] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const [listData, setListData] = useState<any>(null); // Store full list data for lineage
    const [reviewPath, setReviewPath] = useState<string | null>(null);

    const [internalListId, setInternalListId] = useState<string | null>(listId);

    // UX States
    const [ratingsTouched, setRatingsTouched] = useState(false);
    const [originalData, setOriginalData] = useState<string>(''); // JSON string for deep comparison

    // Update internalListId if prop changes
    useEffect(() => {
        if (listId) setInternalListId(listId);
    }, [listId]);

    // Validation Logic
    const isNew = !editReviewId;

    const isValid = useMemo(() => {
        // 1. Place is required
        if (!selectedPlace) return false;

        // 2. Name is required
        if (!itemName.trim()) return false;

        // 3. List is required (use internal state)
        if (!internalListId) return false;

        // 4. Ratings Touched (Only for NEW reviews)
        // If editing, we assume valid unless cleared (which isn't possible here easily)
        if (isNew && !ratingsTouched) return false;

        return true;
    }, [selectedPlace, itemName, internalListId, ratingsTouched, isNew]);

    const isDirty = useMemo(() => {
        if (isNew) return true; // Always dirty if new (until saved)
        const currentData = JSON.stringify({
            itemName,
            comment,
            criteriaScores,
            customTags,
            imagePreview, // crude check for photo change
            listId: internalListId // Include listId in comparison structure
        });

        return currentData !== originalData;
    }, [isNew, itemName, comment, criteriaScores, customTags, imagePreview, originalData, internalListId]);

    // Fetch Review Data for Editing
    useEffect(() => {
        const fetchReviewData = async () => {
            if (!editReviewId) return;
            // If listId is missing, we can try to fetch globally, but we prefer context.

            try {
                // Determine collection path. Assuming 'lists/{listId}/reviews/{reviewId}' or global 'reviews'?
                // The addDoc gets written to 'reviews' (global) now in recent iterations, but let's check.
                const reviewRef = doc(db, 'reviews', editReviewId);
                const snap = await getDoc(reviewRef);

                if (snap.exists()) {
                    const data = snap.data();
                    setReviewPath(`reviews/${editReviewId}`);

                    setItemName(data.itemName || '');
                    setComment(data.comment || '');
                    setOverallRating(data.overallRating || 5);
                    if (data.scores) setCriteriaScores(data.scores);
                    if (data.tags || data.userTags) setCustomTags(data.tags || data.userTags);
                    if (data.photoUrl) setImagePreview(data.photoUrl);

                    // Fixed: Always prefer stored listId from review data if creating/editing
                    if (data.listId) {
                        setInternalListId(data.listId);
                    } else if (listId) {
                        setInternalListId(listId);
                    }

                    // Capture Original Data for Dirty Check
                    setOriginalData(JSON.stringify({
                        itemName: data.itemName || '',
                        comment: data.comment || '',
                        criteriaScores: data.scores || {},
                        customTags: data.tags || data.userTags || [],
                        imagePreview: data.photoUrl || null,
                        listId: data.listId // Match structure
                    }));

                    if (data.placeId) {
                        // Fetch fresh details from Place Service
                        try {
                            const details = await PlaceService.getDetails(data.placeId);
                            const legacyPlace = transformToLegacyPlace({
                                id: data.placeId,
                                name: data.placeName || data.itemName || 'Lugar',
                                address: data.placeAddress || '',
                                lat: data.placeLat || 0,
                                lng: data.placeLng || 0
                            } as any, details);

                            setSelectedPlace({
                                id: legacyPlace.googlePlaceId || data.placeId,
                                name: legacyPlace.name,
                                address: legacyPlace.address,
                                lat: legacyPlace.coordinates.latitude,
                                lng: legacyPlace.coordinates.longitude,
                                types: legacyPlace.types || [] // Hydrate types if available
                            });
                        } catch (e) {
                            // Fallback
                            setSelectedPlace({
                                id: data.placeId,
                                name: data.placeName || data.itemName || 'Lugar',
                                address: data.placeAddress || '',
                                lat: data.placeLat || 0,
                                lng: data.placeLng || 0
                            });
                        }
                    }
                } else if (listId) {
                    // Fallback to subcollection (Legacy)
                    const subRef = doc(db, 'lists', listId, 'reviews', editReviewId);
                    const subSnap = await getDoc(subRef);

                    if (subSnap.exists()) {
                        setReviewPath(`lists/${listId}/reviews/${editReviewId}`);
                        const data = subSnap.data();
                        setItemName(data.itemName || '');
                        setComment(data.comment || '');
                        setOverallRating(data.overallRating || 5);
                        if (data.scores) setCriteriaScores(data.scores);
                        if (data.tags || data.userTags) setCustomTags(data.tags || data.userTags);
                        if (data.photoUrl) setImagePreview(data.photoUrl);
                        if (data.listId) setInternalListId(data.listId);

                        if (data.placeId) {
                            setSelectedPlace({
                                id: data.placeId,
                                name: data.placeName || 'Lugar',
                                address: data.placeAddress || '',
                                lat: data.placeLat || 0,
                                lng: data.placeLng || 0
                            });
                        }
                    }
                }
            } catch (e) {
                console.error("Error fetching review for edit:", e);
                setError("Error cargando la reseña para editar");
            }
        };

        if (editReviewId) {
            fetchReviewData();
        }
    }, [editReviewId, listId]);

    // Hydrate Place from PREFILL (Group Page Context)
    useEffect(() => {
        const hydratePrefillPlace = async () => {
            if (prefillPlaceId && !editReviewId && !selectedPlace) {
                try {
                    const placeRef = doc(db, 'places', prefillPlaceId);
                    const snap = await getDoc(placeRef);

                    if (snap.exists()) {
                        const data = snap.data();
                        setSelectedPlace({
                            id: data.id || data.googlePlaceId || prefillPlaceId,
                            name: data.name,
                            address: data.address,
                            lat: data.location?.latitude || data.lat || 0,
                            lng: data.location?.longitude || data.lng || 0,
                            types: data.types || []
                        });
                    } else {
                        setSelectedPlace({
                            id: prefillPlaceId,
                            name: 'Lugar Seleccionado',
                            address: '',
                            lat: 0,
                            lng: 0
                        });
                    }
                } catch (e) {
                    console.warn("Error hydrating prefill place", e);
                }
            }
        };
        hydratePrefillPlace();
    }, [prefillPlaceId, editReviewId]);

    // Recalculate Overall Rating
    useEffect(() => {
        if (criteriaList.length === 0 || Object.keys(criteriaScores).length === 0) return;

        let total = 0;
        let count = 0;

        criteriaList.forEach((c) => {
            const val = criteriaScores[c.id];
            // Only ponderable items count towards the global rating
            if (c.ponderable !== false && val !== undefined) {
                total += val;
                count++;
            }
        });

        if (count > 0) {
            const avg = total / count;
            setOverallRating(parseFloat(avg.toFixed(1)));
        }
    }, [criteriaScores, criteriaList]);

    // Fetch List Metadata
    useEffect(() => {
        const fetchListMetadata = async () => {
            // If editing, we rely on internalListId rather than prop listId primarily
            const targetListId = internalListId || listId;

            if (!targetListId) {
                setListData(null);
                setInitLoading(false);
                return;
            }
            try {
                const docRef = doc(db, 'lists', targetListId);
                const snap = await getDoc(docRef);
                if (snap.exists()) {
                    const data = snap.data();
                    setListData(data);

                    if (data.name && !itemName && !prefillItemName && !editReviewId) {
                        setItemName(data.name);
                    }

                    if (data.criteriaDefinition) {
                        let cList: any[] = [];
                        let scores: Record<string, number> = {};

                        // Logic: Convert whatever is in DB to an ordered Array
                        if (Array.isArray(data.criteriaDefinition)) {
                            cList = data.criteriaDefinition.map((c: any) => ({
                                ...c,
                                min: 0,
                                max: 10,
                                step: c.step || 0.1,
                                ponderable: c.isPonderable !== false // normalize to boolean (default true)
                            }));
                        } else {
                            // Legacy MAP support: NO guaranteed order, just keys
                            cList = Object.keys(data.criteriaDefinition).map(k => {
                                const def = data.criteriaDefinition[k];
                                return {
                                    id: k,
                                    label: def.label || k,
                                    min: def.min ?? 0,
                                    max: def.max ?? 10,
                                    step: def.step ?? 0.1,
                                    ponderable: def.ponderable !== false,
                                    ...def
                                };
                            });
                        }

                        // Initialize scores if NEW
                        if (!editReviewId) {
                            cList.forEach(c => {
                                scores[c.id] = 5; // Default score
                            });
                            setCriteriaScores(scores);
                        }
                        setCriteriaList(cList);
                    }

                    if (data.availableTags && Array.isArray(data.availableTags)) {
                        setListAvailableTags(data.availableTags);
                    }
                }
            } catch (e) {
                console.error("Error fetching list definition", e);
            } finally {
                setInitLoading(false);
            }
        };
        fetchListMetadata();
    }, [internalListId, listId, editReviewId]); // Re-run if list changes

    // Handlers
    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setImageFile(file);
            const reader = new FileReader();
            reader.onloadend = () => setImagePreview(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    const toggleTag = (tag: string) => {
        if (customTags.includes(tag)) {
            setCustomTags(customTags.filter(t => t !== tag));
        } else {
            setCustomTags([...customTags, tag]);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user || !listId) {
            // START AUTOMATION LOGIC: If no list selected, or even if selected, check for automation
            // If listId IS present, we respect it. But we must also check if we are fulfilling a "Quiero ir" item.
        }
        if (!user) return; // Safety

        if (!itemName.trim()) {
            setError("El nombre del item es obligatorio");
            return;
        }

        if (!selectedPlace && !prefillPlaceId && !editReviewId) {
            setError("Por favor selecciona un lugar (Restaurante, etc.)");
            return;
        }

        setLoading(true);
        setError(null);

        try {
            // --- AUTOMATION: "Quiero ir" -> "Ya fui" (ARCHIVES) ---
            // Requirement: "si hacemos una reseña de ... elemento en Quiero ir, se pase automáticamente a ya fui" (in Archives)

            // 1. Ensure "Ya fui" archive exists
            let yaFuiArchiveId: string | null = null;
            let quieroIrArchiveId: string | null = null;

            try {
                // Determine user archive IDs
                const qArchives = query(collection(db, 'users', user.uid, 'archives'));
                const snapArchives = await getDocs(qArchives);

                snapArchives.forEach(doc => {
                    const data = doc.data();
                    if (data.name === 'Ya fui') yaFuiArchiveId = doc.id;
                    if (data.name === 'Quiero ir') quieroIrArchiveId = doc.id;
                });

                // Auto-create "Ya fui" if missing
                if (!yaFuiArchiveId) {
                    const newRef = await addDoc(collection(db, 'users', user.uid, 'archives'), {
                        name: 'Ya fui',
                        createdAt: serverTimestamp(),
                        itemCount: 0
                    });
                    yaFuiArchiveId = newRef.id;
                }
                // Auto-create "Quiero ir" if missing (for consistency)
                if (!quieroIrArchiveId) {
                    const newRef = await addDoc(collection(db, 'users', user.uid, 'archives'), {
                        name: 'Quiero ir',
                        createdAt: serverTimestamp(),
                        itemCount: 0
                    });
                    quieroIrArchiveId = newRef.id;
                }

                // 2. Check if the current place is in "Quiero ir"
                // Place ID is critical here.
                let finalPlaceId = selectedPlace?.id || prefillPlaceId || 'unknown';
                if (selectedPlace) finalPlaceId = selectedPlace.id; // Correct preference

                if (quieroIrArchiveId && finalPlaceId !== 'unknown') {
                    // Check items subcollection
                    const qItem = query(collection(db, 'users', user.uid, 'archives', quieroIrArchiveId, 'items'), where('placeId', '==', finalPlaceId));
                    const snapItem = await getDocs(qItem);

                    if (!snapItem.empty) {
                        console.log("Found in 'Quiero ir' archive. Moving to 'Ya fui'...");
                        // Move logic:
                        // A. Delete from Quiero ir
                        await deleteDoc(snapItem.docs[0].ref);
                        await updateDoc(doc(db, 'users', user.uid, 'archives', quieroIrArchiveId!), { itemCount: increment(-1) });

                        // B. Add to Ya fui (As a Place Item)
                        const placeName = selectedPlace?.name || prefillItemName || 'Lugar';
                        const subtitle = selectedPlace?.address || '';
                        const photo = imagePreview || '';

                        // We use the Place ID as the doc ID in the new archive for uniqueness
                        await setDoc(doc(db, 'users', user.uid, 'archives', yaFuiArchiveId!, 'items', finalPlaceId), {
                            itemId: finalPlaceId,
                            placeId: finalPlaceId,
                            type: 'place',
                            name: placeName,
                            subtitle: subtitle,
                            photoUrl: photo,
                            savedAt: serverTimestamp(),
                            route: `/place/${finalPlaceId}`
                        });
                        await updateDoc(doc(db, 'users', user.uid, 'archives', yaFuiArchiveId!), { itemCount: increment(1) });
                    }
                }

            } catch (autoErr) {
                console.error("Archive automation error:", autoErr);
                // Non-blocking
            }

            // --- END AUTOMATION ---



            const placeName = selectedPlace?.name || 'Lugar Desconocido';
            const photoUrl = imagePreview || ''; // Mock

            // New logic: Only use the selected/synced place for ID and address.
            // DO NOT create a new place document here. PlaceService handles that.
            let finalPlaceId = selectedPlace?.id || prefillPlaceId || 'unknown';
            let finalPlaceAddress = selectedPlace?.address || '';
            let finalPlaceLat = selectedPlace?.lat || 0;
            let finalPlaceLng = selectedPlace?.lng || 0;
            let finalPhotoUrl = ''; // Declared here

            if (selectedPlace) {
                // Transform Place Data
                finalPlaceId = selectedPlace.id;
                finalPlaceAddress = selectedPlace.address || '';
                finalPlaceLat = selectedPlace.lat || 0;
                finalPlaceLng = selectedPlace.lng || 0;

                // Handle Image Upload
                finalPhotoUrl = photoUrl;
                if (_imageFile) {
                    try {
                        const fileExt = _imageFile.name.split('.').pop();
                        const fileName = `${user.uid}_${Date.now()}.${fileExt}`;
                        const storageRef = ref(storage, `reviews/${user.uid}/${fileName}`);

                        console.log("Uploading review image...", fileName);
                        const snapshot = await uploadBytes(storageRef, _imageFile);
                        finalPhotoUrl = await getDownloadURL(snapshot.ref);
                        console.log("Upload success:", finalPhotoUrl);
                    } catch (uploadErr) {
                        console.error("Upload failed", uploadErr);
                        setError("Error al subir la imagen. Intenta de nuevo.");
                        setLoading(false);
                        return;
                    }
                } else if (imagePreview && imagePreview.startsWith('http')) {
                    // Keep existing info if it was already a URL (edit mode)
                    finalPhotoUrl = imagePreview;
                } else {
                    finalPhotoUrl = '';
                }

                try {
                    console.log(`Ensuring place ${finalPlaceId} exists via backend...`);
                    const idToken = await user.getIdToken();
                    const syncedPlace = await PlaceService.ensurePlaceSyncedWithBackend(finalPlaceId, idToken);

                    if (syncedPlace) {
                        console.log("Place synced successfully:", syncedPlace.name);
                        // Update local snapshot vars with the authoritative data from backend
                        finalPlaceAddress = syncedPlace.address || syncedPlace.formatted_address || finalPlaceAddress;

                        // Use location (object) or coordinates (object) or fallback to lat/lng if available
                        if (syncedPlace.location && typeof syncedPlace.location === 'object') {
                            finalPlaceLat = syncedPlace.location.latitude;
                            finalPlaceLng = syncedPlace.location.longitude;
                        } else if (syncedPlace.coordinates && typeof syncedPlace.coordinates === 'object') {
                            finalPlaceLat = syncedPlace.coordinates.latitude;
                            finalPlaceLng = syncedPlace.coordinates.longitude;
                        }
                    }
                } catch (placeErr) {
                    console.error("Failed to sync place with backend via new logic:", placeErr);
                }
            }



            const listDataLocal = listData || {}; // might need to refetch if we switched listId? 
            // If we relied on listId prop, it's fine.

            const isSublist = !!listData?.parentListId;
            const finalListId = isSublist ? listData.parentListId : internalListId; // Use internalListId to respect selection
            const sublistId = isSublist ? internalListId : null;
            const visibility = listData?.visibility === 'private' ? 'private' : 'public';

            const reviewData = {
                listId: finalListId,
                sublistId: sublistId,
                visibility,
                userId: user.uid,
                authorName: user.displayName || 'Anónimo',
                authorPhoto: user.photoURL || '',
                itemName: itemName.trim(),
                comment: comment.trim(),
                overallRating,
                scores: criteriaScores,
                criteriaDefinition: criteriaList, // SAVE AS ARRAY to preserve order
                tags: customTags,
                photoUrl: finalPhotoUrl,
                updatedAt: serverTimestamp(),
                placeId: finalPlaceId,
                placeName: selectedPlace?.name || placeName,
                placeAddress: finalPlaceAddress,
                placeLat: finalPlaceLat,
                placeLng: finalPlaceLng,
            };

            if (editReviewId) {
                // Update
                const reviewRef = doc(db, reviewPath || `reviews/${editReviewId}`);
                await updateDoc(reviewRef, reviewData as any);
            } else {
                // Create
                await addDoc(collection(db, 'reviews'), {
                    ...reviewData,
                    createdAt: serverTimestamp()
                });
            }

            // Update Counters (Simplified for readability, assuming existing logic was correct just messy)
            if (!editReviewId) {
                const updates = [];
                if (finalListId) {
                    updates.push(updateDoc(doc(db, 'lists', finalListId), {
                        itemCount: increment(1),
                        reviewCount: increment(1),
                        updatedAt: serverTimestamp()
                    }));
                }
                if (sublistId && sublistId !== finalListId) {
                    updates.push(updateDoc(doc(db, 'lists', sublistId), {
                        itemCount: increment(1),
                        reviewCount: increment(1),
                        updatedAt: serverTimestamp()
                    }));
                }
                await Promise.all(updates);
            }

            onSuccess();
            onClose();

        } catch (err: any) {
            console.error("Error adding review:", err);
            setError("Error al guardar: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    if (initLoading && isNew) {
        return (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
                <Loader2 className="w-10 h-10 text-indigo-500 animate-spin" />
            </div>
        );
    }

    // Split Criteria for Display
    const ponderableCriteria = criteriaList.filter(c => c.ponderable !== false);
    const nonPonderableCriteria = criteriaList.filter(c => c.ponderable === false);

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm animate-fade-in md:p-4">
            <div className="bg-[#0b1021] w-full h-full md:h-auto md:max-h-[90vh] md:max-w-2xl md:rounded-2xl shadow-2xl flex flex-col overflow-hidden border-none md:border border-white/10">

                {/* Header */}
                <div className="p-4 border-b border-white/10 flex justify-between items-center bg-[#151b2e]">
                    <h2 className="text-lg font-bold text-white flex items-center gap-2">
                        {isNew ? 'Nueva Reseña' : 'Editar Reseña'}
                    </h2>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                <div className="overflow-y-auto flex-1 custom-scrollbar relative">
                    {/* List Selector Picker */}
                    <div className="p-6 pb-0 space-y-2">
                        {/* CHANGED: Logic for locking list if editing - use internalListId state properly */}
                        {(!lockList && !editReviewId) ? (
                            <>
                                <label className="block text-xs font-bold uppercase text-gray-400 tracking-wider">Guardar en Lista <span className="text-red-400">*</span></label>
                                <ListSearch
                                    onSelect={(id) => {
                                        setInternalListId(id);
                                        if (onListChange) onListChange(id);
                                    }}
                                    selectedListId={internalListId}
                                    placeName={selectedPlace?.name || itemName} // Use place name or item name for smart search
                                    placeTypes={selectedPlace?.types} // Smart search by type
                                    suggestedListIds={suggestedListIds}
                                />
                            </>
                        ) : internalListId ? (
                            <div className="bg-[#151b2e] border border-white/10 p-3 rounded-lg flex justify-between items-center">
                                <span className="text-sm text-gray-300">
                                    Guardando en: <span className="text-indigo-400 font-bold">{listData?.name || 'Lista'}</span>
                                </span>
                                <Lock className="w-4 h-4 text-gray-500" />
                            </div>
                        ) : (
                            <div className="p-2 border border-dashed border-red-500/30 text-red-400 text-xs rounded">
                                Error: No hay lista seleccionada
                            </div>
                        )}
                    </div>

                    <form id="review-form" onSubmit={handleSubmit} className="space-y-6 p-6">

                        {/* 0. Place Search (Locked if Prefilled) */}
                        {prefillPlaceId ? (
                            <div className="space-y-2">
                                <label className="block text-xs font-bold uppercase text-gray-400 tracking-wider">Lugar <span className="text-red-400">*</span></label>
                                <div className="bg-[#1e2538] border border-white/10 rounded-xl p-4 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-indigo-500/10 rounded-lg text-indigo-400">
                                            <MapPinIcon className="w-5 h-5" />
                                        </div>
                                        <div>
                                            <div className="font-bold text-white text-sm">{selectedPlace?.name || 'Cargando lugar...'}</div>
                                            <div className="text-xs text-gray-500">{selectedPlace?.address || 'Dirección no disponible'}</div>
                                        </div>
                                    </div>
                                    <div className="text-gray-500" title="Lugar fijo">
                                        <Lock className="w-4 h-4" />
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="space-y-2">
                                <label className="block text-xs font-bold uppercase text-gray-400 tracking-wider">Lugar <span className="text-red-400">*</span></label>
                                <PlaceSearch
                                    onSelect={setSelectedPlace}
                                    prefillValue={selectedPlace?.name || prefillItemName}
                                    placeholder="Buscar en el mapa (ej. Starbucks)..."
                                />
                                {selectedPlace && (
                                    <div className="text-sm text-green-400 bg-green-400/10 p-2 rounded border border-green-400/20 flex items-center gap-2">
                                        <MapPinIcon className="w-3 h-3" />
                                        Seleccionado: {selectedPlace.name}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* 1. Item Name (Locked if Prefilled) */}
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-400 mb-1 tracking-wider">¿Qué probaste? <span className="text-red-400">*</span></label>
                            <div className="relative">
                                <input
                                    type="text"
                                    value={itemName}
                                    onChange={e => setItemName(e.target.value)}
                                    placeholder="Ej: Pizza Margarita"
                                    disabled={!!prefillItemName}
                                    className={`w-full bg-[#0b1021] border rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 transition-colors ${prefillItemName
                                        ? 'border-indigo-500/30 text-gray-300 cursor-not-allowed bg-[#151b2e]'
                                        : 'border-white/10'
                                        }`}
                                />
                                {prefillItemName && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-indigo-400" title="Nombre fijo">
                                        <Lock className="w-4 h-4" />
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* 3. Overall Rating (Read Only / Auto) */}
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-400 mb-2 tracking-wider">Nota Global</label>
                            <div className="flex items-center gap-4 bg-[#151b2e] p-4 rounded-xl border border-white/5">
                                <div className={`text-4xl font-bold ${overallRating >= 7 ? 'text-green-400' : overallRating >= 5 ? 'text-yellow-400' : 'text-red-400'}`}>
                                    {overallRating}
                                </div>
                                <div className="text-xs text-gray-500">
                                    Esta nota se calcula automáticamente basándose en tus puntuaciones.
                                </div>
                            </div>
                        </div>

                        {/* 4. Detailed Criteria */}
                        {criteriaList.length > 0 ? (
                            <div className="bg-white/5 p-5 rounded-2xl border border-white/5 space-y-6">
                                <h3 className="text-base font-bold text-gray-200 flex items-center gap-2 mb-2">
                                    Valoración Detallada <span className="text-red-400">*</span>
                                </h3>

                                {/* PONDERABLE CRITERIA */}
                                <div className="space-y-6">
                                    {ponderableCriteria.map((criterion) => (
                                        <div key={criterion.id}>
                                            <div className="flex justify-between mb-2">
                                                <label className="text-sm text-gray-300 font-medium">{criterion.label || criterion.id}</label>
                                                <span
                                                    className="text-sm font-bold transition-colors duration-300"
                                                    style={{ color: `hsl(${criteriaScores[criterion.id] * 12}, 90%, 50%)` }}
                                                >
                                                    {criteriaScores[criterion.id]}
                                                </span>
                                            </div>
                                            <div className="relative w-full h-6 flex items-center">
                                                {/* Track Background & Fill */}
                                                <div className="absolute left-0 right-0 h-2 bg-gray-700/50 rounded-full overflow-hidden">
                                                    <div
                                                        className="h-full transition-all duration-300 rounded-full"
                                                        style={{
                                                            width: `${(criteriaScores[criterion.id] / 10) * 100}%`,
                                                            background: `hsl(${criteriaScores[criterion.id] * 12}, 90%, 50%)`,
                                                            boxShadow: `0 0 10px hsl(${criteriaScores[criterion.id] * 12}, 90%, 50%, 0.5)`
                                                        }}
                                                    />
                                                </div>

                                                {/* Interactive Input */}
                                                <input
                                                    type="range"
                                                    min="0"
                                                    max="10"
                                                    step={criterion.step || 0.1}
                                                    value={criteriaScores[criterion.id] || 0}
                                                    onChange={(e) => {
                                                        const val = parseFloat(e.target.value);
                                                        const newScores = { ...criteriaScores, [criterion.id]: val };
                                                        setCriteriaScores(newScores);
                                                        setRatingsTouched(true);
                                                    }}
                                                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                                />
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                {/* NON-PONDERABLE CRITERIA (Separate Section) */}
                                {nonPonderableCriteria.length > 0 && (
                                    <>
                                        <div className="border-t border-white/10 pt-4 mt-6">
                                            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">Otros Detalles</h4>
                                            <div className="space-y-6">
                                                {nonPonderableCriteria.map((criterion) => (
                                                    <div key={criterion.id}>
                                                        <div className="flex justify-between mb-2">
                                                            <label className="text-sm text-gray-300 font-medium">{criterion.label || criterion.id}</label>
                                                            <span className="text-sm font-bold text-indigo-400">
                                                                {criteriaScores[criterion.id]}
                                                            </span>
                                                        </div>
                                                        <div className="relative w-full h-6 flex items-center">
                                                            {/* Track Background & Fill (Neutral Color) */}
                                                            <div className="absolute left-0 right-0 h-2 bg-gray-700/50 rounded-full overflow-hidden">
                                                                <div
                                                                    className="h-full transition-all duration-300 rounded-full bg-indigo-500/50"
                                                                    style={{
                                                                        width: `${(criteriaScores[criterion.id] / 10) * 100}%`
                                                                    }}
                                                                />
                                                            </div>

                                                            {/* Interactive Input with Fixed Step 0.5 */}
                                                            <input
                                                                type="range"
                                                                min="0"
                                                                max="10"
                                                                step={0.5} // Enforce 0.5 step for non-ponderable
                                                                value={criteriaScores[criterion.id] || 0}
                                                                onChange={(e) => {
                                                                    const val = parseFloat(e.target.value);
                                                                    const newScores = { ...criteriaScores, [criterion.id]: val };
                                                                    setCriteriaScores(newScores);
                                                                    setRatingsTouched(true);
                                                                }}
                                                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                                            />
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className="p-8 border border-dashed border-white/10 rounded-xl text-center">
                                <p className="text-gray-400 text-sm">
                                    {listId ? 'Cargando criterios...' : 'Selecciona una lista para ver los criterios de valoración.'}
                                </p>
                            </div>
                        )}

                        {/* 5. Comment */}
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-400 mb-1 tracking-wider">Tu opinión</label>
                            <textarea
                                value={comment}
                                onChange={e => setComment(e.target.value)}
                                placeholder="¿Qué te pareció?"
                                rows={4}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 transition-colors"
                            />
                        </div>

                        {/* 6. Photo */}
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-400 mb-2 tracking-wider">Foto</label>

                            {imagePreview ? (
                                <div className="relative w-full h-48 rounded-xl overflow-hidden border border-white/10 group">
                                    <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                    <button
                                        type="button"
                                        onClick={() => {
                                            setImageFile(null);
                                            setImagePreview(null);
                                        }}
                                        className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                        <div className="bg-red-500/80 p-2 rounded-full text-white">
                                            <Trash2 className="w-6 h-6" />
                                        </div>
                                    </button>
                                </div>
                            ) : (
                                <div
                                    className="w-full h-48 border-2 border-dashed border-white/10 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500/50 hover:bg-indigo-500/5 transition-all group"
                                    onDragOver={(e) => {
                                        e.preventDefault();
                                        e.currentTarget.classList.add('border-indigo-500', 'bg-indigo-500/10');
                                    }}
                                    onDragLeave={(e) => {
                                        e.preventDefault();
                                        e.currentTarget.classList.remove('border-indigo-500', 'bg-indigo-500/10');
                                    }}
                                    onDrop={(e) => {
                                        e.preventDefault();
                                        e.currentTarget.classList.remove('border-indigo-500', 'bg-indigo-500/10');
                                        const file = e.dataTransfer.files?.[0];
                                        if (file && file.type.startsWith('image/')) {
                                            setImageFile(file);
                                            const reader = new FileReader();
                                            reader.onloadend = () => setImagePreview(reader.result as string);
                                            reader.readAsDataURL(file);
                                        }
                                    }}
                                    onClick={() => document.getElementById('review-photo-upload')?.click()}
                                >
                                    <div className="bg-white/5 p-4 rounded-full mb-3 group-hover:scale-110 transition-transform">
                                        <ImageIcon className="w-8 h-8 text-indigo-400" />
                                    </div>
                                    <p className="text-sm font-bold text-gray-300">Arrastra tu foto o haz clic</p>
                                    <p className="text-xs text-gray-500 mt-1">Soporta JPG, PNG, WEBP</p>
                                    <input
                                        id="review-photo-upload"
                                        type="file"
                                        className="hidden"
                                        accept="image/*"
                                        onChange={handleImageChange}
                                    />
                                </div>
                            )}
                        </div>

                        {/* 7. Tags */}
                        <div>
                            <label className="block text-xs font-bold uppercase text-gray-400 mb-2 tracking-wider">Etiquetas</label>
                            <div className="flex flex-wrap gap-2">
                                {listAvailableTags.map(tag => (
                                    <button
                                        type="button"
                                        key={tag}
                                        onClick={() => toggleTag(tag)}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${customTags.includes(tag)
                                            ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/20'
                                            : 'bg-[#1e2538] text-gray-400 hover:bg-white/5'
                                            }`}
                                    >
                                        {tag}
                                    </button>
                                ))}
                                {listAvailableTags.length === 0 && (
                                    <p className="text-gray-500 text-xs italic">No hay etiquetas definidas en esta lista.</p>
                                )}
                            </div>
                        </div>

                    </form>
                </div>

                {/* Footer Actions */}
                <div className="p-4 border-t border-white/10 bg-[#151b2e] flex justify-end gap-3">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-4 py-2 text-gray-400 hover:text-white font-medium transition-colors"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        form="review-form"
                        disabled={loading || !isValid || (!isNew && !isDirty)}
                        className={`px-6 py-2 rounded-xl font-bold flex items-center gap-2 transition-all ${loading || !isValid || (!isNew && !isDirty)
                            ? 'bg-gray-700 text-gray-400 cursor-not-allowed'
                            : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-500/20 hover:scale-105'
                            }`}
                    >
                        {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                        {isNew ? 'Publicar Reseña' : 'Guardar Cambios'}
                    </button>
                </div>
            </div >
        </div >
    );
};

import React from 'react';
import { ChevronRight } from 'lucide-react';
import { Link } from 'react-router-dom';

interface CardCarouselProps {
    title: string;
    subtitle?: string;
    viewAllLink?: string;
    items: any[];
    renderItem: (item: any, index: number) => React.ReactNode;
    loading?: boolean;
    itemClassName?: string;
}

export const CardCarousel: React.FC<CardCarouselProps> = ({
    title,
    subtitle,
    viewAllLink,
    items,
    renderItem,
    loading,
    itemClassName = "min-w-[200px] md:min-w-[240px]"
}) => {
    return (
        <section className="py-2">
            <div className="container mx-auto px-4 mb-4 flex items-end justify-between">
                <div>
                    <h2 className="text-xl md:text-2xl font-display font-bold text-white mb-1">
                        {title}
                    </h2>
                    {subtitle && (
                        <p className="text-sm text-gray-400 font-medium">
                            {subtitle}
                        </p>
                    )}
                </div>
                {viewAllLink && (
                    <Link
                        to={viewAllLink}
                        className="text-sm font-bold text-indigo-400 hover:text-indigo-300 flex items-center gap-1 transition-colors"
                    >
                        Ver todo <ChevronRight className="w-4 h-4" />
                    </Link>
                )}
            </div>

            <div className="relative group">
                {/* Scroll Buttons */}
                {/* Scroll Buttons (Glassmorphism) */}
                <button
                    onClick={() => {
                        document.getElementById(`carousel-${title.replace(/\s+/g, '-')}`)?.scrollBy({ left: -320, behavior: 'smooth' });
                    }}
                    className="absolute -left-5 top-1/2 -translate-y-1/2 z-50 w-12 h-12 bg-black/40 backdrop-blur-xl border border-white/10 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-600 hover:scale-110 shadow-xl"
                >
                    <ChevronRight className="w-6 h-6 rotate-180" />
                </button>
                <button
                    onClick={() => {
                        document.getElementById(`carousel-${title.replace(/\s+/g, '-')}`)?.scrollBy({ left: 320, behavior: 'smooth' });
                    }}
                    className="absolute -right-5 top-1/2 -translate-y-1/2 z-50 w-12 h-12 bg-black/40 backdrop-blur-xl border border-white/10 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-all hover:bg-indigo-600 hover:scale-110 shadow-xl"
                >
                    <ChevronRight className="w-6 h-6" />
                </button>

                {/* Scroll Container */}
                <div
                    id={`carousel-${title.replace(/\s+/g, '-')}`}
                    className="flex overflow-x-auto gap-2 px-4 pb-4 snap-x snap-mandatory hide-scrollbar scroll-smooth"
                >
                    {loading ? (
                        // Skeleton Loaders
                        Array.from({ length: 4 }).map((_, i) => (
                            <div key={i} className="min-w-[280px] md:min-w-[320px] h-64 bg-white/5 rounded-2xl animate-pulse flex-shrink-0 snap-start" />
                        ))
                    ) : (
                        items.map((item, index) => (
                            <div key={index} className={`${itemClassName} flex-shrink-0 snap-start`}>
                                {renderItem(item, index)}
                            </div>
                        ))
                    )}
                </div>

                {/* Fade Edges */}

            </div>
        </section>
    );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { collection, addDoc, serverTimestamp, getDocs, doc, updateDoc, increment } from 'firebase/firestore';
import { db } from '../firebase';
import { Save, Loader, Image as ImageIcon, X } from 'lucide-react';
import { CriteriaBuilder, type Criterion } from './CriteriaBuilder';
import { type ListEntity } from '../hooks/useLists';

interface CreateListFormProps {
    parentListId?: string; // If creating a sublist
    parentListName?: string; // Name of parent list for display
    parentListImage?: string; // Image of parent list for display
    parentCriteria?: Record<string, any>; // Criteria from parent list
    parentTags?: string[]; // Tags from parent list
    initialData?: Partial<ListEntity>; // For editing in the future
    onSuccess: (newListId: string) => void;
    onCancel: () => void;
}

export const CreateListForm: React.FC<CreateListFormProps> = ({ parentListId, parentListName, parentListImage, parentCriteria, parentTags, initialData, onSuccess, onCancel }) => {
    const { user } = useAuth();

    // State
    const [name, setName] = useState(initialData?.name || '');
    const [description, setDescription] = useState(initialData?.description || '');
    const [isPublic, setIsPublic] = useState(initialData?.isPublic ?? true);
    const [publicAccess, setPublicAccess] = useState<'reader' | 'writer'>(initialData?.publicAccess || 'reader');
    // We construct the categoryId if needed, but for now let's just use empty or what's passed
    // NOTE: In the original page, categoryId helps prefill tags/criteria.
    const [categoryId, setCategoryId] = useState('');
    const [categories, setCategories] = useState<any[]>([]);

    // Image
    const [imagePreview, setImagePreview] = useState<string | null>(initialData?.photoUrl || initialData?.mainImageUrl || null);

    // Advanced
    // Advanced
    const [criteria, setCriteria] = useState<Criterion[]>(() => {
        if (parentCriteria) {
            // Convert parent map to array
            const inherited: Criterion[] = [];
            Object.entries(parentCriteria).forEach(([key, val]: [string, any]) => {
                if (val.type === 'slider') {
                    inherited.push({
                        id: key,
                        label: val.label,
                        minLabel: val.labelMin,
                        maxLabel: val.labelMax,
                        isPonderable: val.ponderable !== false
                    });
                }
            });
            return inherited;
        }
        return [
            { id: 'calidad', label: 'Calidad General', minLabel: 'Malo', maxLabel: 'Excelente', isPonderable: true }
        ];
    });

    // Calculate locked IDs
    const lockedCriteriaIds = React.useMemo(() => {
        return parentCriteria ? Object.keys(parentCriteria) : [];
    }, [parentCriteria]);

    const [customTags, setCustomTags] = useState<string[]>(initialData?.availableTags || []);
    const [fixedTags, setFixedTags] = useState<string[]>(parentTags || initialData?.fixedTags || []);
    const [tagInput, setTagInput] = useState('');

    const [loading, setLoading] = useState(false);

    // Fetch Categories
    useEffect(() => {
        const fetchCategories = async () => {
            try {
                const snapshot = await getDocs(collection(db, 'categories'));
                if (!snapshot.empty) {
                    setCategories(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
                }
            } catch (e) {
                console.error("Error fetching categories", e);
            }
        };
        fetchCategories();
    }, []);

    // Handle Category Selection -> Prefill defaults
    useEffect(() => {
        if (!categoryId) return;
        const selectedCat = categories.find(c => c.id === categoryId);
        if (selectedCat) {
            // 1. Prefill Tags
            if (selectedCat['fixed-tags'] && Array.isArray(selectedCat['fixed-tags'])) {
                setFixedTags(selectedCat['fixed-tags']);
            }

            // 2. Prefill Criteria
            if (selectedCat.defaultCriteria) {
                const newCriteria: Criterion[] = [];
                Object.entries(selectedCat.defaultCriteria).forEach(([key, val]: [string, any]) => {
                    // Skip 'like'/'dislike' non-slider keys if present
                    if (val.type === 'slider') {
                        newCriteria.push({
                            id: key,
                            label: val.label,
                            minLabel: val.labelMin || 'Mina',
                            maxLabel: val.labelMax || 'Max',
                            isPonderable: val.ponderable !== false // default true
                        });
                    }
                });
                if (newCriteria.length > 0) {
                    setCriteria(newCriteria);
                }
            }
        }
    }, [categoryId, categories]);

    // Image Handlers
    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => setImagePreview(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    // Tag Handlers
    const addTag = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && tagInput.trim()) {
            e.preventDefault();
            const val = tagInput.trim();
            if (!customTags.includes(val) && !fixedTags.includes(val)) {
                setCustomTags([...customTags, val]);
            }
            setTagInput('');
        }
    };

    const removeTag = (tag: string) => {
        setCustomTags(customTags.filter(t => t !== tag));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) return;
        setLoading(true);

        try {
            const finalPhotoUrl = imagePreview || '';

            // Transform criteria array back to Map/Object for DB
            const criteriaDefinitionMap: Record<string, any> = {};
            criteria.forEach(c => {
                criteriaDefinitionMap[c.id] = {
                    type: 'slider',
                    label: c.label,
                    min: 0,
                    max: 10,
                    step: 0.5, // Standard step
                    labelMin: c.minLabel,
                    labelMax: c.maxLabel,
                    ponderable: c.isPonderable
                };
            });

            const finalListTags = [...fixedTags, ...customTags];

            // Legacy Structure Match
            const newListData = {
                name,
                description,
                categoryId, // "comida_hmm" etc
                userId: user.uid,
                isPublic,
                publicAccess: isPublic ? publicAccess : 'reader', // Reset to reader if private just in case
                parentListId: parentListId || null,

                // Fields expected by new UI / legacy UI
                authorName: user.displayName || 'Anónimo',
                mainImageUrl: finalPhotoUrl, // Legacy name "mainImageUrl", new might use "photoUrl" - let's save both or align
                photoUrl: finalPhotoUrl,

                criteriaDefinition: criteriaDefinitionMap,
                availableTags: finalListTags, // Combined tags
                fixedTags: fixedTags,

                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp(),

                // Counters
                itemCount: 0,
                groupedItemsCount: 0,
                viewCount: 0,
                likes: 0,
                followersCount: 0,
                commentsCount: 0,
                reviewCount: 0,
                averageRating: 0, // Initial average

                // New fields for schema alignment
                criteriaAverages: {},
                criteriaAveragesUpdatedAt: serverTimestamp(),
                reactions: {},
            };

            const docRef = await addDoc(collection(db, 'lists'), newListData);

            // Update User's listsCount
            const userRef = doc(db, 'users', user.uid);
            await updateDoc(userRef, {
                listsCount: increment(1)
            }).catch(e => console.warn("Could not increment user list count", e));

            onSuccess(docRef.id);
        } catch (error) {
            console.error("Error creating list:", error);
            alert("Error al crear la lista");
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            {/* Basic Info */}
            {parentListId && parentListName ? (
                <div className="flex items-center gap-4 mb-2">
                    <div className="w-12 h-12 rounded-lg overflow-hidden border border-white/10 shrink-0">
                        {parentListImage ? (
                            <img src={parentListImage} className="w-full h-full object-cover opacity-80" alt={parentListName} />
                        ) : (
                            <div className="w-full h-full bg-indigo-500/20 flex items-center justify-center text-indigo-400 font-bold text-xs">
                                {parentListName[0]}
                            </div>
                        )}
                    </div>
                    <div>
                        <h2 className="text-xl font-bold font-display text-white">Nueva Sublista</h2>
                        <p className="text-gray-400 text-sm">Basada en <span className="text-indigo-400">{parentListName}</span></p>
                    </div>
                </div>
            ) : null}

            <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-6">
                {!parentListId && <h2 className="text-xl font-bold text-white mb-4">Información Básica</h2>}

                <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2">Nombre de la Lista</label>
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                        placeholder={parentListId ? "Ej: Sushi (Sublista)" : "Ej: Mejores Ramen de Madrid"}
                        required
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2">Categoría</label>
                    <select
                        value={categoryId}
                        onChange={(e) => setCategoryId(e.target.value)}
                        className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                        required={!parentListId} // Maybe optional for sublists? But let's keep it required for consistency
                    >
                        <option value="">Selecciona una categoría</option>
                        {categories.map(cat => (
                            <option key={cat.id} value={cat.id}>{cat.name}</option>
                        ))}
                    </select>
                    {categoryId && categories.find(c => c.id === categoryId)?.['fixed-tags'] && (
                        <p className="text-xs text-indigo-400 mt-2">
                            Incluye etiquetas automáticas: {categories.find(c => c.id === categoryId)['fixed-tags'].join(', ')}
                        </p>
                    )}
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2">Descripción</label>
                    <textarea
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 min-h-[100px]"
                        placeholder="¿De qué trata esta lista?"
                    />
                </div>

                {/* Image Upload */}
                <div>
                    <label className="block text-sm font-medium text-gray-400 mb-2">Portada de la Lista</label>
                    <div className="border-2 border-dashed border-white/10 rounded-xl p-6 text-center hover:bg-white/5 transition-colors relative group">
                        {imagePreview ? (
                            <div className="relative h-48 w-full rounded-lg overflow-hidden">
                                <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                <button
                                    type="button"
                                    onClick={() => { setImagePreview(null); }}
                                    className="absolute top-2 right-2 p-1 bg-black/50 rounded-full text-white hover:bg-red-500 transition-colors"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                            </div>
                        ) : (
                            <>
                                <input
                                    type="file"
                                    accept="image/*"
                                    onChange={handleImageChange}
                                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                />
                                <ImageIcon className="w-12 h-12 text-gray-600 mx-auto mb-3 group-hover:text-indigo-500 transition-colors" />
                                <p className="text-gray-400 text-sm">Arrastra una imagen o haz clic para subir</p>
                                <p className="text-gray-600 text-xs mt-1">PNG, JPG hasta 5MB</p>
                            </>
                        )}
                    </div>
                </div>
            </div>

            {/* Criteria & Tags */}
            <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-8">
                {/* Criteria Builder Component */}
                <CriteriaBuilder criteria={criteria} onChange={setCriteria} lockedIds={lockedCriteriaIds} />

                <div className="border-t border-white/5 pt-6"></div>

                {/* Tags */}
                <div>
                    <h3 className="text-lg font-bold text-white mb-2">Etiquetas (Tags)</h3>
                    <p className="text-sm text-gray-400 mb-4">Ayuda a otros a filtrar tu lista (ej. #Barato, #Terraza).</p>

                    <div className="flex flex-wrap gap-2 mb-3">
                        {fixedTags.map(tag => (
                            <span key={`fixed-${tag}`} className="bg-gray-700/50 text-gray-300 px-3 py-1 rounded-full text-sm flex items-center gap-1 border border-white/5 cursor-not-allowed">
                                {tag}
                            </span>
                        ))}
                        {customTags.map(tag => (
                            <span key={tag} className="bg-indigo-500/20 text-indigo-300 px-3 py-1 rounded-full text-sm flex items-center gap-1">
                                {tag}
                                <button type="button" onClick={() => removeTag(tag)} className="hover:text-white"><X className="w-3 h-3" /></button>
                            </span>
                        ))}
                    </div>

                    <input
                        type="text"
                        value={tagInput}
                        onChange={(e) => setTagInput(e.target.value)}
                        onKeyDown={addTag}
                        placeholder="Escribe un tag y presiona Enter..."
                        className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                    />
                </div>
            </div>

            {/* Visibility */}
            <div className="bg-[#151b2e] p-4 rounded-xl border border-white/10 flex items-center gap-3">
                <input
                    type="checkbox"
                    id="isPublic"
                    checked={isPublic}
                    onChange={(e) => setIsPublic(e.target.checked)}
                    className="w-5 h-5 rounded border-gray-600 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021]"
                />
                <label htmlFor="isPublic" className="text-sm cursor-pointer">
                    <span className="block font-medium text-white">Lista Pública</span>
                    <span className="block text-xs text-gray-500">Visible en tu perfil y resultados de búsqueda.</span>
                </label>
            </div>

            {/* Public Access Level */}
            {isPublic && (
                <div className="bg-[#151b2e] p-4 rounded-xl border border-white/10 animate-fade-in">
                    <label className="block text-sm font-medium text-gray-400 mb-3">Permisos Públicos</label>
                    <div className="space-y-3">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="radio"
                                name="publicAccess"
                                value="reader"
                                checked={publicAccess === 'reader'}
                                onChange={() => setPublicAccess('reader')}
                                className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021] border-gray-600"
                            />
                            <div>
                                <span className="block text-sm font-medium text-white">Solo Lectura</span>
                                <span className="block text-xs text-gray-500">Los visitantes pueden ver la lista pero solo tú (y editores) pueden añadir reseñas.</span>
                            </div>
                        </label>
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="radio"
                                name="publicAccess"
                                value="writer"
                                checked={publicAccess === 'writer'}
                                onChange={() => setPublicAccess('writer')}
                                className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021] border-gray-600"
                            />
                            <div>
                                <span className="block text-sm font-medium text-white">Colaborativa (Escritura)</span>
                                <span className="block text-xs text-gray-500">Cualquier usuario puede añadir sus propias reseñas a esta lista.</span>
                            </div>
                        </label>
                    </div>
                </div>
            )}

            <div className="flex gap-4">
                <button
                    type="button"
                    onClick={onCancel}
                    className="flex-1 py-4 border border-white/10 hover:bg-white/5 text-white font-bold rounded-xl transition-colors"
                >
                    Cancelar
                </button>
                <button
                    type="submit"
                    disabled={loading}
                    className="flex-1 py-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg transition-transform active:scale-[0.99] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                    {loading ? <Loader className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                    {loading ? 'Guardando...' : parentListId ? 'Crear Sublista' : 'Guardar Lista'}
                </button>
            </div>
        </form>
    );
};

import React from 'react';
import { Plus, X, Sliders, Lock } from 'lucide-react';

export interface Criterion {
    id: string;
    label: string;
    minLabel: string;
    maxLabel: string;
    isPonderable: boolean;
    locked?: boolean;
}

interface CriteriaBuilderProps {
    criteria: Criterion[];
    onChange: (criteria: Criterion[]) => void;
    lockedIds?: string[];
}

export const CriteriaBuilder: React.FC<CriteriaBuilderProps> = ({ criteria, onChange, lockedIds = [] }) => {

    const addCriterion = () => {
        const newCriterion: Criterion = {
            id: Date.now().toString(),
            label: '',
            minLabel: 'Malo',
            maxLabel: 'Excelente',
            isPonderable: true
        };
        onChange([...criteria, newCriterion]);
    };

    const removeCriterion = (id: string) => {
        const item = criteria.find(c => c.id === id);
        if (lockedIds.includes(id) || item?.locked) return;
        onChange(criteria.filter(c => c.id !== id));
    };

    const updateCriterion = (id: string, field: keyof Criterion, value: any) => {
        const item = criteria.find(c => c.id === id);
        if (lockedIds.includes(id) || item?.locked) return;
        onChange(criteria.map(c =>
            c.id === id ? { ...c, [field]: value } : c
        ));
    };

    return (
        <div className="space-y-4">
            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Sliders className="w-5 h-5 text-indigo-400" />
                Criterios de Evaluación
            </h3>
            <p className="text-sm text-gray-400">
                Define qué aspectos se valorarán en esta lista (ej. Sabor, Ambiente, Precio).
            </p>

            <div className="space-y-3">
                {criteria.map((criterion) => {
                    const isLocked = lockedIds.includes(criterion.id) || criterion.locked;
                    return (
                        <div key={criterion.id} className={`bg-[#151b2e] p-4 rounded-xl border ${isLocked ? 'border-indigo-500/30' : 'border-white/5'} animate-fade-in relative group`}>
                            {!isLocked && (
                                <button
                                    type="button"
                                    onClick={() => removeCriterion(criterion.id)}
                                    className="absolute top-2 right-2 p-1 text-gray-500 hover:text-red-400 transition-colors opacity-0 group-hover:opacity-100"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                            )}
                            {isLocked && (
                                <div className="absolute top-2 right-2 px-2 py-0.5 bg-indigo-500/20 text-indigo-300 text-[10px] font-bold rounded border border-indigo-500/30 flex items-center gap-1">
                                    <Lock className="w-3 h-3" /> Heredado
                                </div>
                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-medium text-gray-400 mb-1">
                                        Nombre del Criterio {isLocked && '(Heredado)'}
                                    </label>
                                    <input
                                        type="text"
                                        value={criterion.label}
                                        onChange={(e) => updateCriterion(criterion.id, 'label', e.target.value)}
                                        placeholder="Ej: Calidad del Café"
                                        disabled={isLocked}
                                        className={`w-full bg-[#0b1021] border border-white/10 rounded-lg px-3 py-2 text-white text-sm focus:outline-none focus:border-indigo-500 ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    />
                                </div>

                                <div className="flex items-center gap-4 mt-6">
                                    <label className={`flex items-center gap-2 ${isLocked ? 'cursor-not-allowed opacity-50' : 'cursor-pointer'}`}>
                                        <input
                                            type="checkbox"
                                            checked={criterion.isPonderable}
                                            onChange={(e) => updateCriterion(criterion.id, 'isPonderable', e.target.checked)}
                                            disabled={isLocked}
                                            className={`w-4 h-4 rounded border-gray-600 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021] ${isLocked ? 'cursor-not-allowed' : ''}`}
                                        />
                                        <span className="text-sm text-gray-300">Afecta al promedio {isLocked && '(Fijo)'}</span>
                                    </label>
                                </div>
                            </div>

                            {/* Advanced (Min/Max Labels) - Optional or expandable could go here */}
                        </div>
                    );
                })}
            </div>

            <button
                type="button"
                onClick={addCriterion}
                className="w-full py-3 border border-dashed border-white/20 rounded-xl text-gray-400 hover:text-white hover:border-white/40 hover:bg-white/5 transition-all flex items-center justify-center gap-2"
            >
                <Plus className="w-4 h-4" /> Agregar Criterio
            </button>
        </div>
    );
};

import React from 'react';
import { X, Sliders, Star, Trash2, Check, ArrowUpDown } from 'lucide-react';
import type { FilterState } from '../pages/ListPage';

interface FilterModalProps {
    isOpen: boolean;
    onClose: () => void;
    filters: FilterState;
    setFilters: React.Dispatch<React.SetStateAction<FilterState>>;
    criteriaDefinition?: Record<string, { label: string; min?: number; max?: number; step?: number }>;
    sortMode: 'rating' | 'newest' | 'oldest' | 'count';
    setSortMode: (mode: 'rating' | 'newest' | 'oldest' | 'count') => void;
    availableTags: string[];
    selectedTags: string[];
    setSelectedTags: (tags: string[]) => void;
}

export const FilterModal: React.FC<FilterModalProps> = ({
    isOpen,
    onClose,
    filters,
    setFilters,
    criteriaDefinition,
    sortMode,
    setSortMode,
    availableTags,
    selectedTags,
    setSelectedTags
}) => {
    const [activeTab, setActiveTab] = React.useState<'filters' | 'sort'>('filters');

    if (!isOpen) return null;

    const handleCriterionChange = (key: string, value: number) => {
        setFilters(prev => ({
            ...prev,
            criteriaMin: {
                ...prev.criteriaMin,
                [key]: value
            }
        }));
    };

    const clearFilters = () => {
        setFilters({
            minRating: 0,
            hasPhoto: false,
            visited: false,
            criteriaMin: {}
        });
        setSelectedTags([]);
    };

    const toggleTag = (tag: string) => {
        if (selectedTags.includes(tag)) {
            setSelectedTags(selectedTags.filter(t => t !== tag));
        } else {
            setSelectedTags([...selectedTags, tag]);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center sm:p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="bg-[#151b2e] w-full h-full sm:h-auto sm:max-w-md sm:rounded-2xl shadow-2xl border-0 sm:border border-white/10 overflow-hidden flex flex-col sm:max-h-[90vh] transition-all">

                {/* Header with Tabs */}
                <div className="border-b border-white/10 bg-white/5 flex-shrink-0">
                    <div className="p-4 flex items-center justify-between">
                        <h2 className="text-lg font-bold text-white flex items-center gap-2">
                            <Sliders className="w-5 h-5 text-indigo-400" /> Preferencias
                        </h2>
                        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white">
                            <X className="w-5 h-5" />
                        </button>
                    </div>

                    <div className="flex px-4 gap-4">
                        <button
                            onClick={() => setActiveTab('filters')}
                            className={`pb-3 text-sm font-bold border-b-2 transition-colors flex-1 text-center ${activeTab === 'filters' ? 'border-indigo-500 text-white' : 'border-transparent text-gray-400 hover:text-white'}`}
                        >
                            Filtros
                        </button>
                        <button
                            onClick={() => setActiveTab('sort')}
                            className={`pb-3 text-sm font-bold border-b-2 transition-colors flex-1 text-center ${activeTab === 'sort' ? 'border-indigo-500 text-white' : 'border-transparent text-gray-400 hover:text-white'}`}
                        >
                            Ordenar
                        </button>
                    </div>
                </div>

                {/* Body - Scrollable */}
                <div className="p-6 overflow-y-auto flex-1 space-y-8 bg-[#151b2e]">

                    {activeTab === 'filters' ? (
                        <>
                            {/* Tag Cloud */}
                            {availableTags && availableTags.length > 0 && (
                                <div>
                                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3 flex items-center gap-2">
                                        Etiquetas
                                    </h3>
                                    <div className="flex flex-wrap gap-2">
                                        <button
                                            onClick={() => setSelectedTags([])}
                                            className={`px-3 py-1.5 text-xs font-bold rounded-lg border transition-all ${selectedTags.length === 0 ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white/5 border-white/10 text-gray-400 hover:border-white/30'}`}
                                        >
                                            Todas
                                        </button>
                                        {availableTags.map(tag => (
                                            <button
                                                key={tag}
                                                onClick={() => toggleTag(tag)}
                                                className={`px-3 py-1.5 text-xs font-bold rounded-lg border transition-all ${selectedTags.includes(tag) ? 'bg-indigo-500 border-indigo-500 text-white' : 'bg-white/5 border-white/10 text-gray-400 hover:border-white/30'}`}
                                            >
                                                {tag}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Global Rating Filter */}
                            <div>
                                <div className="flex justify-between items-center mb-3">
                                    <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                                        <Star className="w-4 h-4 text-yellow-500 fill-current" /> Nota Global Mínima
                                    </label>
                                    <span className="text-sm font-bold text-white bg-white/10 px-2.5 py-1 rounded-md min-w-[3rem] text-center">
                                        {filters.minRating > 0 ? filters.minRating.toFixed(1) : 'Anyone'}
                                    </span>
                                </div>
                                <input
                                    type="range"
                                    min="0"
                                    max="10"
                                    step="0.5"
                                    value={filters.minRating}
                                    onChange={(e) => setFilters(prev => ({ ...prev, minRating: parseFloat(e.target.value) }))}
                                    className="w-full accent-indigo-500 h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                                />
                                <div className="flex justify-between text-xs text-gray-500 mt-2 font-medium">
                                    <span>0</span>
                                    <span>5</span>
                                    <span>10</span>
                                </div>
                            </div>

                            {/* Criteria Filters */}
                            {criteriaDefinition && Object.keys(criteriaDefinition).length > 0 && (
                                <div>
                                    <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4 border-b border-white/5 pb-2">Por Criterio</h3>
                                    <div className="space-y-6">
                                        {Object.entries(criteriaDefinition).map(([key, def]) => {
                                            const currentVal = filters.criteriaMin[key] || 0;
                                            const min = def.min ?? 0;
                                            const max = def.max ?? 10;
                                            return (
                                                <div key={key}>
                                                    <div className="flex justify-between items-center mb-2">
                                                        <label className="text-sm text-gray-300">{def.label}</label>
                                                        <span className={`text-xs px-2 py-0.5 rounded font-bold ${currentVal > min ? 'bg-indigo-500/20 text-indigo-300' : 'text-gray-500'}`}>
                                                            {currentVal > min ? `> ${currentVal}` : 'Cualquiera'}
                                                        </span>
                                                    </div>
                                                    <input
                                                        type="range"
                                                        min={min}
                                                        max={max}
                                                        step={def.step ?? 0.5}
                                                        value={currentVal}
                                                        onChange={(e) => handleCriterionChange(key, parseFloat(e.target.value))}
                                                        className="w-full accent-emerald-500 h-1.5 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                                                    />
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            )}

                            {/* Toggles */}
                            <div className="space-y-3 pt-2">
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 border-b border-white/5 pb-2">Estado</h3>
                                <label className="flex items-center justify-between cursor-pointer group p-3 bg-white/5 rounded-xl transition-all hover:bg-white/10 border border-white/5">
                                    <span className="text-gray-300 text-sm font-medium">Visitados por mí</span>
                                    <div className={`w-11 h-6 rounded-full relative transition-colors ${filters.visited ? 'bg-indigo-600' : 'bg-gray-700 group-hover:bg-gray-600'}`}>
                                        <input type="checkbox" className="hidden" checked={filters.visited} onChange={(e) => setFilters(prev => ({ ...prev, visited: e.target.checked }))} />
                                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform shadow-sm ${filters.visited ? 'translate-x-6' : 'translate-x-1'}`}></div>
                                    </div>
                                </label>
                                <label className="flex items-center justify-between cursor-pointer group p-3 bg-white/5 rounded-xl transition-all hover:bg-white/10 border border-white/5">
                                    <span className="text-gray-300 text-sm font-medium">Con fotos</span>
                                    <div className={`w-11 h-6 rounded-full relative transition-colors ${filters.hasPhoto ? 'bg-indigo-600' : 'bg-gray-700 group-hover:bg-gray-600'}`}>
                                        <input type="checkbox" className="hidden" checked={filters.hasPhoto} onChange={(e) => setFilters(prev => ({ ...prev, hasPhoto: e.target.checked }))} />
                                        <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform shadow-sm ${filters.hasPhoto ? 'translate-x-6' : 'translate-x-1'}`}></div>
                                    </div>
                                </label>
                            </div>
                        </>
                    ) : (
                        <div className="space-y-3">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-2 flex items-center gap-2">
                                <ArrowUpDown className="w-3 h-3" /> Ordenar Por
                            </h3>
                            {[
                                { id: 'rating', label: 'Mejor Valorados', icon: <Star className="w-4 h-4" /> },
                                { id: 'newest', label: 'Más Recientes', icon: <Check className="w-4 h-4" /> },
                                { id: 'oldest', label: 'Más Antiguos', icon: <Check className="w-4 h-4" /> },
                                { id: 'count', label: 'Más Reseñados', icon: <Check className="w-4 h-4" /> }
                            ].map(option => (
                                <button
                                    key={option.id}
                                    onClick={() => setSortMode(option.id as any)}
                                    className={`w-full p-4 rounded-xl border text-left text-sm font-bold transition-all flex items-center justify-between group
                                        ${sortMode === option.id ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'bg-[#0b1021] border-white/10 text-gray-400 hover:border-white/30 hover:text-white hover:bg-white/5'}`}
                                >
                                    <span className="flex items-center gap-3">
                                        {/* Icon could be dynamic based on option if desired */}
                                        {option.label}
                                    </span>
                                    {sortMode === option.id && <div className="w-2.5 h-2.5 rounded-full bg-white shadow-glow"></div>}
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Spacer for bottom actions */}
                    <div className="h-4"></div>
                </div>

                {/* Footer Actions - Fixed Bottom */}
                <div className="border-t border-white/10 bg-[#0b1021] p-4 flex items-center justify-between gap-4 flex-shrink-0 z-10 safe-area-bottom">
                    <button
                        onClick={clearFilters}
                        className="px-4 py-3 rounded-xl hover:bg-white/5 text-gray-400 hover:text-white transition-colors text-sm font-bold flex items-center gap-2"
                    >
                        <Trash2 className="w-4 h-4" />
                        <span className="hidden sm:inline">Limpiar</span>
                        <span className="sm:hidden">Reset</span>
                    </button>

                    <button
                        onClick={onClose}
                        className="flex-1 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl shadow-lg shadow-indigo-500/25 transition-all active:scale-95 text-center"
                    >
                        Ver Resultados
                    </button>
                </div>

            </div>
        </div>
    );
};

