import React, { useEffect, useState } from 'react';
import { X, ChevronLeft, ChevronRight, ZoomIn, ZoomOut } from 'lucide-react';
import { createPortal } from 'react-dom';

interface LightboxProps {
    isOpen: boolean;
    onClose: () => void;
    images: string[];
    initialIndex?: number;
}

export const Lightbox: React.FC<LightboxProps> = ({ isOpen, onClose, images, initialIndex = 0 }) => {
    const [currentIndex, setCurrentIndex] = useState(initialIndex);
    const [scale, setScale] = useState(1);
    const [isZoomed, setIsZoomed] = useState(false);

    // Sync index if initial changes (e.g. reopening)
    useEffect(() => {
        if (isOpen) {
            setCurrentIndex(initialIndex);
            setScale(1);
            setIsZoomed(false);
        }
    }, [isOpen, initialIndex]);

    // Keyboard Navigation
    useEffect(() => {
        if (!isOpen) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
            if (e.key === 'ArrowLeft') handlePrev();
            if (e.key === 'ArrowRight') handleNext();
        };

        window.addEventListener('keydown', handleKeyDown);
        // Lock body scroll
        document.body.style.overflow = 'hidden';

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, currentIndex]);

    const handlePrev = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex(prev => (prev === 0 ? images.length - 1 : prev - 1));
        resetZoom();
    };

    const handleNext = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex(prev => (prev === images.length - 1 ? 0 : prev + 1));
        resetZoom();
    };

    const resetZoom = () => {
        setScale(1);
        setIsZoomed(false);
    };

    const toggleZoom = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (isZoomed) {
            setScale(1);
            setIsZoomed(false);
        } else {
            setScale(2);
            setIsZoomed(true);
        }
    };

    if (!isOpen) return null;

    return createPortal(
        <div
            className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-md flex items-center justify-center animate-fade-in"
            onClick={onClose}
        >
            {/* Toolbar */}
            <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-center z-50 bg-gradient-to-b from-black/80 to-transparent">
                <span className="text-white/80 text-sm font-mono">
                    {currentIndex + 1} / {images.length}
                </span>
                <div className="flex items-center gap-4">
                    <button
                        onClick={toggleZoom}
                        className="p-2 hover:bg-white/10 rounded-full text-white/80 hover:text-white transition-colors"
                    >
                        {isZoomed ? <ZoomOut className="w-5 h-5" /> : <ZoomIn className="w-5 h-5" />}
                    </button>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-white/10 rounded-full text-white/80 hover:text-white transition-colors"
                    >
                        <X className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Navigation Buttons (Desktop) */}
            <button
                onClick={handlePrev}
                className="absolute left-4 z-50 p-3 bg-black/50 hover:bg-white/10 rounded-full text-white/80 hover:text-white transition-all hidden sm:flex backdrop-blur-sm border border-white/5"
            >
                <ChevronLeft className="w-8 h-8" />
            </button>

            <button
                onClick={handleNext}
                className="absolute right-4 z-50 p-3 bg-black/50 hover:bg-white/10 rounded-full text-white/80 hover:text-white transition-all hidden sm:flex backdrop-blur-sm border border-white/5"
            >
                <ChevronRight className="w-8 h-8" />
            </button>

            {/* Main Image Container */}
            <div
                className="relative w-full h-full flex items-center justify-center p-4 sm:p-12 overflow-hidden"
            >
                <img
                    key={currentIndex} // Force re-render for animation
                    src={images[currentIndex]}
                    alt={`Gallery ${currentIndex}`}
                    className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-300 ease-out select-none"
                    style={{
                        transform: `scale(${scale})`,
                        cursor: isZoomed ? 'zoom-out' : 'zoom-in'
                    }}
                    onClick={toggleZoom}
                    draggable={false}
                />
            </div>

            {/* Mobile Thumb Strip (Optional - kept simple for now) */}
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 overflow-x-auto max-w-[80vw] pb-2 scrollbar-hide z-50">
                {images.map((img, idx) => (
                    <button
                        key={idx}
                        onClick={(e) => { e.stopPropagation(); setCurrentIndex(idx); resetZoom(); }}
                        className={`w-10 h-10 shrink-0 rounded-lg overflow-hidden border-2 transition-all ${idx === currentIndex ? 'border-indigo-500 opacity-100 scale-110' : 'border-transparent opacity-40 hover:opacity-80'
                            }`}
                    >
                        <img src={img} alt="" className="w-full h-full object-cover" />
                    </button>
                ))}
            </div>
        </div>,
        document.body
    );
};

import React from 'react';
import { Link } from 'react-router-dom';

import { MapPin, ChevronRight, Users } from 'lucide-react';

interface ListItemCardProps {
    item: {
        id: string; // Group ID (usually placeId or itemId)
        name: string;
        placeId?: string;
        placeName?: string;
        placeCity?: string;
        placeAddress?: string;
        photoUrl?: string; // Best photo from reviews
        avgRating: number;
        reviewCount: number;
        criteriaAverages?: Record<string, number>;
        criteriaDefinition?: Record<string, any>;
        authorName?: string;
        authorPhoto?: string;
        listName?: string; // For items (to show which list they belong to)
        followersCount?: number;
        itemCount?: number;
        listId?: string;
    };
    rank?: number;
    isGrid?: boolean;
    groupingMode?: 'place' | 'dish' | 'list';
    listId?: string; // Outer phrasing, maybe redundant with item.listId but keeping for compat
}

export const ListItemCard: React.FC<ListItemCardProps> = ({ item, rank, isGrid, groupingMode = 'place', listId }) => {

    // Helper for score colors (Legacy logic)
    const getScoreColor = (score: number) => {
        if (score >= 9) return 'bg-emerald-500 text-emerald-50';
        if (score >= 7) return 'bg-indigo-500 text-indigo-50';
        if (score >= 5) return 'bg-amber-500 text-amber-50';
        return 'bg-red-500 text-red-50';
    };

    const getBarColor = (score: number) => {
        if (score >= 9) return 'bg-emerald-500';
        if (score >= 7) return 'bg-indigo-500';
        if (score >= 5) return 'bg-amber-500';
        return 'bg-red-500';
    };

    // New format for stats (similar to Carousels)
    const renderStats = () => {
        if (groupingMode === 'place' || groupingMode === 'dish') {
            // For Places/Items, usually we show review count (already there)
            return null;
        }
        // For Lists
        return (
            <div className="flex items-center gap-3 mt-2 text-xs text-gray-400 font-medium">
                {item.itemCount !== undefined && (
                    <span className="flex items-center gap-1">
                        <MapPin className="w-3 h-3" /> {item.itemCount} lugares
                    </span>
                )}
                {item.followersCount !== undefined && (
                    <span className="flex items-center gap-1">
                        <Users className="w-3 h-3" /> {item.followersCount} seg.
                    </span>
                )}
            </div>
        );
    };

    // --- Render Content ---
    return (
        <article className={`group relative bg-[var(--card-bg)] transition-all overflow-hidden shadow-sm hover:shadow-xl 
            ${isGrid
                ? 'flex flex-row md:flex-col h-28 sm:h-32 md:h-64 rounded-xl' // Grid mode: Fixed height horizontal on mobile, Vertical on desktop
                : 'flex flex-row rounded-xl hover:bg-white/5 border border-transparent hover:border-white/10'}`}>

            {/* --- GRID MODE (Rich Background Card - DESKTOP ONLY / Horizontal Mobile) --- */}
            {isGrid ? (
                <>
                    {/* Desktop View (Background Image Card) - Hidden on Mobile */}
                    <div className="hidden md:block absolute inset-0 bg-gray-900">
                        {item.photoUrl ? (
                            <img src={item.photoUrl} alt={item.name} className="w-full h-full object-cover opacity-80 group-hover:opacity-60 group-hover:scale-105 transition-all duration-500" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center bg-gray-800 text-gray-700">
                                <MapPin className="w-12 h-12 opacity-20" />
                            </div>
                        )}
                        <div className="absolute inset-0 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-transparent" />
                    </div>

                    {/* Mobile View (Thumbnail Left) - Visible Only on Mobile */}
                    <div className="md:hidden w-28 h-28 shrink-0 relative bg-gray-800">
                        {item.photoUrl ? (
                            <img src={item.photoUrl} alt={item.name} className="w-full h-full object-cover" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center bg-gray-800 text-gray-700">
                                <MapPin className="w-8 h-8 opacity-20" />
                            </div>
                        )}
                        {/* Rank on Mobile Image */}
                        {rank && (
                            <div className="absolute top-0 left-0 bg-black/60 text-white text-[10px] font-bold px-2 py-1 rounded-br-lg">
                                #{rank}
                            </div>
                        )}
                    </div>

                    {/* Content Container */}
                    <div className="relative flex-1 p-3 md:p-4 flex flex-col justify-between md:absolute md:inset-0 md:justify-end z-20 min-w-0">

                        {/* Tags - Top Left (Desktop) / Inline Top (Mobile) */}
                        <div className="flex flex-wrap gap-2 mb-1 md:mb-3 items-center md:absolute md:top-3 md:left-3 md:z-30 md:max-w-[90%] pointer-events-none">

                            {/* List Badge */}
                            {item.listName && (
                                <div className="pointer-events-auto shadow-sm md:shadow-lg">
                                    {item.listId ? (
                                        <Link
                                            to={`/list/${item.listId}`}
                                            onClick={(e) => e.stopPropagation()}
                                            className="inline-flex items-center px-2 py-1 rounded-lg text-[10px] font-bold bg-black/60 backdrop-blur-md text-indigo-300 border border-white/10 truncate hover:text-indigo-200 transition-colors shadow-sm"
                                        >
                                            {item.listName}
                                        </Link>
                                    ) : (
                                        <span className="inline-flex items-center px-2 py-1 rounded-lg text-[10px] font-bold bg-black/60 backdrop-blur-md text-indigo-300 border border-white/10 truncate shadow-sm">
                                            {item.listName}
                                        </span>
                                    )}
                                </div>
                            )}

                            {/* Place Badge */}
                            {(item.placeName || item.placeCity || item.placeAddress) && (
                                <div className="pointer-events-auto">
                                    <span className="inline-flex items-center px-2 py-1 rounded-lg text-[10px] font-bold bg-black/60 backdrop-blur-md text-white border border-white/10 truncate shadow-sm">
                                        <MapPin className="w-3 h-3 mr-1 text-emerald-400" />
                                        {item.placeName || item.placeCity || item.placeAddress?.split(',')[0]}
                                    </span>
                                </div>
                            )}
                        </div>


                        {/* Main Content Info */}
                        <div className="pointer-events-auto md:mt-auto">
                            <h3 className="font-display font-bold text-sm sm:text-base md:text-xl text-[var(--text-primary)] md:text-white leading-tight mb-1 group-hover:text-indigo-500 md:group-hover:text-indigo-300 transition-colors line-clamp-2 md:drop-shadow-md">
                                {item.placeId ? (
                                    groupingMode === 'dish' ? (
                                        <Link
                                            to={`/group/${item.placeId}/${encodeURIComponent(item.name)}${listId ? `?listId=${listId}` : ''}`}
                                            className="hover:underline inset-0"
                                        >
                                            {item.name}
                                        </Link>
                                    ) : (
                                        <Link to={`/place/${item.placeId}`} className="hover:underline inset-0">{item.name}</Link>
                                    )
                                ) : (
                                    <Link to={`/list/${item.id}`} className="hover:underline inset-0">{item.name}</Link>
                                )}
                            </h3>

                            {/* Author info (List only) */}
                            {item.authorName && !item.placeName && (
                                <div className="flex items-center gap-1.5 opacity-90 mb-1">
                                    {item.authorPhoto && <img src={item.authorPhoto} className="w-4 h-4 rounded-full border border-gray-200 md:border-white/20" alt="" />}
                                    <span className="text-gray-500 md:text-gray-300 text-xs">por <span className="text-gray-700 md:text-white font-medium">{item.authorName}</span></span>
                                </div>
                            )}

                            {/* Stats Row */}
                            <div className="flex items-center justify-between border-t border-gray-200 dark:border-gray-800 md:border-white/10 pt-2 mt-2">
                                <div className="flex items-center gap-3 text-xs text-gray-500 md:text-gray-300 font-medium">
                                    {(item.reviewCount > 0 || (groupingMode !== 'place' && groupingMode !== 'dish')) && (
                                        <span className="flex items-center gap-1">
                                            <Users className="w-3 h-3 text-indigo-500 md:text-indigo-400" />
                                            {item.followersCount !== undefined ? item.followersCount : item.reviewCount}
                                        </span>
                                    )}
                                    {item.itemCount !== undefined && (
                                        <span className="flex items-center gap-1">
                                            <MapPin className="w-3 h-3 text-indigo-500 md:text-indigo-400" /> {item.itemCount}
                                        </span>
                                    )}
                                </div>
                                {/* Score */}
                                {groupingMode !== 'list' && (
                                    <div className={`flex items-center justify-center w-7 h-7 md:w-8 md:h-8 rounded-lg ${getScoreColor(item.avgRating)} shadow-sm md:shadow-lg font-bold text-white text-xs md:text-sm`}>
                                        {item.avgRating.toFixed(1)}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Desktop Rank Badge (Top Right) */}
                    {rank && (
                        <div className={`hidden md:block absolute top-0 right-0 z-20 px-3 py-1.5 rounded-bl-xl font-bold text-xs shadow-lg backdrop-blur-md
                            ${rank === 1 ? 'bg-yellow-500/80 text-white' :
                                rank === 2 ? 'bg-gray-400/80 text-white' :
                                    rank === 3 ? 'bg-orange-500/80 text-white' :
                                        'bg-black/40 text-white border-l border-b border-white/10'}`}>
                            #{rank}
                        </div>
                    )}
                </>
            ) : (
                /* --- LIST MODE (Horizontal Compact) --- */
                <>
                    {/* Rank Badge (Podium) */}
                    {rank && (
                        <div className={`absolute top-0 left-0 z-20 px-3 py-1.5 rounded-br-xl font-bold text-sm shadow-lg flex items-center justify-center min-w-[36px]
                            ${rank === 1 ? 'bg-yellow-400 text-yellow-950 shadow-yellow-500/20' :
                                rank === 2 ? 'bg-gray-200 text-gray-800 shadow-white/10' :
                                    rank === 3 ? 'bg-orange-400 text-orange-950 shadow-orange-500/20' :
                                        'bg-black/60 backdrop-blur-md text-white border-r border-b border-white/10 text-xs'
                            }`}>
                            <span className={rank <= 3 ? "scale-110 block" : ""}>#{rank}</span>
                        </div>
                    )}

                    {/* Image Section */}
                    <div className="relative shrink-0 bg-gray-800 w-24 h-24 sm:w-32 sm:h-32">
                        {item.photoUrl ? (
                            <img src={item.photoUrl} alt={item.name} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-gray-600 bg-gray-200 dark:bg-gray-800">
                                <MapPin className="w-8 h-8 opacity-50" />
                            </div>
                        )}
                    </div>

                    {/* Content Section */}
                    <div className="flex-1 p-3 flex flex-col justify-between min-w-0">
                        <div className="flex justify-between items-start gap-2">
                            <div className="min-w-0 flex-1">
                                <h3 className="font-display font-bold text-base sm:text-lg text-[var(--text-primary)] leading-tight line-clamp-2 pr-1 group-hover:text-indigo-500 transition-colors">
                                    {item.placeId ? (
                                        groupingMode === 'dish' ? (
                                            <Link
                                                to={`/group/${item.placeId}/${encodeURIComponent(item.name)}${listId ? `?listId=${listId}` : ''}`}
                                                className="hover:underline inset-0"
                                            >
                                                {item.name}
                                            </Link>
                                        ) : (
                                            <Link to={`/place/${item.placeId}`} className="hover:underline inset-0">{item.name}</Link>
                                        )
                                    ) : (
                                        <Link to={`/list/${item.id}`} className="hover:underline inset-0">{item.name}</Link>
                                    )}
                                </h3>

                                {/* Improved Subtext: Place Name + City */}
                                <div className="text-xs text-[var(--text-secondary)] flex flex-wrap gap-1 mt-1 leading-relaxed">
                                    {/* Place Context (Items/Places) */}
                                    {item.placeName && item.placeName !== item.name && (
                                        <span className="flex items-center gap-1 font-medium text-gray-400 truncate max-w-full">
                                            <MapPin className="w-3 h-3 shrink-0" />
                                            <span className="truncate">{item.placeName}</span>
                                        </span>
                                    )}

                                    {(item.placeCity || item.placeAddress) && (
                                        <>
                                            <span className="text-gray-600 hidden sm:inline">•</span>
                                            <span className="text-indigo-400/80 font-medium truncate max-w-full block sm:inline">
                                                {item.placeCity || item.placeAddress}
                                            </span>
                                        </>
                                    )}

                                    {/* List Context Badge (for Items) */}
                                    {item.listName && (
                                        <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-bold bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 truncate max-w-[120px]">
                                            {item.listName}
                                        </span>
                                    )}

                                    {/* Author Context (Lists) */}
                                    {item.authorName && !item.placeName && (
                                        <div className="flex items-center gap-2">
                                            {item.authorPhoto && <img src={item.authorPhoto} className="w-4 h-4 rounded-full" alt="" />}
                                            <span className="text-gray-400">por <span className="text-gray-300 font-medium">{item.authorName}</span></span>
                                        </div>
                                    )}
                                </div>

                                <div className="text-xs text-gray-500 mt-1">
                                    {item.reviewCount > 0 && `${item.reviewCount} ${item.reviewCount === 1 ? 'reseña' : 'reseñas'}`}
                                </div>

                                {/* List Stats */}
                                {renderStats()}
                            </div>

                            {/* Score Box - Visible on Mobile List View now */}
                            <div className={`flex flex-col items-center justify-center w-10 h-10 sm:w-12 sm:h-12 rounded-lg ${getScoreColor(item.avgRating)} shadow-lg shrink-0`}>
                                <span className="font-display font-bold text-base sm:text-lg text-white">{item.avgRating.toFixed(1)}</span>
                            </div>
                        </div>

                        {/* Mini Criteria Bars (Legacy Compact Style) */}
                        {item.criteriaAverages && item.criteriaDefinition && (
                            <div className="mt-2 grid grid-cols-4 gap-x-2 gap-y-0.5 sm:grid-cols-4">
                                {Object.entries(item.criteriaAverages || {}).slice(0, 4).map(([key, score]) => {
                                    const label = item.criteriaDefinition?.[key]?.label || key;
                                    return (
                                        <div key={key} className="flex flex-col">
                                            <div className="flex justify-between items-end text-[9px] text-[var(--text-secondary)] leading-none mb-0.5">
                                                <span className="truncate max-w-[70%] opacity-80">{label}</span>
                                                <span className="font-mono opacity-100 font-bold">{score.toFixed(1)}</span>
                                            </div>
                                            <div className="h-0.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                                                <div
                                                    className={`h-full rounded-full ${getBarColor(score)}`}
                                                    style={{ width: `${score * 10}%` }}
                                                />
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {/* Interactions / CTA */}
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity hidden sm:block">
                        <ChevronRight className="w-5 h-5 text-[var(--text-secondary)]" />
                    </div>
                </>
            )}
        </article>
    );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useAuth } from '../context/AuthContext';
import { db } from '../firebase';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { Search, List as ListIcon, Plus, ChevronDown, Check, Sparkles, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface ListSearchProps {
    onSelect: (listId: string) => void;
    selectedListId: string | null;
    placeName?: string;
    placeTypes?: string[];
    suggestedListIds?: string[];
}

interface EnrichedList {
    id: string;
    name: string;
    parentListId?: string;
    parentListName?: string; // For display
    score: number;
    isSuggested?: boolean;
}

export const ListSearch: React.FC<ListSearchProps> = ({ onSelect, selectedListId, placeName, placeTypes, suggestedListIds }) => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [lists, setLists] = useState<EnrichedList[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [isOpen, setIsOpen] = useState(false);

    const containerRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);

    // Fetch Lists
    useEffect(() => {
        const fetchLists = async () => {
            if (!user) return;
            try {
                // Fetch Owned
                const qOwned = query(collection(db, 'lists'), where('userId', '==', user.uid));
                // Fetch Edited
                const qEdited = query(collection(db, 'lists'), where('editors', 'array-contains', user.uid));

                const [snapOwned, snapEdited] = await Promise.allSettled([
                    getDocs(qOwned),
                    getDocs(qEdited)
                ]);

                const allDocs: any[] = [];
                if (snapOwned.status === 'fulfilled') {
                    snapOwned.value.docs.forEach(d => allDocs.push(d));
                } else {
                    console.error("ListSearch: Error fetching owned lists", snapOwned.reason);
                    if (snapOwned.reason?.code === 'permission-denied') {
                        throw new Error("Permisos insuficientes para ver tus listas.");
                    }
                }

                if (snapEdited.status === 'fulfilled') {
                    snapEdited.value.docs.forEach(d => allDocs.push(d));
                } else {
                    console.warn("ListSearch: Error fetching shared lists", snapEdited.reason);
                    // Don't fail everything if shared lists fail, but maybe log it?
                }

                const uniqueLists = new Map<string, any>();
                allDocs.forEach(d => {
                    if (!uniqueLists.has(d.id)) {
                        const data = d.data();

                        // Strict filter for Archives as requested
                        const nameLower = data.name.toLowerCase();
                        if (nameLower === 'quiero ir' || nameLower === 'ya fui') return;
                        // Filter out archives check.
                        // Relying primarily on 'type' field if it exists.
                        if (data.type === 'archive') return;

                        uniqueLists.set(d.id, { id: d.id, ...data });
                    }
                });

                // Calculate Initial Context Scores (Suggestions)
                const keywords = new Set<string>();
                if (placeTypes) placeTypes.forEach(t => t.split('_').forEach(w => keywords.add(w.toLowerCase())));
                if (placeName) placeName.split(' ').forEach(w => keywords.add(w.toLowerCase()));

                const processed: EnrichedList[] = Array.from(uniqueLists.values()).map(data => {
                    let score = 0;
                    const listNameLower = data.name.toLowerCase();

                    // Boost if suggested explicitly
                    let isSuggested = false;
                    if (suggestedListIds && suggestedListIds.includes(data.id)) {
                        score += 500;
                        isSuggested = true;
                    }

                    keywords.forEach(kw => {
                        if (kw.length > 2 && listNameLower.includes(kw)) {
                            score += 10;
                        }
                    });

                    return {
                        id: data.id,
                        name: data.name,
                        parentListId: data.parentListId,
                        parentListName: data.parentListId ? uniqueLists.get(data.parentListId)?.name : undefined,
                        score,
                        isSuggested
                    };
                });

                // Initial Sort: Score DESC, Name ASC
                processed.sort((a, b) => {
                    if (b.score !== a.score) return b.score - a.score;
                    return a.name.localeCompare(b.name);
                });

                setLists(processed);

                // Auto-select if only 1 list and nothing selected
                if (!selectedListId && processed.length === 1) {
                    onSelect(processed[0].id);
                }

            } catch (e: any) {
                console.error("Error fetching lists", e);
                setError(e.message || "Error cargando listas");
            } finally {
                setLoading(false);
            }
        };
        fetchLists();
    }, [user, placeName, placeTypes, suggestedListIds]);

    // Handle Open/Close & Focus
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
                setSearchTerm(''); // Reset search on close
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        if (isOpen && searchInputRef.current) {
            searchInputRef.current.focus();
        }
    }, [isOpen]);

    // Selected Display Data
    const selectedList = lists.find(l => l.id === selectedListId);

    // Robust Searching / Filtering Logic
    const filteredLists = useMemo(() => {
        if (!searchTerm.trim()) return lists;

        const lowerTerm = searchTerm.toLowerCase();
        const terms = lowerTerm.split(' ').filter(t => t.length > 0);

        // Score based on search match
        const searchScored = lists.map(list => {
            let searchScore = 0;
            const nameLower = list.name.toLowerCase();

            // Check each search term
            terms.forEach(term => {
                if (nameLower === term) searchScore += 100; // Exact match
                else if (nameLower.startsWith(term)) searchScore += 50; // Starts with
                else if (nameLower.includes(term)) searchScore += 20; // Contains
                else {
                    // Fuzzy check? (Simple typo tolerance for now omitted to keep it fast, but partial match is usually enough)
                }
            });

            if (list.parentListName?.toLowerCase().includes(lowerTerm)) searchScore += 5; // Match parent name

            return { ...list, searchScore };
        });

        const matches = searchScored.filter(l => l.searchScore > 0);

        // Sort by search relevance
        matches.sort((a, b) => b.searchScore - a.searchScore);

        return matches;
    }, [lists, searchTerm]);

    const suggestions = filteredLists.filter(l => l.score > 0 && !searchTerm); // Show context suggestions only when NOT searching manually
    const others = filteredLists.filter(l => !suggestions.includes(l));

    return (
        <div className="relative font-sans" ref={containerRef}>
            {/* Trigger Button */}
            <button
                type="button"
                onClick={() => setIsOpen(!isOpen)}
                className={`w-full bg-[#1e2538] border rounded-xl p-3 flex items-center justify-between transition-all group ${isOpen ? 'border-indigo-500 ring-1 ring-indigo-500/50' : 'border-white/10 hover:border-white/20'
                    }`}
            >
                <div className="flex items-center gap-3 flex-1 min-w-0">
                    <div className={`p-2 rounded-lg transition-colors ${selectedListId
                        ? 'bg-indigo-500/10 text-indigo-400'
                        : 'bg-gray-700/50 text-gray-500 group-hover:text-gray-400'
                        }`}>
                        <ListIcon className="w-5 h-5" />
                    </div>

                    <div className="flex flex-col items-start truncate">
                        <span className={`font-bold truncate w-full text-left ${selectedList ? 'text-white' : 'text-gray-400'}`}>
                            {selectedList ? selectedList.name : 'Seleccionar Lista...'}
                        </span>
                        {selectedList?.parentListName && (
                            <span className="text-[10px] text-gray-500 flex items-center gap-1">
                                <div className="w-1 h-1 rounded-full bg-gray-600"></div>
                                en {selectedList.parentListName}
                            </span>
                        )}
                    </div>
                </div>
                <ChevronDown className={`w-4 h-4 text-gray-500 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </button>

            {/* Dropdown Menu */}
            {isOpen && (
                <div className="absolute top-full left-0 right-0 mt-2 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl z-[50] max-h-[300px] flex flex-col animate-in fade-in zoom-in-95 duration-100 overflow-hidden">

                    {/* Search Header */}
                    <div className="p-2 border-b border-white/5 bg-[#0b1021]/50 sticky top-0 z-10">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                            <input
                                ref={searchInputRef}
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder="Buscar lista..."
                                className="w-full bg-[#1e2538] border border-white/10 rounded-lg pl-9 pr-8 py-2 text-sm text-white focus:outline-none focus:border-indigo-500 transition-colors placeholder:text-gray-500"
                                onClick={(e) => e.stopPropagation()}
                            />
                            {searchTerm && (
                                <button
                                    onClick={(e) => { e.stopPropagation(); setSearchTerm(''); searchInputRef.current?.focus(); }}
                                    className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-gray-400 hover:text-white"
                                >
                                    <X className="w-3 h-3" />
                                </button>
                            )}
                        </div>
                    </div>

                    {/* List Content */}
                    <div className="overflow-y-auto custom-scrollbar flex-1 p-1">
                        {loading ? (
                            <div className="p-6 flex justify-center">
                                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-indigo-500"></div>
                            </div>
                        ) : error ? (
                            <div className="p-4 text-center bg-red-500/10 m-2 rounded-lg">
                                <p className="text-red-400 text-xs font-bold mb-1">Error de conexión</p>
                                <p className="text-red-300/80 text-[10px] break-words">{error}</p>
                            </div>
                        ) : filteredLists.length === 0 ? (
                            <div className="p-6 text-center">
                                <p className="text-gray-500 text-sm mb-3">No se encontraron listas.</p>
                                <button
                                    onClick={() => navigate('/create')}
                                    className="px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600 hover:text-white rounded-lg text-xs font-bold transition-all"
                                >
                                    Crear "{searchTerm || 'Nueva Lista'}"
                                </button>
                            </div>
                        ) : (
                            <div className="space-y-0.5">
                                {/* Suggestions */}
                                {suggestions.length > 0 && (
                                    <div className="mb-2">
                                        <div className="px-3 py-1.5 text-[10px] font-bold uppercase text-indigo-400 tracking-wider flex items-center gap-1 bg-indigo-500/5 mx-1 rounded">
                                            <Sparkles className="w-3 h-3" />
                                            Sugeridas
                                        </div>
                                        {suggestions.map(list => (
                                            <ListItem
                                                key={list.id}
                                                list={list}
                                                isSelected={selectedListId === list.id}
                                                onSelect={(id) => { onSelect(id); setIsOpen(false); }}
                                            />
                                        ))}
                                        <div className="h-px bg-white/5 my-2 mx-2" />
                                    </div>
                                )}

                                {/* Others / Search Results */}
                                {(suggestions.length > 0 ? others : filteredLists).map(list => (
                                    <ListItem
                                        key={list.id}
                                        list={list}
                                        isSelected={selectedListId === list.id}
                                        onSelect={(id) => { onSelect(id); setIsOpen(false); }}
                                    />
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Fixed Footer for Creation */}
                    {!searchTerm && !error && (
                        <div className="p-2 border-t border-white/5 bg-[#0b1021]/30">
                            <button
                                onClick={() => navigate('/create')}
                                className="w-full py-2 flex items-center justify-center gap-2 text-xs font-bold text-gray-400 hover:text-white hover:bg-white/5 rounded-lg transition-colors"
                            >
                                <Plus className="w-3 h-3" />
                                Crear Nueva Lista
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

const ListItem = ({ list, isSelected, onSelect }: { list: EnrichedList, isSelected: boolean, onSelect: (id: string) => void }) => (
    <button
        type="button"
        onClick={() => onSelect(list.id)}
        className={`w-full text-left px-3 py-2.5 rounded-lg flex items-center justify-between group transition-colors ${isSelected ? 'bg-indigo-500/20 text-indigo-200' : 'hover:bg-white/5 text-gray-300'
            }`}
    >
