);

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { db } from '../firebase';
import { collection, query, where, getDocs, doc, getDoc } from 'firebase/firestore';
import { X, List as ListIcon, Search, Plus } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

export const ListSelector = ({ onSelect, onCancel, preselectedId }: { onSelect: (listId: string) => void, onCancel: () => void, preselectedId?: string | null }) => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [lists, setLists] = useState<{ id: string; name: string; parentListId?: string }[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        const fetchLists = async () => {
            if (!user) return;
            try {
                // 1. Fetch Owned Lists
                const qOwned = query(
                    collection(db, 'lists'),
                    where('ownerId', '==', user.uid)
                );

                // 2. Fetch Edited Lists (handle missing index gracefully)
                const qEdited = query(
                    collection(db, 'lists'),
                    where('editors', 'array-contains', user.uid)
                );

                const [snapOwnedResult, snapEditedResult] = await Promise.allSettled([
                    getDocs(qOwned),
                    getDocs(qEdited)
                ]);

                const allDocs: any[] = [];

                if (snapOwnedResult.status === 'fulfilled') {
                    snapOwnedResult.value.docs.forEach(d => allDocs.push(d));
                }

                if (snapEditedResult.status === 'fulfilled') {
                    snapEditedResult.value.docs.forEach(d => allDocs.push(d));
                }

                const uniqueListsMap = new Map();

                allDocs.forEach(d => {
                    const data = d.data();
                    if (!uniqueListsMap.has(d.id)) {
                        uniqueListsMap.set(d.id, {
                            id: d.id,
                            name: data.name,
                            parentListId: data.parentListId
                        });
                    }
                });

                const finalLists = Array.from(uniqueListsMap.values());
                setLists(finalLists as any);

                // Auto-select logic:
                // Only auto-select if:
                // 1. We have NO preselectedId (user hasn't chosen one yet) AND there is exactly ONE list available.
                // 2. We DO NOT auto-select if preselectedId matches, because that prevents changing the selection (modal opens and closes instantly).
                if (!preselectedId && finalLists.length === 1) {
                    onSelect(finalLists[0].id);
                }

            } catch (e) {
                console.error("Error fetching user lists", e);
            } finally {
                setLoading(false);
            }
        };
        fetchLists();
    }, [user]); // Removed preselectedId from dependency to prevent re-runs on prop change if parent updates it

    const filteredLists = lists.filter(l =>
        l.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (loading) return (
        <div className="fixed inset-0 z-[105] flex items-center justify-center bg-black/80 backdrop-blur-sm">
            <div className="flex flex-col items-center gap-2">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
                <div className="text-white text-xs font-medium">Cargando listas...</div>
            </div>
        </div>
    );

    // If fetching finished and we auto-selected (handled in useEffect), we might render briefly.
    // Ideally we render unless filteredLists is empty AND we aren't searching.

    return (
        <div className="fixed inset-0 z-[105] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in" onClick={(e) => {
            if (e.target === e.currentTarget) onCancel();
        }}>
            <div className="bg-[#151b2e] rounded-2xl w-full max-w-md border border-white/10 shadow-2xl flex flex-col max-h-[70vh] animate-in fade-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#0b1021]/50 sticky top-0 z-10">
                    <h3 className="font-bold text-white text-lg">Seleccionar Lista</h3>
                    <button onClick={onCancel} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                {/* Search */}
                <div className="p-4 border-b border-white/5 bg-[#151b2e]">
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                        <input
                            type="text"
                            placeholder="Buscar lista..."
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            autoFocus
                            className="w-full bg-[#0b1021] border border-white/10 rounded-xl pl-9 pr-4 py-3 text-sm text-white focus:outline-none focus:border-indigo-500 transition-colors placeholder:text-gray-600"
                        />
                    </div>
                </div>

                {/* List */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
                    {filteredLists.length > 0 ? (
                        <div className="space-y-1">
                            {filteredLists.map(list => {
                                const isSelected = list.id === preselectedId;
                                return (
                                    <button
                                        key={list.id}
                                        onClick={() => onSelect(list.id)}
                                        className={`w-full text-left p-3 rounded-xl transition-all flex items-center gap-3 group ${isSelected
                                                ? 'bg-indigo-500/20 ring-1 ring-indigo-500/50'
                                                : 'hover:bg-white/5'
                                            }`}
                                    >
                                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center transition-colors ${isSelected ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/20' : 'bg-[#1e2538] text-gray-400 group-hover:text-white group-hover:bg-[#252b3d]'
                                            }`}>
                                            <ListIcon className="w-5 h-5" />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className={`font-bold truncate ${isSelected ? 'text-indigo-200' : 'text-gray-200'}`}>
                                                {list.name}
                                            </div>
                                            {list.parentListId && (
                                                <div className="text-xs text-gray-500 truncate flex items-center gap-1">
                                                    <div className="w-1.5 h-1.5 rounded-full bg-gray-600"></div>
                                                    Sublista
                                                </div>
                                            )}
                                        </div>
                                        {isSelected && <div className="w-2 h-2 rounded-full bg-indigo-400 mr-2"></div>}
                                    </button>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center p-8 text-center opacity-0 animate-in fade-in slide-in-from-bottom-2 duration-500 delay-100 fill-mode-forwards">
                            <div className="w-16 h-16 bg-[#1e2538] rounded-full flex items-center justify-center mb-4">
                                <ListIcon className="w-8 h-8 text-gray-600" />
                            </div>
                            <p className="text-gray-400 text-sm mb-6 max-w-[200px]">
                                {searchTerm ? 'No se encontraron listas con ese nombre.' : 'No tienes ninguna lista creada todavía.'}
                            </p>
                            {!searchTerm && (
                                <button
                                    onClick={() => {
                                        // Use navigation instead of Link to handle potential logic/warnings if needed
                                        onCancel(); // Close selector first
                                        navigate('/create');
                                    }}
                                    className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl transition-all shadow-lg shadow-indigo-500/20 flex items-center gap-2 hover:scale-105 active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                    Crear Nueva Lista
                                </button>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap, Circle } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { createLegacyMarkerIcon } from '../utils/mapUtils';
import { useLocation } from '../hooks/useLocation';
import { Locate } from 'lucide-react';
import L from 'leaflet';
import { Link } from 'react-router-dom';

// Component to handle User Location Marker & Range Circle
const UserLocationFeatures = ({ range }: { range: number | null }) => {
    const { location } = useLocation();

    if (!location) return null;

    // Custom Blue Dot Icon using DivIcon
    const blueDotIcon = L.divIcon({
        className: 'user-location-marker',
        html: `<div class="w-4 h-4 bg-blue-500 rounded-full border-2 border-white shadow-lg relative">
                 <div class="absolute -inset-2 bg-blue-500/30 rounded-full animate-ping"></div>
               </div>`,
        iconSize: [16, 16],
        iconAnchor: [8, 8]
    });

    return (
        <>
            <Marker
                position={[location.latitude, location.longitude]}
                icon={blueDotIcon}
                zIndexOffset={1000} // Bring to front
            >
                <Popup>
                    <div className="text-sm font-bold text-gray-900">Tu ubicación</div>
                </Popup>
            </Marker>

            {range !== null && (
                <Circle
                    center={[location.latitude, location.longitude]}
                    radius={range * 1000} // km to meters
                    pathOptions={{
                        color: '#6366f1', // Indigo-500
                        fillColor: '#6366f1',
                        fillOpacity: 0.1,
                        weight: 1,
                        dashArray: '5, 10'
                    }}
                />
            )}
        </>
    );
};

// Component to handle "Center on Me" button - Custom Overlay
const CustomLocateControl = () => {
    const map = useMap();
    const { location, requestLocation, loading } = useLocation();

    const handleLocate = (e: React.MouseEvent) => {
        e.stopPropagation();
        requestLocation();
        if (location) {
            map.flyTo([location.latitude, location.longitude], 14, {
                animate: true,
                duration: 1.5
            });
        }
    };

    return (
        <div className="absolute bottom-6 right-6 z-[1000]">
            <button
                onClick={handleLocate}
                className="bg-[#151b2e] text-white hover:bg-indigo-600 p-3 rounded-full shadow-lg cursor-pointer flex items-center justify-center transition-all border border-white/20 hover:scale-110 active:scale-95"
                title="Centrar en mi ubicación"
            >
                <Locate className={`w-5 h-5 ${loading ? 'animate-spin' : ''}`} />
            </button>
        </div>
    );
};

// Add placeId to MapItem interface (Line 85)
export interface MapItem {
    id: string;
    placeId?: string; // Added field
    lat?: number;
    lng?: number;
    name: string;
    photoUrl?: string;
    rating?: number;
    reviewsCount?: number;
    items?: {
        name: string;
        score: number;
    }[];
}

interface MapViewProps {
    items: any[];
    mode?: 'global' | 'list';
    center?: [number, number];
    range?: number | null;
}

function MapUpdater({ center, items, range, location }: { center: [number, number], items: any[], range: number | null, location: any }) {
    const map = useMap();

    useEffect(() => {
        if (range !== null && location) {
            let zoom = 12;
            if (range <= 1) zoom = 15;
            else if (range <= 5) zoom = 13;
            else if (range <= 10) zoom = 12;
            else zoom = 9;

            map.flyTo([location.latitude, location.longitude], zoom, { duration: 1.5 });
        } else if (items.length > 0) {
            if (items.length === 1 && items[0].lat && items[0].lng) {
                map.flyTo([items[0].lat, items[0].lng], 14, { duration: 1.5 });
            } else {
                const bounds = L.latLngBounds(items.map(i => [i.lat, i.lng] as [number, number]));
                if (bounds.isValid()) {
                    map.fitBounds(bounds, { padding: [50, 50], maxZoom: 15, animate: true, duration: 1.5 });
                }
            }
        } else {
            map.flyTo(center, 10, { duration: 1.5 });
        }
    }, [range, items, center, location, map]);

    return null;
}

export const MapView: React.FC<MapViewProps> = ({ items, mode = 'global', center = [40.416, -3.703], range = null }) => {

    const { location } = useLocation();

    // Normalize Items based on input to match Interface
    const validItems: MapItem[] = items
        .filter(item => (item.lat || item.latitude) && (item.lng || item.longitude))
        .map(item => ({
            id: item.id || item.placeId,
            placeId: item.placeId, // Preserve placeId
            lat: item.lat || item.latitude,
            lng: item.lng || item.longitude,
            name: item.name || item.placeName || 'Lugar desconocido',
            photoUrl: item.photoUrl || item.placeMainImage || item.mainImageUrl,
            rating: item.rating || item.placeAverageRating || item.overallRating || item.avgRating || 0,
            reviewsCount: item.reviewsCount || item.reviewCount || item.count || 0,
            items: item.items
        }));

    // Determine Initial Map Center (Fallback)
    const initialCenter = location
        ? [location.latitude, location.longitude] as [number, number]
        : (validItems.length > 0 && validItems[0].lat && validItems[0].lng
            ? [validItems[0].lat!, validItems[0].lng!] as [number, number]
            : center);

    return (
        <div className="h-full w-full relative z-0">
            <MapContainer center={initialCenter} zoom={12} scrollWheelZoom={false} className="h-full w-full bg-[#0b1021]">
                <TileLayer
                    attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
                    url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
                />

                <MapUpdater center={center} items={validItems} range={range} location={location} />

                {/* User Location Features */}
                <UserLocationFeatures range={range} />
                <CustomLocateControl />

                {validItems.map((item) => (
                    <Marker
                        key={item.id}
                        position={[item.lat!, item.lng!]}
                        icon={createLegacyMarkerIcon(item.rating || 0)}
                    >
                        <Popup className="legacy-popup" closeButton={false} maxWidth={280} minWidth={260}>
                            <div className="bg-[#0b1021]/95 backdrop-blur-xl rounded-2xl overflow-hidden shadow-2xl border border-white/10 flex flex-col w-[260px]">
                                {/* Header Image */}
