                                    {/* Rating Badge */}
                                    <div className="absolute top-3 right-3 bg-black/50 backdrop-blur-md border border-white/10 px-2 py-1 rounded-lg flex items-center gap-1">
                                        <span className="text-yellow-400 text-xs">★</span>
