                                                    <span className={`font-bold ${subItem.score >= 8 ? 'text-emerald-400' : 'text-indigo-400'}`}>
                                                        {subItem.score.toFixed(1)}
                                                    </span>
                                                </div>
                                            ))}
                                            {item.items.length > 3 && (
                                                <div className="text-center text-[10px] text-gray-500 mt-1">
                                                    +{item.items.length - 3} más
                                                </div>
