import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Search, Archive, MessageSquare, User, Moon, Sun, Menu, X, Plus, Compass, Users, Bell } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useAppConfig } from '../context/AppConfigContext';
import { db } from '../firebase';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { NotificationModal } from './NotificationModal';
import { NotificationHistoryModal } from './NotificationHistoryModal';

export const Navbar: React.FC = () => {
    const { user } = useAuth();
    const config = useAppConfig();
    const location = useLocation();
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const [showNotifications, setShowNotifications] = useState(false);
    const [showHistory, setShowHistory] = useState(false); // New state lifted
    const [unreadCount, setUnreadCount] = useState(0);

    useEffect(() => {
        if (!user) return;
        const q = query(
            collection(db, 'users', user.uid, 'notifications'),
            where('read', '==', false)
        );
        const unsubscribe = onSnapshot(q, (snap: any) => {
            setUnreadCount(snap.size);
        });
        return () => unsubscribe();
    }, [user]);

    // Initial theme state (force dark for Navy Theme)
    const [isDark, setIsDark] = useState(true);

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 20);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // Close mobile menu on route change
    useEffect(() => {
        setIsMenuOpen(false);
    }, [location]);

    const toggleTheme = () => {
        const newIsDark = !isDark;
        setIsDark(newIsDark);
        if (newIsDark) {
            document.documentElement.classList.remove('light-mode');
        } else {
            document.documentElement.classList.add('light-mode');
        }
    };



    // --- Unread Chats Logic ---
    const [unreadChatCount, setUnreadChatCount] = useState(0);

    useEffect(() => {
        if (!user) return;
        const q = query(
            collection(db, 'chats'),
            where('participants', 'array-contains', user.uid)
        );
        const unsubscribe = onSnapshot(q, (snapshot: any) => {
            let total = 0;
            snapshot.docs.forEach((doc: any) => {
                const data = doc.data();
                if (data.unreadCount && typeof data.unreadCount[user.uid] === 'number') {
                    total += data.unreadCount[user.uid];
                }
            });
            setUnreadChatCount(total);
        });
        return () => unsubscribe();
    }, [user]);

    const NavItem = ({ to, icon: Icon, label, badge, count }: { to: string; icon: any; label: string; badge?: boolean; count?: number }) => {
        const isActive = location.pathname === to;
        return (
            <Link
                to={to}
                className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all duration-300 group
                    ${isActive
                        ? 'bg-indigo-500/10 text-indigo-400 font-medium'
                        : 'text-gray-400 hover:text-white hover:bg-white/5'
                    }`}
            >
                <div className="relative">
                    <Icon className={`w-4 h-4 ${isActive ? 'text-indigo-400' : 'group-hover:text-indigo-400 transition-colors'}`} />
                    {/* Generic Badge (boolean) */}
                    {badge && <span className="absolute -top-1 -right-1 w-1.5 h-1.5 bg-indigo-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(99,102,241,0.6)]" />}

                    {/* Count Badge (number) */}
                    {count !== undefined && count > 0 && (
                        <span className="absolute -top-2 -right-2 bg-red-500 text-white text-[10px] font-bold px-1 min-w-[16px] h-4 rounded-full flex items-center justify-center border border-[#0b1021]">
                            {count > 9 ? '9+' : count}
                        </span>
                    )}
                </div>
                <span className="text-sm">{label}</span>
            </Link>
        );
    };

    return (
        <header
            className={`fixed top-0 w-full z-50 transition-all duration-300 
            ${scrolled || isMenuOpen
                    ? 'bg-[#0b1021]/95 backdrop-blur-md border-b border-white/5 shadow-lg shadow-indigo-500/10'
                    : 'bg-gradient-to-b from-[#0b1021]/80 to-transparent'
                }`}
        >
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex items-center justify-between h-20">

                    {/* Brand */}
                    <Link to="/" className="flex items-center gap-3 group brand-logo relative z-50">
                        {config.logoType === 'image' && config.logoUrl ? (
                            <img src={config.logoUrl} alt={config.appName} className="max-h-12 w-auto object-contain transition-transform group-hover:scale-105" />
                        ) : (
                            // Default CSS Logo
                            <div className="flex items-center gap-3">
                                <div className="relative group-hover:scale-105 group-hover:rotate-6 transition-all duration-300">
                                    <div className="absolute inset-0 bg-blue-600 blur-lg opacity-40 group-hover:opacity-60 transition-opacity rounded-xl"></div>
                                    <div className="relative w-10 h-10 rounded-xl bg-gradient-to-tr from-cyan-500 via-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                                        <div className="w-4 h-4 bg-white rounded-full shadow-sm" />
                                    </div>
                                </div>
                                <span className="text-xl font-display font-bold tracking-tight text-white group-hover:text-indigo-200 transition-colors">
                                    {config.appName}
                                </span>
                            </div>
                        )}
                    </Link>

                    {/* Desktop Navigation */}
                    <nav className="hidden md:flex items-center bg-white/5 backdrop-blur-md rounded-full px-2 py-1.5 border border-white/5 shadow-inner">
                        <NavItem to="/search" icon={Search} label="Buscar" />
                        <div className="w-px h-4 bg-white/10 mx-1" />
                        <NavItem to="/archive" icon={Archive} label="Archivo" />
                        <NavItem to="/chats" icon={MessageSquare} label="Chats" count={unreadChatCount} />
                    </nav>

                    {/* Right Actions */}
                    <div className="hidden md:flex items-center gap-4">
                        <Link
                            to="/create-sublist"
                            className="group flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white rounded-full text-sm font-bold shadow-lg shadow-indigo-500/20 transition-all hover:shadow-indigo-500/40 active:scale-95"
                        >
                            <Plus className="w-4 h-4" />
                            <span>Crear Sublista</span>
                        </Link>

                        {/* NOTIFICATIONS BELL */}
                        {user && (
                            <div className="relative">
                                <button
                                    onClick={() => setShowNotifications(!showNotifications)}
                                    className={`p-2.5 rounded-full transition-all duration-300 relative ${unreadCount > 0
                                        ? 'text-emerald-500 bg-emerald-500/10 hover:bg-emerald-500/20'
                                        : 'text-gray-400 hover:text-white hover:bg-white/10'
                                        }`}
                                >
                                    <Bell className="w-5 h-5" />
                                    {unreadCount > 0 && (
                                        <span className="absolute top-2 right-2.5 w-2 h-2 bg-red-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.6)]" />
                                    )}
                                </button>

                                {showNotifications && (
                                    <NotificationModal
                                        onClose={() => setShowNotifications(false)}
                                        onOpenHistory={() => {
                                            setShowNotifications(false);
                                            setShowHistory(true);
                                        }}
                                    />
                                )}
                            </div>
                        )}

                        {/* History Modal rendered outside the relative container to avoid clipping/nesting issues */}
                        {showHistory && (
                            <NotificationHistoryModal onClose={() => setShowHistory(false)} />
                        )}

                        {user ? (
                            <Link to={`/profile/${user.uid}`} className="flex items-center gap-3 ml-2 group">
                                <span className="text-sm font-medium text-gray-300 group-hover:text-white transition-colors text-right hidden lg:block">
                                    <span className="block text-xs text-gray-500 group-hover:text-gray-400">Hola,</span>
                                    {user.displayName?.split(' ')[0] || 'Usuario'}
                                </span>
                                <div className="relative">
                                    <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 p-[2px] transition-transform group-hover:scale-105 shadow-lg shadow-indigo-500/20">
                                        <div className="w-full h-full rounded-full bg-[#151b2e] flex items-center justify-center overflow-hidden">
                                            {user.photoURL ? (
                                                <img src={user.photoURL} alt="Profile" className="w-full h-full object-cover" />
                                            ) : (
                                                <User className="w-5 h-5 text-indigo-400" />
                                            )}
                                        </div>
                                    </div>
                                    <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 border-2 border-[#0b1021] rounded-full"></div>
                                </div>
                            </Link>
                        ) : (
                            <Link to="/login" className="px-6 py-2 rounded-full bg-white/10 hover:bg-white/20 text-white text-sm font-semibold transition-colors border border-white/5">
                                Iniciar Sesión
                            </Link>
                        )}
                    </div>

                    {/* Mobile Menu Button */}
                    <div className="md:hidden flex items-center gap-4">
                        {user && (
                            <Link to={`/profile/${user.uid}`} className="w-8 h-8 rounded-full bg-gray-800 overflow-hidden">
                                {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <User className="w-4 h-4 m-2" />}
                            </Link>
                        )}
                        <button
                            onClick={() => setIsMenuOpen(!isMenuOpen)}
                            className="p-2 text-gray-300 hover:text-white transition-colors z-50 relative"
                        >
                            {isMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
                        </button>
                    </div>
                </div>
            </div>

            {/* Mobile Menu Overlay */}
            {isMenuOpen && (
                <div className="fixed inset-0 bg-[#0b1021]/95 z-40 pt-24 px-6 animate-fade-in flex flex-col backdrop-blur-3xl">
                    <div className="space-y-4 bg-[#0b1021] p-6 rounded-3xl border border-white/10 shadow-2xl">
                        <Link to="/create-sublist" className="flex items-center justify-center gap-2 w-full py-4 bg-indigo-600 rounded-xl text-white font-bold text-lg mb-8 shadow-lg shadow-indigo-600/20">
                            <Plus className="w-6 h-6" /> Crear Sublista
                        </Link>

                        <div className="space-y-2">
                            <Link to="/search" className="flex items-center gap-3 p-4 rounded-xl bg-white/5 border border-white/5 text-gray-200">
                                <Search className="w-5 h-5 text-indigo-400" /> Buscar
                            </Link>
                            <Link to="/explore" className="flex items-center gap-3 p-4 rounded-xl bg-white/5 border border-white/5 text-gray-200">
                                <Compass className="w-5 h-5 text-indigo-400" /> Explorar
                            </Link>
                            <Link to="/chats" className="flex items-center gap-3 p-4 rounded-xl bg-white/5 border border-white/5 text-gray-200 justify-between">
                                <div className="flex items-center gap-3">
                                    <MessageSquare className="w-5 h-5 text-indigo-400" /> Chats
                                </div>
                                {unreadChatCount > 0 && (
                                    <span className="bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                                        {unreadChatCount}
                                    </span>
                                )}
                            </Link>
                            <Link to="/archive" className="flex items-center gap-3 p-4 rounded-xl bg-white/5 border border-white/5 text-gray-200">
                                <Archive className="w-5 h-5 text-indigo-400" /> Archivo
                            </Link>
                        </div>

                        <div className="space-y-2 pt-4 border-t border-white/5">
                            {!user && (
                                <Link to="/login" className="flex items-center gap-3 p-4 rounded-xl bg-indigo-600 text-white font-bold w-full justify-center">
                                    Iniciar Sesión
                                </Link>
                            )}
                        </div>
                    </div>

                    <div className="mt-auto pb-8 text-center text-gray-500 text-sm">
                        <p>© 2024 Listopic App</p>
                    </div>
                </div>
            )}
        </header>
    );
};

import React, { useEffect, useState } from 'react';
import { X, Bell, Heart, UserPlus, MessageSquare, Star, Trash2 } from 'lucide-react';
import { collection, query, orderBy, getDocs, doc, deleteDoc, writeBatch } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';

interface NotificationHistoryModalProps {
    onClose: () => void;
}

export const NotificationHistoryModal: React.FC<NotificationHistoryModalProps> = ({ onClose }) => {
    const { user } = useAuth();
    const [notifications, setNotifications] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAll = async () => {
            if (!user) return;
            try {
                const q = query(
                    collection(db, 'users', user.uid, 'notifications'),
                    orderBy('createdAt', 'desc')
                );
                const snap = await getDocs(q);
                setNotifications(snap.docs.map(d => ({ id: d.id, ...d.data() })));
            } catch (error) {
                console.error("Error fetching history:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchAll();
    }, [user]);

    const handleDelete = async (e: React.MouseEvent, id: string) => {
        e.preventDefault();
        e.stopPropagation();
        if (!user) return;

        // Optimistic update
        setNotifications(prev => prev.filter(n => n.id !== id));

        try {
            await deleteDoc(doc(db, 'users', user.uid, 'notifications', id));
        } catch (error) {
            console.error("Error deleting notification:", error);
        }
    };

    const getIcon = (type: string) => {
        switch (type) {
            case 'like': return <Heart className="w-4 h-4 text-pink-500" />;
            case 'follow': return <UserPlus className="w-4 h-4 text-indigo-500" />;
            case 'comment': return <MessageSquare className="w-4 h-4 text-blue-500" />;
            case 'system': return <Star className="w-4 h-4 text-amber-500" />;
            default: return <Bell className="w-4 h-4 text-gray-500" />;
        }
    };

    const getLink = (notification: any) => {
        if (notification.link) return notification.link;
        if (notification.type === 'follow' && notification.fromUserId) return `/profile/${notification.fromUserId}`;
        if (notification.type === 'like' && notification.placeId) return `/place/${notification.placeId}`;
        return '#';
    }

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm animate-fade-in md:p-4">
            <div className="bg-[#0b1021] w-full h-full md:h-auto md:max-h-[90vh] md:max-w-2xl md:rounded-2xl shadow-2xl flex flex-col overflow-hidden border-none md:border border-white/10">
                <div className="p-4 border-b border-white/10 flex items-center justify-between bg-[#151b2e]">
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        <Bell className="w-5 h-5 text-indigo-400" />
                        Histórico de Notificaciones
                    </h2>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-[#0b1021]">
                    {loading ? (
                        <div className="py-20 text-center text-gray-500">Cargando historial...</div>
                    ) : notifications.length === 0 ? (
                        <div className="py-20 text-center text-gray-500 flex flex-col items-center gap-4">
                            <Bell className="w-12 h-12 opacity-20" />
                            <p>No hay notificaciones.</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {notifications.map(notification => (
                                <div key={notification.id} className="group relative flex items-start gap-4 p-4 rounded-xl bg-white/5 hover:bg-white/10 transition-colors border border-white/5">
                                    <Link
                                        to={getLink(notification)}
                                        onClick={onClose}
                                        className="flex-1 flex items-start gap-4"
                                    >
                                        <div className="shrink-0 w-10 h-10 rounded-full bg-black/30 border border-white/10 flex items-center justify-center mt-1">
                                            {getIcon(notification.type)}
                                        </div>
                                        <div>
                                            <p className="text-gray-200 text-sm md:text-base leading-relaxed">
                                                {notification.senderName && <span className="font-bold text-white">{notification.senderName} </span>}
                                                {notification.message}
                                            </p>
                                            <div className="flex flex-wrap gap-x-4 gap-y-1 mt-2 text-xs text-gray-500">
                                                <span>
                                                    {notification.createdAt?.seconds
                                                        ? new Date(notification.createdAt.seconds * 1000).toLocaleString()
                                                        : 'Fecha desconocida'}
                                                </span>
                                                {notification.placeName && <span className="text-indigo-400 font-medium">{notification.placeName}</span>}
                                            </div>
                                        </div>
                                    </Link>

                                    <button
                                        onClick={(e) => handleDelete(e, notification.id)}
                                        className="p-2 text-gray-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors absolute top-2 right-2 md:static md:opacity-0 md:group-hover:opacity-100"
                                        title="Eliminar notificación"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { X, Bell, Heart, UserPlus, MessageSquare, Star } from 'lucide-react';
import { collection, query, orderBy, limit, onSnapshot, doc, updateDoc, writeBatch, where } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import { Link } from 'react-router-dom';
import { NotificationHistoryModal } from './NotificationHistoryModal';

interface NotificationModalProps {
    onClose: () => void;
    onOpenHistory: () => void;
}

export const NotificationModal: React.FC<NotificationModalProps> = ({ onClose, onOpenHistory }) => {
    const { user } = useAuth();
    const [notifications, setNotifications] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    // showHistory removed, controlled by parent

    useEffect(() => {
        if (!user) return;

        // Subscribe to notifications
        const q = query(
            collection(db, 'users', user.uid, 'notifications'),
            orderBy('createdAt', 'desc'),
            limit(20)
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            setNotifications(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
            setLoading(false);
        });

        return () => unsubscribe();
    }, [user]);

    const handleMarkAllRead = async () => {
        if (!user) return;
        const unreadBatch = notifications.filter(n => !n.read);
        if (unreadBatch.length === 0) return;

        const batch = writeBatch(db);
        unreadBatch.forEach(n => {
            batch.update(doc(db, 'users', user.uid, 'notifications', n.id), { read: true });
        });
        await batch.commit();
    };

    const getIcon = (type: string) => {
        switch (type) {
            case 'like': return <Heart className="w-4 h-4 text-pink-500" />;
            case 'follow': return <UserPlus className="w-4 h-4 text-indigo-500" />;
            case 'comment': return <MessageSquare className="w-4 h-4 text-blue-500" />;
            case 'system': return <Star className="w-4 h-4 text-amber-500" />;
            default: return <Bell className="w-4 h-4 text-gray-500" />;
        }
    };

    const getLink = (notification: any) => {
        if (notification.link) return notification.link;
        if (notification.type === 'follow' && notification.fromUserId) return `/profile/${notification.fromUserId}`;
        if (notification.type === 'like' && notification.placeId) return `/place/${notification.placeId}`; // Simplified
        return '#';
    }

    return (
        <div className="absolute top-12 right-0 w-80 md:w-96 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl overflow-hidden z-50 animate-fade-in origin-top-right">
            <div className="p-4 border-b border-white/10 flex items-center justify-between bg-black/20">
                <h3 className="font-bold text-white flex items-center gap-2">
                    <Bell className="w-4 h-4 text-indigo-400" /> Notificaciones
                </h3>
                <div className="flex items-center gap-2">
                    <button
                        onClick={handleMarkAllRead}
                        className="text-[10px] uppercase font-bold text-indigo-400 hover:text-indigo-300 transition-colors"
                    >
                        Marcar leídas
                    </button>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">
                        <X className="w-4 h-4" />
                    </button>
                </div>
            </div>

            <div className="max-h-[400px] overflow-y-auto">
                {loading ? (
                    <div className="p-8 text-center text-gray-500 text-sm">Cargando...</div>
                ) : notifications.length === 0 ? (
                    <div className="p-8 text-center text-gray-500 text-sm flex flex-col items-center gap-2">
                        <Bell className="w-8 h-8 opacity-20" />
                        Sin notificaciones recientes
                    </div>
                ) : (
                    <div className="divide-y divide-white/5">
                        {notifications.map(notification => (
                            <Link
                                key={notification.id}
                                to={getLink(notification)}
                                onClick={() => {
                                    // Mark as read on click
                                    if (!notification.read && user) {
                                        updateDoc(doc(db, 'users', user.uid, 'notifications', notification.id), { read: true });
                                    }
                                    onClose();
                                }}
                                className={`block p-4 hover:bg-white/5 transition-colors ${!notification.read ? 'bg-indigo-500/5' : ''}`}
                            >
                                <div className="flex gap-3">
                                    <div className={`mt-1 shrink-0 w-8 h-8 rounded-full flex items-center justify-center bg-black/20 border border-white/5`}>
                                        {getIcon(notification.type)}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm text-gray-200 leading-snug">
                                            {notification.senderName && <span className="font-bold text-white">{notification.senderName} </span>}
                                            {notification.message || 'Nueva notificación'}
                                        </p>
                                        <span className="text-xs text-gray-500 mt-1 block">
                                            {notification.createdAt?.seconds ? new Date(notification.createdAt.seconds * 1000).toLocaleDateString() : 'Hace un momento'}
                                        </span>
                                    </div>
                                    {!notification.read && (
                                        <div className="mt-2 w-2 h-2 rounded-full bg-indigo-500 shrink-0" />
                                    )}
                                </div>
                            </Link>
                        ))}
                    </div>
                )}
            </div>

            <div className="p-2 border-t border-white/10 bg-black/20 text-center">
                <button
                    onClick={onOpenHistory}
                    className="text-xs text-gray-400 hover:text-white transition-colors w-full py-1"
                >
                    Ver todas
                </button>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { PlaceService, type PlaceResult } from '../services/PlaceService';
import { Search, MapPin, Loader, X } from 'lucide-react';

import { useLocation } from '../hooks/useLocation';

interface PlaceSearchProps {
    onSelect: (place: PlaceResult) => void;
    placeholder?: string;
    prefillValue?: string;
    onManualToggle?: () => void;
}

export const PlaceSearch: React.FC<PlaceSearchProps> = ({ onSelect, placeholder = "Ej: La Pizzería Genial", prefillValue, onManualToggle }) => {
    const { location, loading: locLoading } = useLocation();
    const [query, setQuery] = useState(prefillValue || '');
    const [results, setResults] = useState<PlaceResult[]>([]);
    const [loading, setLoading] = useState(false);
    const [statusMessage, setStatusMessage] = useState<string | null>(null);
    const [isOpen, setIsOpen] = useState(false);
    const wrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (prefillValue) {
            setQuery(prefillValue);
        }
    }, [prefillValue]);

    // Unified Search Handler
    const handleSearch = async () => {
        setLoading(true);
        setResults([]);
        setIsOpen(false);

        try {
            // Case 1: Empty Query -> Search Nearby
            if (!query.trim()) {
                if (!location && !navigator.geolocation) {
                    setStatusMessage("Ubicación necesaria para búsqueda cercana.");
                    setLoading(false);
                    return;
                }

                setStatusMessage("Obteniendo ubicación...");

                // Use cached location or fetch fresh
                const lat = location?.latitude;
                const lng = location?.longitude;

                if (lat && lng) {
                    setStatusMessage("Buscando lugares cercanos...");
                    let data = await PlaceService.searchNearby(lat, lng);

                    // Sort by distance
                    data.sort((a, b) => {
                        if (a.distance === undefined) return 1;
                        if (b.distance === undefined) return -1;
                        return a.distance - b.distance;
                    });

                    setResults(data);
                    setIsOpen(true);
                    if (data.length === 0) setStatusMessage("No se encontraron lugares cercanos.");
                    else setStatusMessage(null);
                } else {
                    // Force refresh if hook didn't catch it yet
                    navigator.geolocation.getCurrentPosition(async (pos) => {
                        let data = await PlaceService.searchNearby(pos.coords.latitude, pos.coords.longitude);

                        // Sort by distance
                        data.sort((a, b) => {
                            if (a.distance === undefined) return 1;
                            if (b.distance === undefined) return -1;
                            return a.distance - b.distance;
                        });

                        setResults(data);
                        setIsOpen(true);
                        setLoading(false);
                        if (data.length === 0) setStatusMessage("No se encontraron lugares cercanos.");
                        else setStatusMessage(null);
                    }, (err) => {
                        console.warn("Geo error", err);
                        setStatusMessage("No se pudo obtener la ubicación.");
                        setLoading(false);
                    });
                    // Return here to wait for callback
                    return;
                }
            }
            // Case 2: Text Query -> Text Search
            else {
                if (query.length < 3) {
                    setStatusMessage("Introduce al menos 3 caracteres.");
                    setLoading(false);
                    return;
                }

                setStatusMessage(location ? "Buscando..." : "Buscando globalmente...");
                let data = await PlaceService.searchPlaces(query, location?.latitude, location?.longitude);

                // Smart Sort: Prioritize Relevance (Name Match) THEN Distance
                // 1. Exact/Partial Name Match
                // 2. Others
                const normalizedQuery = query.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

                const exactMatches: PlaceResult[] = [];
                const others: PlaceResult[] = [];

                data.forEach(item => {
                    const normalizedName = item.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                    // Check if name includes query words (basic relevance)
                    if (normalizedName.includes(normalizedQuery)) {
                        exactMatches.push(item);
                    } else {
                        others.push(item);
                    }
                });

                // Sort both groups by distance
                const sortByDistance = (a: PlaceResult, b: PlaceResult) => {
                    if (a.distance === undefined) return 1;
                    if (b.distance === undefined) return -1;
                    return a.distance - b.distance;
                };

                exactMatches.sort(sortByDistance);
                others.sort(sortByDistance);

                // Combine: Matches first, then others
                setResults([...exactMatches, ...others]);

                setIsOpen(true);
                if (data.length === 0) {
                    setStatusMessage("No se encontraron resultados.");
                } else {
                    setStatusMessage(null);
                }
            }
        } catch (error) {
            console.error("Search error:", error);
            setStatusMessage("Error al buscar.");
        } finally {
            setLoading(false);
        }
    };

    // Removed handleNearby as it is integrated into handleSearch or manual toggle

    // Auto-search (Debounce) integration too for modern UX? User asked to replicate "how it works in old version".
    // Old version had explicit buttons but mostly relied on them. I'll keep explicit handlers as primary but maybe allow Enter key.
    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            handleSearch();
        }
    };

    // Click outside handler
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleSelect = (place: PlaceResult) => {
        setQuery(place.name);
        setIsOpen(false);
        onSelect(place);
    };

    return (
        <div ref={wrapperRef} className="space-y-2">
            <div className="flex gap-2">
                <div className="relative flex-1">
                    <input
                        type="text"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder={placeholder}
                        className="w-full bg-[#0b1021] border border-white/10 rounded-lg py-3 pl-10 pr-10 text-white focus:outline-none focus:border-indigo-500 transition-colors"
                    />
                    <div className="absolute left-3 top-3.5 text-gray-400">
                        <Search className="w-4 h-4" />
                    </div>

                    {/* Location Status Indicator */}
                    <div className="absolute right-3 top-3.5 flex items-center gap-2">
                        {query ? (
                            <button
                                onClick={() => { setQuery(''); setResults([]); setStatusMessage(null); }}
                                className="text-gray-500 hover:text-white"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        ) : (
                            <div title={locLoading ? "Buscando GPS..." : location ? "Ubicación lista" : "Sin ubicación"}>
                                {locLoading ? (
                                    <Loader className="w-4 h-4 text-indigo-500 animate-spin" />
                                ) : location ? (
                                    <MapPin className="w-4 h-4 text-green-500/50" />
                                ) : (
                                    <MapPin className="w-4 h-4 text-gray-600" />
                                )}
                            </div>
                        )}
                    </div>
                </div>
                <button
                    type="button"
                    onClick={handleSearch}
                    disabled={loading}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 rounded-lg font-medium transition-colors flex items-center gap-2"
                >
                    {loading ? <Loader className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
                    <span className="hidden sm:inline">Buscar</span>
                </button>
            </div>

            {/* Status / Error Message */}
            {statusMessage && (
                <div className="text-xs text-indigo-300 bg-indigo-500/10 p-2 rounded border border-indigo-500/20">
                    {statusMessage}
                </div>
            )}

            {/* Results Dropdown */}
            {isOpen && results.length > 0 && (
                <div className="absolute z-50 w-full md:w-[500px] mt-1 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl overflow-hidden animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                    {results.map((place) => (
                        <div
                            key={place.id}
                            onClick={() => handleSelect(place)}
                            className="p-3 hover:bg-white/5 cursor-pointer border-b border-white/5 last:border-0 transition-colors"
                        >
                            <div className="flex items-start gap-3">
                                <MapPin className="w-5 h-5 text-indigo-400 mt-0.5 shrink-0" />
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-start">
                                        <h4 className="font-bold text-white text-sm truncate pr-2">{place.name}</h4>
                                        {place.distance !== undefined && (
                                            <span className="text-[10px] font-mono bg-indigo-500/20 text-indigo-300 px-1.5 py-0.5 rounded whitespace-nowrap">
                                                {place.distance < 1000
                                                    ? `${Math.round(place.distance)} m`
                                                    : `${(place.distance / 1000).toFixed(1)} km`}
                                            </span>
                                        )}
                                    </div>
                                    <p className="text-xs text-gray-400 line-clamp-2">{place.address}</p>
                                </div>
                            </div>
                        </div>
                    ))}
                    <div className="p-2 bg-[#0b1021]/50 text-center flex justify-between items-center text-[10px] text-gray-500 px-4">
                        <span>OpenStreetMap Data</span>
                        {onManualToggle && (
                            <button onClick={onManualToggle} className="text-indigo-400 hover:text-indigo-300 underline">
                                ¿No lo encuentras? Añadir manual
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { MessageCircle, Share2, MapPin, ThumbsUp, ThumbsDown, Bookmark, MoreHorizontal, Edit, Trash2, User, Heart, MessageSquare, Flag } from 'lucide-react';
import { ReviewComments } from './ReviewComments';
import { doc, setDoc, deleteDoc, getDoc, collection, onSnapshot, query, where, getDocs, serverTimestamp } from 'firebase/firestore';
import { Link, useNavigate } from 'react-router-dom';
import { type ReviewEntity } from '../hooks/useListDetails';
import { useAuth } from '../context/AuthContext';
import { ShareModal } from './ShareModal';
import { SaveToArchiveModal } from './SaveToArchiveModal';
import { ReviewService } from '../services/ReviewService';
import { ReportModal } from './ReportModal';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import { db } from '../firebase';
import { NonPonderableGauge } from './NonPonderableGauge';

interface ReviewCardProps {
    review: ReviewEntity;
    onDelete?: (id: string) => void;
    onEdit?: (review: ReviewEntity) => void;
    reactionConfig?: { like?: string; dislike?: string }; // Text for animation (e.g. "ñam!")
}


export const ReviewCard: React.FC<ReviewCardProps> = ({ review, onDelete, onEdit, reactionConfig }) => {
    const { user } = useAuth();
    const navigate = useNavigate();

    // Visual States
    const [liked, setLiked] = useState(false);
    const [likeCount, setLikeCount] = useState(review.reactionCounts?.like || 0); // Placeholder count
    const [showComments, setShowComments] = useState(false);
    const [showAnimation, setShowAnimation] = useState(false); // For "ñam!" animation

    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [isShareOpen, setIsShareOpen] = useState(false);
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [showReportModal, setShowReportModal] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);

    const menuRef = useRef<HTMLDivElement>(null);

    // Local count for optimistic updates
    const [commentCount, setCommentCount] = useState(review.commentCount || 0);

    // Sync state with props if they change (e.g. after a fresh fetch)
    useEffect(() => {
        setCommentCount(review.commentCount || 0);
    }, [review.commentCount]);

    // Derived States
    const isOwner = user?.uid && (user.uid === review.userId || user.uid === review.authorId);

    // Config Defaults
    const likeText = reactionConfig?.like || "¡Me gusta!";

    // ... (Score Logic Omitted for Brevity - keeping existing) ...
    const getScoreColor = (score: number) => {
        if (score >= 9) return 'from-emerald-400 to-teal-500 shadow-emerald-500/50';
        if (score >= 7) return 'from-indigo-400 to-blue-500 shadow-indigo-500/50';
        if (score >= 5) return 'from-yellow-400 to-amber-500 shadow-amber-500/50';
        return 'from-red-400 to-rose-500 shadow-red-500/50';
    };

    const bubbleColor = review.overallRating && review.overallRating >= 7 ? 'from-emerald-500 to-teal-500' :
        review.overallRating && review.overallRating >= 5 ? 'from-yellow-400 to-orange-500' :
            'from-red-500 to-pink-500';

    // Extract Criteria for Visualization
    const { ponderable, nonPonderable } = React.useMemo(() => {
        let allCriteria: { key: string, label: string, score: number, isPonderable: boolean }[] = [];

        if (review.criteriaDefinition) {
            if (Array.isArray(review.criteriaDefinition)) {
                // New Format: Array (Preserves Order)
                allCriteria = review.criteriaDefinition.map((def: any) => ({
                    key: def.id,
                    label: def.label || def.id,
                    score: review.scores?.[def.id] || 0,
                    isPonderable: def.ponderable !== false && def.isPonderable !== false
                }));
            } else {
                // Legacy Format: Map (No Order)
                allCriteria = Object.entries(review.criteriaDefinition).map(([key, def]) => ({
                    key,
                    label: def.label || key,
                    score: review.scores?.[key] || 0,
                    isPonderable: def.ponderable !== false
                }));
            }
        }

        return {
            ponderable: allCriteria.filter(c => c.isPonderable),
            nonPonderable: allCriteria.filter(c => !c.isPonderable)
        };
    }, [review.criteriaDefinition, review.scores]);


    // Check if Liked (Graceful Error Handling)
    useEffect(() => {
        if (!user || !review.id || !review.listId) return;
        const checkLike = async () => {
            try {
                // Correct path: lists/{listId}/reviews/{reviewId}/reactions/{userId}
                const reactionRef = doc(db, 'lists', review.listId, 'reviews', review.id, 'reactions', user.uid);
                const reactionSnap = await getDoc(reactionRef);
                if (reactionSnap.exists()) {
                    setLiked(true);
                }
            } catch (e: any) {
                // Ignore permission errors to prevent console spam
                if (e.code !== 'permission-denied') {
                    console.warn("Error checking like status:", e);
                }
            }
        };
        checkLike();
    }, [user, review.id, review.listId]);

    // Close menu on click outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsMenuOpen(false);
            }
        };
        if (isMenuOpen) {
            document.addEventListener("mousedown", handleClickOutside);
        }
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, [isMenuOpen]);

    const handleCardClick = () => {
        if (review.placeId && review.itemName) {
            navigate(`/group/${review.placeId}/${encodeURIComponent(review.itemName)}`);
        }
    };

    const handleLike = async (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!user || !review.id || !review.listId) return;

        const newLiked = !liked;

        // Optimistic UI
        setLiked(newLiked);
        setLikeCount(prev => newLiked ? prev + 1 : prev - 1);

        if (newLiked) {
            setShowAnimation(true);
            setTimeout(() => setShowAnimation(false), 2000);
        }

        try {
            await ReviewService.toggleReaction(review.listId, review.id, user.uid);
        } catch (error) {
            console.error("Failed to toggle reaction", error);
            setLiked(!newLiked); // Revert
            setLikeCount(prev => !newLiked ? prev + 1 : prev - 1);
        }
    };

    const handleShareClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsShareOpen(true);
        setIsMenuOpen(false);
    };

    const handleSaveClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        setIsSaveModalOpen(true);
        setIsMenuOpen(false);
    };

    const handleEdit = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (onEdit) onEdit(review);
        setIsMenuOpen(false);
    };

    const handleDelete = async (e: React.MouseEvent) => {
        e.stopPropagation();
        if (window.confirm("¿Eliminar reseña?")) {
            setIsDeleting(true);
            try {
                await ReviewService.deleteReview(review.listId, review.id);
                if (onDelete) onDelete(review.id);
            } catch (error) {
                console.error(error);
                setIsDeleting(false);
            }
        }
    };

    const handleReportClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        setShowReportModal(true);
        setIsMenuOpen(false);
    };

    const handleCommentToggle = (e: React.MouseEvent) => {
        e.stopPropagation();
        setShowComments(!showComments);
    };

    if (isDeleting) {
        return <div className="animate-pulse bg-[#151b2e] h-64 rounded-3xl border border-white/5 mx-auto w-full"></div>;
    }



    const handleCommentChange = (increment: number) => {
        setCommentCount(prev => Math.max(0, prev + increment));
    };

    return (
        <>
            <article
                onClick={handleCardClick}
                style={{ willChange: 'transform' }} // Optimize for GPU
                className="bg-[#101628] border-y sm:border border-white/5 sm:rounded-3xl overflow-hidden shadow-lg hover:shadow-2xl flex flex-col hover:border-white/10 transition-transform duration-300 cursor-pointer group relative -mx-4 sm:mx-0 w-[calc(100%+2rem)] sm:w-full"
            >
                {/* 1. Header: User, Context, Menu */}
                {/* ... (Header code unchanged) ... */}
                <div className="px-4 py-3 flex items-center justify-center">
                    <div className="flex items-center gap-3 w-full">
                        {/* Living Avatar Ring */}
                        <Link
                            to={review.userId ? `/profile/${review.userId}` : '#'}
                            onClick={(e) => e.stopPropagation()}
                            className="block relative group/avatar z-10 shrink-0"
                        >
                            <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500 via-purple-500 to-pink-500 rounded-full blur-[2px] opacity-70 group-hover/avatar:opacity-100 transition-opacity" />
                            <div className="relative w-10 h-10 rounded-full p-[2px] bg-gradient-to-tr from-indigo-500 via-purple-500 to-pink-500">
                                <div className="w-full h-full rounded-full border-2 border-[#0b1021] overflow-hidden bg-gray-800">
                                    {review.authorPhoto ? (
                                        <img src={review.authorPhoto} alt="User" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-gray-400">
                                            <User className="w-5 h-5" />
                                        </div>
                                    )}
                                </div>
                            </div>
                        </Link>

                        <div className="flex flex-col leading-tight z-10 min-w-0 flex-1">
                            <div className="flex items-start justify-between w-full">
                                <div className="flex flex-col">
                                    <Link
                                        to={review.userId ? `/profile/${review.userId}` : '#'}
                                        onClick={(e) => e.stopPropagation()}
                                        className="font-bold text-sm text-gray-100 hover:underline cursor-pointer truncate"
                                    >
                                        {review.authorName || 'Anónimo'}
                                    </Link>
                                    {(review.listName || review.placeName) && (
                                        <span className="text-sm text-gray-400 truncate w-full">
                                            en <Link
                                                to={review.listId ? `/list/${review.listId}` : '#'}
                                                onClick={(e) => e.stopPropagation()}
                                                className="font-semibold text-gray-200 hover:text-indigo-400 transition-colors"
                                            >
                                                {review.listName || review.placeName}
                                            </Link>
                                        </span>
                                    )}
                                </div>
                                <span className="text-xs text-gray-500 whitespace-nowrap ml-2">
                                    {(() => {
                                        const date = review.createdAt;
                                        let dateObj: Date | null = null;
                                        if (date && typeof date.toDate === 'function') dateObj = date.toDate();
                                        else if (date instanceof Date) dateObj = date;
                                        else if (typeof date === 'string' || typeof date === 'number') dateObj = new Date(date);
                                        return dateObj ? formatDistanceToNow(dateObj, { locale: es }) : 'Reciente';
                                    })()}
                                </span>
                            </div>
                        </div>

                        <div className="relative z-20 shrink-0 self-start mt-1" ref={menuRef}>
                            <button
                                className="text-gray-500 hover:text-white transition-colors p-1"
                                onClick={(e) => { e.stopPropagation(); setIsMenuOpen(!isMenuOpen); }}
                            >
                                <MoreHorizontal className="w-5 h-5" />
                            </button>

                            {isMenuOpen && (
                                <div className="absolute right-0 mt-2 w-48 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl py-1 overflow-hidden animate-fade-in origin-top-right z-50">
                                    <button
                                        onClick={handleSaveClick}
                                        className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                    >
                                        <Bookmark className="w-4 h-4" /> Guardar
                                    </button>
                                    <button
                                        onClick={handleShareClick}
                                        className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                    >
                                        <Share2 className="w-4 h-4" /> Compartir
                                    </button>

                                    {isOwner ? (
                                        <>
                                            <div className="h-px bg-white/10 my-1"></div>
                                            <button
                                                onClick={handleEdit}
                                                className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                            >
                                                <Edit className="w-4 h-4" /> Editar
                                            </button>
                                            <button
                                                onClick={handleDelete}
                                                className="w-full text-left px-4 py-2.5 text-sm text-rose-400 hover:bg-rose-500/10 hover:text-rose-300 flex items-center gap-2 transition-colors"
                                            >
                                                <Trash2 className="w-4 h-4" /> Eliminar
                                            </button>
                                        </>
                                    ) : (
                                        <>
                                            <div className="h-px bg-white/10 my-1"></div>
                                            <button
                                                onClick={handleReportClick}
                                                className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                            >
                                                <Flag className="w-4 h-4" /> Reportar
                                            </button>
                                        </>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* 2. Main Visual: Large Image with Overlay Bubble (Also for fallback) */}
                <div className={`relative w-full bg-gray-900 group/image ${review.photoUrl ? 'aspect-auto' : 'h-32 sm:h-40 overflow-hidden'}`}>

                    {/* "Ñam!" Animation Overlay */}
                    {showAnimation && (
                        <div className="absolute inset-0 z-50 flex items-center justify-center pointer-events-none">
                            <div className="bg-black/60 backdrop-blur-md px-6 py-3 rounded-2xl border border-white/20 shadow-2xl animate-bounce-in">
                                <span className="text-3xl font-black text-transparent bg-clip-text bg-gradient-to-r from-pink-500 via-red-500 to-yellow-500 drop-shadow-sm filter">
                                    {likeText}
                                </span>
                            </div>
                        </div>
                    )}

                    {review.photoUrl ? (
                        <img
                            src={review.photoUrl}
                            alt={review.itemName}
                            className="w-full h-auto object-cover block"
                        />
                    ) : (
                        review.placeMainImage ? (
                            <img src={review.placeMainImage} alt={review.placeName} className="w-full h-full object-cover object-center opacity-60 group-hover/image:scale-105 transition-transform duration-700" />
                        ) : (
                            <div className="w-full h-full flex flex-col items-center justify-center text-gray-700 bg-gray-800/10">
                                <MapPin className="w-8 h-8 mb-1 opacity-20" />
                            </div>
                        )
                    )}

                    {/* Overlay Bubbles Container - Always visible now if we have fallback image or legitimate image */}
                    <div className={`absolute ${review.photoUrl ? 'top-4 right-4 flex-col items-end gap-2' : 'top-1/2 -translate-y-1/2 right-4 flex-row items-center gap-3'} flex z-10`}>

                        {/* City Bubble (Overlay) */}
                        {(review as any).placeCity && (
                            <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-black/40 border border-white/10 backdrop-blur-md shadow-lg transform transition-transform group-hover:scale-105">
                                <MapPin className="w-3.5 h-3.5 text-white/90" />
                                <span className="text-white font-bold text-xs uppercase tracking-wide">{(review as any).placeCity}</span>
                            </div>
                        )}

                        {/* The "Living" Score Bubble */}
                        <div className={`relative w-16 h-16 flex items-center justify-center animate-blob transition-all duration-500 group-hover:scale-110`}>
                            {/* Inner Gradient Blob */}
                            <div className={`absolute inset-0 bg-gradient-to-br ${bubbleColor} opacity-90 blur-sm rounded-full`} />
                            {/* Core Bubble */}
                            <div className={`relative w-full h-full bg-gradient-to-br ${bubbleColor} flex items-center justify-center shadow-lg border-2 border-white/10 backdrop-blur-sm rounded-full`}>
                                <span className="text-white font-display font-bold text-2xl drop-shadow-md">
                                    {review.overallRating?.toFixed(1) || '-'}
                                </span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* 3. Content Body */}
                <div className="p-4 pt-3 space-y-3 flex-1">
                    {/* Title & Item */}
                    <div>
                        {review.placeName && (
                            <Link
                                to={`/place/${review.placeId}`}
                                onClick={(e) => e.stopPropagation()}
                                className="block font-display font-bold text-lg sm:text-xl text-gray-100 hover:text-indigo-400 transition-colors leading-tight mb-1"
                            >
                                {review.placeName}
                            </Link>
                        )}
                        <h3 className="text-sm font-medium text-indigo-400 group-hover:text-indigo-300 transition-colors">
                            {review.itemName}
                        </h3>
                    </div>

                    {/* Criteria Bars (Grouped) */}
                    {(ponderable.length > 0 || nonPonderable.length > 0) && (
                        <div className="py-2 space-y-3">

                            {/* Ponderable (Standard) - Grid */}
                            {ponderable.length > 0 && (
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-3">
                                    {ponderable.map((crit, idx) => {
                                        const barColor = `bg-gradient-to-r ${getScoreColor(crit.score).split(' ')[0]} ${getScoreColor(crit.score).split(' ')[1]}`;
                                        const scoreColor = crit.score >= 8 ? 'text-emerald-400' : crit.score >= 5 ? 'text-indigo-400' : 'text-rose-400';

                                        return (
                                            <div key={idx} className="flex flex-col">
                                                <div className="flex justify-between items-end text-xs mb-1">
                                                    <span className="text-gray-400 font-medium truncate opacity-90">{crit.label}</span>
                                                    <span className={`font-mono font-bold ${scoreColor}`}>
                                                        {crit.score.toFixed(1)}
                                                    </span>
                                                </div>
                                                <div className="h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                                    <div
                                                        className={`h-full rounded-full ${barColor}`}
                                                        style={{ width: `${crit.score * 10}%` }}
                                                    />
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}

                            {/* Non-Ponderable (Extras) - Gauges Grid */}
                            {nonPonderable.length > 0 && (
                                <div className="pt-2 border-t border-white/5">
                                    <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                        {nonPonderable.map((crit, idx) => (
                                            <NonPonderableGauge key={idx} score={crit.score} label={crit.label} size={60} />
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {/* Review Text */}
                    {review.comment && (
                        <div className="pl-3 border-l-2 border-white/10 mt-2">
                            <p className="text-gray-300 text-sm leading-relaxed italic line-clamp-3">
                                "{review.comment}"
                            </p>
                        </div>
                    )}

                    {/* Tags */}
                    {(review.tags && review.tags.length > 0) || (review.userTags && review.userTags.length > 0) ? (
                        <div className="flex flex-wrap gap-2 mt-3">
                            {[...(review.tags || []), ...(review.userTags || [])].filter((t, i, a) => a.indexOf(t) === i).map((tag, i) => (
                                <span key={i} className="text-[10px] sm:text-xs font-bold text-indigo-300 bg-indigo-500/10 px-2.5 py-1 rounded-lg border border-indigo-500/20">
                                    #{tag}
                                </span>
                            ))}
                        </div>
                    ) : null}
                </div>

                {/* 4. Footer: Interactive Bar */}
                <div className="px-4 py-3 border-t border-white/5 bg-white/[0.02] flex items-center justify-between mt-auto relative z-10">
                    <div className="flex items-center gap-4">
                        <button
                            className={`flex items-center gap-1.5 transition-all group/btn ${liked ? 'text-pink-500 scale-105' : 'text-gray-400 hover:text-pink-500'}`}
                            onClick={handleLike}
                        >
                            <ThumbsUp className={`w-5 h-5 group-hover/btn:scale-110 transition-transform stroke-[1.5] ${liked ? 'fill-current' : ''}`} />
                            <span className="text-sm font-semibold">{likeCount > 0 ? likeCount : ''}</span>
                        </button>
                        <button
                            className={`flex items-center gap-1.5 transition-colors group/btn ${showComments ? 'text-indigo-400' : 'text-gray-400 hover:text-indigo-400'}`}
                            onClick={handleCommentToggle}
                        >
                            <MessageCircle className="w-5 h-5 group-hover/btn:scale-110 transition-transform stroke-[1.5]" />
                            <span className="text-sm font-semibold">{commentCount > 0 ? commentCount : ''}</span>
                        </button>
                    </div>

                    <div className="flex items-center gap-3">
                        <button
                            className="text-gray-500 hover:text-indigo-400 transition-colors p-1"
                            onClick={(e) => { e.stopPropagation(); setIsSaveModalOpen(true); }}
                            title="Guardar"
                        >
                            <Bookmark className="w-5 h-5 stroke-[1.5]" />
                        </button>
                        <button
                            className="text-gray-500 hover:text-white transition-colors p-1"
                            onClick={handleShareClick}
                            title="Compartir"
                        >
                            <Share2 className="w-5 h-5 stroke-[1.5]" />
                        </button>
                    </div>
                </div>

                {/* Inline Comments Section */}
                {showComments && review.listId && review.id && (
                    <div className="border-t border-white/10 bg-[#0b1021]/50 p-4" onClick={e => e.stopPropagation()}>
                        <ReviewComments
                            listId={review.listId}
                            reviewId={review.id}
                            onCommentChange={handleCommentChange}
                        />
                    </div>
                )}
            </article>

            {/* Modals */}
            <SaveToArchiveModal
                isOpen={isSaveModalOpen}
                onClose={() => setIsSaveModalOpen(false)}
                item={{
                    itemId: review.id || '',
                    placeId: review.placeId || '',
                    name: review.itemName || review.placeName || '',
                    type: 'review',
                    route: review.placeId && review.itemName ? `/group/${review.placeId}/${encodeURIComponent(review.itemName)}` : '',
                    photoUrl: review.photoUrl
                }}
            />

            <ShareModal
                isOpen={isShareOpen}
                onClose={() => setIsShareOpen(false)}
                title={`Compartir Reseña`}
                url={`${window.location.origin}/group/${review.placeId}/${encodeURIComponent(review.itemName || '')}`}
                text={`¡Mira esta reseña de ${review.itemName} en ${review.placeName}!`}
                review={review}
            />

            <ReportModal
                isOpen={showReportModal}
                onClose={() => setShowReportModal(false)}
                targetId={review.id || ''}
                targetName={review.itemName || 'Reseña'}
                itemName={review.placeName}
                targetType="review"
            />
        </>
    );
};

import React from 'react';
import { Link } from 'react-router-dom';
import { MapPin, User } from 'lucide-react';
import { type ReviewEntity } from '../hooks/useListDetails';

interface ReviewCarouselItemProps {
    review: ReviewEntity;
    variant?: 'review' | 'item';
}

export const ReviewCarouselItem: React.FC<ReviewCarouselItemProps> = ({ review, variant = 'review' }) => {
    // Helper for score color (same as ReviewCard)
    const getScoreColor = (score: number) => {
        if (score >= 9) return 'bg-emerald-500 shadow-emerald-500/50 text-white';
        if (score >= 7) return 'bg-[#fcb900] shadow-amber-500/50 text-black'; // Specific yellow from image roughly
        if (score >= 5) return 'bg-indigo-500 shadow-indigo-500/50 text-white';
        return 'bg-rose-500 shadow-rose-500/50 text-white';
    };

    const scoreColorClass = getScoreColor(review.overallRating || 0);

    return (
        <article style={{ willChange: 'transform' }} className="relative w-[220px] h-[160px] md:w-[260px] md:h-[190px] rounded-3xl overflow-hidden shadow-lg border border-white/5 group bg-gray-900 flex-shrink-0 transition-transform hover:scale-105 duration-300">
            {/* Background Image */}
            <div className="absolute inset-0">
                {review.photoUrl || review.placeMainImage ? (
                    <img
                        src={review.photoUrl || review.placeMainImage}
                        alt={review.itemName}
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                    />
                ) : (
                    <div className="w-full h-full bg-gradient-to-br from-gray-800 to-gray-900 flex items-center justify-center">
                        <MapPin className="w-10 h-10 text-gray-700" />
                    </div>
                )}
                {/* Gradient Overlay for Text Readability */}
                <div className="absolute inset-x-0 bottom-0 h-3/4 bg-gradient-to-t from-[#0b1021]/95 via-[#0b1021]/40 to-transparent" />
            </div>

            {/* Top Elements */}
            <div className="absolute top-3 left-3 right-3 flex justify-between items-start z-10">

                {/* Top Left Pills */}
                {variant === 'review' ? (
                    <div className="flex flex-col items-start gap-1.5 max-w-[70%]">
                        {/* Author Bubble */}
                        <div className="flex items-center gap-2 bg-black/40 backdrop-blur-md border border-white/10 rounded-full pr-3 pl-1 py-1 shadow-lg">
                            <div className="w-6 h-6 rounded-full overflow-hidden border border-white/20 flex-shrink-0 bg-gray-700">
                                <img
                                    src={review.authorPhoto || `https://ui-avatars.com/api/?name=${review.authorName || 'User'}`}
                                    alt={review.authorName}
                                    className="w-full h-full object-cover"
                                />
                            </div>
                            <span className="text-[10px] font-bold text-white truncate leading-none">
                                {review.authorName?.split(' ')[0] || 'Anónimo'}
                            </span>
                        </div>

                        {/* City Bubble (Small, Below) */}
                        {(review as any).placeCity && (
                            <div className="flex items-center gap-1 bg-black/40 backdrop-blur-md border border-white/10 rounded-full px-2 py-0.5 shadow-lg ml-0.5">
                                <MapPin className="w-2.5 h-2.5 text-white/70" />
                                <span className="text-[9px] font-bold text-white/90 truncate leading-none uppercase tracking-wide">
                                    {(review as any).placeCity}
                                </span>
                            </div>
                        )}
                    </div>
                ) : (
                    // Item Variant: Single City Bubble
                    (review as any).placeCity ? (
                        <div className="flex items-center gap-1.5 bg-black/40 backdrop-blur-md border border-white/10 rounded-full px-2.5 py-1 shadow-lg max-w-[70%]">
                            <MapPin className="w-3 h-3 text-white/80" />
                            <span className="text-[10px] font-bold text-white truncate leading-none uppercase tracking-wide">
                                {(review as any).placeCity}
                            </span>
                        </div>
                    ) : null
                )}

                {/* Score Bubble */}
                <div className={`w-9 h-9 rounded-full flex items-center justify-center shadow-lg backdrop-blur-sm border border-white/10 ${scoreColorClass}`}>
                    <span className="font-display font-bold text-sm">
                        {review.overallRating?.toFixed(1) || '-'}
                    </span>
                </div>
            </div>

            {/* Bottom Content */}
            <div className="absolute bottom-3 left-3 right-3 z-10 text-left">
                <h3 className="text-white font-bold text-sm leading-tight mb-0.5 line-clamp-1 group-hover:text-indigo-300 transition-colors">
                    {review.itemName}
                </h3>

                <div className="flex items-center gap-1 text-[10px] text-gray-400 mb-1">
                    <MapPin className="w-3 h-3 flex-shrink-0" />
                    <span className="truncate">
                        {review.placeName}
                    </span>
                </div>

                {/* Tags (New) */}
                {review.tags && review.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1">
                        {review.tags.slice(0, 2).map((tag, idx) => (
                            <span key={idx} className="px-1.5 py-0.5 text-[9px] rounded-full bg-white/10 border border-white/10 text-gray-300">
                                {tag}
                            </span>
                        ))}
                    </div>
                )}
            </div>

            {/* Full Card Link */}
            <Link
                to={review.placeId ? `/group/${review.placeId}/${encodeURIComponent(review.itemName || review.placeName || '')}` : '#'}
                className="absolute inset-0 z-20"
                aria-label={`Ver reseña de ${review.itemName || review.placeName}`}
            />
        </article >
    );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { collection, addDoc, query, orderBy, onSnapshot, serverTimestamp, deleteDoc, doc } from 'firebase/firestore';
import { db } from '../firebase';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import { Send, Trash2 } from 'lucide-react';

interface Comment {
    id: string;
    userId: string;
    userName: string;
    userPhoto?: string;
    text: string;
    createdAt: any;
}

interface ReviewCommentsProps {
    listId: string;
    reviewId: string;
    placeId?: string;
    onClose?: () => void;
    onCommentChange?: (increment: number) => void;
}

export const ReviewComments: React.FC<ReviewCommentsProps> = ({ listId, reviewId, placeId, onClose, onCommentChange }) => {
    const { user } = useAuth();
    const [comments, setComments] = useState<Comment[]>([]);
    const [newComment, setNewComment] = useState('');
    const [submitting, setSubmitting] = useState(false);

    useEffect(() => {
        if (!listId || !reviewId) return;

        // Path: lists/{listId}/reviews/{reviewId}/comments
        const q = query(
            collection(db, 'lists', listId, 'reviews', reviewId, 'comments'),
            orderBy('createdAt', 'asc')
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            setComments(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Comment)));
        });
        return () => unsubscribe();
    }, [listId, reviewId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newComment.trim() || !user || !listId || !reviewId) return;

        setSubmitting(true);
        try {
            await addDoc(collection(db, 'lists', listId, 'reviews', reviewId, 'comments'), {
                userId: user.uid,
                userName: user.displayName || 'Usuario',
                userPhoto: user.photoURL || null,
                text: newComment.trim(),
                createdAt: serverTimestamp()
            });
            setNewComment('');
            if (onCommentChange) onCommentChange(1);
        } catch (error) {
            console.error("Error posting comment:", error);
        } finally {
            setSubmitting(false);
        }
    };

    const handleDelete = async (commentId: string) => {
        if (!confirm("¿Borrar comentario?") || !listId || !reviewId) return;
        try {
            await deleteDoc(doc(db, 'lists', listId, 'reviews', reviewId, 'comments', commentId));
            if (onCommentChange) onCommentChange(-1);
        } catch (error) {
            console.error(error);
        }
    };

    return (
        <div className="bg-[#0b1021]/50 border-t border-white/5 p-4 animate-in slide-in-from-top-2 duration-200">
            {/* List */}
            <div className="space-y-4 mb-4 max-h-60 overflow-y-auto custom-scrollbar">
                {comments.length === 0 && (
                    <p className="text-gray-500 text-xs text-center italic">Sé el primero en comentar...</p>
                )}
                {comments.map(comment => (
                    <div key={comment.id} className="flex gap-3 group">
                        <div className="w-8 h-8 rounded-full overflow-hidden shrink-0 border border-white/10">
                            <img src={comment.userPhoto || `https://ui-avatars.com/api/?name=${comment.userName}`} className="w-full h-full object-cover" />
                        </div>
                        <div className="flex-1">
                            <div className="bg-white/5 rounded-2xl rounded-tl-none p-3 relative">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-bold text-xs text-gray-300">{comment.userName}</span>
                                    {comment.createdAt && (
                                        <span className="text-[10px] text-gray-600">
                                            {formatDistanceToNow(comment.createdAt?.toDate ? comment.createdAt.toDate() : new Date(), { locale: es })}
                                        </span>
                                    )}
                                </div>
                                <p className="text-sm text-gray-200">{comment.text}</p>

                                {user?.uid === comment.userId && (
                                    <button
                                        onClick={() => handleDelete(comment.id)}
                                        className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-300 transition-opacity"
                                    >
                                        <Trash2 className="w-3 h-3" />
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Input */}
            {user && (
                <form onSubmit={handleSubmit} className="flex gap-2 relative">
                    <input
                        type="text"
                        value={newComment}
                        onChange={(e) => setNewComment(e.target.value)}
                        placeholder="Escribe un comentario..."
                        className="flex-1 bg-black/20 border border-white/10 rounded-full px-4 py-2 text-sm text-white outline-none focus:border-indigo-500 transition-colors"
                        disabled={submitting}
                    />
                    <button
                        type="submit"
                        disabled={!newComment.trim() || submitting}
                        className="p-2 bg-indigo-600 rounded-full text-white disabled:opacity-50 hover:bg-indigo-500 transition-colors"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </form>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useArchives, type SavedItemEntity } from '../hooks/useArchives';
import { Folder, Check, Plus, X } from 'lucide-react';

interface SaveToArchiveModalProps {
    isOpen: boolean;
    onClose: () => void;
    item: Omit<SavedItemEntity, 'savedAt' | 'id'>; // ID isn't needed for input, we generate it or ignore it
}

export const SaveToArchiveModal: React.FC<SaveToArchiveModalProps> = ({ isOpen, onClose, item }) => {
    const { archives, fetchArchives, createArchive, checkItemSavedStatus, toggleItemInArchive } = useArchives();
    const [initialSelectedIds, setInitialSelectedIds] = useState<string[]>([]);
    const [tempSelectedIds, setTempSelectedIds] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [newArchiveName, setNewArchiveName] = useState('');
    const [isCreating, setIsCreating] = useState(false);

    useEffect(() => {
        if (isOpen) {
            init();
        } else {
            // Reset states on close
            setTempSelectedIds([]);
            setInitialSelectedIds([]);
            setNewArchiveName('');
            setSaving(false);
        }
    }, [isOpen]);

    const init = async () => {
        setLoading(true);
        // Refresh archives to be sure we have the latest list
        await fetchArchives();
        // Check where it is currently saved
        const savedIds = await checkItemSavedStatus(item.itemId);
        setInitialSelectedIds(savedIds);
        setTempSelectedIds(savedIds);
        setLoading(false);
    };

    const handleToggle = (archiveId: string) => {
        setTempSelectedIds(prev => {
            if (prev.includes(archiveId)) {
                return prev.filter(id => id !== archiveId);
            } else {
                return [...prev, archiveId];
            }
        });
    };

    const handleCreate = async () => {
        if (!newArchiveName.trim()) return;
        setIsCreating(true);
        try {
            const newId = await createArchive(newArchiveName);
            if (newId) {
                // Auto select the new archive
                setTempSelectedIds(prev => [...prev, newId]);
                setNewArchiveName('');
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsCreating(false);
        }
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            // Calculate diffs
            const toAdd = tempSelectedIds.filter(id => !initialSelectedIds.includes(id));
            const toRemove = initialSelectedIds.filter(id => !tempSelectedIds.includes(id));

            // Execute in parallel
            await Promise.all([
                ...toAdd.map(id => toggleItemInArchive(id, { ...item, id: '', savedAt: null }, true)),
                ...toRemove.map(id => toggleItemInArchive(id, { ...item, id: '', savedAt: null }, false))
            ]);

            onClose();
        } catch (e) {
            console.error("Error saving archives:", e);
            alert("Hubo un error al guardar los cambios.");
        } finally {
            setSaving(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in" onClick={onClose}>
            <div
                className="bg-[#151b2e] rounded-2xl w-full max-w-sm border border-white/10 shadow-2xl overflow-hidden flex flex-col max-h-[80vh]"
                onClick={e => e.stopPropagation()}
            >

                {/* Header */}
                <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#0b1021]/50">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <Folder className="w-5 h-5 text-indigo-400" />
                        Guardar en...
                    </h3>
