                    )}
                </div>

                {/* Create New */}
                <div className="p-4 border-t border-white/5 bg-[#0b1021]/30">
                    <div className="flex gap-2 mb-4">
                        <input
                            type="text"
                            placeholder="Nueva colección..."
                            value={newArchiveName}
                            onChange={(e) => setNewArchiveName(e.target.value)}
