                        >
                            {isCreating ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Plus className="w-5 h-5" />}
                        </button>
                    </div>

                    {/* Actions */}
                    <button
                        onClick={handleSave}
