                    >
                        {saving ? 'Guardando...' : 'Hecho'}
                    </button>
                </div>

            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { X, Search, UserPlus, Check, Shield, Trash2, Users, Edit3, Eye } from 'lucide-react';
import { collection, query, where, getDocs, doc, updateDoc, arrayUnion, arrayRemove } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';

interface ShareListModalProps {
    isOpen: boolean;
    onClose: () => void;
    listId: string;
    listName: string;
    currentGuests?: string[]; // Readers
    currentEditors?: string[]; // Writers
    ownerId: string;
    onUpdate?: () => void; // Optional: Refresh list data in parent if needed, but we handle UI locally
}

export const ShareListModal: React.FC<ShareListModalProps> = ({
    isOpen,
    onClose,
    listId,
    listName,
    currentGuests = [],
    currentEditors = [],
    ownerId,
    onUpdate
}) => {
    const { user } = useAuth();
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResults, setSearchResults] = useState<any[]>([]);
    const [isSearching, setIsSearching] = useState(false);

    // Role Selection for new users
    const [selectedRole, setSelectedRole] = useState<'reader' | 'writer'>('reader');

    // Internal state for guests to update UI immediately
    const [readers, setReaders] = useState<string[]>(currentGuests);
    const [writers, setWriters] = useState<string[]>(currentEditors);

    // Sync props to state when modal opens
    useEffect(() => {
        if (isOpen) {
            setReaders(currentGuests || []);
            setWriters(currentEditors || []);
            setSearchTerm('');
            setSearchResults([]);
        }
    }, [isOpen, currentGuests, currentEditors]);

    // Search Users
    const handleSearch = async () => {
        if (!searchTerm.trim()) return;
        setIsSearching(true);
        try {
            const rawTerm = searchTerm.trim();
            // Firestore is case sensitive. We will try:
            // 1. As typed
            // 2. Lowercase
            // 3. Capitalized (first letter upper, rest lower) - Common for names

            const termsToTry = new Set<string>();
            termsToTry.add(rawTerm);
            termsToTry.add(rawTerm.toLowerCase());
            termsToTry.add(rawTerm.charAt(0).toUpperCase() + rawTerm.slice(1).toLowerCase());

            if (rawTerm.includes('@')) {
                // It's likely an email, simple matching
                const usersRef = collection(db, 'users');
                const qEmail = query(usersRef, where('email', '==', rawTerm));
                const snapEmail = await getDocs(qEmail);
                const results = snapEmail.docs.map(d => ({ id: d.id, ...d.data() }));

                // Filter
                const filtered = results.filter((u: any) => u.id !== user?.uid && u.id !== ownerId);
                setSearchResults(filtered);
                return;
            }

            const usersRef = collection(db, 'users');
            const promises = Array.from(termsToTry).map(async (t) => {
                const q = query(usersRef, where('username', '>=', t), where('username', '<=', t + '\uf8ff'));
                return getDocs(q);
            });

            const snapshots = await Promise.all(promises);
            let combinedResults: any[] = [];
            const seenIds = new Set<string>();

            snapshots.forEach(snap => {
                snap.docs.forEach(doc => {
                    if (!seenIds.has(doc.id)) {
                        seenIds.add(doc.id);
                        combinedResults.push({ id: doc.id, ...doc.data() });
                    }
                });
            });

            // Exclude self and owner
            combinedResults = combinedResults.filter((u: any) => u.id !== user?.uid && u.id !== ownerId);
            setSearchResults(combinedResults);

        } catch (error) {
            console.error("Error searching users:", error);
        } finally {
            setIsSearching(false);
        }
    };

    const handleAddUser = async (userIdentifier: string) => {
        // Add to the selected role list
        try {
            if (selectedRole === 'writer') {
                await updateDoc(doc(db, 'lists', listId), {
                    editors: arrayUnion(userIdentifier),
                    guests: arrayRemove(userIdentifier) // Ensure strictly one role
                });
                setWriters(prev => [...prev, userIdentifier]);
                setReaders(prev => prev.filter(g => g !== userIdentifier));
            } else {
                await updateDoc(doc(db, 'lists', listId), {
                    guests: arrayUnion(userIdentifier),
                    editors: arrayRemove(userIdentifier)
                });
                setReaders(prev => [...prev, userIdentifier]);
                setWriters(prev => prev.filter(e => e !== userIdentifier));
            }

            // Do NOT reload, just update state (already done above)
            // if (onUpdate) onUpdate(); // Optional background refresh
        } catch (error) {
            console.error("Error adding user:", error);
            alert("Error al añadir usuario");
        }
    };

    const handleRemoveUser = async (userIdentifier: string, fromRole: 'reader' | 'writer') => {
        try {
            if (fromRole === 'writer') {
                await updateDoc(doc(db, 'lists', listId), {
                    editors: arrayRemove(userIdentifier)
                });
                setWriters(writers.filter(w => w !== userIdentifier));
            } else {
                await updateDoc(doc(db, 'lists', listId), {
                    guests: arrayRemove(userIdentifier)
                });
                setReaders(readers.filter(r => r !== userIdentifier));
            }
        } catch (error) {
            console.error("Error removing user:", error);
            alert("Error al eliminar usuario");
        }
    };

    if (!isOpen) return null;
    if (user?.uid !== ownerId) return null; // Only owner can share

    // Helper to check status
    const getUserStatus = (identifier: string) => {
        if (writers.includes(identifier)) return 'writer';
        if (readers.includes(identifier)) return 'reader';
        return null;
    };

    const allGuests = [...new Set([...writers, ...readers])]; // Unique identifiers

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
            <div className="bg-[#151b2e] w-full max-w-lg rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

                {/* Header */}
                <div className="p-4 border-b border-white/5 flex items-center justify-between bg-[#0b1021]/50">
                    <div>
                        <h2 className="text-xl font-bold text-white flex items-center gap-2">
                            <Users className="w-5 h-5 text-indigo-400" />
                            Compartir Lista
                        </h2>
                        <p className="text-xs text-gray-500 truncate max-w-[300px]">{listName}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                        <X className="w-5 h-5 text-gray-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="p-6 overflow-y-auto custom-scrollbar">

                    {/* Access Level Info */}
                    <div className="mb-6 bg-indigo-500/10 border border-indigo-500/20 rounded-lg p-3">
                        <div className="flex gap-3">
                            <Shield className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                            <div>
                                <h4 className="text-sm font-bold text-indigo-300">Roles de Acceso</h4>
                                <ul className="text-xs text-indigo-200/70 mt-1 list-disc list-inside space-y-1">
                                    <li><strong>Lector:</strong> Puede ver la lista (si es privada).</li>
                                    <li><strong>Escritor:</strong> Puede ver y <u>añadir reseñas</u>.</li>
                                </ul>
                            </div>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="mb-8">
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">Añadir Personas</label>
                        <div className="flex gap-2 mb-2">
                            <div className="relative flex-1">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                                <input
                                    type="text"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                                    placeholder="Buscar por nombre de usuario..."
                                    className="w-full bg-[#0b1021] border border-white/10 rounded-lg pl-9 pr-4 py-2 text-sm text-white focus:outline-none focus:border-indigo-500"
                                />
                            </div>

                            {/* Role Selector for Search */}
                            <div className="flex bg-[#0b1021] border border-white/10 rounded-lg p-0.5 shrink-0 h-10 items-center">
                                <button
                                    onClick={() => setSelectedRole('reader')}
                                    className={`px-3 py-1.5 rounded-md text-xs font-bold transition-colors ${selectedRole === 'reader' ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white'} `}
                                    title="Añadir como Lector"
                                >
                                    <Eye className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={() => setSelectedRole('writer')}
                                    className={`px-3 py-1.5 rounded-md text-xs font-bold transition-colors ${selectedRole === 'writer' ? 'bg-purple-600 text-white' : 'text-gray-400 hover:text-white'} `}
                                    title="Añadir como Escritor"
                                >
                                    <Edit3 className="w-4 h-4" />
                                </button>
                            </div>

                            <button
                                onClick={handleSearch}
                                disabled={isSearching}
                                className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/5 rounded-lg text-sm font-medium transition-colors"
                            >
                                {isSearching ? '...' : 'Buscar'}
                            </button>
                        </div>

                        <div className="text-xs text-gray-500 mb-2">
                            Añadiendo como: <span className={`font-bold ${selectedRole === 'writer' ? 'text-purple-400' : 'text-indigo-400'} `}>{selectedRole === 'writer' ? 'Escritor' : 'Lector'}</span>
                        </div>

                        {/* Search Results */}
                        {searchResults.length > 0 && (
                            <div className="mt-2 bg-[#0b1021] border border-white/5 rounded-lg overflow-hidden">
                                {searchResults.map(u => {
                                    const status = getUserStatus(u.username) || getUserStatus(u.email);

                                    return (
                                        <div key={u.id} className="p-3 flex items-center justify-between hover:bg-white/5 transition-colors border-b border-white/5 last:border-0">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden">
                                                    {u.photoURL ? <img src={u.photoURL} alt={u.username} className="w-full h-full object-cover" /> : null}
                                                </div>
                                                <div>
                                                    <p className="text-sm font-medium text-white">{u.displayName || u.username}</p>
                                                    <p className="text-xs text-gray-500">@{u.username}</p>
                                                </div>
                                            </div>

                                            {status ? (
                                                <span className={`px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1 ${status === 'writer' ? 'bg-purple-500/20 text-purple-400' : 'bg-green-500/20 text-green-400'} `}>
                                                    <Check className="w-3 h-3" /> {status === 'writer' ? 'Escritor' : 'Lector'}
                                                </span>
                                            ) : (
                                                <button
                                                    onClick={() => handleAddUser(u.username || u.email)}
                                                    className={`px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1 ${selectedRole === 'writer' ? 'bg-purple-600 hover:bg-purple-500 text-white' : 'bg-indigo-600 hover:bg-indigo-500 text-white'} `}
                                                >
                                                    <UserPlus className="w-3 h-3" /> Añadir
                                                </button>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    {/* Current Guests */}
                    <div>
                        <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-2">
                            Usuarios con Acceso ({allGuests.length})
                        </label>

                        {allGuests.length === 0 ? (
                            <div className="text-center py-8 border border-dashed border-white/10 rounded-lg">
                                <p className="text-gray-500 text-sm">No hay usuarios añadidos.</p>
                            </div>
                        ) : (
                            <div className="space-y-2">
                                {allGuests.map((identifier, idx) => {
                                    const role = getUserStatus(identifier) || 'reader';
                                    return (
                                        <div key={idx} className="bg-[#0b1021] border border-white/5 rounded-lg p-3 flex items-center justify-between group">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${role === 'writer' ? 'bg-purple-500/20 text-purple-400' : 'bg-indigo-500/20 text-indigo-400'} `}>
                                                    {identifier[0].toUpperCase()}
                                                </div>
                                                <div>
                                                    <span className="text-sm text-gray-300 block">{identifier}</span>
                                                    <span className={`text-[10px] uppercase font-bold ${role === 'writer' ? 'text-purple-500' : 'text-indigo-500'} `}>{role === 'writer' ? 'Escritor' : 'Lector'}</span>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => handleRemoveUser(identifier, role)}
                                                className="p-2 text-gray-600 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                                                title="Eliminar acceso"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { X, Plus, ChevronRight, Layers } from 'lucide-react';
import { collection, query, where, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Link } from 'react-router-dom';
import { CreateListForm } from './CreateListForm';
import { type ListEntity } from '../hooks/useLists';

interface SublistsModalProps {
    listId: string;
    listName: string;
    isOpen: boolean;
    onClose: () => void;
    sublists?: ListEntity[] | null;
    parentCriteria?: Record<string, any>; // Criteria from parent list
    parentTags?: string[]; // Tags from parent list
}

export const SublistsModal: React.FC<SublistsModalProps> = ({ listId, listName, isOpen, onClose, sublists: initialSublists, parentCriteria, parentTags }) => {
    const [view, setView] = useState<'list' | 'create'>('list');
    const [sublists, setSublists] = useState<ListEntity[]>([]);
    const [loading, setLoading] = useState(true);

    // Fetch Sublists
    const fetchSublists = async () => {
        setLoading(true);
        try {
            const q = query(
                collection(db, 'lists'),
                where('parentListId', '==', listId),
                orderBy('createdAt', 'desc')
            );
            const snapshot = await getDocs(q);
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as ListEntity[];
            setSublists(data);
        } catch (error) {
            console.error("Error fetching sublists:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (isOpen) {
            if (initialSublists && initialSublists.length > 0) {
                setSublists(initialSublists);
                setLoading(false);
            } else {
                fetchSublists();
            }
            setView('list'); // Reset view on open
        }
    }, [isOpen, listId, initialSublists]);

    const handleCreateSuccess = (newListId: string) => {
        // Refresh list and go back to list view
        fetchSublists();
        setView('list');
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
            <div className="bg-[#151b2e] w-full max-w-2xl rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">

                {/* Header */}
                <div className="p-4 border-b border-white/10 flex items-center justify-between bg-[#0b1021]">
                    <h2 className="text-xl font-bold text-white flex items-center gap-2">
                        {view === 'create' && (
                            <button onClick={() => setView('list')} className="mr-2 hover:bg-white/10 p-1 rounded-full transition-colors">
                                <ChevronRight className="w-5 h-5 rotate-180" />
                            </button>
                        )}
                        <Layers className="w-5 h-5 text-indigo-400" />
                        {view === 'create' ? 'Nueva Sublista' : `Sublistas de ${listName}`}
                    </h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
                        <X className="w-6 h-6" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-gray-700 scrollbar-track-transparent">
                    {view === 'list' ? (
                        <div className="space-y-4">
                            <div className="flex justify-between items-center mb-4">
                                <p className="text-sm text-gray-400">
                                    Las sublistas heredan el contexto de la lista principal pero pueden tener sus propias reseñas.
                                </p>
                                <button
                                    onClick={() => setView('create')}
                                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg text-sm font-bold transition-colors shadow-lg shadow-indigo-500/20"
                                >
                                    <Plus className="w-4 h-4" />
                                    Crear Sublista
                                </button>
                            </div>

                            {loading ? (
                                <div className="space-y-3">
                                    {[1, 2, 3].map(i => (
                                        <div key={i} className="h-16 bg-white/5 rounded-xl animate-pulse" />
                                    ))}
                                </div>
                            ) : sublists.length > 0 ? (
                                <div className="grid gap-3">
                                    {sublists.map(list => (
                                        <Link
                                            key={list.id}
                                            to={`/list/${list.id}`}
                                            className="flex items-center gap-4 p-3 rounded-xl bg-[#0b1021] border border-white/5 hover:border-indigo-500/50 hover:bg-[#1a2035] transition-all group"
                                        >
                                            <div className="w-12 h-12 rounded-lg bg-gray-800 flex-shrink-0 overflow-hidden">
                                                {list.mainImageUrl || list.photoUrl ? (
                                                    <img src={list.mainImageUrl || list.photoUrl} alt="" className="w-full h-full object-cover" />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center text-xl bg-indigo-900/20">📃</div>
                                                )}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <h3 className="font-bold text-white truncate group-hover:text-indigo-400 transition-colors">{list.name}</h3>
                                                <p className="text-xs text-gray-500 truncate">{list.itemCount || 0} reseñas</p>
                                            </div>
                                            <ChevronRight className="w-5 h-5 text-gray-600 group-hover:text-white transition-colors" />
                                        </Link>
                                    ))}
                                </div>
                            ) : (
                                <div className="text-center py-10 border-2 border-dashed border-white/5 rounded-xl">
                                    <Layers className="w-12 h-12 text-gray-600 mx-auto mb-3" />
                                    <p className="text-gray-400">No hay sublistas todavía.</p>
                                    <button
                                        onClick={() => setView('create')}
                                        className="text-indigo-400 hover:text-indigo-300 text-sm font-bold mt-2"
                                    >
                                        Crear la primera
                                    </button>
                                </div>
                            )}
                        </div>
                    ) : (
                        <CreateListForm
                            parentListId={listId}
                            parentListName={listName}
                            parentCriteria={parentCriteria}
                            parentTags={parentTags}
                            onSuccess={handleCreateSuccess}
                            onCancel={() => setView('list')}
                            initialData={{
                                name: `${listName} (Sublista)`
                            }}
                        />
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { useAppConfig } from '../../context/AppConfigContext';
import { db, storage } from '../../firebase';
import { doc, setDoc } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { Upload, Save, Layout, Image as ImageIcon, Type, Globe, CheckCircle, AlertCircle } from 'lucide-react';

export const BrandingManager: React.FC = () => {
    const config = useAppConfig();
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    // Form State (initialize with current config)
    const [logoType, setLogoType] = useState<'default' | 'image'>(config.logoType);
    const [faviconType, setFaviconType] = useState<'default' | 'image'>(config.faviconType || 'default');
    const [appName, setAppName] = useState(config.appName);
    const [appDescription, setAppDescription] = useState(config.appDescription);
    const [logoPreview, setLogoPreview] = useState<string | null>(config.logoUrl || null);
    const [faviconPreview, setFaviconPreview] = useState<string | null>(config.faviconUrl || null);

    const logoInputRef = useRef<HTMLInputElement>(null);
    const faviconInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, type: 'logo' | 'favicon') => {
        if (!e.target.files || e.target.files.length === 0) return;
        const file = e.target.files[0];

        // Create local preview
        const reader = new FileReader();
        reader.onload = (ev) => {
            if (type === 'logo') setLogoPreview(ev.target?.result as string);
            else {
                setFaviconPreview(ev.target?.result as string);
                setFaviconType('image'); // Auto-switch to image when uploading
            }
        };
        reader.readAsDataURL(file);
    };

    const handleSave = async () => {
        setLoading(true);
        setMessage(null);

        try {
            let newLogoUrl = config.logoUrl;
            let newFaviconUrl = config.faviconUrl;

            // Upload Logo if changed
            if (logoInputRef.current?.files?.length) {
                const file = logoInputRef.current.files[0];
                const storageRef = ref(storage, `branding/logo_${Date.now()}.png`);
                await uploadBytes(storageRef, file);
                newLogoUrl = await getDownloadURL(storageRef);
            }

            // Upload Favicon if changed
            if (faviconInputRef.current?.files?.length) {
                const file = faviconInputRef.current.files[0];
                const storageRef = ref(storage, `branding/favicon_${Date.now()}.png`);
                await uploadBytes(storageRef, file);
                newFaviconUrl = await getDownloadURL(storageRef);
            }

            // Save Config to Firestore
            await setDoc(doc(db, 'config', 'app'), {
                logoType,
                faviconType,
                appName,
                appDescription,
                logoUrl: newLogoUrl || null,
                faviconUrl: newFaviconUrl || null,
                updatedAt: new Date()
            }, { merge: true });

            setMessage({ type: 'success', text: 'Configuración actualizada correctamente' });
        } catch (error: any) {
            console.error("Error saving branding:", error);
            setMessage({ type: 'error', text: error.message || 'Error al guardar' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <h2 className="text-2xl font-bold text-white mb-6 flex items-center gap-2">
                <Layout className="w-6 h-6 text-pink-500" /> Gestión de Marca
            </h2>

            {/* MESSAGE ALERT */}
            {message && (
                <div className={`p-4 rounded-xl border flex items-center gap-3 ${message.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-red-500/10 border-red-500/20 text-red-400'
                    }`}>
                    {message.type === 'success' ? <CheckCircle className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
                    {message.text}
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

                {/* --- LOGO SETTINGS --- */}
                <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 space-y-6">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <ImageIcon className="w-5 h-5 text-indigo-400" /> Logotipo Principal
                    </h3>

                    {/* Type Selection */}
                    <div className="flex gap-4 p-1 bg-black/20 rounded-lg">
                        <button
                            onClick={() => setLogoType('default')}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${logoType === 'default' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Default (CSS)
                        </button>
                        <button
                            onClick={() => setLogoType('image')}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${logoType === 'image' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Imagen Personalizada
                        </button>
                    </div>

                    {/* Preview Area */}
                    <div className="h-32 bg-black/40 rounded-xl border border-dashed border-white/10 flex items-center justify-center overflow-hidden relative group">
                        {logoType === 'default' ? (
                            <div className="flex items-center gap-3">
                                <div className="relative w-10 h-10 rounded-xl bg-gradient-to-tr from-cyan-500 via-blue-600 to-indigo-600 flex items-center justify-center shadow-lg">
                                    <div className="w-4 h-4 bg-white rounded-full shadow-sm" />
                                </div>
                                <span className="text-xl font-bold text-white tracking-tight">LISTOPIC</span>
                            </div>
                        ) : (
                            logoPreview ? (
                                <img src={logoPreview} alt="Logo Preview" className="h-full object-contain" />
                            ) : (
                                <span className="text-gray-500 text-sm">Sin imagen seleccionada</span>
                            )
                        )}

                        {/* Overlay Upload Button (Only for Image Type) */}
                        {logoType === 'image' && (
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                <button
                                    onClick={() => logoInputRef.current?.click()}
                                    className="px-4 py-2 bg-white text-black font-bold rounded-lg flex items-center gap-2"
                                >
                                    <Upload className="w-4 h-4" /> Cambiar
                                </button>
                            </div>
                        )}
                    </div>

                    <input
                        type="file"
                        ref={logoInputRef}
                        className="hidden"
                        accept="image/png,image/jpeg,image/svg+xml"
                        onChange={(e) => handleFileChange(e, 'logo')}
                    />

                    <p className="text-xs text-gray-500">
                        * Default usa el logo CSS animado. Imagen reemplaza todo el bloque del logo en el Navbar. Recomendado PNG transparente o SVG.
                    </p>
                </div>

                {/* --- FAVICON SETTINGS --- */}
                <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 space-y-6">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <Globe className="w-5 h-5 text-indigo-400" /> Favicon (Navegador)
                    </h3>

                    {/* Type Selection */}
                    <div className="flex gap-4 p-1 bg-black/20 rounded-lg">
                        <button
                            onClick={() => setFaviconType('default')}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${faviconType === 'default' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Default (Logo)
                        </button>
                        <button
                            onClick={() => setFaviconType('image')}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${faviconType === 'image' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Imagen Personalizada
                        </button>
                    </div>

                    <div className="flex items-center gap-6">
                        <div className="w-20 h-20 bg-black/40 rounded-xl border border-dashed border-white/10 flex items-center justify-center shrink-0 relative group">
                            {faviconType === 'default' ? (
                                <img src="/default_favicon.svg" className="w-10 h-10 object-contain" alt="Default Favicon" />
                            ) : (
                                faviconPreview ? (
                                    <img src={faviconPreview} className="w-10 h-10 object-contain" alt="Custom Favicon" />
                                ) : (
                                    <span className="text-gray-500 text-xs text-center px-2">Sin imagen</span>
                                )
                            )}

                            {faviconType === 'image' && (
                                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center rounded-xl">
                                    <button
                                        onClick={() => faviconInputRef.current?.click()}
                                        className="p-2 bg-white text-black rounded-lg"
                                    >
                                        <Upload className="w-4 h-4" />
                                    </button>
                                </div>
                            )}
                        </div>
                        <div className="flex-1">
                            <p className="text-sm text-gray-300 mb-2">Icono de pestaña</p>
                            <p className="text-xs text-gray-500">
                                {faviconType === 'default'
                                    ? 'Usa el logotipo degradado de la aplicación.'
                                    : 'Sube tu propia imagen (64x64px o SVG recomendado).'
                                }
                            </p>
                        </div>
                    </div>
                    <input
                        type="file"
                        ref={faviconInputRef}
                        className="hidden"
                        accept="image/png,image/x-icon,image/svg+xml,image/jpeg"
                        onChange={(e) => handleFileChange(e, 'favicon')}
                    />
                </div>

                {/* --- SEO & METADATA --- */}
                <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 space-y-6 md:col-span-2">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
