import { useState, useEffect } from 'react';

export interface Location {
    latitude: number;
    longitude: number;
}

export const useLocation = () => {
    const [location, setLocation] = useState<Location | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState<boolean>(true);

    useEffect(() => {
        if (!navigator.geolocation) {
            setError('Geolocalización no soportada por el navegador');
            setLoading(false);
            return;
        }

        const success = (position: GeolocationPosition) => {
            setLocation({
                latitude: position.coords.latitude,
                longitude: position.coords.longitude
            });
            setLoading(false);
        };

        const fail = (err: GeolocationPositionError) => {
            setError(err.message);
            setLoading(false);
            console.warn('Error obteniendo ubicación:', err);
        };

        // Solicitar ubicación al montar
        navigator.geolocation.getCurrentPosition(success, fail);
    }, []);

    // Fórmula del Haversine para calcular distancia en km
    const calculateDistance = (targetLat: number, targetLng: number): number | null => {
        if (!location) return null;

        const toRad = (value: number) => (value * Math.PI) / 180;
        const R = 6371; // Radio de la Tierra en km

        const dLat = toRad(targetLat - location.latitude);
        const dLon = toRad(targetLng - location.longitude);
        const lat1 = toRad(location.latitude);
        const lat2 = toRad(targetLat);

        const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.sin(dLon / 2) * Math.sin(dLon / 2) * Math.cos(lat1) * Math.cos(lat2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        return R * c;
    };

    const requestLocation = () => {
        setLoading(true);
        setError(null);
        if (!navigator.geolocation) {
            setError('Geolocalización no soportada');
            setLoading(false);
            return;
        }
        navigator.geolocation.getCurrentPosition(
            (position) => {
                setLocation({
                    latitude: position.coords.latitude,
                    longitude: position.coords.longitude
                });
                setLoading(false);
            },
            (err) => {
                setError(err.message);
                setLoading(false);
            }
        );
    };

    return { location, error, loading, calculateDistance, requestLocation };
};

import { useState, useEffect } from 'react';
import { collection, query, where, getDocs, doc, getDoc, limit } from 'firebase/firestore';
import { db } from '../firebase';
import { type ReviewEntity } from './useListDetails';

export interface PlaceDetails {
    placeId: string;
    name: string;
    photoUrl?: string;
    address?: string;
    avgScore: number;
    reviewCount: number;
    reviews: ReviewEntity[];
    relatedLists: { id: string; name: string; authorName?: string; parentListId?: string; photoUrl?: string; }[];
    coords?: { lat: number; lng: number };
    googleRating?: number;
    googleUserRatingCount?: number;
    // Rich Data Fields
    website?: string;
    phone?: string;
    priceLevel?: number; // 0-4
    googleMapsUri?: string;
    accessibility?: {
        wheelchairAccessibleEntrance?: boolean;
        wheelchairAccessibleRestroom?: boolean;
        wheelchairAccessibleSeating?: boolean;
    };
    options?: {
        delivery?: boolean;
        takeout?: boolean;
        dineIn?: boolean;
        reservable?: boolean;
        servesBeer?: boolean;
        servesWine?: boolean;
        servesBreakfast?: boolean;
        servesLunch?: boolean;
        servesDinner?: boolean;
    };
    openingHours?: string[]; // Array of strings if available
    category?: string;
}

const toMillis = (value: any): number => {
    if (!value) return 0;
    if (typeof value?.toMillis === 'function') return value.toMillis();
    if (typeof value?.seconds === 'number') return value.seconds * 1000;
    return 0;
};

export const usePlaceDetails = (placeId: string | undefined) => {
    const [place, setPlace] = useState<PlaceDetails | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchPlaceDetails = async () => {
        if (!placeId) {
            setLoading(false);
            return;
        }

        setLoading(true);
        try {
            // 1. Fetch detailed Place info from 'places' collection
            const placeDocRef = doc(db, 'places', placeId);
            const placeDocSnap = await getDoc(placeDocRef);
            const placeData = placeDocSnap.exists() ? placeDocSnap.data() : null;

            // 2. Build candidate readable lists and fetch place reviews from each subcollection.
            const { getAuth } = await import('firebase/auth');
            const currentUser = getAuth().currentUser;

            const [publicListsSnap, followingListsSnap, ownListsSnap] = await Promise.all([
                getDocs(query(collection(db, 'lists'), where('isPublic', '==', true), limit(60))),
                currentUser ? getDocs(query(collection(db, 'users', currentUser.uid, 'followingLists'), limit(60))) : Promise.resolve(null),
                currentUser ? getDocs(query(collection(db, 'lists'), where('userId', '==', currentUser.uid), limit(40))) : Promise.resolve(null)
            ]);

            const candidateListIds = Array.from(new Set([
                ...publicListsSnap.docs.map((d) => d.id),
                ...(followingListsSnap ? followingListsSnap.docs.map((d) => d.id) : []),
                ...(ownListsSnap ? ownListsSnap.docs.map((d) => d.id) : [])
            ])).slice(0, 80);

            const reviewsByList = await Promise.all(candidateListIds.map(async (listId) => {
                try {
                    const listReviewsSnap = await getDocs(
                        query(collection(db, 'lists', listId, 'reviews'), where('placeId', '==', placeId), limit(20))
                    );
                    return listReviewsSnap.docs.map((reviewDoc) => ({
                        id: reviewDoc.id,
                        ...(reviewDoc.data() as any),
                        listId
                    } as ReviewEntity));
                } catch (error: any) {
                    if (error?.code !== 'permission-denied') {
                        console.warn(`Failed loading place reviews for list ${listId}`, error);
                    }
                    return [] as ReviewEntity[];
                }
            }));

            const reviewMap = new Map<string, ReviewEntity>();
            for (const listReviews of reviewsByList) {
                for (const review of listReviews) {
                    reviewMap.set(`${review.listId || 'unknown'}:${review.id}`, review);
                }
            }

            const reviews = Array.from(reviewMap.values()).sort((a: any, b: any) => toMillis(b.createdAt) - toMillis(a.createdAt));

            if (reviews.length === 0 && !placeData) {
                setError("No se encontraron datos para este lugar.");
                setLoading(false);
                return;
            }

            // 2.5 Enrich with Authors (Fix for missing authors)
            const userIds = [...new Set(reviews.map(r => r.userId || r.authorId).filter(Boolean))] as string[];
            const usersMap: Record<string, any> = {};

            if (userIds.length > 0) {
                await Promise.all(userIds.slice(0, 20).map(async (uid) => {
                    try {
                        const userSnap = await getDoc(doc(db, 'users', uid));
                        if (userSnap.exists()) {
                            usersMap[uid] = userSnap.data();
                        }
                    } catch (e) { console.warn("Failed fetch user", uid); }
                }));
            }

            // 3. Fetch List Info for Context (Fix for missing List Name)
            // 3. Fetch List Info for Context (Fix for missing List Name & Criteria)
            const listIds = [...new Set(reviews.map(r => r.listId).filter(Boolean))] as string[];
            const listsMap: Record<string, any> = {}; // Store full list data
            const relatedLists: { id: string; name: string; authorName?: string; parentListId?: string; photoUrl?: string; }[] = [];

            if (listIds.length > 0) {
                await Promise.all(listIds.slice(0, 20).map(async (lid) => {
                    try {
                        const listSnap = await getDoc(doc(db, 'lists', lid));
                        if (listSnap.exists()) {
                            const d = listSnap.data();
                            listsMap[lid] = d; // Store full data
                            if (relatedLists.length < 10) {
                                relatedLists.push({
                                    id: lid,
                                    name: d.name,
                                    authorName: d.authorName,
                                    parentListId: d.parentListId,
                                    photoUrl: d.photoUrl
                                });
                            }
                        }
                    } catch (e) { console.warn("Failed fetch list", lid); }
                }));
            }

            const enrichedReviews = reviews.map(r => {
                const uid = r.userId || r.authorId;
                const user = uid ? usersMap[uid] : null;
                const listData = r.listId ? listsMap[r.listId] : undefined;

                return {
                    ...r,
                    authorName: user?.displayName || user?.name || user?.username || r.authorName || 'Anónimo',
                    authorPhoto: user?.photoUrl || user?.photoURL || r.authorPhoto,
                    listName: listData?.name || r.listName, // Enrich list name
                    criteriaDefinition: listData?.criteriaDefinition || r.criteriaDefinition, // Enrich criteria for charts
                    // Enrich Place Data for ReviewCard fallback
                    placeMainImage: placeData?.mainImageUrl || placeData?.photos?.[0],
                    placeName: placeData?.name || r.placeName,
                    placeCity: placeData?.city || r.placeCity
                };
            });

            // Enrichment
            const avgScore = reviews.length
                ? reviews.reduce((sum, r) => sum + (r.overallRating || 0), 0) / reviews.length
                : (placeData?.rating || placeData?.avgScore || 0);

            const name = placeData?.name || reviews[0]?.itemName || "Lugar";
            const photoUrl = placeData?.mainImageUrl || placeData?.photos?.[0] || reviews.find(r => r.photoUrl)?.photoUrl;
            const address = placeData?.formattedAddress || placeData?.address;

            let coords = undefined;
            if (placeData?.location) {
                coords = { lat: placeData.location.latitude, lng: placeData.location.longitude };
            } else if (reviews.find(r => r.lat && r.lng)) {
                const r = reviews.find(r => r.lat && r.lng);
                coords = { lat: r!.lat!, lng: r!.lng! };
            }

            // Map Rich Data
            // Note: We safely access properties assuming standard Google Places Fields naming or custom internal naming
            const website = placeData?.websiteUri || placeData?.website;
            const phone = placeData?.formattedPhoneNumber || placeData?.internationalPhoneNumber;
            const priceLevel = placeData?.priceLevel; // e.g., PRICE_LEVEL_MODERATE or number
            const googleMapsUri = placeData?.googleMapsUrl || placeData?.googleMapsUri;

            const accessibility = placeData?.accessibilityOptions ? {
                wheelchairAccessibleEntrance: placeData.accessibilityOptions.wheelchairAccessibleEntrance,
                wheelchairAccessibleRestroom: placeData.accessibilityOptions.wheelchairAccessibleRestroom
            } : placeData?.accessibility; // Fallback to raw accessibility map if storing legacy structure

            // Map Service Options (from 'serviceOptions' map or root fields fallback)
            const optsSrc = placeData?.serviceOptions || placeData;
            const options = {
                delivery: optsSrc?.delivery,
                takeout: optsSrc?.takeout,
                dineIn: optsSrc?.dineIn || optsSrc?.dine_in,
                reservable: optsSrc?.reservable,
                servesBeer: optsSrc?.servesBeer || optsSrc?.serves_beer,
                servesWine: optsSrc?.servesWine || optsSrc?.serves_wine,
                servesBreakfast: optsSrc?.servesBreakfast || optsSrc?.serves_breakfast,
                servesLunch: optsSrc?.servesLunch || optsSrc?.serves_lunch,
                servesDinner: optsSrc?.servesDinner || optsSrc?.serves_dinner
            };

            const openingHours = placeData?.currentOpeningHours?.weekdayDescriptions || placeData?.openingHours;

            const googleRating = placeData?.googleRating || placeData?.rating;
            const googleUserRatingCount = placeData?.userRatingCount || placeData?.user_ratings_total;
            const category = placeData?.category || placeData?.types?.[0]; // Fallback to first type

            setPlace({
                placeId,
                name,
                photoUrl,
                address,
                avgScore,
                reviewCount: reviews.length,
                reviews: enrichedReviews,
                relatedLists,
                coords,
                website,
                phone,
                priceLevel,
                googleMapsUri,
                accessibility,
                options,
                openingHours,
                googleRating,
                googleUserRatingCount,
                category
            });

        } catch (err: any) {
            console.error("Error fetching place details:", err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPlaceDetails();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [placeId]);

    return { place, loading, error, refresh: () => fetchPlaceDetails() };
};

import { useState, useEffect } from 'react';
import { collection, collectionGroup, query, orderBy, limit, getDocs, doc, getDoc, where, startAfter } from 'firebase/firestore';
import { db } from '../firebase';
import { type ReviewEntity } from './useListDetails';

// Helper to dedup IDs
const uniqueIds = (ids: (string | undefined)[]) => [...new Set(ids.filter((id): id is string => !!id))];

// Simplified batch fetcher
const fetchDocsBatch = async (collectionName: string, ids: string[]) => {
    if (!ids.length) return {};
    // Firestore 'in' limit is 10, preventing simplified batching for large sets without chunking
    // For MVP, we'll fetch individually or use a simple loop if the set is small (20 reviews max means ~20 lists max)
    const docsMap: Record<string, any> = {};
    await Promise.all(ids.map(async (id) => {
        try {
            const snap = await getDoc(doc(db, collectionName, id));
            if (snap.exists()) docsMap[id] = snap.data();
        } catch (e: any) {
            // Ignore permission/not-found errors which are expected for private lists/items
            if (e.code === 'permission-denied' || e.code === 'not-found') {
                return;
            }
            console.warn(`Failed to fetch ${collectionName} ${id}`, e);
        }
    }));
    return docsMap;
};

const enrichRawReviews = async (rawReviews: ReviewEntity[]): Promise<ReviewEntity[]> => {
    if (!rawReviews.length) return [];
    const listIds = uniqueIds(rawReviews.map(r => r.listId));
    const placeIds = uniqueIds(rawReviews.map(r => r.placeId));
    const userIds = uniqueIds(rawReviews.map(r => (r as any).userId || (r as any).authorId)); // 'authorId' legacy fallback

    const [listsMap, placesMap, usersMap] = await Promise.all([
        fetchDocsBatch('lists', listIds),
        fetchDocsBatch('places', placeIds),
        fetchDocsBatch('users', userIds)
    ]);

    return rawReviews.map(review => {
        const list = review.listId ? listsMap[review.listId] : null;
        const place = review.placeId ? placesMap[review.placeId] : null;
        const reviewAny = review as any;
        const userId = reviewAny.userId || reviewAny.authorId;
        const user = userId && usersMap[userId] ? usersMap[userId] : null;

        // Cast as any to access legacy 'establishmentName' if it exists on the record but not on the type yet
        const legacyReview = review as any;

        return {
            ...review,
            listName: list?.name,
            criteriaDefinition: list?.criteriaDefinition, // Critical for charts
            placeName: place?.name || legacyReview.establishmentName, // Legacy fallback
            placeMainImage: place?.mainImageUrl || place?.photos?.[0],
            placeAverageRating: place?.averageRating,
            placeAddress: place?.address,
            authorName: user?.displayName || user?.name || user?.username || legacyReview.authorName,
            authorPhoto: user?.photoUrl || user?.photoURL || legacyReview.authorPhoto,
            placeLat: place?.location?.latitude || place?.lat || place?.latitude || legacyReview.lat || legacyReview.placeLat,
            placeLng: place?.location?.longitude || place?.lng || place?.longitude || legacyReview.lng || legacyReview.placeLng,
            placeCity: place?.city || (place?.address ? place.address.split(',').pop()?.trim() : '')
        };
    }) as ReviewEntity[];
};

const fetchPublicReviewsFromListSubcollections = async (
    type: 'recent' | 'trending' | 'following',
    options: {
        pageLimit: number;
        followingIds?: string[];
    }
) => {
    const { pageLimit, followingIds } = options;

    const publicListsSnapshot = await getDocs(
        query(collection(db, 'lists'), where('isPublic', '==', true), limit(40))
    );
    const publicListIds = publicListsSnapshot.docs.map((listDoc) => listDoc.id);

    if (publicListIds.length === 0) {
        return [] as ReviewEntity[];
    }

    // Keep per-list reads bounded to avoid large fan-out on first paint.
    const perListLimit = type === 'following' ? 10 : 4;
    const listReviewSnapshots = await Promise.all(
        publicListIds.map((listId) =>
            getDocs(
                query(
                    collection(db, 'lists', listId, 'reviews'),
                    orderBy('createdAt', 'desc'),
                    limit(perListLimit)
                )
            ).then((snapshot) => ({ listId, snapshot }))
        )
    );

    let rawReviews = listReviewSnapshots.flatMap(({ listId, snapshot }) =>
        snapshot.docs.map((reviewDoc) => ({
            id: reviewDoc.id,
            ...(reviewDoc.data() as any),
            listId
        } as ReviewEntity))
    );

    if (type === 'following' && Array.isArray(followingIds) && followingIds.length > 0) {
        const followingSet = new Set(followingIds);
        rawReviews = rawReviews.filter((review) => {
            const authorId = (review as any).userId || (review as any).authorId;
            return typeof authorId === 'string' && followingSet.has(authorId);
        });
    }

    rawReviews.sort((a: any, b: any) => {
        const tA = a.createdAt?.seconds || 0;
        const tB = b.createdAt?.seconds || 0;
        return tB - tA;
    });

    if (type === 'trending') {
        rawReviews.sort((a, b) => (b.overallRating || 0) - (a.overallRating || 0));
    }

    return rawReviews.slice(0, pageLimit);
};

export interface UseReviewsOptions {
    type?: 'recent' | 'trending' | 'following';
    userId?: string;
    listId?: string;
    followingIds?: string[];
    limit?: number;
}

export const useReviews = (options: UseReviewsOptions | 'recent' | 'trending' | 'following' = 'recent') => {
    // Normalize options
    const { type = 'recent', userId, listId, followingIds, limit: customLimit } = typeof options === 'string' ? { type: options } : options;

    const [reviews, setReviews] = useState<ReviewEntity[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [lastDoc, setLastDoc] = useState<any>(null);
    const [hasMore, setHasMore] = useState(true);
    const [loadingMore, setLoadingMore] = useState(false);

    const fetchReviews = async (isLoadMore = false) => {
        if (isLoadMore) {
            setLoadingMore(true);
        } else {
            setLoading(true);
            setReviews([]);
            setLastDoc(null);
            setHasMore(true);
        }

        console.log(`[useReviews] Fetching reviews. Type: ${type}, userId: ${userId}, listId: ${listId}, isLoadMore: ${isLoadMore}`);

        try {
            // Pre-check for following
            if (type === 'following') {
                if (!followingIds || followingIds.length === 0) {
                    setReviews([]);
                    setLoading(false);
                    setLoadingMore(false);
                    setHasMore(false);
                    return;
                }
            }

            let rawReviews: ReviewEntity[] = [];
            let newLastDoc = null;

            if (type === 'following' && followingIds && followingIds.length > 0) {
                rawReviews = await fetchPublicReviewsFromListSubcollections('following', {
                    pageLimit: customLimit || 20,
                    followingIds
                });
                setHasMore(false);

            } else {
                // Public feeds should only include public-list reviews; avoid global collectionGroup
                // queries because private-list documents would invalidate the whole query.
                if (!userId && !listId) {
                    rawReviews = await fetchPublicReviewsFromListSubcollections(type, {
                        pageLimit: customLimit || 6
                    });
                    setHasMore(false);
                } else {
                    // Standard Logic for filtered reads (profile/list specific).
                    // Use collectionGroup to include legacy subcollection reviews + new root reviews.
                    const reviewsRef = collectionGroup(db, 'reviews');

                    const constraints = [];

                    if (userId) constraints.push(where('userId', '==', userId));
                    if (listId) constraints.push(where('listId', '==', listId));

                    constraints.push(orderBy('createdAt', 'desc'));

                    // Pagination Logic
                    if (isLoadMore && lastDoc) {
                        constraints.push(startAfter(lastDoc));
                    }

                    // Initial request: customLimit or 6 items.
                    const pageSize = customLimit || 6;
                    constraints.push(limit(pageSize));

                    const q = query(reviewsRef, ...constraints);
                    const snapshot = await getDocs(q);

                    console.log(`[useReviews] Query success. Found ${snapshot.size} docs.`);

                    if (snapshot.docs.length < pageSize) {
                        setHasMore(false);
                    } else {
                        setHasMore(true);
                    }

                    if (snapshot.docs.length > 0) {
                        newLastDoc = snapshot.docs[snapshot.docs.length - 1];
                        setLastDoc(newLastDoc);
                    }

                    rawReviews = snapshot.docs.map(doc => {
                        const data = doc.data() as any;
                        let listId = data.listId;
                        // Fix: If listId is missing (legacy subcollection), retrieve from parent path
                        if (!listId && doc.ref.parent.parent) {
                            listId = doc.ref.parent.parent.id;
                        }
                        return {
                            id: doc.id,
                            ...data,
                            listId
                        };
                    }) as ReviewEntity[];
                }
            }

            // --- Enrich Data ---
            const enrichedReviews = await enrichRawReviews(rawReviews);

            if (type === 'trending') {
                enrichedReviews.sort((a, b) => (b.overallRating || 0) - (a.overallRating || 0));
            }

            if (isLoadMore) {
                setReviews(prev => [...prev, ...enrichedReviews]);
            } else {
                setReviews(enrichedReviews);
            }

        } catch (err: any) {
            console.error("Error fetching reviews:", err);
            if (err?.code === 'permission-denied') {
                try {
                    let fallbackReviews = await fetchPublicReviewsFromListSubcollections(type, {
                        pageLimit: customLimit || 20,
                        followingIds
                    });

                    if (userId) {
                        fallbackReviews = fallbackReviews.filter((review: any) =>
                            review.userId === userId || review.authorId === userId
                        );
                    }

                    if (listId) {
                        fallbackReviews = fallbackReviews.filter((review) => review.listId === listId);
                    }

                    const enrichedFallback = await enrichRawReviews(fallbackReviews);

                    if (type === 'trending') {
                        enrichedFallback.sort((a, b) => (b.overallRating || 0) - (a.overallRating || 0));
                    }

                    if (isLoadMore) {
                        setReviews(prev => [...prev, ...enrichedFallback]);
                    } else {
                        setReviews(enrichedFallback);
                    }

                    setHasMore(false);
                    setError(null);
                    return;
                } catch (fallbackError: any) {
                    console.error("Fallback fetching reviews failed:", fallbackError);
                }
            }
            setError(err?.message || 'No se pudieron cargar las reseñas.');
        } finally {
            setLoading(false);
            setLoadingMore(false);
        }
    };

    useEffect(() => {
        // Reset and fetch when filters change
        fetchReviews(false);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [type, userId, listId, JSON.stringify(followingIds)]); // Deep compare followingIds

    return {
        reviews,
        loading,
        error,
        refresh: () => fetchReviews(false),
        fetchMore: () => fetchReviews(true),
        hasMore,
        loadingMore
    };
};

import { useState, useEffect } from 'react';
import { doc, getDoc, Timestamp } from 'firebase/firestore';
import { db } from '../firebase';

export interface UserProfileEntity {
    uid: string;
    email: string;
    username: string;
    displayName?: string;
    photoUrl?: string;
    userType: 'user' | 'admin' | 'jefe' | string[];
    bio?: string;
    location?: string;
    website?: string;
    instagram?: string;
    twitter?: string;
    createdAt?: any;
    xp?: number;
    level?: number;
    followersCount?: number;
    followingCount?: number;
    reviewsCount?: number;
    badges?: any[]; // Or string[], using any[] for safety as I saw objects in gamification
    // Add other fields as needed based on legacy schema
    defaultDistanceKm?: number;
    followingListsCount?: number;
    followingUsersCount?: number;
    followingPlacesCount?: number;
}

export const useUserProfile = (uid: string | undefined) => {
    const [profile, setProfile] = useState<UserProfileEntity | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!uid) {
            setLoading(false);
            return;
        }

        const fetchProfile = async () => {
            setLoading(true);
            try {
                const docRef = doc(db, 'users', uid);
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    setProfile({ uid: docSnap.id, ...docSnap.data() } as UserProfileEntity);
                } else {
                    setError('Perfil no encontrado');
                }
            } catch (err: any) {
                console.error("Error fetching user profile:", err);
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };

        fetchProfile();
    }, [uid]);

    return { profile, loading, error };
};

import { useState, useEffect } from 'react';
import { collection, query, orderBy, limit, getDocs } from 'firebase/firestore';
import { db } from '../firebase';

export interface UserEntity {
    uid: string;
    displayName: string;
    photoUrl?: string;
    username?: string;
    bio?: string;
    followersCount?: number;
    publicListsCount?: number;
    reviewsCount?: number;
}

export const useUsers = () => {
    const [users, setUsers] = useState<UserEntity[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchUsers = async () => {
            setLoading(true);
            try {
                // Try to order by followersCount if index exists
                // If not, we might need a fallback or create index
                let q = query(collection(db, 'users'), orderBy('followersCount', 'desc'), limit(15));

                try {
                    const snap = await getDocs(q);
                    setUsers(snap.docs.map(d => ({ uid: d.id, ...d.data() } as UserEntity)));
                } catch (idxError) {
                    console.warn("Index missing for followersCount, falling back to simple fetch");
                    // Fallback: fetch recent users or just default order
                    q = query(collection(db, 'users'), limit(15));
                    const snap = await getDocs(q);
                    setUsers(snap.docs.map(d => ({ uid: d.id, ...d.data() } as UserEntity)));
                }

            } catch (err) {
                console.error("Error fetching users:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchUsers();
    }, []);

    return { users, loading };
};

import React, { useState, useEffect } from 'react';
import { useArchives, type ArchiveEntity, type SavedItemEntity } from '../hooks/useArchives';
import { Folder, ChevronDown, ChevronRight, MapPin, MessageSquare, List as ListIcon, Trash2, ExternalLink } from 'lucide-react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { collection, getDocs, orderBy, query } from 'firebase/firestore';
import { db } from '../firebase';

export const ArchivePage: React.FC = () => {
    const { user } = useAuth();
    const { archives, fetchArchives, toggleItemInArchive, createArchive, deleteArchive } = useArchives();
    const [expandedIds, setExpandedIds] = useState<string[]>([]);
    const [archiveItems, setArchiveItems] = useState<Record<string, SavedItemEntity[]>>({});
    const [loadingItems, setLoadingItems] = useState<Record<string, boolean>>({});
    const [filterType, setFilterType] = useState<'all' | 'place' | 'list' | 'review' | 'group'>('all');

    useEffect(() => {
        fetchArchives();
    }, [fetchArchives]);

    // Auto-expand first archive if exists
    useEffect(() => {
        if (archives.length > 0 && expandedIds.length === 0) {
            setExpandedIds([archives[0].id]);
        }
    }, [archives]);

    // Fetch items when expanding
    useEffect(() => {
        expandedIds.forEach(id => {
            if (!archiveItems[id] && !loadingItems[id]) {
                fetchItemsForArchive(id);
            }
        });
    }, [expandedIds]);

    const toggleExpand = (archiveId: string) => {
        setExpandedIds(prev =>
            prev.includes(archiveId) ? prev.filter(id => id !== archiveId) : [...prev, archiveId]
        );
    };

    const fetchItemsForArchive = async (archiveId: string) => {
        if (!user) return;
        setLoadingItems(prev => ({ ...prev, [archiveId]: true }));
        try {
            const q = query(collection(db, 'users', user.uid, 'archives', archiveId, 'items'), orderBy('savedAt', 'desc'));
            const snap = await getDocs(q);
            const items = snap.docs.map(iDoc => {
                const data = iDoc.data();
                let route = data.route;
                if (!route) {
                    const type = (data.entityType || '').toLowerCase();
                    if (type === 'place' && data.placeId) route = `/place/${data.placeId}`;
                    else if (type === 'group' && data.placeId && data.itemName) route = `/group/${data.placeId}/${encodeURIComponent(data.itemName)}`;
                    else if (type === 'review' && data.placeId) route = `/place/${data.placeId}`;
                }

                return {
                    id: iDoc.id,
                    itemId: data.itemId || iDoc.id,
                    type: data.type || data.entityType || 'other',
                    name: data.name || data.title || data.itemName || 'Sin nombre',
                    subtitle: data.subtitle,
                    photoUrl: data.photoUrl || data.imageUrl,
                    route: route || '#',
                    placeId: data.placeId,
                    listId: data.listId,
                    savedAt: data.savedAt || data.createdAt
                } as SavedItemEntity;
            });
            setArchiveItems(prev => ({ ...prev, [archiveId]: items }));
        } catch (e) {
            console.error(e);
        } finally {
            setLoadingItems(prev => ({ ...prev, [archiveId]: false }));
        }
    };

    const handleDragStart = (e: React.DragEvent, item: SavedItemEntity, sourceArchiveId: string) => {
        e.dataTransfer.setData('json/item', JSON.stringify(item));
        e.dataTransfer.setData('text/sourceArchiveId', sourceArchiveId);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    };

    const handleDrop = async (e: React.DragEvent, targetArchiveId: string) => {
        e.preventDefault();
        const itemJson = e.dataTransfer.getData('json/item');
        const sourceArchiveId = e.dataTransfer.getData('text/sourceArchiveId');

        if (!itemJson || !sourceArchiveId) return;
        if (sourceArchiveId === targetArchiveId) return;

        const item = JSON.parse(itemJson) as SavedItemEntity;

        try {
            await toggleItemInArchive(targetArchiveId, { ...item, id: '', savedAt: null }, true);
            await toggleItemInArchive(sourceArchiveId, item, false);
            await fetchItemsForArchive(targetArchiveId);
            await fetchItemsForArchive(sourceArchiveId);

            if (!expandedIds.includes(targetArchiveId)) {
                setExpandedIds(prev => [...prev, targetArchiveId]);
            }
        } catch (err) {
            console.error("Move failed:", err);
            alert("Error moviendo el elemento.");
        }
    };

    const handleRemoveItem = async (archiveId: string, item: SavedItemEntity) => {
        if (!confirm("¿Quitar este elemento de la colección?")) return;
        await toggleItemInArchive(archiveId, item, false);
        await fetchItemsForArchive(archiveId);
    };

    const handleCreateArchive = async () => {
        const name = prompt("Nombre de la nueva colección:");
        if (name && name.trim()) {
            try {
                await createArchive(name.trim());
            } catch (e) {
                alert("Error al crear la colección.");
            }
        }
    };

    const handleDeleteArchive = async (e: React.MouseEvent, id: string, name: string) => {
        e.stopPropagation();
        if (confirm(`¿Eliminar la colección "${name}"? Esta acción no se puede deshacer.`)) {
            try {
                await deleteArchive(id);
            } catch (error) {
                alert("Error al eliminar.");
            }
        }
    };

    const getFilteredItems = (items: SavedItemEntity[]) => {
        if (filterType === 'all') return items;
        return items.filter(i => i.type === filterType);
    };

    if (!user) return <div className="pt-32 text-center text-gray-500">Inicia sesión para ver tu archivo.</div>;

    return (
        <div className="min-h-screen bg-[#0b1021] pt-24 pb-20 px-4 sm:px-6">
            <div className="max-w-4xl mx-auto">
                <header className="mb-8 flex justify-between items-end">
                    <div>
                        <h1 className="text-3xl font-bold text-white mb-4">Mi Archivo</h1>
                        <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
                            {[
                                { id: 'all', label: 'Todo' },
                                { id: 'place', label: 'Lugares' },
                                { id: 'list', label: 'Listas' },
                                { id: 'group', label: 'Elementos' },
                                { id: 'review', label: 'Reseñas' },
                            ].map(f => (
                                <button
                                    key={f.id}
                                    onClick={() => setFilterType(f.id as any)}
                                    className={`px-4 py-1.5 rounded-full text-sm font-bold whitespace-nowrap transition-colors border ${filterType === f.id
                                        ? 'bg-indigo-600 border-indigo-500 text-white'
                                        : 'bg-[#151b2e] border-white/10 text-gray-400 hover:text-white hover:border-white/30'
                                        }`}
                                >
                                    {f.label}
                                </button>
                            ))}
                        </div>
                    </div>
                    <button
                        onClick={handleCreateArchive}
                        className="mb-2 px-4 py-2 bg-white/10 hover:bg-white/20 text-white text-sm font-bold rounded-xl border border-white/10 transition-colors"
                    >
                        + Nueva
                    </button>
                </header>

                <div className="space-y-4">
                    {archives.length === 0 ? (
                        <div className="text-center py-20 border-2 border-dashed border-white/5 rounded-2xl">
                            <Folder className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                            <p className="text-gray-500">No tienes colecciones aún.</p>
                            <p className="text-xs text-gray-600 mt-2">Guarda cosas pulsando el botón <span className="inline-block border border-gray-600 px-1 rounded">Guardar</span> en cualquier tarjeta.</p>
                        </div>
                    ) : (
                        archives.map(arch => (
                            <div
                                key={arch.id}
                                className="bg-[#151b2e] rounded-xl border border-white/10 overflow-hidden transition-colors relative group/archive"
                                onDragOver={handleDragOver}
                                onDrop={(e) => handleDrop(e, arch.id)}
                            >
                                <button
                                    onClick={() => toggleExpand(arch.id)}
                                    className={`w-full flex items-center justify-between p-4 hover:bg-white/5 transition-colors ${expandedIds.includes(arch.id) ? 'bg-white/[0.02]' : ''
                                        }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${expandedIds.includes(arch.id) ? 'bg-indigo-500 text-white' : 'bg-gray-800 text-gray-500'}`}>
                                            <Folder className="w-5 h-5" />
                                        </div>
                                        <div className="text-left">
                                            <h3 className="text-white font-bold">{arch.name}</h3>
                                            <div className="flex gap-2 text-xs text-gray-500">
                                                <span>{arch.itemCount || 0} elementos</span>
                                                {archiveItems[arch.id] && (
