                                    {expandedIds.includes(arch.id) ? <ChevronDown className="text-gray-500" /> : <ChevronRight className="text-gray-500" />}
                                </button>

                                {/* Delete Archive Button */}
                                <button
                                    onClick={(e) => handleDeleteArchive(e, arch.id, arch.name)}
                                    className="absolute top-4 right-12 p-2 text-gray-600 hover:text-red-500 opacity-0 group-hover/archive:opacity-100 transition-opacity"
                                    title="Eliminar colección"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>

                                {expandedIds.includes(arch.id) && (
                                    <div className="border-t border-white/5 bg-black/20 p-4 min-h-[100px]">
                                        {loadingItems[arch.id] ? (
                                            <div className="text-center py-4 text-gray-500 text-xs">Cargando elementos...</div>
                                        ) : (
                                            <>
                                                {getFilteredItems(archiveItems[arch.id] || []).length === 0 ? (
                                                    <div className="text-center py-8 text-gray-500 italic text-sm">
                                                        {archiveItems[arch.id]?.length ? 'No hay items de este tipo.' : 'Arrastra elementos aquí para moverlos.'}
                                                    </div>
                                                ) : (
                                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                                        {getFilteredItems(archiveItems[arch.id]).map(item => (
                                                            <div
                                                                key={item.itemId}
                                                                className="flex bg-[#1f2937] rounded-lg overflow-hidden border border-white/5 hover:border-indigo-500/30 transition-colors group relative cursor-grab active:cursor-grabbing"
                                                                draggable="true"
                                                                onDragStart={(e) => handleDragStart(e, item, arch.id)}
                                                            >
                                                                <div className="w-20 h-auto bg-gray-800 shrink-0">
                                                                    {item.photoUrl ? (
                                                                        <img src={item.photoUrl} alt={item.name} className="w-full h-full object-cover" />
                                                                    ) : (
                                                                        <div className="w-full h-full flex items-center justify-center text-gray-600">
                                                                            <Folder className="w-6 h-6 opacity-30" />
                                                                        </div>
                                                                    )}
                                                                </div>
                                                                <div className="p-3 flex-1 min-w-0 flex flex-col justify-center">
                                                                    <div className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider text-gray-500 mb-0.5">
                                                                        {item.type === 'place' && <><MapPin className="w-3 h-3" /> Lugar</>}
                                                                        {item.type === 'review' && <><MessageSquare className="w-3 h-3" /> Reseña</>}
                                                                        {item.type === 'group' && <><ListIcon className="w-3 h-3" /> Plato</>}
                                                                        {item.type === 'list' && <><Folder className="w-3 h-3" /> Lista</>}
                                                                    </div>
                                                                    <h4 className="text-white font-bold text-sm truncate">{item.name}</h4>
                                                                    {item.subtitle && <p className="text-indigo-400 text-xs truncate">{item.subtitle}</p>}
                                                                    <div className="mt-2 flex gap-2">
                                                                        <Link to={item.route} className="px-3 py-1 bg-white/10 hover:bg-white/20 text-white text-xs rounded transition-colors flex items-center gap-1">
                                                                            Ver <ExternalLink className="w-3 h-3" />
                                                                        </Link>
                                                                    </div>
                                                                </div>
                                                                <button
                                                                    onClick={() => handleRemoveItem(arch.id, item)}
                                                                    className="absolute top-2 right-2 p-1.5 rounded-full bg-black/40 text-gray-400 hover:text-red-400 hover:bg-black/80 opacity-0 group-hover:opacity-100 transition-all"
                                                                    title="Quitar"
                                                                >
                                                                    <Trash2 className="w-3 h-3" />
                                                                </button>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </>
                                        )}
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { ChatService, type Chat, type Message } from '../services/ChatService';
import { Send, MoreVertical, Search, MessageSquare, ArrowLeft, UserPlus, X, Users, User, Plus } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { algoliaClient, INDEX_NAMES } from '../services/algoliaClient';

export const ChatsPage: React.FC = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { chatId } = useParams();
    const [chats, setChats] = useState<Chat[]>([]);
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState('');
    const [activeChat, setActiveChat] = useState<string | null>(chatId || null);
    const [mobileView, setMobileView] = useState<'list' | 'chat'>('list');
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Group Creation State
    const [isGroupModalOpen, setIsGroupModalOpen] = useState(false);
    const [newGroupName, setNewGroupName] = useState('');
    const [isCreatingGroup, setIsCreatingGroup] = useState(false);
    const [usersMap, setUsersMap] = useState<Record<string, any>>({});

    const [isInfoModalOpen, setIsInfoModalOpen] = useState(false);
    const [participantInput, setParticipantInput] = useState('');
    const [addingParticipant, setAddingParticipant] = useState(false);

    // Search State
    const [searchResults, setSearchResults] = useState<any[]>([]);
    const [isSearching, setIsSearching] = useState(false);

    // Debounced Search Effect
    useEffect(() => {
        const timer = setTimeout(async () => {
            if (!participantInput.trim() || participantInput.length < 2) {
                setSearchResults([]);
                return;
            }

            setIsSearching(true);
            try {
                const response = await algoliaClient.search({
                    requests: [{ indexName: INDEX_NAMES.users, query: participantInput, hitsPerPage: 5 }]
                });
                setSearchResults((response.results[0] as any).hits);
            } catch (error) {
                console.error("Search error:", error);
            } finally {
                setIsSearching(false);
            }
        }, 500);

        return () => clearTimeout(timer);
    }, [participantInput]);

    // Fetch User Details for Private Chats
    useEffect(() => {
        const fetchChatUsers = async () => {
            if (!user || chats.length === 0) return;

            const userIdsToFetch = new Set<string>();
            chats.forEach(c => {
                if (c.type === 'private') {
                    const targetId = c.participants.find(p => p !== user.uid);
                    if (targetId && !usersMap[targetId]) {
                        userIdsToFetch.add(targetId);
                    }
                }
            });

            if (userIdsToFetch.size === 0) return;

            const newUsers: Record<string, any> = {};
            await Promise.all(Array.from(userIdsToFetch).map(async (uid) => {
                try {
                    const snap = await getDoc(doc(db, 'users', uid));
                    if (snap.exists()) {
                        newUsers[uid] = snap.data();
                    } else {
                        // Fallback for deleted/missing users to prevent infinite refetch
                        newUsers[uid] = { displayName: 'Usuario Eliminado', name: 'Usuario Eliminado' };
                    }
                } catch (e) {
                    console.warn("Failed to fetch user", uid);
                    // On error, also set placeholder to avoid loop, or leave empty to retry
                    newUsers[uid] = { displayName: 'Usuario Desconocido' };
                }
            }));

            setUsersMap(prev => ({ ...prev, ...newUsers }));
        };

        fetchChatUsers();
    }, [chats, user]);

    // Initial load of chats
    useEffect(() => {
        if (!user) return;
        const unsubscribe = ChatService.subscribeToChats(user.uid, (data) => {
            setChats(data);
        });
        return () => unsubscribe();
    }, [user]);

    // Handle URL param sync
    useEffect(() => {
        if (chatId) {
            setActiveChat(chatId);
            setMobileView('chat');
        } else {
            setActiveChat(null);
            setMobileView('list');
        }
    }, [chatId]);

    // Load messages for active chat
    useEffect(() => {
        if (!activeChat) return;
        const unsubscribe = ChatService.subscribeToMessages(activeChat, (data) => {
            setMessages(data);
            setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
        });

        // Mark as read when opening
        if (user) {
            ChatService.markChatAsRead(activeChat, user.uid).catch(console.error);
        }

        return () => unsubscribe();
    }, [activeChat, user]);

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user || !activeChat || !newMessage.trim()) return;

        try {
            await ChatService.sendMessage(activeChat, user.uid, newMessage);
            setNewMessage('');
        } catch (error) {
            console.error("Error sending message:", error);
        }
    };

    const getChatName = (chat: Chat) => {
        if (chat.type === 'group') return chat.groupName || 'Grupo sin nombre';

        const targetId = chat.participants.find(p => p !== user?.uid);
        if (targetId && usersMap[targetId]) {
            return usersMap[targetId].displayName || usersMap[targetId].username || usersMap[targetId].name || 'Usuario';
        }

        // If we have a target ID but no data yet, it's loading or failed
        if (targetId) return 'Usuario...';

        return `Chat`;
    };

    const getChatPhoto = (chat: Chat) => {
        if (chat.type === 'group') return chat.groupPhoto || null; // Return null to show default icon

        const targetId = chat.participants.find(p => p !== user?.uid);
        if (targetId && usersMap[targetId]) {
            return usersMap[targetId].photoUrl || null;
        }
        return null; // Default
    };

    const activeChatObj = chats.find(c => c.id === activeChat);

    return (
        <div className="min-h-screen bg-[var(--bg-primary)] pt-20 flex h-screen overflow-hidden">
            {/* Chat List Sidebar */}
            <div className={`w-full md:w-80 lg:w-96 bg-[#151b2e] border-r border-white/10 flex flex-col ${mobileView === 'chat' ? 'hidden md:flex' : 'flex'}`}>
                <div className="p-4 border-b border-white/10 flex justify-between items-center bg-[#151b2e]">
                    <h1 className="text-xl font-bold text-white">Mensajes</h1>
                    <button
                        onClick={() => setIsGroupModalOpen(true)}
                        className="p-2 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500 transition-colors"
                        title="Crear Grupo"
                    >
                        <UserPlus className="w-5 h-5" />
                    </button>
                </div>
                <div className="px-4 pb-4 border-b border-white/10">
                    <div className="relative">
                        <input
                            type="text"
                            placeholder="Buscar chats..."
                            className="w-full bg-[#0b1021] border border-white/10 rounded-lg py-2 pl-9 pr-4 text-sm text-white focus:outline-none focus:border-indigo-500"
                        />
                        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400" />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto">
                    {chats.length === 0 ? (
                        <div className="p-8 text-center text-gray-500">
                            <MessageSquare className="w-12 h-12 mx-auto mb-2 opacity-20" />
                            <p className="text-sm">No tienes chats activos.</p>
                        </div>
                    ) : (
                        chats.map(chat => (
                            <div
                                key={chat.id}
                                onClick={() => navigate(`/chats/${chat.id}`)}
                                className={`p-4 border-b border-white/5 cursor-pointer hover:bg-white/5 transition-colors ${activeChat === chat.id ? 'bg-indigo-900/20 border-l-4 border-l-indigo-500' : ''}`}
                            >
                                <div className="flex items-center gap-3">
                                    <div className="w-12 h-12 rounded-full overflow-hidden flex-shrink-0 bg-gray-700 border border-white/10 relative">
                                        {getChatPhoto(chat) ? (
                                            <img src={getChatPhoto(chat)!} alt="Chat" className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center bg-indigo-900/50 text-indigo-200 font-bold text-lg">
                                                {getChatName(chat).charAt(0).toUpperCase()}
                                            </div>
                                        )}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-start mb-0.5">
                                            <h3 className="font-bold text-white text-sm truncate">{getChatName(chat)}</h3>
                                            {chat.lastMessageTimestamp && (
                                                <div className="flex flex-col items-end">
                                                    <span className="text-[10px] text-gray-500 whitespace-nowrap ml-2">
                                                        {new Date(chat.lastMessageTimestamp?.seconds * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                    </span>
                                                    {(chat.unreadCount?.[user?.uid || ''] || 0) > 0 && (
                                                        <span className="mt-1 bg-red-500 text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[18px] text-center">
                                                            {chat.unreadCount?.[user?.uid || ''] || 0}
                                                        </span>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                        <p className="text-gray-400 text-xs truncate">{chat.lastMessage || 'Nueva conversación'}</p>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Chat Area */}
            <div className={`flex-1 flex flex-col bg-[#0b1021] ${mobileView === 'list' ? 'hidden md:flex' : 'flex'}`}>
                {activeChat ? (
                    <>
                        {/* Header */}
                        <div className="h-16 border-b border-white/10 flex items-center justify-between px-4 bg-[#151b2e]">
                            <div className="flex items-center gap-3">
                                <button onClick={() => navigate('/chats')} className="md:hidden text-gray-400 hover:text-white">
                                    <ArrowLeft className="w-6 h-6" />
                                </button>

                                {/* Avatar */}
                                <div className="w-10 h-10 rounded-full bg-gray-700 overflow-hidden flex-shrink-0 border border-white/10">
                                    {activeChatObj && getChatPhoto(activeChatObj) ? (
                                        <img src={getChatPhoto(activeChatObj)!} alt="Chat" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center bg-indigo-900/50">
                                            {activeChatObj?.type === 'group' ? <Users className="w-5 h-5 text-indigo-300" /> : <User className="w-5 h-5 text-indigo-300" />}
                                        </div>
                                    )}
                                </div>

                                <div>
                                    <h2 className="text-white font-bold text-sm md:text-base">{activeChatObj ? getChatName(activeChatObj) : 'Conversación'}</h2>
                                    {activeChatObj?.type === 'group' ? (
                                        <span className="text-xs text-gray-500">{activeChatObj.participants.length} participantes</span>
                                    ) : (
                                        <span className="text-xs text-green-500 flex items-center gap-1">
                                            <span className="w-2 h-2 rounded-full bg-green-500 text-green-500 animate-pulse"></span> En línea
                                        </span>
                                    )}
                                </div>
                            </div>
                            <button
                                onClick={() => setIsInfoModalOpen(true)}
                                className="p-2 text-gray-400 hover:text-white hover:bg-white/5 rounded-full transition-colors"
                            >
                                <MoreVertical className="w-5 h-5" />
                            </button>
                        </div>

                        {/* Messages */}
                        <div className="flex-1 overflow-y-auto p-4 space-y-4">
                            {messages.map((msg) => (
                                <div key={msg.id} className={`flex ${msg.senderId === user?.uid ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[75%] rounded-2xl px-4 py-2 ${msg.senderId === user?.uid
                                        ? 'bg-indigo-600 text-white rounded-br-none shadow-lg shadow-indigo-500/10'
                                        : 'bg-[#1e2337] text-gray-200 rounded-bl-none border border-white/5'
                                        }`}>
                                        <p>{msg.text}</p>
                                        <span className="text-[10px] opacity-50 block text-right mt-1">
                                            {msg.createdAt?.seconds ? new Date(msg.createdAt.seconds * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '...'}
                                        </span>
                                    </div>
                                </div>
                            ))}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Input */}
                        <form onSubmit={handleSendMessage} className="p-4 bg-[#151b2e] border-t border-white/10">
                            <div className="flex items-center gap-2">
                                <input
                                    type="text"
                                    value={newMessage}
                                    onChange={(e) => setNewMessage(e.target.value)}
                                    placeholder="Escribe un mensaje..."
                                    className="flex-1 bg-[#0b1021] border border-white/10 rounded-full px-4 py-3 text-white focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                                />
                                <button
                                    type="submit"
                                    disabled={!newMessage.trim()}
                                    className="p-3 bg-indigo-600 text-white rounded-full hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
                                >
                                    <Send className="w-5 h-5" />
                                </button>
                            </div>
                        </form>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center text-gray-500 p-4 text-center">
                        <div className="w-20 h-20 bg-[#151b2e] rounded-full flex items-center justify-center mb-6 animate-pulse">
                            <MessageSquare className="w-10 h-10 opacity-50" />
                        </div>
                        <h2 className="text-xl font-bold text-white mb-2">Tus conversaciones</h2>
                        <p className="max-w-md">Selecciona un chat de la lista o busca un usuario para comenzar a enviarle mensajes.</p>
                    </div>
                )}
            </div>

            {/* Create Group Modal */}
            {
                isGroupModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                        <div className="bg-[#151b2e] rounded-2xl w-full max-w-md border border-white/10 shadow-2xl overflow-hidden">
                            <div className="p-4 border-b border-white/5 flex justify-between items-center">
                                <h2 className="text-lg font-bold text-white flex items-center gap-2">
                                    <Users className="w-5 h-5 text-indigo-400" /> Crear Grupo
                                </h2>
                                <button onClick={() => setIsGroupModalOpen(false)} className="text-gray-400 hover:text-white">
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                            <div className="p-6">
                                <label className="block text-xs font-bold uppercase text-gray-400 mb-2">Nombre del Grupo</label>
                                <input
                                    type="text"
                                    value={newGroupName}
                                    onChange={(e) => setNewGroupName(e.target.value)}
                                    placeholder="Ej. Amigos de Listopic"
                                    className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 mb-6"
                                />

                                <button
                                    onClick={async () => {
                                        if (!user || !newGroupName.trim()) return;
                                        setIsCreatingGroup(true);
                                        try {
                                            // Create group with just creator for now. User can add others later (TODO)
                                            const chatId = await ChatService.createGroupChat(user.uid, newGroupName, []);
                                            setIsGroupModalOpen(false);
                                            setNewGroupName('');
                                            navigate(`/chats/${chatId}`);
                                        } catch (e) {
                                            console.error(e);
                                        } finally {
                                            setIsCreatingGroup(false);
                                        }
                                    }}
                                    disabled={isCreatingGroup || !newGroupName.trim()}
                                    className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3 rounded-xl transition-all disabled:opacity-50"
                                >
                                    {isCreatingGroup ? 'Creando...' : 'Crear Grupo'}
                                </button>
                            </div>
                        </div>
                    </div>
                )
            }


            {/* Chat Info Modal */}
            {
                isInfoModalOpen && activeChatObj && (
                    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                        <div className="bg-[#151b2e] rounded-2xl w-full max-w-sm border border-white/10 shadow-2xl overflow-hidden">
                            <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#0b1021]/50">
                                <h2 className="text-lg font-bold text-white">Info. del Chat</h2>
                                <button onClick={() => setIsInfoModalOpen(false)} className="text-gray-400 hover:text-white">
                                    <X className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="p-6 text-center">
                                <div className="w-20 h-20 rounded-full bg-gray-700 overflow-hidden border-2 border-indigo-500/30 mx-auto mb-4 relative group">
                                    {getChatPhoto(activeChatObj) ? (
                                        <img src={getChatPhoto(activeChatObj)!} alt="Chat" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center bg-indigo-900/50">
                                            {activeChatObj.type === 'group' ? <Users className="w-8 h-8 text-indigo-300" /> : <User className="w-8 h-8 text-indigo-300" />}
                                        </div>
                                    )}
                                </div>
                                <h3 className="text-xl font-bold text-white mb-1">{getChatName(activeChatObj)}</h3>
                                <p className="text-sm text-gray-500 mb-6 capitalize">{activeChatObj.type === 'private' ? 'Chat Privado' : 'Grupo'}</p>

                                <div className="text-left mb-6">
                                    <h4 className="text-xs font-bold uppercase text-gray-400 mb-3 tracking-wider">Participantes ({activeChatObj.participants.length})</h4>
                                    <div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar pr-2">
                                        {activeChatObj.participants.map(pid => {
                                            const p = usersMap[pid] || { displayName: 'Usuario...' };
                                            return (
                                                <div key={pid} className="flex items-center gap-3 p-2 rounded-lg hover:bg-white/5">
                                                    <div className="w-8 h-8 rounded-full bg-gray-700 overflow-hidden">
                                                        {p.photoUrl ? <img src={p.photoUrl} className="w-full h-full object-cover" /> : <User className="w-4 h-4 m-2 text-gray-400" />}
                                                    </div>
                                                    <span className="text-sm text-gray-200">{pid === user?.uid ? 'Tú' : (p.displayName || p.username || p.name)}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>

                                <div className="border-t border-white/5 pt-4">
                                    <h4 className="text-xs font-bold uppercase text-gray-400 mb-2 tracking-wider text-left">Añadir participante</h4>
                                    <div className="relative">
                                        <div className="flex gap-2">
                                            <input
                                                type="text"
                                                value={participantInput}
                                                onChange={(e) => setParticipantInput(e.target.value)}
                                                placeholder="Buscar usuario (nombre, email)..."
                                                className="flex-1 bg-[#0b1021] border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:outline-none focus:border-indigo-500"
                                            />
                                        </div>

                                        {/* Search Results Dropdown */}
                                        {(searchResults.length > 0 || isSearching) && participantInput.length >= 2 && (
                                            <div className="absolute bottom-full mb-2 left-0 right-0 bg-[#0b1021] border border-white/10 rounded-lg shadow-xl overflow-hidden z-20 max-h-48 overflow-y-auto">
                                                {isSearching ? (
                                                    <div className="p-3 text-center text-xs text-gray-500">Buscando...</div>
                                                ) : (
                                                    searchResults.map((hit: any) => (
                                                        <button
                                                            key={hit.objectID}
                                                            onClick={async () => {
                                                                if (activeChatObj.participants.includes(hit.objectID)) {
                                                                    alert("Este usuario ya está en el chat");
                                                                    return;
                                                                }

                                                                setAddingParticipant(true);
                                                                try {
                                                                    await ChatService.addParticipant(activeChatObj.id, hit.objectID);
                                                                    setParticipantInput('');
                                                                    setSearchResults([]);
                                                                    // Optional: Close modal or show success feedback
                                                                } catch (e) {
                                                                    console.error(e);
                                                                    alert("Error al añadir participante");
                                                                } finally {
                                                                    setAddingParticipant(false);
                                                                }
                                                            }}
                                                            className="w-full text-left p-3 hover:bg-white/5 flex items-center gap-3 transition-colors border-b border-white/5 last:border-0"
                                                            disabled={addingParticipant}
                                                        >
                                                            <img src={hit.photoUrl || hit.image || `https://ui-avatars.com/api/?name=${hit.username}`} className="w-8 h-8 rounded-full object-cover" />
                                                            <div className="flex-1 min-w-0">
                                                                <p className="text-sm font-bold text-white truncate">{hit.username || hit.name}</p>
                                                                <p className="text-xs text-gray-500 truncate">{hit.bio || 'Sin biografía'}</p>
                                                            </div>
                                                            {activeChatObj.participants.includes(hit.objectID) && <span className="text-xs text-indigo-400">En chat</span>}
                                                        </button>
                                                    ))
                                                )}
                                            </div>
                                        )}
                                    </div>
                                    {activeChatObj.type === 'private' && (
                                        <p className="text-[10px] text-gray-500 mt-2 text-left">
                                            * Añadir a alguien convertirá este chat en un grupo.
                                        </p>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
        </div >
    );
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { collection, addDoc, serverTimestamp, getDocs, doc, getDoc, query, limit, where } from 'firebase/firestore';
import { db } from '../firebase';
import { ArrowLeft, Save, Loader, Image as ImageIcon, X, Search, ChevronRight } from 'lucide-react';
import { CriteriaBuilder, type Criterion } from '../components/CriteriaBuilder';

export const CreateSublistPage: React.FC = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { parentId } = useParams<{ parentId: string }>();

    // Selection Mode State
    const [searchTerm, setSearchTerm] = useState('');
    const [mainLists, setMainLists] = useState<any[]>([]);
    const [loadingLists, setLoadingLists] = useState(false);

    // Creation Mode State
    const [parentList, setParentList] = useState<any>(null);
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [isPublic, setIsPublic] = useState(true);
    const [isPublicWritable, setIsPublicWritable] = useState(false);

    // Image
    const [_imageFile, setImageFile] = useState<File | null>(null); // Prefix with _ or remove if truly unused. used in handler but state never read.
    const [imagePreview, setImagePreview] = useState<string | null>(null);

    // Advanced
    const [criteria, setCriteria] = useState<Criterion[]>([]);
    const [customTags, setCustomTags] = useState<string[]>([]);
    const [fixedTags, setFixedTags] = useState<string[]>([]);
    const [tagInput, setTagInput] = useState('');

    const [loading, setLoading] = useState(false);

    // 1. Fetch Lists for Selection (if no parentId)
    useEffect(() => {
        if (!parentId) {
            const fetchLists = async () => {
                setLoadingLists(true);
                try {
                    // Fetch top lists or just recent ones to choose from
                    // Fetch lists - Relaxed query to ensure legacy lists appear
                    // orderBy('itemCount') excludes docs where that field is missing.
                    // Fetch lists - must filter by public to satisfy security rules
                    const q = query(
                        collection(db, 'lists'),
                        where('isPublic', '==', true),
                        limit(50)
                    );
                    const snapshot = await getDocs(q);
                    const docs = snapshot.docs
                        .map(d => ({ id: d.id, ...d.data() }))
                        .filter((l: any) => !l.parentListId); // Only show main lists
                    setMainLists(docs);
                } catch (e) {
                    console.error("Error fetching parent lists", e);
                } finally {
                    setLoadingLists(false);
                }
            };
            fetchLists();
        }
    }, [parentId]);

    // 2. Fetch Parent List Details (if parentId)
    useEffect(() => {
        if (parentId) {
            const fetchParent = async () => {
                try {
                    const docRef = doc(db, 'lists', parentId);
                    const docSnap = await getDoc(docRef);
                    if (docSnap.exists()) {
                        const data = docSnap.data();
                        setParentList({ id: docSnap.id, ...data });

                        // Prefill data
                        setName(`${data.name} (Mi Versión)`);
                        setFixedTags(data.availableTags || []);

                        // Prefill criteria
                        if (data.criteriaDefinition) {
                            const inheritedCriteria: Criterion[] = [];
                            Object.entries(data.criteriaDefinition).forEach(([key, val]: [string, any]) => {
                                if (val.type === 'slider') {
                                    inheritedCriteria.push({
                                        id: key,
                                        label: val.label,
                                        minLabel: val.labelMin,
                                        maxLabel: val.labelMax,
                                        isPonderable: val.ponderable !== false,
                                        locked: true // Inherited criteria are locked
                                    });
                                }
                            });
                            setCriteria(inheritedCriteria);
                        }
                    } else {
                        navigate('/create-sublist'); // Redirect if invalid
                    }
                } catch (e) {
                    console.error("Error fetching parent list", e);
                }
            };
            fetchParent();
        }
    }, [parentId, navigate]);

    // Image Handlers
    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setImageFile(file);
            const reader = new FileReader();
            reader.onloadend = () => setImagePreview(reader.result as string);
            reader.readAsDataURL(file);
        }
    };

    // Tag Handlers
    const addTag = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && tagInput.trim()) {
            e.preventDefault();
            const val = tagInput.trim();
            if (!customTags.includes(val) && !fixedTags.includes(val)) {
                setCustomTags([...customTags, val]);
            }
            setTagInput('');
        }
    };
    const removeTag = (tag: string) => {
        setCustomTags(customTags.filter(t => t !== tag));
    };

    // Guests State
    const [guests, setGuests] = useState<string[]>([]);
    const [guestInput, setGuestInput] = useState('');

    const handleAddGuest = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && guestInput.trim()) {
            e.preventDefault();
            const val = guestInput.trim();
            if (!guests.includes(val)) {
                setGuests([...guests, val]);
            }
            setGuestInput('');
        }
    };

    const removeGuest = (email: string) => {
        setGuests(guests.filter(g => g !== email));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user || !parentList) return;
        setLoading(true);

        try {
            const finalPhotoUrl = imagePreview || parentList.photoUrl || '';

            const criteriaDefinitionMap: Record<string, any> = {};
            criteria.forEach(c => {
                criteriaDefinitionMap[c.id] = {
                    type: 'slider',
                    label: c.label,
                    min: 0,
                    max: 10,
                    step: 0.5,
                    labelMin: c.minLabel,
                    labelMax: c.maxLabel,
                    ponderable: c.isPonderable
                };
            });

            const finalListTags = [...fixedTags, ...customTags];

            const newListData = {
                name,
                description,
                categoryId: parentList.categoryId,
                parentListId: parentList.id, // THE KEY LINK
                isSublist: true,

                userId: user.uid,
                isPublic, // Legacy boolean
                visibility: isPublic ? 'public' : 'private', // New explicit field
                publicAccess: isPublic && isPublicWritable ? 'writer' : 'reader', // Consistent with EditListPage
                guests, // Array of strings (emails/usernames)

                authorName: user.displayName || 'Anónimo',
                photoUrl: finalPhotoUrl,
                mainImageUrl: finalPhotoUrl, // Legacy compat

                criteriaDefinition: criteriaDefinitionMap,
                availableTags: finalListTags,

                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp(),

                // Reset counters
                itemCount: 0,
                viewCount: 0,
                likes: 0,
                followersCount: 0,
                averageRating: 0,

                criteriaAverages: {},
                criteriaAveragesUpdatedAt: serverTimestamp(),
            };

            const docRef = await addDoc(collection(db, 'lists'), newListData);
            navigate(`/list/${docRef.id}`);
        } catch (error) {
            console.error("Error creating sublist:", error);
            alert("Error al crear la sublista");
        } finally {
            setLoading(false);
        }
    };

    // RENDER: Selection Mode
    if (!parentId) {
        return (
            <div className="min-h-screen bg-[#0b1021] text-gray-100 pt-24 pb-20 px-4">
                <div className="max-w-4xl mx-auto">
                    <h1 className="text-3xl font-bold font-display text-white mb-2">Crear Sublista</h1>
                    <p className="text-gray-400 mb-8">Selecciona una lista base para personalizarla con tus propios lugares.</p>

                    <div className="relative mb-8">
                        <Search className="absolute left-4 top-3.5 text-gray-500 w-5 h-5" />
                        <input
                            type="text"
                            placeholder="Buscar listas principales..."
                            className="w-full bg-[#151b2e] border border-white/10 rounded-xl pl-12 pr-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                        />
                    </div>

                    {loadingLists ? (
                        <div className="text-center py-20"><Loader className="w-8 h-8 animate-spin mx-auto text-indigo-500" /></div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {mainLists.filter(l => l.name.toLowerCase().includes(searchTerm.toLowerCase())).map(list => (
                                <div key={list.id}
                                    onClick={() => navigate(`/create-sublist/${list.id}`)}
                                    className="bg-[#151b2e] border border-white/10 rounded-xl p-4 hover:border-indigo-500/50 cursor-pointer transition-all hover:translate-x-1 group flex items-center gap-4"
                                >
                                    <div className="w-16 h-16 bg-gray-800 rounded-lg overflow-hidden shrink-0">
                                        {list.photoUrl && <img src={list.photoUrl} alt={list.name} className="w-full h-full object-cover" />}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h3 className="font-bold text-white truncate">{list.name}</h3>
                                        <p className="text-xs text-gray-500 truncate">{list.itemCount} lugares • Por {list.authorName}</p>
                                    </div>
                                    <ChevronRight className="w-5 h-5 text-gray-600 group-hover:text-indigo-400" />
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        );
    }

    // RENDER: Creation Form
    if (!parentList) {
        return <div className="min-h-screen bg-[#0b1021] pt-24 flex justify-center"><Loader className="animate-spin text-white" /></div>;
    }

    return (
        <div className="min-h-screen bg-[#0b1021] text-gray-100 pt-24 pb-20 px-4">
            <div className="max-w-3xl mx-auto">
                <button onClick={() => navigate('/create-sublist')} className="flex items-center text-gray-400 hover:text-white mb-6 transition-colors">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Volver a selección
                </button>

                <div className="flex items-center gap-4 mb-8">
                    <div className="w-12 h-12 rounded-lg overflow-hidden border border-white/10">
                        {parentList.photoUrl && <img src={parentList.photoUrl} className="w-full h-full object-cover opacity-50" />}
                    </div>
                    <div>
                        <h1 className="text-2xl font-bold font-display text-white">Nueva Sublista</h1>
                        <p className="text-gray-400 text-sm">Basada en <span className="text-indigo-400">{parentList.name}</span></p>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-2">Nombre de tu lista</label>
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                                required
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-2">Descripción</label>
                            <textarea
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 min-h-[100px]"
                                placeholder="Describe tu versión de esta lista..."
                            />
                        </div>

                        {/* Image Upload */}
                        <div>
                            <label className="block text-sm font-medium text-gray-400 mb-2">Portada (Opcional)</label>
                            <div className="border-2 border-dashed border-white/10 rounded-xl p-6 text-center hover:bg-white/5 transition-colors relative group">
                                {imagePreview ? (
                                    <div className="relative h-48 w-full rounded-lg overflow-hidden">
                                        <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                        <button
                                            type="button"
                                            onClick={() => { setImagePreview(null); setImageFile(null); }}
                                            className="absolute top-2 right-2 p-1 bg-black/50 rounded-full text-white hover:bg-red-500 transition-colors"
                                        >
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                ) : (
                                    <>
                                        <input
                                            type="file"
                                            accept="image/*"
                                            onChange={handleImageChange}
                                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                        />
                                        <ImageIcon className="w-12 h-12 text-gray-600 mx-auto mb-3 group-hover:text-indigo-500 transition-colors" />
                                        <p className="text-gray-400 text-sm">Usar imagen personalizada</p>
                                        <p className="text-gray-600 text-xs mt-1">Si no subes nada, se usará la de la lista original</p>
                                    </>
                                )}
                            </div>
                        </div>
                    </div>

                    <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-8">
                        <CriteriaBuilder criteria={criteria} onChange={setCriteria} />

                        <div className="border-t border-white/5 pt-6"></div>

                        <div>
                            <h3 className="text-lg font-bold text-white mb-2">Etiquetas (Globales + Tuyas)</h3>
                            <div className="flex flex-wrap gap-2 mb-3">
                                {fixedTags.map(tag => (
                                    <span key={`fixed-${tag}`} className="bg-gray-700/50 text-gray-300 px-3 py-1 rounded-full text-sm flex items-center gap-1 border border-white/5 cursor-not-allowed">
                                        {tag}
                                    </span>
                                ))}
                                {customTags.map(tag => (
                                    <span key={tag} className="bg-indigo-500/20 text-indigo-300 px-3 py-1 rounded-full text-sm flex items-center gap-1">
                                        {tag}
                                        <button type="button" onClick={() => removeTag(tag)} className="hover:text-white"><X className="w-3 h-3" /></button>
                                    </span>
                                ))}
                            </div>
                            <input
                                type="text"
                                value={tagInput}
                                onChange={(e) => setTagInput(e.target.value)}
                                onKeyDown={addTag}
                                placeholder="Añadir más tags..."
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                            />
                        </div>
                    </div>

                    {/* Permission & Visibility */}
                    <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-6">
                        <h3 className="text-lg font-bold text-white">Privacidad y Acceso</h3>

                        {/* Visibility Toggle */}
                        <div className="flex items-center gap-4">
                            <button
                                type="button"
                                onClick={() => setIsPublic(true)}
                                className={`flex-1 p-4 rounded-xl border transition-all ${isPublic
                                    ? 'bg-indigo-600/20 border-indigo-500 text-white'
                                    : 'bg-[#0b1021] border-white/10 text-gray-400 hover:bg-white/5'}`}
                            >
                                <span className="block font-bold">Pública</span>
                                <span className="text-xs opacity-70">Visible para todos</span>
                            </button>
                            <button
                                type="button"
                                onClick={() => setIsPublic(false)}
                                className={`flex-1 p-4 rounded-xl border transition-all ${!isPublic
                                    ? 'bg-indigo-600/20 border-indigo-500 text-white'
                                    : 'bg-[#0b1021] border-white/10 text-gray-400 hover:bg-white/5'}`}
                            >
                                <span className="block font-bold">Privada</span>
                                <span className="text-xs opacity-70">Solo invitados</span>
                            </button>
                        </div>

                        {/* Public Write Access Toggle */}
                        {isPublic && (
                            <div className="animate-fade-in mt-4 p-4 bg-[#0b1021]/50 rounded-xl border border-white/5 flex items-center justify-between">
                                <div>
                                    <h4 className="text-sm font-bold text-gray-200">Permitir Colaboración Pública</h4>
                                    <p className="text-xs text-gray-500 mt-1">
                                        Si activas esto, cualquier usuario podrá añadir lugares a esta lista.
                                    </p>
                                </div>
                                <label className="relative inline-flex items-center cursor-pointer">
                                    <input
                                        type="checkbox"
                                        checked={isPublicWritable}
                                        onChange={(e) => setIsPublicWritable(e.target.checked)}
                                        className="sr-only peer"
                                    />
                                    <div className="w-11 h-6 bg-gray-700 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-indigo-800 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                                </label>
                            </div>
                        )}

                        {/* Guest Management (Only relevant if Private usually, but technically can have guests on public too?) 
                            The prompt implies guests for private lists mostly. */}
                        {!isPublic && (
                            <div className="animate-fade-in space-y-3">
                                <label className="block text-sm font-medium text-gray-400">Invitados (Emails o Usuarios)</label>
                                <div className="flex flex-wrap gap-2 mb-2 p-2 bg-[#0b1021] rounded-lg border border-white/10 min-h-[50px]">
                                    {guests.map(g => (
                                        <span key={g} className="bg-purple-500/20 text-purple-300 px-3 py-1 rounded-full text-xs flex items-center gap-1">
                                            {g}
                                            <button type="button" onClick={() => removeGuest(g)} className="hover:text-white"><X className="w-3 h-3" /></button>
                                        </span>
                                    ))}
                                    <input
                                        type="text"
                                        value={guestInput}
                                        onChange={(e) => setGuestInput(e.target.value)}
                                        onKeyDown={handleAddGuest}
                                        placeholder="Escribe y pulsa Enter..."
                                        className="bg-transparent text-white text-sm focus:outline-none min-w-[150px] flex-1"
                                    />
                                </div>
                                <p className="text-xs text-gray-500">
                                    Los invitados podrán ver la lista y añadir reseñas (si se habilita).
                                </p>
                            </div>
                        )}
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg transition-transform active:scale-[0.99] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                    >
                        {loading ? <Loader className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                        {loading ? 'Creando Sublista...' : 'Crear Sublista'}
                    </button>
                </form>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { collection, getDocs, limit, query } from 'firebase/firestore';
import { db, auth } from '../firebase';

export const DebugView: React.FC = () => {
    const [lists, setLists] = useState<any[]>([]);
    const [logs, setLogs] = useState<string[]>([]);
    const [user, setUser] = useState<any>(null);

    const log = (msg: string) => setLogs(prev => [...prev, `${new Date().toLocaleTimeString()}: ${msg}`]);

    useEffect(() => {
        log("Iniciando DebugView...");

        // Check Auth
        log(`Auth State: ${auth.currentUser ? 'Logueado as ' + auth.currentUser.email : 'No logueado'}`);
        setUser(auth.currentUser);

        const fetchRaw = async () => {
            try {
                log("Intentando fetch 'lists' collection...");
                const q = query(collection(db, 'lists'), limit(5));
                const snap = await getDocs(q);

                log(`Snapshot query existosa. Docs encontrados: ${snap.size}`);

                if (snap.empty) {
                    log("⚠️ La colección 'lists' está vacía o no se tienen permisos.");
                }

                const rawData = snap.docs.map(doc => ({
                    id: doc.id,
                    ...doc.data()
                }));
                setLists(rawData);
            } catch (e: any) {
                log(`❌ ERROR FETCHING LISTS: ${e.message}`);
                console.error(e);
            }
        };

        fetchRaw();
    }, []);

    return (
        <div className="p-8 bg-black text-green-400 font-mono text-sm min-h-screen overflow-auto">
            <h1 className="text-xl font-bold mb-4">📢 DIAGNOSTICO DE DATOS</h1>

            <div className="mb-6 border border-green-800 p-4">
                <h2 className="text-white mb-2">Logs:</h2>
                {logs.map((l, i) => <div key={i}>{l}</div>)}
            </div>

            <div className="mb-6 border border-green-800 p-4">
                <h2 className="text-white mb-2">Usuario Actual:</h2>
                <pre>{JSON.stringify(user?.toJSON() || "Null", null, 2)}</pre>
            </div>

            <div className="border border-green-800 p-4">
                <h2 className="text-white mb-2">Muestra de Datos (Colección 'lists'):</h2>
                <pre>{JSON.stringify(lists, null, 2)}</pre>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useUserProfile } from '../hooks/useUserProfile';
import { BrandingManager } from '../components/developer/BrandingManager';
import { db, functions, storage } from '../firebase';
import { collection, query, where, getDocs, doc, getDoc, limit as firestoreLimit, setDoc, updateDoc, deleteDoc } from 'firebase/firestore';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { Terminal, Search, AlertCircle, RefreshCw, List as ListIcon, MapPin, Layers, Database, CloudLightning, Tag, CheckCircle, X, Upload, Flag, MessageSquare, Palette, Users } from 'lucide-react';
import { DeveloperItemModal } from '../components/developer/DeveloperItemModal';

const FUNCTIONS_REGION = 'europe-west1';

interface ConsoleSearchParams {
    collection: string;
    id?: string;
    user?: string;
    nameContains?: string;
    googleId?: string;
    limit: number;
}

export const DeveloperPage: React.FC = () => {
    const { user } = useAuth();
    const { profile, loading: loadingProfile } = useUserProfile(user?.uid);
    const [activeTab, setActiveTab] = useState<'console' | 'algolia' | 'maintenance' | 'gamification' | 'reports' | 'branding'>('console');
    const [isAuthorized, setIsAuthorized] = useState<boolean | null>(null);

    // Console State
    const [consoleParams, setConsoleParams] = useState<ConsoleSearchParams>({
        collection: 'lists',
        limit: 100
    });
    const [consoleResults, setConsoleResults] = useState<any[]>([]);
    const [loadingConsole, setLoadingConsole] = useState(false);
    const [consoleError, setConsoleError] = useState<string | null>(null);

    // Modal State
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedItem, setSelectedItem] = useState<any | null>(null);

    // Reports State
    const [reports, setReports] = useState<any[]>([]);
    const [loadingReports, setLoadingReports] = useState(false);
    const [reportFilter, setReportFilter] = useState<'pending' | 'resolved' | 'rejected'>('pending');

    // Algolia State
    const [algoliaLog, setAlgoliaLog] = useState<string[]>([]);
    const [processingAlgolia, setProcessingAlgolia] = useState(false);

    // Maintenance State
    const [targetListId, setTargetListId] = useState('');
    const [targetPlaceId, setTargetPlaceId] = useState('');
    const [maintenanceLog, setMaintenanceLog] = useState<string[]>([]);
    const [processingMaintenance, setProcessingMaintenance] = useState(false);

    // Reports State Removed (Duplicate)

    // Badge Management State
    const [badges, setBadges] = useState<any[]>([]);
    const [loadingBadges, setLoadingBadges] = useState(false);
    const [editingBadge, setEditingBadge] = useState<any | null>(null);
    const [badgeModalOpen, setBadgeModalOpen] = useState(false);


    useEffect(() => {
        if (!loadingProfile && profile) {
            const isJefe = (Array.isArray(profile.userType) && profile.userType.includes('jefe')) || profile.userType === 'jefe';
            setIsAuthorized(isJefe);
        }
    }, [profile, loadingProfile]);

    const handleConsoleSearch = async () => {
        setLoadingConsole(true);
        setConsoleError(null);
        setConsoleResults([]);

        try {
            const { collection: colName, id, user: userId, nameContains, googleId, limit: limitVal } = consoleParams;

            if (id) {
                const docRef = doc(db, colName, id);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setConsoleResults([{ id: docSnap.id, ...docSnap.data() }]);
                } else {
                    setConsoleResults([]);
                }
                setLoadingConsole(false);
                return;
            }

            let q = query(collection(db, colName));

            if (colName === 'places') {
                if (googleId) q = query(q, where('googlePlaceId', '==', googleId));
                if (userId) q = query(q, where('createdByUserId', '==', userId));
            } else if (colName === 'lists') {
                if (userId) q = query(q, where('userId', '==', userId));
            } else if (colName === 'users') {
                if (userId) q = query(q, where('emailLowerCase', '==', userId.toLowerCase())); // specific case from legacy
            } else if (colName === 'listForums') {
                if (userId) q = query(q, where('ownerId', '==', userId));
            }

            // Apply limit
            q = query(q, firestoreLimit(limitVal || 50));

            const snap = await getDocs(q);
            let results = snap.docs.map(d => ({ id: d.id, ...d.data() }));

            if (nameContains) {
                const term = nameContains.toLowerCase();
                results = results.filter((r: any) => {
                    const name = (r.name || r.displayName || r.title || '').toLowerCase();
                    return name.includes(term);
                });
            }

            setConsoleResults(results);

        } catch (err: any) {
            console.error("Search error:", err);
            setConsoleError(err.message);
        } finally {
            setLoadingConsole(false);
        }
    };

    const runAlgoliaSync = async (target: string | null) => {
        const collections = target ? [target] : ['lists', 'places', 'users', 'grouped_items'];
        if (!window.confirm(`¿Estás seguro de que quieres sincronizar ${target || 'TODO (lists, places, users, grouped_items)'} con Algolia?`)) return;

        setProcessingAlgolia(true);
        const functions = getFunctions(undefined, FUNCTIONS_REGION);
        const adminBackfillAlgolia = httpsCallable(functions, 'adminBackfillAlgolia');

        try {
            for (const col of collections) {
                setAlgoliaLog(prev => [`[${new Date().toLocaleTimeString()}] Iniciando sync de ${col}...`, ...prev]);

                const result = await adminBackfillAlgolia({ collectionName: col });
                const data: any = result.data;

                setAlgoliaLog(prev => [`[${new Date().toLocaleTimeString()}] Éxito ${col}: ${JSON.stringify(data)}`, ...prev]);
            }
        } catch (err: any) {
            setAlgoliaLog(prev => [`[${new Date().toLocaleTimeString()}] Error: ${err.message}`, ...prev]);
        } finally {
            setProcessingAlgolia(false);
        }
    };

    const handleRecalculateList = async () => {
        if (!targetListId) return;
        setProcessingMaintenance(true);
        setMaintenanceLog(prev => [`[${new Date().toLocaleTimeString()}] Iniciando recálculo para lista: ${targetListId}...`, ...prev]);

        try {
            const functions = getFunctions(undefined, FUNCTIONS_REGION);
            // Call both to be safe: averages and aggregates
            const recalculateAverages = httpsCallable(functions, 'adminRecalculateListAverages');
            const updateAggregates = httpsCallable(functions, 'adminUpdateSingleListAggregates');

            setMaintenanceLog(prev => [`... Llamando adminRecalculateListAverages...`, ...prev]);
            const res1: any = await recalculateAverages({ listId: targetListId });
            setMaintenanceLog(prev => [`✅ Averages: ${JSON.stringify(res1.data)}`, ...prev]);

            setMaintenanceLog(prev => [`... Llamando adminUpdateSingleListAggregates...`, ...prev]);
            const res2: any = await updateAggregates({ listId: targetListId });
            setMaintenanceLog(prev => [`✅ Aggregates: ${JSON.stringify(res2.data)}`, ...prev]);

            setMaintenanceLog(prev => [`✨ COMPLETADO para ${targetListId}`, ...prev]);

        } catch (error: any) {
            console.error('Error recalculating list:', error);
            setMaintenanceLog(prev => [`❌ Error: ${error.message}`, ...prev]);
        } finally {
            setProcessingMaintenance(false);
        }
    };

    const handleRecalculatePlace = async () => {
        if (!targetPlaceId) return;
        setProcessingMaintenance(true);
        setMaintenanceLog(prev => [`[${new Date().toLocaleTimeString()}] Iniciando recálculo para lugar: ${targetPlaceId}...`, ...prev]);

        try {
            const functions = getFunctions(undefined, FUNCTIONS_REGION);
            const recalculatePlace = httpsCallable(functions, 'adminRecalculatePlaceStats');

            setMaintenanceLog(prev => [`... Llamando adminRecalculatePlaceStats...`, ...prev]);
            const res: any = await recalculatePlace({ placeId: targetPlaceId });
            setMaintenanceLog(prev => [`✅ Resultado: ${JSON.stringify(res.data)}`, ...prev]);
            setMaintenanceLog(prev => [`✨ COMPLETADO para lugar ${targetPlaceId}`, ...prev]);

        } catch (error: any) {
            console.error('Error recalculating place:', error);
            setMaintenanceLog(prev => [`❌ Error: ${error.message}`, ...prev]);
        } finally {
            setProcessingMaintenance(false);
        }
    };

    const handleGlobalRecalculate = async (type: 'lists' | 'places' | 'users') => {
        setProcessingMaintenance(true);
        setMaintenanceLog(prev => [`[${new Date().toLocaleTimeString()}] Iniciando recálculo GLOBAL para: ${type.toUpperCase()}...`, ...prev]);

        try {
            const functions = getFunctions(undefined, FUNCTIONS_REGION);
            // Decide function based on type
            let fnName = '';
            if (type === 'lists') fnName = 'adminRecalculateAllLists';
            else if (type === 'places') fnName = 'adminRecalculateAllPlaces';
            else if (type === 'users') fnName = 'adminRecalculateAllUsers';

            const bulkFn = httpsCallable(functions, fnName);

            setMaintenanceLog(prev => [`... Llamando ${fnName} ...`, ...prev]);
            const res: any = await bulkFn();
            setMaintenanceLog(prev => [`✅ Resultado Global (${type}): ${JSON.stringify(res.data)}`, ...prev]);
            setMaintenanceLog(prev => [`✨ MANTENIMIENTO GLOBAL COMPLETADO para ${type}`, ...prev]);

        } catch (error: any) {
            console.error(`Error filtering ${type}:`, error);
            setMaintenanceLog(prev => [`❌ Error Global: ${error.message}`, ...prev]);
        } finally {
            setProcessingMaintenance(false);
        }
    };

    const handleRecalculateEverything = async () => {
        if (!confirm("¿Estás seguro de que quieres recalcular TODO (Listas, Lugares y Usuarios)? Esto puede tardar un rato.")) return;

        // Chain them sequentially
        await handleGlobalRecalculate('lists');
        await handleGlobalRecalculate('places');
        await handleGlobalRecalculate('users');

        setMaintenanceLog(prev => [`🎉🎉 MANTENIMIENTO TOTAL COMPLETADO 🎉🎉`, ...prev]);
    };



    // --- Badge Management Functions ---
    const fetchBadges = async () => {
        setLoadingBadges(true);
        try {
            const q = query(collection(db, 'badges'));
            const snap = await getDocs(q);
            setBadges(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        } catch (error) {
            console.error("Error fetching badges:", error);
        } finally {
            setLoadingBadges(false);
        }
    };

    const handleSaveBadge = async (badgeData: any) => {
        try {
            const { id, ...data } = badgeData;
            if (id) {
                await setDoc(doc(db, 'badges', id), data, { merge: true });
            }
            fetchBadges();
            setBadgeModalOpen(false);
        } catch (error) {
            console.error("Error saving badge:", error);
            alert("Error saving badge");
        }
    };

    // --- Reports Functions ---
    const fetchReports = async () => {
        setLoadingReports(true);
        try {
            const snap = await getDocs(query(collection(db, 'reports'), firestoreLimit(50)));
            setReports(snap.docs.map(d => ({ id: d.id, ...d.data() })).sort((a: any, b: any) => b.createdAt?.seconds - a.createdAt?.seconds));
        } catch (error) {
            console.error("Error fetching reports:", error);
        } finally {
            setLoadingReports(false);
        }
    };

    const handleUpdateReportStatus = async (reportId: string, newStatus: string) => {
        try {
            await updateDoc(doc(db, 'reports', reportId), { status: newStatus });
            fetchReports();
        } catch (error) {
            console.error("Error updating report:", error);
            alert("Error al actualizar reporte");
        }
    };

    useEffect(() => {
        if (activeTab === 'gamification') fetchBadges();
        if (activeTab === 'reports') fetchReports();
    }, [activeTab]);

    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    useEffect(() => {
        if (!isAuthorized && !loadingProfile) {
            // Optional: redirect or just show the unauthorized message
        }
    }, [isAuthorized, loadingProfile]);

    // Update active tab logic if needed

    if (loadingProfile || isAuthorized === null) {
        return <div className="min-h-screen pt-24 text-center text-gray-500">Verificando permisos...</div>;
    }

    return (
        <>
            {!isAuthorized ? (
                <div className="flex flex-col items-center justify-center h-[calc(100vh-80px)] p-6 text-center pt-24">
                    <AlertCircle className="w-16 h-16 text-red-500 mb-4 opacity-80" />
                    <h2 className="text-2xl font-bold text-white mb-2">Acceso Restringido</h2>
                    <p className="text-gray-500 max-w-md">Esta área es exclusiva para administradores del sistema.</p>
                </div>
            ) : (
                <div className="flex h-screen overflow-hidden pt-16"> {/* Added pt-16 for header spacing */}
                    {/* Mobile Sidebar Toggle */}
                    <button
                        className="fixed top-20 left-4 z-50 p-2 bg-[#151b2e] border border-white/10 rounded-lg text-white md:hidden shadow-xl"
                        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                    >
                        {isSidebarOpen ? <X className="w-6 h-6" /> : <ListIcon className="w-6 h-6" />}
                    </button>

                    {/* Sidebar Nav */}
                    <nav className={`
                        fixed md:static inset-y-0 left-0 z-40 w-64 bg-[#121624] border-r border-white/5 flex flex-col pt-20 md:pt-6 shrink-0 transition-transform duration-300 ease-in-out
                        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
                    `}>
                        <div className="px-6 mb-6 md:hidden">
                            <h2 className="text-xl font-bold text-white">Menú Dev</h2>
                        </div>

                        <button
                            onClick={() => { setActiveTab('console'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'console' ? 'border-indigo-500 bg-indigo-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <Database className="w-5 h-5" /> Consola de Datos
                        </button>
                        <button
                            onClick={() => { setActiveTab('algolia'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'algolia' ? 'border-cyan-500 bg-cyan-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <CloudLightning className="w-5 h-5" /> Algolia Sync
                        </button>
                        <button
                            onClick={() => { setActiveTab('maintenance'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'maintenance' ? 'border-emerald-500 bg-emerald-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <RefreshCw className="w-5 h-5" /> Mantenimiento
                        </button>
                        <button
                            onClick={() => { setActiveTab('gamification'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'gamification' ? 'border-amber-500 bg-amber-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <Tag className="w-5 h-5" /> Gamificación
                        </button>
                        <button
                            onClick={() => { setActiveTab('reports'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'reports' ? 'border-red-500 bg-red-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <Flag className="w-5 h-5" /> Reportes
                        </button>
                        <button
                            onClick={() => { setActiveTab('branding'); setIsSidebarOpen(false); }}
                            className={`flex items-center gap-3 px-6 py-3 border-l-2 transition-all ${activeTab === 'branding' ? 'border-indigo-500 bg-indigo-500/5 text-white' : 'border-transparent text-gray-500 hover:text-gray-300'}`}
                        >
                            <Palette className="w-5 h-5" /> Marca & SEO
                        </button>
                    </nav>

                    {/* Main Content */}
                    <main className="flex-1 overflow-y-auto bg-[#0a0c10] p-8">

                        {activeTab === 'console' && (
                            <div className="space-y-6">
                                {/* Search Bar */}
                                <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 shadow-xl">
                                    <h2 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                        <Search className="w-5 h-5 text-indigo-400" /> Explorador de Firestore
                                    </h2>
                                    <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-4">
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Colección</label>
                                            <select
                                                value={consoleParams.collection}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, collection: e.target.value })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            >
                                                <option value="lists">Listas</option>
                                                <option value="places">Lugares</option>
                                                <option value="users">Usuarios</option>
                                                <option value="categories">Categorías</option>
                                                <option value="listForums">Foros</option>
                                            </select>
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Doc ID</label>
                                            <input
                                                placeholder="Exact Match"
                                                value={consoleParams.id || ''}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, id: e.target.value })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            />
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">User ID / Email</label>
                                            <input
                                                placeholder="Owner ID"
                                                value={consoleParams.user || ''}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, user: e.target.value })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            />
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nombre (Contiene)</label>
                                            <input
                                                placeholder="Client Filter"
                                                value={consoleParams.nameContains || ''}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, nameContains: e.target.value })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            />
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Google Place ID</label>
                                            <input
                                                placeholder="ChIJ..."
                                                value={consoleParams.googleId || ''}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, googleId: e.target.value })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            />
                                        </div>
                                        <div className="col-span-1">
                                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Límite</label>
                                            <input
                                                type="number"
                                                value={consoleParams.limit}
                                                onChange={(e) => setConsoleParams({ ...consoleParams, limit: parseInt(e.target.value) || 50 })}
                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                            />
                                        </div>
                                    </div>
                                    <div className="flex justify-end gap-3">
                                        <button
                                            onClick={() => setConsoleParams({ collection: 'lists', limit: 100 })}
                                            className="px-4 py-2 rounded-lg bg-white/5 hover:bg-white/10 text-white text-sm font-bold transition-colors"
                                        >
                                            Limpiar
                                        </button>
                                        <button
                                            onClick={handleConsoleSearch}
                                            disabled={loadingConsole}
                                            className="px-6 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white font-bold transition-colors flex items-center gap-2"
                                        >
                                            {loadingConsole ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
                                            Buscar
                                        </button>
                                    </div>
                                </div>

                                {/* Results */}
                                {consoleError && (
                                    <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400">
                                        Error: {consoleError}
                                    </div>
                                )}

                                <div className="grid grid-cols-1 gap-4">
                                    <div className="flex justify-between items-center text-gray-400 text-sm">
                                        <span>Resultados: {consoleResults.length}</span>
                                    </div>
                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden overflow-x-auto">
                                        <table className="w-full text-left text-sm text-gray-300">
                                            <thead className="bg-white/5 text-gray-100 font-bold uppercase text-xs">
                                                <tr>
                                                    <th className="p-4">ID</th>
                                                    <th className="p-4">Name / Title</th>
                                                    <th className="p-4">User</th>
                                                    <th className="p-4">Created</th>
                                                    <th className="p-4">Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-white/5">
                                                {consoleResults.map(item => (
                                                    <tr
                                                        key={item.id}
                                                        className="hover:bg-white/5 transition-colors cursor-pointer"
                                                        onClick={() => {
                                                            setSelectedItem(item);
                                                            setIsModalOpen(true);
                                                        }}
                                                    >
                                                        <td className="p-4 font-mono text-xs text-indigo-400">{item.id}</td>
                                                        <td className="p-4 font-medium">{item.name || item.displayName || item.title || '-'}</td>
                                                        <td className="p-4 text-xs">{item.userId || item.ownerId || item.email || '-'}</td>
                                                        <td className="p-4 text-xs font-mono">
                                                            {item.createdAt?.seconds ? new Date(item.createdAt.seconds * 1000).toLocaleDateString() : '-'}
                                                        </td>
                                                        <td className="p-4">
                                                            <button
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    setSelectedItem(item);
                                                                    setIsModalOpen(true);
                                                                }}
                                                                className="text-xs bg-indigo-500/20 text-indigo-400 px-2 py-1 rounded hover:bg-indigo-500/30"
                                                            >
                                                                Editar
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                                {consoleResults.length === 0 && !loadingConsole && (
                                                    <tr>
                                                        <td colSpan={5} className="p-8 text-center text-gray-500">
                                                            Sin resultados
                                                        </td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>

                                <DeveloperItemModal
                                    isOpen={isModalOpen}
                                    onClose={() => setIsModalOpen(false)}
                                    collectionName={consoleParams.collection}
                                    item={selectedItem}
                                    onSaved={handleConsoleSearch}
                                />
                            </div >
                        )}

                        {
                            activeTab === 'algolia' && (
                                <div className="space-y-6">
                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6">
                                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                                            <CloudLightning className="w-5 h-5 text-yellow-400" /> Sincronización Manual
                                        </h3>
                                        <p className="text-gray-400 mb-6">Fuerza la re-indexación de datos en Algolia. Úsalo con precaución.</p>

                                        <div className="flex flex-wrap gap-4">
                                            <button
                                                onClick={() => runAlgoliaSync(null)}
                                                disabled={processingAlgolia}
                                                className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded-lg flex items-center gap-2"
                                            >
                                                Sincronizar TODO
                                            </button>
                                            <button
                                                onClick={() => runAlgoliaSync('lists')}
                                                disabled={processingAlgolia}
                                                className="px-4 py-3 bg-white/5 hover:bg-white/10 disabled:opacity-50 text-white font-bold rounded-lg border border-white/10"
                                            >
                                                Sync Lists
                                            </button>
                                            <button
                                                onClick={() => runAlgoliaSync('places')}
                                                disabled={processingAlgolia}
                                                className="px-4 py-3 bg-white/5 hover:bg-white/10 disabled:opacity-50 text-white font-bold rounded-lg border border-white/10"
                                            >
                                                Sync Places
                                            </button>
                                            <button
                                                onClick={() => runAlgoliaSync('users')}
                                                disabled={processingAlgolia}
                                                className="px-4 py-3 bg-white/5 hover:bg-white/10 disabled:opacity-50 text-white font-bold rounded-lg border border-white/10"
                                            >
                                                Sync Users
                                            </button>
                                        </div>
                                    </div>

                                    <div className="bg-black/40 border border-white/10 rounded-xl p-4 font-mono text-xs h-96 overflow-y-auto">
                                        <div className="text-gray-500 mb-2 border-b border-white/5 pb-2">Logs de actividad...</div>
                                        {algoliaLog.map((log, i) => (
                                            <div key={i} className="text-gray-300 py-1">{log}</div>
                                        ))}
                                    </div>
                                </div>
                            )
                        }


                        {
                            activeTab === 'maintenance' && (
                                <div className="space-y-6">
                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6">
                                        <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                                            <ListIcon className="w-5 h-5 text-purple-400" /> Mantenimiento de Listas
                                        </h3>
                                        <p className="text-gray-400 mb-6">Herramientas para recalcular contadores y estadísticas de listas desincronizadas.</p>

                                        {/* Global Maintenance */}
                                        <div className="mb-8 p-4 bg-indigo-500/10 border border-indigo-500/20 rounded-xl">
                                            <h4 className="text-sm font-bold text-indigo-300 uppercase mb-3 flex items-center gap-2">
                                                <Database className="w-4 h-4" /> Mantenimiento Global
                                            </h4>
                                            <div className="flex gap-4 flex-wrap">
                                                <button
                                                    onClick={handleRecalculateEverything}
                                                    disabled={processingMaintenance}
                                                    className="px-6 py-2 bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-600 hover:from-indigo-500 hover:to-pink-500 disabled:opacity-50 text-white text-sm font-bold rounded-lg flex items-center gap-2 transition-all shadow-lg shadow-purple-900/40"
                                                >
                                                    {processingMaintenance ? <RefreshCw className="w-5 h-5 animate-spin" /> : <CloudLightning className="w-5 h-5" />}
                                                    ACTUALIZAR TODO (MASTER)
                                                </button>
                                                <div className="w-full h-px bg-white/5 my-2"></div>
                                                <button
                                                    onClick={() => handleGlobalRecalculate('lists')}
                                                    disabled={processingMaintenance}
                                                    className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white text-sm font-bold rounded-lg flex items-center gap-2 transition-colors"
                                                >
                                                    {processingMaintenance ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />}
                                                    Recalcular TODAS las Listas
                                                </button>
                                                <button
                                                    onClick={() => handleGlobalRecalculate('places')}
                                                    disabled={processingMaintenance}
                                                    className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-sm font-bold rounded-lg flex items-center gap-2 transition-colors"
                                                >
                                                    {processingMaintenance ? <RefreshCw className="w-4 h-4 animate-spin" /> : <MapPin className="w-4 h-4" />}
                                                    Recalcular TODOS los Lugares
                                                </button>
                                                <button
                                                    onClick={() => handleGlobalRecalculate('users')}
                                                    disabled={processingMaintenance}
                                                    className="px-4 py-2 bg-pink-600 hover:bg-pink-500 disabled:opacity-50 text-white text-sm font-bold rounded-lg flex items-center gap-2 transition-colors"
                                                >
                                                    {processingMaintenance ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Users className="w-4 h-4" />}
                                                    Recalcular TODOS los Usuarios
                                                </button>
                                            </div>
                                            <p className="text-xs text-gray-500 mt-2">
                                                ⚠️ Estas operaciones pueden tardar varios minutos. No cierres la pestaña.
                                            </p>
                                        </div>

                                        <div className="flex gap-4 items-end max-w-2xl">
                                            <div className="flex-1">
                                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">List ID</label>
                                                <input
                                                    type="text"
                                                    value={targetListId}
                                                    onChange={(e) => setTargetListId(e.target.value)}
                                                    placeholder="Paste List ID here..."
                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-purple-500 font-mono"
                                                />
                                            </div>
                                            <button
                                                onClick={handleRecalculateList}
                                                disabled={processingMaintenance || !targetListId}
                                                className="px-6 py-2 bg-purple-600 hover:bg-purple-500 disabled:opacity-50 text-white font-bold rounded-lg flex items-center gap-2"
                                            >
                                                {processingMaintenance ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                                                Recalcular Lista
                                            </button>
                                        </div>
                                        <div className="flex gap-4 items-end max-w-2xl mt-4 border-t border-white/5 pt-4">
                                            <div className="flex-1">
                                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Place ID</label>
                                                <input
                                                    type="text"
                                                    value={targetPlaceId || ''}
                                                    onChange={(e) => setTargetPlaceId(e.target.value)}
                                                    placeholder="Paste Place ID here..."
                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-purple-500 font-mono"
                                                />
                                            </div>
                                            <button
                                                onClick={handleRecalculatePlace}
                                                disabled={processingMaintenance || !targetPlaceId}
                                                className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white font-bold rounded-lg flex items-center gap-2"
                                            >
                                                {processingMaintenance ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                                                Recalcular Lugar
                                            </button>
                                        </div>
                                    </div>

                                    <div className="bg-black/40 border border-white/10 rounded-xl p-4 font-mono text-xs h-96 overflow-y-auto">
                                        <div className="text-gray-500 mb-2 border-b border-white/5 pb-2">Logs de mantenimiento...</div>
                                        {maintenanceLog.map((log, i) => (
                                            <div key={i} className="text-gray-300 py-1">{log}</div>
                                        ))}
                                    </div>
                                </div>
                            )
                        }

                        {activeTab === 'branding' && <BrandingManager />}

                        {
                            activeTab === 'gamification' && (
                                <div className="max-w-6xl mx-auto">
                                    <div className="flex items-center justify-between mb-6">
                                        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                                            <Tag className="w-6 h-6 text-amber-500" /> Gamificación Avanzada
                                        </h2>
                                        <div className="flex gap-2">
                                            <button
                                                onClick={() => {
                                                    setEditingBadge({}); // Empty object for new badge
                                                    setBadgeModalOpen(true);
                                                }}
                                                className="px-4 py-2 bg-amber-600 hover:bg-amber-500 text-white font-bold rounded-lg flex items-center gap-2 shadow-lg shadow-amber-900/20"
                                            >
                                                <div className="text-lg leading-none">+</div> Nueva Medalla
                                            </button>
                                            <button
                                                onClick={fetchBadges}
                                                className="p-2 bg-white/5 rounded-lg hover:bg-white/10 text-white"
                                            >
                                                <RefreshCw className={`w-4 h-4 ${loadingBadges ? 'animate-spin' : ''}`} />
                                            </button>
                                        </div>
                                    </div>

                                    {/* --- MANUAL ASSIGNMENT TOOL --- */}
                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 mb-8 relative overflow-hidden">
                                        <div className="absolute top-0 right-0 p-4 opacity-5">
                                            <CheckCircle className="w-32 h-32 text-indigo-500" />
                                        </div>
                                        <h3 className="text-lg font-bold text-white mb-4 relative z-10 flex items-center gap-2">
                                            <CheckCircle className="w-5 h-5 text-indigo-400" /> Asignación Manual
                                        </h3>
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 relative z-10 items-end">
                                            <div className="col-span-1">
                                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">User ID</label>
                                                <input
                                                    id="manualAssignUserId"
                                                    placeholder="User UID"
                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                                />
                                            </div>
                                            <div className="col-span-1">
                                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Badge ID</label>
                                                <select
                                                    id="manualAssignBadgeId"
                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-indigo-500"
                                                >
                                                    <option value="">Seleccionar Medalla...</option>
                                                    {badges.map(b => (
                                                        <option key={b.id} value={b.id}>{b.name} ({b.id})</option>
                                                    ))}
                                                </select>
                                            </div>
                                            <div className="col-span-1 flex gap-2">
                                                <button
                                                    onClick={async () => {
                                                        const uid = (document.getElementById('manualAssignUserId') as HTMLInputElement).value;
                                                        const badgeId = (document.getElementById('manualAssignBadgeId') as HTMLSelectElement).value;
                                                        if (!uid || !badgeId) return alert("Faltan datos");
                                                        if (!confirm(`¿Asignar ${badgeId} a ${uid}?`)) return;

                                                        try {
                                                            await setDoc(doc(db, `users/${uid}/obtainedBadges/${badgeId}`), {
                                                                obtainedAt: new Date(),
                                                                assignedBy: 'admin',
                                                                reason: 'Manual Assignment via Console'
                                                            });
                                                            alert("✅ Medalla Asignada");
                                                        } catch (e: any) {
                                                            alert("Error: " + e.message);
                                                        }
                                                    }}
                                                    className="flex-1 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-lg transition-colors"
                                                >
                                                    Asignar
                                                </button>
                                                <button
                                                    onClick={async () => {
                                                        const uid = (document.getElementById('manualAssignUserId') as HTMLInputElement).value;
                                                        const badgeId = (document.getElementById('manualAssignBadgeId') as HTMLSelectElement).value;
                                                        if (!uid || !badgeId) return alert("Faltan datos");
                                                        if (!confirm(`¿REVOCAR ${badgeId} a ${uid}?`)) return;

                                                        try {
                                                            await deleteDoc(doc(db, `users/${uid}/obtainedBadges/${badgeId}`)); // Requires import deleteDoc
                                                            alert("🗑️ Medalla Revocada");
                                                        } catch (e: any) {
                                                            alert("Error: " + e.message);
                                                        }
                                                    }}
                                                    className="px-4 py-2 bg-red-600/20 hover:bg-red-600 text-red-500 hover:text-white font-bold rounded-lg transition-colors border border-red-600/30"
                                                >
                                                    Revocar
                                                </button>
                                            </div>
                                        </div>
                                    </div>

                                    {/* --- BADGE LIST --- */}
                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
                                        {badges.map(badge => (
                                            <div key={badge.id} className="bg-[#151b2e] border border-white/10 rounded-xl p-6 relative group hover:border-amber-500/50 transition-all">
                                                <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button
                                                        onClick={() => { setEditingBadge(badge); setBadgeModalOpen(true); }}
                                                        className="p-1 hover:bg-white/10 rounded text-gray-400 hover:text-white"
                                                    >
                                                        <Palette className="w-4 h-4" /> {/* Edit Icon */}
                                                    </button>
                                                    <button
                                                        onClick={async () => {
                                                            if (confirm(`¿ELIMINAR DEFINITIVAMENTE la medalla ${badge.name}? Esto no la quita de los usuarios que ya la tienen.`)) {
                                                                try {
                                                                    await deleteDoc(doc(db, 'badges', badge.id));
                                                                    fetchBadges();
                                                                } catch (e) { console.error(e); alert("Error eliminando"); }
                                                            }
                                                        }}
                                                        className="p-1 hover:bg-red-500/20 rounded text-gray-400 hover:text-red-500"
                                                    >
                                                        <X className="w-4 h-4" />
                                                    </button>
                                                </div>
                                                <div className="absolute top-4 left-4 text-xs font-mono text-gray-600 select-all">{badge.id}</div>

                                                <div className="flex items-center gap-4 mb-4 mt-6">
                                                    <div className="w-16 h-16 rounded-full bg-gradient-to-tr from-amber-600 to-yellow-400 flex items-center justify-center text-3xl shadow-lg relative overflow-hidden">
                                                        {badge.imageUrl ? (
                                                            <img src={badge.imageUrl} alt={badge.name} className="w-full h-full object-cover" />
                                                        ) : (
                                                            <span>{badge.icon || '🏅'}</span>
                                                        )}
                                                    </div>
                                                    <div>
                                                        <h3 className="font-bold text-white text-lg leading-tight">{badge.name}</h3>
                                                        <span className="text-[10px] bg-amber-500/10 text-amber-500 px-2 py-0.5 rounded border border-amber-500/20 font-bold uppercase tracking-wider">
                                                            {badge.category || 'GENERAL'}
                                                        </span>
                                                        {badge.active === false && <span className="ml-2 text-[10px] bg-red-500/10 text-red-500 px-2 py-0.5 rounded border border-red-500/20 font-bold uppercase">INACTIVA</span>}
                                                    </div>
                                                </div>
                                                <p className="text-gray-400 text-sm mb-3 line-clamp-2 min-h-[40px]">{badge.description}</p>

                                                <div className="flex flex-wrap gap-2 text-xs font-mono text-gray-500">
                                                    <span className="bg-black/20 px-2 py-1 rounded border border-white/5">Type: {badge.type}</span>
                                                    {badge.threshold > 0 && <span className="bg-black/20 px-2 py-1 rounded border border-white/5">Thres: {badge.threshold}</span>}
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {/* --- BULK OPERATIONS (Moved to bottom) --- */}
                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 opacity-60 hover:opacity-100 transition-opacity">
                                        <h3 className="text-sm font-bold text-gray-500 uppercase mb-4 flex items-center gap-2">
                                            <CloudLightning className="w-4 h-4" /> Zona de Peligro / Global
                                        </h3>
                                        <div className="flex gap-4">
                                            <button
                                                onClick={async () => {
                                                    if (!confirm("⚠️ RECALCULAR GAMIFICACIÓN GLOBAL: ¿Estás seguro?")) return;
                                                    setLoadingBadges(true);
                                                    setMaintenanceLog(prev => [`[${new Date().toLocaleTimeString()}] GLOBAL SYNC START...`, ...prev]);
                                                    try {
                                                        const functions = getFunctions(undefined, FUNCTIONS_REGION);
                                                        const bulkFn = httpsCallable(functions, 'adminRecalculateAllGamification');
                                                        const res: any = await bulkFn();
                                                        if (res.data.logs) setMaintenanceLog(prev => [...res.data.logs.reverse(), ...prev]);
                                                        setMaintenanceLog(prev => [`✅ DONE`, ...prev]);
                                                    } catch (e: any) {
                                                        setMaintenanceLog(prev => [`❌ ERROR: ${e.message}`, ...prev]);
                                                    } finally {
                                                        setLoadingBadges(false);
                                                    }
                                                }}
                                                disabled={loadingBadges}
                                                className="px-4 py-2 border border-red-500/30 text-red-500 hover:bg-red-500 hover:text-white rounded-lg text-xs font-bold transition-all"
                                            >
                                                Recalcular TODO
                                            </button>
                                        </div>
                                    </div>

                                    {/* --- EDIT MODAL --- */}
                                    {badgeModalOpen && (
                                        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in" onClick={() => setBadgeModalOpen(false)}>
                                            <div className="bg-[#151b2e] rounded-2xl w-full max-w-2xl border border-white/10 shadow-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
                                                <div className="p-6 border-b border-white/10 flex justify-between items-center bg-[#1a2036]">
                                                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                                                        {editingBadge?.id ? <Palette className="w-5 h-5 text-amber-500" /> : <Tag className="w-5 h-5 text-green-500" />}
                                                        {editingBadge?.id ? 'Editar Medalla' : 'Nueva Medalla'}
                                                    </h3>
                                                    <button onClick={() => setBadgeModalOpen(false)} className="text-gray-400 hover:text-white"><X className="w-6 h-6" /></button>
                                                </div>

                                                <div className="p-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                                                    <div className="space-y-5">

                                                        <div className="grid grid-cols-2 gap-4">
                                                            <div>
                                                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">ID (Slug)</label>
                                                                <input
                                                                    disabled={!!editingBadge?.id} // Cannot change ID of existing
                                                                    className={`w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500 font-mono ${editingBadge?.id ? 'opacity-50 cursor-not-allowed' : ''}`}
                                                                    value={editingBadge?.id || editingBadge?.newId || ''}
                                                                    onChange={e => !editingBadge?.id && setEditingBadge({ ...editingBadge, newId: e.target.value })}
                                                                    placeholder="ej: early_adopter"
                                                                />
                                                            </div>
                                                            <div>
                                                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Categoría</label>
                                                                <select
                                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500"
                                                                    value={editingBadge?.category || 'GENERAL'}
                                                                    onChange={e => setEditingBadge({ ...editingBadge, category: e.target.value })}
                                                                >
                                                                    <option value="GENERAL">General</option>
                                                                    <option value="EXPERT">Expert</option>
                                                                    <option value="SPECIAL">Special</option>
                                                                    <option value="HIDDEN">Hidden</option>
                                                                </select>
                                                            </div>
                                                        </div>

                                                        <div>
                                                            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Nombre</label>
                                                            <input
                                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500"
                                                                value={editingBadge?.name || ''}
                                                                onChange={e => setEditingBadge({ ...editingBadge, name: e.target.value })}
                                                            />
                                                        </div>

                                                        <div>
                                                            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Descripción Pública</label>
                                                            <textarea
                                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500 h-20"
                                                                value={editingBadge?.description || ''}
                                                                onChange={e => setEditingBadge({ ...editingBadge, description: e.target.value })}
                                                            />
                                                        </div>

                                                        <div>
                                                            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Lógica (Interna/Notas)</label>
                                                            <textarea
                                                                className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-amber-200 outline-none focus:border-amber-500 h-16 font-mono text-xs"
                                                                value={editingBadge?.logicNotes || ''}
                                                                onChange={e => setEditingBadge({ ...editingBadge, logicNotes: e.target.value })}
                                                                placeholder="Notas para devs sobre cómo se gana..."
                                                            />
                                                        </div>

                                                        <div className="grid grid-cols-3 gap-4">
                                                            <div className="col-span-1">
                                                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Tipo</label>
                                                                <select
                                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500"
                                                                    value={editingBadge?.type || 'custom'}
                                                                    onChange={e => setEditingBadge({ ...editingBadge, type: e.target.value })}
                                                                >
                                                                    <option value="custom">Custom (Manual)</option>
                                                                    <option value="review_count">Contador Reseñas</option>
                                                                    <option value="place_count">Contador Lugares</option>
                                                                </select>
                                                            </div>
                                                            <div className="col-span-1">
                                                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Umbral</label>
                                                                <input
                                                                    type="number"
                                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500"
                                                                    value={editingBadge?.threshold || 0}
                                                                    onChange={e => setEditingBadge({ ...editingBadge, threshold: parseInt(e.target.value) })}
                                                                />
                                                            </div>
                                                            <div className="col-span-1">
                                                                <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Icono (Emoji)</label>
                                                                <input
                                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500 text-center"
                                                                    value={editingBadge?.icon || ''}
                                                                    onChange={e => setEditingBadge({ ...editingBadge, icon: e.target.value })}
                                                                    placeholder="🏆"
                                                                />
                                                            </div>
                                                        </div>

                                                        <div>
                                                            <label className="block text-xs font-bold text-gray-400 uppercase mb-2">Imagen URL (Upload)</label>

                                                            <div className="flex flex-col gap-3">
                                                                {/* URL Input */}
                                                                <input
                                                                    type="text"
                                                                    className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-white outline-none focus:border-amber-500 text-xs font-mono"
                                                                    value={editingBadge?.imageUrl || ''}
                                                                    onChange={e => setEditingBadge({ ...editingBadge, imageUrl: e.target.value })}
                                                                    placeholder="https://..."
                                                                />

                                                                {/* Drag & Drop Zone */}
                                                                <div
                                                                    className="relative group border-2 border-dashed border-white/10 hover:border-amber-500/50 bg-black/20 hover:bg-black/30 rounded-xl p-6 transition-all cursor-pointer text-center"
                                                                    onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
                                                                    onDrop={async (e) => {
                                                                        e.preventDefault(); e.stopPropagation();
                                                                        const file = e.dataTransfer.files?.[0];
                                                                        if (!file) return;

                                                                        // Reuse upload logic
                                                                        const badgeId = editingBadge?.id || editingBadge?.newId;
                                                                        if (!badgeId) return alert("Primero define un ID para la medalla");

                                                                        try {
                                                                            const { ref: sRef, uploadBytes, getDownloadURL } = await import('firebase/storage');
                                                                            const storageRef = sRef(storage, `badges/${badgeId}/${Date.now()}_icon`);

                                                                            // Show temp loading state visually if needed, but for now just blocking
                                                                            const snap = await uploadBytes(storageRef, file);
                                                                            const url = await getDownloadURL(snap.ref);
                                                                            setEditingBadge((prev: any) => ({ ...prev, imageUrl: url }));
                                                                        } catch (err: any) {
                                                                            console.error(err);
                                                                            alert("Error subiendo icono: " + err.message);
                                                                        }
                                                                    }}
                                                                >
                                                                    <input
                                                                        type="file"
                                                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                                                        accept="image/*"
                                                                        onChange={async (e) => {
                                                                            const file = e.target.files?.[0];
                                                                            const badgeId = editingBadge?.id || editingBadge?.newId;
                                                                            if (file && badgeId) {
                                                                                try {
                                                                                    const { ref: sRef, uploadBytes, getDownloadURL } = await import('firebase/storage');
                                                                                    const storageRef = sRef(storage, `badges/${badgeId}/${Date.now()}_icon`);
                                                                                    const snap = await uploadBytes(storageRef, file);
                                                                                    const url = await getDownloadURL(snap.ref);
                                                                                    setEditingBadge((prev: any) => ({ ...prev, imageUrl: url }));
                                                                                } catch (err: any) {
                                                                                    console.error(err);
                                                                                    alert("Error subiendo icono: " + err.message);
                                                                                }
                                                                            } else if (file) {
                                                                                alert("Primero define un ID para la medalla");
                                                                            }
                                                                        }}
                                                                    />

                                                                    <div className="flex flex-col items-center gap-2 pointer-events-none">
                                                                        {editingBadge?.imageUrl ? (
                                                                            <img src={editingBadge.imageUrl} className="w-16 h-16 object-contain mb-2 rounded-lg bg-black/50" />
                                                                        ) : (
                                                                            <Upload className="w-8 h-8 text-gray-500 group-hover:text-amber-500 transition-colors" />
                                                                        )}
                                                                        <span className="text-sm font-bold text-gray-400 group-hover:text-white">
                                                                            {editingBadge?.imageUrl ? 'Arrastra para cambiar imagen' : 'Arrastra imagen o click para subir'}
                                                                        </span>
                                                                        <span className="text-xs text-gray-600">Max 2MB (PNG/JPG)</span>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </div>

                                                        <div className="flex items-center gap-2 pt-2">
                                                            <input
                                                                type="checkbox"
                                                                id="activeCheck"
                                                                checked={editingBadge?.active !== false}
                                                                onChange={e => setEditingBadge({ ...editingBadge, active: e.target.checked })}
                                                                className="w-4 h-4 rounded border-gray-600 bg-gray-700 text-amber-600 focus:ring-amber-500"
                                                            />
                                                            <label htmlFor="activeCheck" className="text-sm text-gray-300 select-none font-bold">Medalla Activa</label>
                                                        </div>

                                                    </div>
                                                </div>

                                                <div className="p-6 border-t border-white/10 flex justify-end gap-3 bg-[#151b2e]">
                                                    <button
                                                        onClick={() => setBadgeModalOpen(false)}
                                                        className="px-4 py-2 text-gray-400 hover:text-white font-bold transition-colors"
                                                    >
                                                        Cancelar
                                                    </button>
                                                    <button
                                                        onClick={() => {
                                                            const finalData = { ...editingBadge };
                                                            // Use newId if creating
                                                            if (!finalData.id && finalData.newId) {
                                                                finalData.id = finalData.newId;
                                                                delete finalData.newId;
                                                            }
                                                            if (!finalData.id) return alert("Falta ID");

                                                            handleSaveBadge(finalData);
                                                        }}
                                                        className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-lg font-bold shadow-lg shadow-amber-900/20 transition-all hover:scale-105"
                                                    >
                                                        Guardar Medalla
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )
                        }

                        {
                            activeTab === 'reports' && (
                                <div className="max-w-6xl mx-auto space-y-6">
                                    <div className="flex items-center justify-between">
                                        <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                                            <Flag className="w-6 h-6 text-red-500" /> Centro de Reportes
                                        </h2>
                                        <button onClick={fetchReports} className="p-2 bg-white/5 rounded-lg hover:bg-white/10 text-white">
                                            <RefreshCw className={`w-4 h-4 ${loadingReports ? 'animate-spin' : ''}`} />
                                        </button>
                                    </div>

                                    <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden">
                                        <table className="w-full text-left text-sm text-gray-300">
                                            <thead className="bg-white/5 text-gray-100 font-bold uppercase text-xs">
                                                <tr>
                                                    <th className="p-4">Estado</th>
                                                    <th className="p-4">Tipo</th>
                                                    <th className="p-4">Target</th>
                                                    <th className="p-4">Mensaje</th>
                                                    <th className="p-4">Reportado Por</th>
                                                    <th className="p-4">Fecha</th>
                                                    <th className="p-4">Acciones</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-white/5">
                                                {reports.map(report => (
                                                    <tr key={report.id} className="hover:bg-white/5 transition-colors">
                                                        <td className="p-4">
                                                            <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${report.status === 'resolved' ? 'bg-emerald-500/20 text-emerald-400' :
                                                                report.status === 'rejected' ? 'bg-red-500/20 text-red-400' :
                                                                    'bg-yellow-500/20 text-yellow-400'
                                                                }`}>
                                                                {report.status || 'pending'}
                                                            </span>
                                                        </td>
                                                        <td className="p-4 capitalize text-white">{report.targetType} - {report.issueType}</td>
                                                        <td className="p-4 text-xs font-mono text-gray-500">
                                                            {report.targetId} <br />
                                                            <span className="text-indigo-400">{report.targetName}</span>
                                                        </td>
                                                        <td className="p-4 max-w-xs truncate" title={report.description}>{report.description || '-'}</td>
                                                        <td className="p-4 text-xs">{report.reportedByUserId}</td>
                                                        <td className="p-4 text-xs">{report.createdAt?.seconds ? new Date(report.createdAt.seconds * 1000).toLocaleDateString() : '-'}</td>
                                                        <td className="p-4 flex gap-2">
                                                            {report.status !== 'resolved' && (
                                                                <button
                                                                    onClick={() => handleUpdateReportStatus(report.id, 'resolved')}
                                                                    className="p-1 hover:bg-emerald-500/20 text-emerald-500 rounded" title="Resolver"
                                                                >
                                                                    <CheckCircle className="w-4 h-4" />
                                                                </button>
                                                            )}
                                                            {report.status !== 'rejected' && (
                                                                <button
                                                                    onClick={() => handleUpdateReportStatus(report.id, 'rejected')}
                                                                    className="p-1 hover:bg-red-500/20 text-red-500 rounded" title="Rechazar"
                                                                >
                                                                    <X className="w-4 h-4" />
                                                                </button>
                                                            )}
                                                        </td>
                                                    </tr>
                                                ))}
                                                {reports.length === 0 && !loadingReports && (
                                                    <tr>
                                                        <td colSpan={7} className="p-8 text-center text-gray-500">No hay reportes recientes.</td>
                                                    </tr>
                                                )}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            )
                        }
                    </main >
                </div >
            )}
        </>
    );
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
    doc,
    getDoc,
    updateDoc,
    deleteDoc,
    collection,
    query,
    where,
    getDocs,
    writeBatch
} from 'firebase/firestore';
import { db } from '../firebase';
import { ArrowLeft, Save, Loader, X } from 'lucide-react';
import { CriteriaBuilder, type Criterion } from '../components/CriteriaBuilder';

export const EditListPage: React.FC = () => {
    const { listId } = useParams<{ listId: string }>();
    const { user } = useAuth();
    const navigate = useNavigate();

    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [isPublic, setIsPublic] = useState(true);
    const [publicAccess, setPublicAccess] = useState<'reader' | 'writer'>('reader');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const [parentListId, setParentListId] = useState<string | null>(null);

    // Advanced State
    const [criteria, setCriteria] = useState<Criterion[]>([]);
    const [customTags, setCustomTags] = useState<string[]>([]);
    const [tagInput, setTagInput] = useState('');

    // Inheritance Locks
    const [inheritedCriteriaIds, setInheritedCriteriaIds] = useState<string[]>([]);
    const [inheritedTags, setInheritedTags] = useState<string[]>([]);

    useEffect(() => {
        const fetchList = async () => {
            if (!listId) return;
            try {
                const docRef = doc(db, 'lists', listId);
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    const data = docSnap.data();
                    if (user && data.userId !== user.uid) {
                        alert("No tienes permiso para editar esta lista");
                        navigate('/');
                        return;
                    }
                    setName(data.name);
                    setDescription(data.description || '');
                    setIsPublic(data.isPublic !== false); // Default true
                    setPublicAccess(data.publicAccess || 'reader');
                    const pListId = data.parentListId || null;
                    setParentListId(pListId);

                    // Load Tags
                    const loadedTags = data.availableTags || [];
                    setCustomTags(loadedTags);

                    // Fetch Parent List for Inheritance info
                    if (pListId) {
                        try {
                            const parentSnap = await getDoc(doc(db, 'lists', pListId));
                            if (parentSnap.exists()) {
                                const parentData = parentSnap.data();
                                // Identify Locked Tags
                                if (parentData.availableTags) {
                                    setInheritedTags(parentData.availableTags);
                                }
                                // Identify Locked Criteria
                                if (parentData.criteriaDefinition) {
                                    setInheritedCriteriaIds(Object.keys(parentData.criteriaDefinition));
                                }
                            }
                        } catch (err) {
                            console.warn("Failed to fetch parent list", err);
                        }
                    }

                    // Load Criteria
                    if (data.criteriaDefinition) {
                        const loadedCriteria: Criterion[] = [];
                        Object.entries(data.criteriaDefinition).forEach(([key, val]: [string, any]) => {
                            if (val.type === 'slider') {
                                loadedCriteria.push({
                                    id: key,
                                    label: val.label,
                                    minLabel: val.labelMin || 'Malo',
                                    maxLabel: val.labelMax || 'Excelente',
                                    isPonderable: val.ponderable !== false
                                });
                            }
                        });
                        setCriteria(loadedCriteria);
                    }
                } else {
                    alert("Lista no encontrada");
                    navigate('/');
                }
            } catch (error) {
                console.error("Error fetching list:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchList();
    }, [listId, user, navigate]);

    // HANDLERS
    const addTag = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && tagInput.trim()) {
            e.preventDefault();
            const val = tagInput.trim();
            if (!customTags.includes(val)) {
                setCustomTags([...customTags, val]);
            }
            setTagInput('');
        }
    };
    const removeTag = (tag: string) => {
        if (inheritedTags.includes(tag)) return; // Prevent removing inherited tags
        setCustomTags(customTags.filter(t => t !== tag));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!listId) return;
        setSaving(true);

        try {
            const docRef = doc(db, 'lists', listId);

            // 1. Update List Document
            // Sync `isPublic` (legacy) with `visibility` (new)
            const newVisibility = isPublic ? 'public' : 'private';

            // Prepare Criteria Map
            const criteriaDefinitionMap: Record<string, any> = {};
            criteria.forEach(c => {
                criteriaDefinitionMap[c.id] = {
                    type: 'slider',
                    label: c.label,
                    min: 0,
                    max: 10,
                    step: 0.5,
                    labelMin: c.minLabel,
                    labelMax: c.maxLabel,
                    ponderable: c.isPonderable
                };
            });

            await updateDoc(docRef, {
                name,
                description,
                isPublic,
                publicAccess: isPublic ? publicAccess : 'reader',
                visibility: newVisibility,
                criteriaDefinition: criteriaDefinitionMap,
                availableTags: customTags // Overwrite all tags
            });

            // 2. Batch Update Reviews
            // Changing visibility requires updating all reviews for this list/sublist
            // Query all reviews where listId == listId (for main lists) OR sublistId == listId (for sublists)
            // But strict schema says reviews have `listId` as parent. 
            // If this is a sublist, reviews have `sublistId` == this ID.
            // If this is a main list, reviews have `listId` == this ID AND `sublistId` == null (technically).

            // Simplest safe approach:
            // Find all reviews where sublistId == listId (if sublist) OR listId == listId (if main list, but be careful not to touch sublist reviews if we only want to change main list visibility?)
            // Actually, if a MAIN list becomes private, all its reviews should be private.
            // If a SUBLIST becomes private, only its reviews should be private.

            // Strategy: query reviews targeting this list context.
            // Since we know if we are a sublist (parentListId exists), we can target precisely.

            let q;
            if (parentListId) {
                // We are a sublist
                q = query(collection(db, 'reviews'), where('sublistId', '==', listId));
            } else {
                // We are a main list
                // If main list changes visibility, typically we want to update its direct reviews.
                // However, sublist reviews might have their own visibility. 
                // For now, let's assume we update all reviews where listId == listId.
                q = query(collection(db, 'reviews'), where('listId', '==', listId));
            }

            const snap = await getDocs(q);
            const batch = writeBatch(db);
            let count = 0;

            snap.docs.forEach(doc => {
                // Only update if visibility is different to save writes? 
                // Or just overwrite to be safe.
                if (doc.data().visibility !== newVisibility) {
                    batch.update(doc.ref, { visibility: newVisibility });
                    count++;
                }
            });

            if (count > 0) {
                await batch.commit();
                console.log(`Updated visibility for ${count} reviews`);
            }

            navigate(`/list/${listId}`);
        } catch (error) {
            console.error("Error updating list:", error);
            alert("Error al guardar cambios");
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async () => {
        if (!listId) return;

        const confirmDelete = window.confirm(
            "¿Estás seguro de que quieres eliminar esta lista permanentemente? Esta acción no se puede deshacer."
        );

        if (!confirmDelete) return;

        setSaving(true);
        try {
            // Delete the list document
            await deleteDoc(doc(db, 'lists', listId));

            // Note: Ideally we should also delete all reviews in a batch or cloud function,
            // but for now we just delete the list entry.
            // Reviews might become orphaned or handle nicely if we filter by existing lists.

            if (parentListId) {
                navigate(`/list/${parentListId}`);
            } else {
                navigate('/');
            }
        } catch (error) {
            console.error("Error deleting list:", error);
            alert("Error al eliminar la lista");
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-[#0b1021] pt-32 flex justify-center">
                <Loader className="w-8 h-8 text-indigo-500 animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#0b1021] text-gray-100 pt-24 pb-20 px-4">
            <div className="max-w-2xl mx-auto">
                <button onClick={() => navigate(-1)} className="flex items-center text-gray-400 hover:text-white mb-6 transition-colors">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Cancelar
                </button>

                <h1 className="text-3xl font-bold font-display text-white mb-8">Editar Lista</h1>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl">
                        {/* Name */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-400 mb-2">Nombre de la Lista</label>
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all placeholder-gray-600"
                                required
                            />
                        </div>

                        {/* Description */}
                        <div className="mb-6">
                            <label className="block text-sm font-medium text-gray-400 mb-2">Descripción</label>
                            <textarea
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all placeholder-gray-600 min-h-[120px]"
                            />
                        </div>

                        {/* Visibility */}
                        <div className="flex items-center gap-3 p-4 bg-[#0b1021] rounded-lg border border-white/5">
                            <input
                                type="checkbox"
                                id="isPublic"
                                checked={isPublic}
                                onChange={(e) => setIsPublic(e.target.checked)}
                                className="w-5 h-5 rounded border-gray-600 text-indigo-600 focus:ring-indigo-500 bg-[#151b2e]"
                            />
                            <label htmlFor="isPublic" className="text-sm">
                                <span className="block font-medium text-white">Lista Pública</span>
                                <span className="block text-xs text-gray-500">Muestra esta lista en tu perfil y en la búsqueda global.</span>
                            </label>
                        </div>

                        {/* Public Access Level */}
                        {isPublic && (
                            <div className="bg-[#151b2e] p-4 rounded-xl border border-white/10 animate-fade-in mt-4">
                                <label className="block text-sm font-medium text-gray-400 mb-3">Permisos Públicos</label>
                                <div className="space-y-3">
                                    <label className="flex items-center gap-3 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="publicAccess"
                                            value="reader"
                                            checked={publicAccess === 'reader'}
                                            onChange={() => setPublicAccess('reader')}
                                            className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021] border-gray-600"
                                        />
                                        <div>
                                            <span className="block text-sm font-medium text-white">Solo Lectura</span>
                                            <span className="block text-xs text-gray-500">Los visitantes pueden ver la lista pero solo tú (y editores) pueden añadir reseñas.</span>
                                        </div>
                                    </label>
                                    <label className="flex items-center gap-3 cursor-pointer">
                                        <input
                                            type="radio"
                                            name="publicAccess"
                                            value="writer"
                                            checked={publicAccess === 'writer'}
                                            onChange={() => setPublicAccess('writer')}
                                            className="w-4 h-4 text-indigo-600 focus:ring-indigo-500 bg-[#0b1021] border-gray-600"
                                        />
                                        <div>
                                            <span className="block text-sm font-medium text-white">Colaborativa (Escritura)</span>
                                            <span className="block text-xs text-gray-500">Cualquier usuario puede añadir sus propias reseñas a esta lista.</span>
                                        </div>
                                    </label>
                                </div>
                            </div>
                        )}

                        <div className="bg-[#151b2e] p-6 rounded-xl border border-white/10 shadow-xl space-y-8">
                            <CriteriaBuilder criteria={criteria} onChange={setCriteria} lockedIds={inheritedCriteriaIds} />

                            <div className="border-t border-white/5 pt-6"></div>

                            <div>
                                <h3 className="text-lg font-bold text-white mb-2">Etiquetas</h3>
                                <p className="text-sm text-gray-400 mb-3">Define qué etiquetas estarán disponibles para clasificar las reseñas.</p>

                                <div className="flex flex-wrap gap-2 mb-3">
                                    {customTags.map(tag => {
                                        const isLocked = inheritedTags.includes(tag);
                                        return (
                                            <span key={tag} className={`px-3 py-1 rounded-full text-sm flex items-center gap-1 ${isLocked ? 'bg-indigo-900/40 text-indigo-300 border border-indigo-500/30' : 'bg-indigo-500/20 text-indigo-300'}`}>
                                                #{tag}
                                                {!isLocked && (
                                                    <button type="button" onClick={() => removeTag(tag)} className="hover:text-white"><X className="w-3 h-3" /></button>
                                                )}
                                            </span>
                                        );
                                    })}
                                </div>
                                <input
                                    type="text"
                                    value={tagInput}
                                    onChange={(e) => setTagInput(e.target.value)}
                                    onKeyDown={addTag}
                                    placeholder="Escribe y presiona Enter para añadir tag..."
                                    className="w-full bg-[#0b1021] border border-white/10 rounded-lg px-4 py-3 text-white focus:outline-none focus:border-indigo-500"
                                />
                            </div>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={saving}
                        className="w-full py-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold rounded-xl shadow-lg transition-transform active:scale-[0.99] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                    >
                        {saving ? <Loader className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                        {saving ? 'Guardando...' : 'Guardar Cambios'}
                    </button>

                    {/* Delete button */}
                    <div className="pt-8 border-t border-white/5 text-center">
                        <button
                            type="button"
                            onClick={handleDelete}
                            disabled={saving}
                            className="text-red-400 text-sm hover:underline hover:text-red-300 transition-colors disabled:opacity-50"
                        >
                            Eliminar Lista de forma permanente
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, Link, useLocation, useNavigate } from 'react-router-dom';
import { collection, query, where, getDocs, doc, getDoc, limit } from 'firebase/firestore';
import { db } from '../firebase';
import { useAuth } from '../context/AuthContext';
import { MessageSquare, MapPin, List as ListIcon, Plus, X, Camera, Bookmark, Share2, MoreVertical, Flag, Image as ImageIcon, ZoomIn } from 'lucide-react';
import { Lightbox } from '../components/Lightbox';
import { NonPonderableGauge } from '../components/NonPonderableGauge';
import { ReportModal } from '../components/ReportModal';
import { ReviewCard } from '../components/ReviewCard';
import { AddReviewForm } from '../components/AddReviewForm';
import { SaveToArchiveModal } from '../components/SaveToArchiveModal';
import { ShareModal } from '../components/ShareModal';
import { type ReviewEntity } from '../hooks/useListDetails';

// Helper for Criteria Colors
const getScoreColor = (score: number) => {
    if (score >= 9) return 'from-emerald-400 to-emerald-600';
    if (score >= 7) return 'from-indigo-400 to-indigo-600';
    if (score >= 5) return 'from-yellow-400 to-yellow-600';
    return 'from-red-400 to-red-600';
};

import { ListSelector } from '../components/ListSelector';

const toMillis = (value: any): number => {
    if (!value) return 0;
    if (typeof value?.toMillis === 'function') return value.toMillis();
    if (typeof value?.seconds === 'number') return value.seconds * 1000;
    return 0;
};


export const GroupPage: React.FC = () => {
    const { placeId, itemName } = useParams<{ placeId: string; itemName: string }>();
    const { user } = useAuth();
    const navigate = useNavigate();
    const decodedName = decodeURIComponent(itemName || '');

    // Redirect if no item name
    useEffect(() => {
        if (!itemName && placeId) {
            navigate(`/place/${placeId}`, { replace: true });
        }
    }, [itemName, placeId, navigate]);

    const [reviews, setReviews] = useState<ReviewEntity[]>([]);
    const [placeName, setPlaceName] = useState('');
    const [primaryListCriteria, setPrimaryListCriteria] = useState<any[]>([]); // New: Store definition for ordering
    const [loading, setLoading] = useState(true);

    // Navigation Context
    const location = useLocation();
    const searchParams = new URLSearchParams(location.search);
    const fromListId = searchParams.get('listId');

    // Logic for "Valorar"
    const [isFlowOpen, setIsFlowOpen] = useState(false);
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isShareModalOpen, setIsShareModalOpen] = useState(false);
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [showReportModal, setShowReportModal] = useState(false);
    const [selectedListId, setSelectedListId] = useState<string | null>(null);
    const [editingReviewId, setEditingReviewId] = useState<string | null>(null);

    // Lightbox
    const [isLightboxOpen, setIsLightboxOpen] = useState(false);
    const [lightboxIndex, setLightboxIndex] = useState(0);

    // Infinite Scroll
    const [visibleCount, setVisibleCount] = useState(4);
    const loadMoreRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                setVisibleCount(prev => prev + 5);
            }
        }, { threshold: 0.1 });

        if (loadMoreRef.current) observer.observe(loadMoreRef.current);
        return () => observer.disconnect();
    }, [reviews, visibleCount]);

    const handleEditReview = (review: ReviewEntity) => {
        setEditingReviewId(review.id);
        setIsFlowOpen(true);
    };

    const fetchData = React.useCallback(async () => {
        if (!placeId || !decodedName) return;
        setLoading(true);
        try {
            console.log("Fetching Group Data for:", { placeId, decodedName });

            // 1. Fetch Place Details First to get authoritative Name
            const pSnap = await getDoc(doc(db, 'places', placeId));
            let fetchedPlaceName = '';
            let placeData: any = null;
            if (pSnap.exists()) {
                placeData = pSnap.data();
                fetchedPlaceName = placeData.name;
                setPlaceName(fetchedPlaceName);
            }

            const [publicListsSnap, followingListsSnap, ownListsSnap] = await Promise.all([
                getDocs(query(collection(db, 'lists'), where('isPublic', '==', true), limit(60))),
                user ? getDocs(query(collection(db, 'users', user.uid, 'followingLists'), limit(60))) : Promise.resolve(null),
                user ? getDocs(query(collection(db, 'lists'), where('userId', '==', user.uid), limit(40))) : Promise.resolve(null)
            ]);

            const candidateListIds = Array.from(new Set([
                ...publicListsSnap.docs.map((d) => d.id),
                ...(followingListsSnap ? followingListsSnap.docs.map((d) => d.id) : []),
                ...(ownListsSnap ? ownListsSnap.docs.map((d) => d.id) : [])
            ])).slice(0, 80);

            const reviewsByList = await Promise.all(candidateListIds.map(async (candidateListId) => {
                try {
                    const listReviewsSnap = await getDocs(
                        query(collection(db, 'lists', candidateListId, 'reviews'), where('placeId', '==', placeId), limit(25))
                    );
                    return listReviewsSnap.docs.map((reviewDoc) => ({
                        id: reviewDoc.id,
                        ...(reviewDoc.data() as any),
                        listId: candidateListId
                    } as ReviewEntity));
                } catch (error: any) {
                    if (error?.code !== 'permission-denied') {
                        console.warn(`Error loading group reviews for list ${candidateListId}`, error);
                    }
                    return [] as ReviewEntity[];
                }
            }));

            const reviewMap = new Map<string, ReviewEntity>();
            for (const listReviews of reviewsByList) {
                for (const review of listReviews) {
                    reviewMap.set(`${review.listId || 'unknown'}:${review.id}`, review);
                }
            }

            const allPlaceReviews = Array.from(reviewMap.values());
            console.log("Group query candidate reviews:", allPlaceReviews.length);

            // Robust normalization for filtering
            const normalize = (s: string) => s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
            const targetName = normalize(decodedName);
            const normalizedPlaceName = normalize(fetchedPlaceName);

            const feats: ReviewEntity[] = allPlaceReviews
                .filter(r => {
                    if (r.itemName) {
                        return normalize(r.itemName) === targetName;
                    }
                    // If review has no item name, it belongs to the Place.
                    // Include it ONLY if the current Group Page IS the Place Page (TargetName == PlaceName)
                    return normalizedPlaceName === targetName;
                })
                .sort((a: any, b: any) => toMillis(b.createdAt) - toMillis(a.createdAt));

            console.log("Group query filtered matches:", feats.length);

            // --- Enrichment: Users & Lists (FIX for missing names) ---
            const userIds = [...new Set(feats.map(r => r.userId || r.authorId).filter(Boolean))] as string[];
            const usersMap: Record<string, any> = {};

            if (userIds.length > 0) {
                await Promise.all(userIds.slice(0, 20).map(async (uid) => {
                    try {
                        const userSnap = await getDoc(doc(db, 'users', uid));
                        if (userSnap.exists()) {
                            usersMap[uid] = userSnap.data();
                        }
                    } catch (e) { console.warn("Failed enrich user", uid); }
                }));
            }

            const listIds = [...new Set(feats.map(r => r.listId).filter(Boolean))] as string[];
            const listsMap: Record<string, any> = {};

            if (listIds.length > 0) {
                await Promise.all(listIds.slice(0, 20).map(async (lid) => {
                    try {
                        const lSnap = await getDoc(doc(db, 'lists', lid));
                        if (lSnap.exists()) {
                            listsMap[lid] = lSnap.data();
                        }
                    } catch (e) { console.warn("Failed enrich list", lid); }
                }));
            }

            // Apply Enrichment
            const enriched = feats.map(r => {
                const uid = r.userId || r.authorId;
                const user = uid ? usersMap[uid] : null;
                const listData = r.listId ? listsMap[r.listId] : undefined;
                return {
                    ...r,
                    authorName: user?.displayName || user?.name || user?.username || r.authorName || 'Anónimo',
                    authorPhoto: user?.photoUrl || user?.photoURL || r.authorPhoto,
                    listName: listData?.name || r.listName,
                    criteriaDefinition: listData?.criteriaDefinition || r.criteriaDefinition,
                    tags: (r as any).userTags || r.tags || [],
                    // Enrich Place Data
                    placeMainImage: placeData?.mainImageUrl || placeData?.photos?.[0],
                    placeName: placeData?.name || r.placeName,
                    placeCity: placeData?.city || (r as any).placeCity
                };
            });

            setReviews(enriched);

        } catch (error) {
            console.error("Error fetching group data", error);
        } finally {
            setLoading(false);
        }
    }, [placeId, decodedName, user?.uid]); // Dependencies for callback

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // Aggregate Stats (Overall + Criteria) - REFACTORED to use Primary List Order
    const stats = useMemo(() => {
        if (!reviews.length) return null;

        let totalRating = 0;
        const criteriaSums: Record<string, number> = {};
        const criteriaCounts: Record<string, number> = {};
        const labels: Record<string, string> = {};
        const tagCounts: Record<string, number> = {};

        reviews.forEach(r => {
            totalRating += (r.overallRating || 0);

            // Aggregate Criteria
            if (r.scores) {
                Object.entries(r.scores).forEach(([k, v]) => {
                    criteriaSums[k] = (criteriaSums[k] || 0) + v;
                    criteriaCounts[k] = (criteriaCounts[k] || 0) + 1;

                    // Try to get label from review if not yet found
                    if (!labels[k] && r.criteriaDefinition) {
                        if (Array.isArray(r.criteriaDefinition)) {
                            const found = r.criteriaDefinition.find((c: any) => c.id === k);
                            if (found) labels[k] = found.label;
                        } else {
                            labels[k] = r.criteriaDefinition[k]?.label;
                        }
                    }
                    if (!labels[k]) labels[k] = k; // Fallback
                });
            }

            // Aggregate Tags
            const tags = (r as any).userTags || r.tags || [];
            if (Array.isArray(tags)) {
                tags.forEach((t: string) => {
                    if (t) tagCounts[t] = (tagCounts[t] || 0) + 1;
                });
            }
        });

        const avg = totalRating / reviews.length;

        // Process Criteria using PRIMARY LIST ORDER if available
        let orderedCriteria: { key: string, label: string, avg: number, count: number, isPonderable: boolean, step: number }[] = [];
        const processedKeys = new Set();

        // 1. Add keys from Primary List in order
        if (primaryListCriteria.length > 0) {
            primaryListCriteria.forEach(pc => {
                const k = pc.id;
                if (criteriaCounts[k]) { // Only if we have data for it
                    orderedCriteria.push({
                        key: k,
                        label: pc.label || labels[k] || k, // Prefer primary list label
                        avg: criteriaSums[k] / criteriaCounts[k],
                        count: criteriaCounts[k],
                        isPonderable: pc.ponderable !== false && pc.isPonderable !== false,
                        step: pc.step || 0.1
                    });
                    processedKeys.add(k);
                }
            });
        }

        // 2. Add remaining keys (orphaned or from other lists)
        Object.keys(criteriaSums).forEach(k => {
            if (!processedKeys.has(k)) {
                orderedCriteria.push({
                    key: k,
                    label: labels[k] || k,
                    avg: criteriaSums[k] / criteriaCounts[k],
                    count: criteriaCounts[k],
                    isPonderable: true, // Default to true if unknown
                    step: 0.1
                });
            }
        });

        // Split into Ponderable / Non-Ponderable
        const ponderable = orderedCriteria.filter(c => c.isPonderable);
        const nonPonderable = orderedCriteria.filter(c => !c.isPonderable);

        // Process Tags (50% Rule)
        const minThreshold = Math.ceil(reviews.length / 2);
        const consensusTags = Object.entries(tagCounts)
            .filter(([_, count]) => count >= minThreshold)
            .map(([tag]) => tag).sort();

        // Collect Photos
        const photos = reviews.map(r => r.photoUrl).filter(Boolean) as string[];

        return {
            avg,
            count: reviews.length,
            mainPhoto: photos[0] || null,
            photos,
            ponderable,
            nonPonderable,
            tags: consensusTags
        };
    }, [reviews, primaryListCriteria]);

    // Aggregate Lists
    const relatedLists = useMemo(() => {
        return [...new Set(reviews.map(r => r.listId).filter(Boolean))];
    }, [reviews]);

    const [listsDetails, setListsDetails] = useState<{ id: string, name: string, author: string, parentListId?: string }[]>([]);

    // List Comparison States
    const [listStats, setListStats] = useState<Record<string, number> | null>(null);
    const [primaryListName, setPrimaryListName] = useState('');

    // Fetch Details for Related Lists
    useEffect(() => {
        const fetchListDetails = async () => {
            const details: any[] = [];
            for (const lid of relatedLists.slice(0, 5)) {
                try {
                    const s = await getDoc(doc(db, 'lists', lid));
                    if (s.exists()) {
                        const d = s.data();
                        details.push({
                            id: lid,
                            name: d.name,
                            author: d.authorName,
                            parentListId: d.parentListId
                        });
                    }
                } catch (e) { }
            }
            setListsDetails(details);
        };
        if (relatedLists.length > 0) fetchListDetails();
    }, [relatedLists]);

    // Fetch Stats for Primary Comparison List
    useEffect(() => {
        const fetchListStats = async () => {
            if (relatedLists.length === 0) return;
            const primaryId = relatedLists[0]; // Pick the first list

            try {
                // Get List Name & Definition
                const lSnap = await getDoc(doc(db, 'lists', primaryId));
                if (lSnap.exists()) {
                    const data = lSnap.data();
                    setPrimaryListName(data.name);

                    // Extract Criteria Definition (Array vs Map)
                    let criteriaDef: any[] = [];
                    if (data.criteriaDefinition) {
                        if (Array.isArray(data.criteriaDefinition)) {
                            criteriaDef = data.criteriaDefinition;
                        } else {
                            criteriaDef = Object.keys(data.criteriaDefinition).map(k => ({
                                id: k,
                                ...data.criteriaDefinition[k]
                            }));
                        }
                    }
                    setPrimaryListCriteria(criteriaDef);
                }

                // Get all reviews from the list subcollection to calculate averages.
                const snap = await getDocs(collection(db, 'lists', primaryId, 'reviews'));
                const lReviews = snap.docs.map(d => d.data() as ReviewEntity);

                if (lReviews.length === 0) return;

                const avgs: Record<string, number> = {};
                const counts: Record<string, number> = {};

                lReviews.forEach(r => {
                    if (r.scores) {
                        Object.entries(r.scores).forEach(([k, v]) => {
                            avgs[k] = (avgs[k] || 0) + v;
                            counts[k] = (counts[k] || 0) + 1;
                        });
                    }
                });

                Object.keys(avgs).forEach(k => {
                    avgs[k] = avgs[k] / (counts[k] || 1);
                });

                setListStats(avgs);

            } catch (e) {
                console.error("Error fetching comparison stats", e);
            }
        };
        fetchListStats();
    }, [relatedLists]);


    if (loading) {
        return (
            <div className="min-h-screen pt-32 flex justify-center bg-[#0b1021]">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
            </div>
        );
    }



    const handleDeleteReview = (deletedId: string) => {
        // 1. Remove locally
        const updated = reviews.filter(r => r.id !== deletedId);
        setReviews(updated);

        // 2. Refresh stats? (Handled by useMemo)

        // 3. Redirect if empty
        if (updated.length === 0) {
            // Try to find where to go.
            // If we came from a list (URL param), go back there.
            // If not, try to use the deleted review's listId.
            const lastReview = reviews.find(r => r.id === deletedId);
            const targetListId = fromListId || lastReview?.listId;

            if (targetListId) {
                navigate(`/list/${targetListId}`);
            } else {
                // Fallback: Go to place page or home
                navigate(`/place/${placeId}`);
            }
        }
    };

    return (
        <div className="min-h-screen bg-[#0b1021] pb-20">
            {/* Hero */}
            <div className="relative h-[40vh] min-h-[300px] w-full overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-black/40 z-10" />
                {stats?.mainPhoto ? (
                    <img src={stats.mainPhoto} className="w-full h-full object-cover opacity-80 group-hover:scale-105 transition-transform duration-1000" alt={decodedName} />
                ) : (
                    <div className="w-full h-full bg-gray-800 flex items-center justify-center">
                        <MessageSquare className="w-20 h-20 text-white/20" />
                    </div>
                )}

                {/* Top Actions Menu */}
                <div className="absolute top-4 right-4 z-30">
                    <div className="relative">
                        <button
                            onClick={() => setIsMenuOpen(!isMenuOpen)}
                            className="p-2 rounded-full bg-black/40 text-white hover:bg-black/60 backdrop-blur-sm transition-colors"
                        >
                            <MoreVertical className="w-5 h-5" />
                        </button>

                        {isMenuOpen && (
                            <div className="absolute right-0 mt-2 w-48 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl py-1 overflow-hidden animate-fade-in origin-top-right">
                                <button
                                    onClick={() => { setIsMenuOpen(false); setIsShareModalOpen(true); }}
                                    className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                >
                                    <Share2 className="w-4 h-4" /> Compartir
                                </button>
                                <button
                                    onClick={() => { setIsMenuOpen(false); setShowReportModal(true); }}
                                    className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                >
                                    <Flag className="w-4 h-4" /> Reportar
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                <div className="absolute bottom-0 left-0 w-full p-4 sm:p-8 z-20 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-transparent pt-20">
                    <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-end md:justify-between gap-6">

                        {/* Title & Place Info */}
                        <div className="flex-1">
                            <h1 className="text-3xl sm:text-4xl md:text-6xl font-display font-bold text-white mb-2 shadow-sm text-shadow-lg leading-tight line-clamp-2">{decodedName}</h1>
                            <Link to={`/place/${placeId}`} className="text-lg md:text-xl text-indigo-300 hover:text-white flex items-center gap-2 font-medium transition-colors">
                                <MapPin className="w-5 h-5 opacity-70 shrink-0" />
                                <span className="underline decoration-indigo-500/30 underline-offset-4">{placeName || 'Lugar Desconocido'}</span>
                            </Link>
                        </div>

                        {/* Ratings & Stats Row */}
                        {stats && (
                            <div className="flex flex-col items-start md:items-end gap-3">
                                <div className="flex flex-wrap items-center gap-2">
                                    {/* Rating Bubble */}
                                    <div className="flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-bold bg-emerald-500/20 border border-emerald-500/30 text-emerald-400 backdrop-blur-md">
                                        <div className="text-lg leading-none">{stats.avg.toFixed(1)}</div>
                                    </div>

                                    {/* Count Bubble */}
                                    <div className="flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-bold bg-white/10 border border-white/10 text-white backdrop-blur-md">
                                        <MessageSquare className="w-4 h-4 text-indigo-400" />
                                        <span>{stats.count}</span>
                                    </div>

                                    {/* Add Review Button */}
                                    <button
                                        onClick={() => {
                                            if (fromListId) {
                                                setSelectedListId(fromListId);
                                                setIsFlowOpen(true);
                                            } else {
                                                setSelectedListId(null);
                                                setIsFlowOpen(true);
                                            }
                                        }}
                                        className="px-4 py-2 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white text-sm font-bold rounded-xl shadow-lg shadow-emerald-500/20 flex items-center gap-2 hover:scale-105 transition-all ml-2"
                                    >
                                        <Plus className="w-4 h-4" />
                                        <span>Añadir Reseña</span>
                                    </button>
                                </div>

                                {/* Tags Row */}
                                {stats.tags && stats.tags.length > 0 && (
                                    <div className="flex flex-wrap items-center gap-2 mt-2 md:justify-end">
                                        {stats.tags.map(tag => (
                                            <span key={tag} className="px-2.5 py-0.5 rounded-full bg-white/10 border border-white/20 text-white/90 text-xs font-medium backdrop-blur-md">
                                                #{tag}
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <main className="max-w-7xl mx-auto px-4 sm:px-6 pt-4 sm:pt-8 flex flex-col lg:grid lg:grid-cols-12 gap-8">

                <div className="order-1 lg:col-span-4 lg:order-last space-y-6">

                    {/* Actions Row */}
                    <div className="bg-[#151b2e] p-3 rounded-xl border border-white/10 grid grid-cols-2 gap-3">
                        <button
                            onClick={() => setIsSaveModalOpen(true)}
                            className="bg-[#1e2538] hover:bg-[#2a3449] text-gray-200 hover:text-white rounded-xl p-4 flex flex-col items-center justify-center gap-2 transition-all border border-white/5 group"
                        >
                            <Bookmark className="w-6 h-6 group-hover:scale-110 transition-transform text-indigo-400" />
                            <span className="text-xs font-bold tracking-wide">GUARDAR</span>
                        </button>

                        <button
                            onClick={() => setIsShareModalOpen(true)}
                            className="bg-[#1e2538] hover:bg-[#2a3449] text-gray-200 hover:text-white rounded-xl p-4 flex flex-col items-center justify-center gap-2 transition-all border border-white/5 group"
                        >
                            <Share2 className="w-6 h-6 group-hover:scale-110 transition-transform text-indigo-400" />
                            <span className="text-xs font-bold tracking-wide">COMPARTIR</span>
                        </button>
                    </div>

                    {/* 1. Detailed Stats (Refactored) */}
                    {stats && (stats.ponderable.length > 0 || stats.nonPonderable.length > 0) && (
                        <div className="bg-[#151b2e] rounded-xl border border-white/10 p-5">
                            <h3 className="font-bold text-white border-b border-white/5 pb-2 text-sm uppercase tracking-wider mb-4 flex justify-between items-center">
                                <span>Puntuaciones</span>
                            </h3>

                            {/* Ponderable (Charts) */}
                            <div className="space-y-4">
                                {stats.ponderable.map((c, i) => {
                                    const listAvg = listStats?.[c.key];
                                    return (
                                        <div key={c.key}>
                                            <div className="flex justify-between items-end mb-1">
                                                <span className="text-gray-400 text-xs font-medium">{c.label}</span>
                                                <div className="flex items-center gap-2">
                                                    {listAvg && (
                                                        <span className="text-[10px] text-gray-500 font-mono" title={`Media de la lista: ${listAvg.toFixed(1)}`}>
                                                            (L: {listAvg.toFixed(1)})
                                                        </span>
                                                    )}
                                                    <span className="text-emerald-400 font-bold font-mono text-sm">{c.avg.toFixed(1)}</span>
                                                </div>
                                            </div>
                                            <div className="h-2 bg-gray-800 rounded-full overflow-hidden relative">
                                                {/* List Avg Marker */}
                                                {listAvg && (
                                                    <div
                                                        className="absolute top-0 bottom-0 w-1 bg-white/40 z-10 shadow-[0_0_4px_rgba(255,255,255,0.5)]"
                                                        style={{ left: `${Math.min(listAvg * 10, 100)}%` }}
                                                    />
                                                )}
                                                <div
                                                    className={`h-full rounded-full bg-gradient-to-r ${getScoreColor(c.avg)}`}
                                                    style={{ width: `${c.avg * 10}%` }}
                                                />
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {/* Non-Ponderable (Gauges) */}
                            {stats.nonPonderable.length > 0 && (
                                <div className="mt-6 pt-4 border-t border-white/5">
                                    <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-3">Otros Detalles</h4>
                                    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4">
                                        {stats.nonPonderable.map((c) => (
                                            <NonPonderableGauge key={c.key} score={c.avg} label={c.label} size={70} />
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {/* 2. Lists */}
                    {listsDetails.length > 0 && (
                        <div className="bg-[#151b2e] rounded-xl border border-white/10 p-5">
                            <h3 className="font-bold text-white border-b border-white/5 pb-2 text-sm uppercase tracking-wider mb-4">
                                Listas Relacionadas
                            </h3>
                            <div className="space-y-3">
                                {listsDetails.slice(0, 5).map((l: any) => (
                                    <Link key={l.id} to={`/list/${l.id}`} className="block group">
                                        <div className="flex items-center gap-3 p-2 hover:bg-white/5 rounded-lg transition-colors border border-transparent hover:border-white/5">
                                            {/* Thumbnail */}
                                            <div className={`w-12 h-12 shrink-0 rounded overflow-hidden flex items-center justify-center transition-colors bg-gray-800`}>
                                                {l.photoUrl ? (
                                                    <img src={l.photoUrl} className="w-full h-full object-cover" />
                                                ) : (
                                                    <ListIcon className={`w-5 h-5 ${l.parentListId ? 'text-purple-400' : 'text-gray-500'}`} />
                                                )}
                                            </div>

                                            <div className="min-w-0 flex-1">
                                                <div className="flex items-center gap-2">
                                                    <div className={`font-bold text-sm truncate transition-colors ${l.parentListId ? 'text-purple-300 group-hover:text-purple-400' : 'text-gray-200 group-hover:text-indigo-400'}`}>
                                                        {l.name}
                                                    </div>
                                                    {l.parentListId && (
                                                        <span className="text-[9px] px-1.5 py-0.5 rounded bg-purple-500/20 text-purple-400 uppercase tracking-wide font-bold">Sub</span>
                                                    )}
                                                </div>
                                                <div className="text-xs text-gray-500 truncate mt-0.5">
                                                    {l.itemCount ? `${l.itemCount} lugares` : 'Ver lista'}
                                                </div>
                                            </div>
                                        </div>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {/* Main Content (Left) */}
                <div className="order-2 lg:col-span-8 lg:order-first">

                    {/* Photos (Horizontal Scroll -> Grid with Lightbox) */}
                    {stats && stats.photos.length > 0 && (
                        <div className="mb-8">
                            <h3 className="font-bold text-white text-lg mb-4 flex items-center gap-2">
                                <ImageIcon className="w-5 h-5 text-indigo-500" />
                                Galería ({stats.photos.length})
                            </h3>
                            <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                {stats.photos.map((url, i) => (
                                    <div
                                        key={i}
                                        onClick={() => {
                                            setLightboxIndex(i);
                                            setIsLightboxOpen(true);
                                        }}
                                        className="aspect-square rounded-xl overflow-hidden cursor-pointer bg-gray-800 relative group border border-white/10"
                                    >
                                        <img src={url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" alt={`Foto ${i}`} />
                                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                                            <ZoomIn className="w-6 h-6 text-white drop-shadow-md" />
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <Lightbox
                                isOpen={isLightboxOpen}
                                onClose={() => setIsLightboxOpen(false)}
                                images={stats.photos}
                                initialIndex={lightboxIndex}
                            />
                        </div>
                    )}

                    {/* Reviews Header */}
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-xl font-bold text-white flex items-center gap-2">
                            <MessageSquare className="w-5 h-5 text-indigo-500" />
                            Opiniones ({reviews.length})
                        </h2>
                        {/* Mobile 'Add' button could go here if needed, but Hero button covers it */}
                    </div>

                    {/* Reviews Grid */}
                    {reviews.length > 0 ? (
                        <div className="grid grid-cols-1 gap-8 animate-fade-in">
                            {reviews.slice(0, visibleCount).map(review => (
                                <ReviewCard key={review.id} review={review} onDelete={handleDeleteReview} onEdit={handleEditReview} />
                            ))}
                            {visibleCount < reviews.length && (
                                <div ref={loadMoreRef} className="py-4 flex justify-center">
                                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="p-8 bg-[#151b2e] rounded-xl border border-white/10 text-center animate-fade-in">
                            <MessageSquare className="w-12 h-12 text-gray-600 mx-auto mb-4" />
                            <h3 className="text-lg font-bold text-white mb-2">Sé el primero en opinar</h3>
                            <p className="text-gray-400 mb-6 text-sm">Nadie ha escrito una reseña detallada sobre este plato aún.</p>
                            <button
                                onClick={() => setIsFlowOpen(true)}
                                className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-bold transition-all shadow-lg shadow-indigo-500/20"
                            >
                                Añadir Reseña
                            </button>
                        </div>
                    )}
                </div>
            </main>

            {/* Modals */}
            {
                isFlowOpen && (
                    <AddReviewForm
                        listId={selectedListId}
                        onListChange={setSelectedListId}
                        prefillPlaceId={placeId}
                        prefillItemName={decodedName}
                        editReviewId={editingReviewId || undefined}
                        lockList={!!selectedListId} // Lock if we pre-selected a list
                        onClose={() => {
                            setIsFlowOpen(false);
                            setSelectedListId(null);
                            setEditingReviewId(null);
                        }}
                        onSuccess={() => fetchData()}
                    />
                )
            }

            <SaveToArchiveModal
                isOpen={isSaveModalOpen}
                onClose={() => setIsSaveModalOpen(false)}
                item={{
                    itemId: `${placeId}_${decodedName}`, // Composite ID for group
                    type: 'group',
                    name: decodedName,
                    subtitle: placeName,
                    route: `/group/${placeId}/${encodeURIComponent(decodedName)}`,
                    photoUrl: stats?.mainPhoto || undefined,
                    placeId: placeId
                }}
            />

            <ShareModal
                isOpen={isShareModalOpen}
                onClose={() => setIsShareModalOpen(false)}
                title={`Compartir ${decodedName}`}
                text={`¡Mira lo que dicen sobre ${decodedName} en ${placeName}!`}
            />

            <ReportModal
                isOpen={showReportModal}
                onClose={() => setShowReportModal(false)}
                targetId={`${placeId}_${decodedName}`}
                targetName={decodedName}
                itemName={placeName}
                targetType="group"
            />
        </div >
    );
};

import React, { useState } from 'react';
import { ArrowRight, Sparkles, LayoutGrid, Newspaper } from 'lucide-react';
import { Link } from 'react-router-dom';
import { useLists } from '../hooks/useLists';
import { useUsers } from '../hooks/useUsers';
import { useReviews } from '../hooks/useReviews';
import { Carousel } from '../components/Carousel';
import { UserCarousel } from '../components/UserCarousel';
import { ReviewCard } from '../components/ReviewCard';

export const Home: React.FC = () => {
    const [activeTab, setActiveTab] = useState<'discovery' | 'news'>('discovery');

    const { lists: recentLists, loading: recentLoading } = useLists('recent');
    const { lists: topLists, loading: topLoading } = useLists('top_rated');
    const { users: topUsers, loading: usersLoading } = useUsers();
    const { reviews: newReviews, loading: reviewsLoading } = useReviews('recent');

    return (
        <div className="min-h-screen bg-[#0b1021]">
            {/* Hero Section */}
            <div className="relative pt-32 pb-12 px-4 sm:px-6 lg:px-8 overflow-hidden">
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full max-w-7xl h-full opacity-30 pointer-events-none">
                    <div className="absolute top-20 left-10 w-96 h-96 bg-indigo-500 rounded-full blur-[100px]" />
                    <div className="absolute bottom-20 right-10 w-96 h-96 bg-purple-500 rounded-full blur-[100px]" />
                </div>

                <div className="relative max-w-4xl mx-auto text-center z-10">
                    <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-300 text-sm mb-6 animate-fade-in-up">
                        <Sparkles className="w-4 h-4" />
                        <span>Nueva Versión Beta 2.0</span>
                    </div>

                    <h1 className="text-4xl md:text-7xl font-bold text-white mb-6 leading-tight tracking-tight animate-fade-in-up delay-100">
                        Descubre y comparte <br />
                        <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400">lo mejor de todo</span>
                    </h1>

                    <p className="text-lg md:text-xl text-gray-400 mb-10 max-w-2xl mx-auto animate-fade-in-up delay-200">
                        Crea listas de tus cosas favoritas, encuentra recomendaciones auténticas y conecta con una comunidad que comparte tus gustos.
                    </p>

                    <div className="flex flex-col sm:flex-row items-center justify-center gap-4 animate-fade-in-up delay-300">
                        <Link to="/create" className="px-8 py-4 rounded-full bg-white text-black font-bold text-lg hover:scale-105 transition-transform shadow-xl shadow-white/10 flex items-center gap-2">
                            Crear una lista
                            <ArrowRight className="w-5 h-5" />
                        </Link>
                        <Link to="/search" className="px-8 py-4 rounded-full bg-white/5 text-white font-bold text-lg hover:bg-white/10 border border-white/10 backdrop-blur-sm transition-colors">
                            Explorar
                        </Link>
                    </div>
                </div>
            </div>

            {/* Tabs Navigation */}
            <div className="sticky top-16 z-30 bg-[#0b1021]/80 backdrop-blur-md border-y border-white/5 mb-8">
                <div className="max-w-7xl mx-auto px-4 flex justify-center gap-8">
                    <button
                        onClick={() => setActiveTab('discovery')}
                        className={`flex items-center gap-2 py-4 border-b-2 transition-colors ${activeTab === 'discovery' ? 'border-indigo-500 text-indigo-400' : 'border-transparent text-gray-400 hover:text-white'}`}
                    >
                        <LayoutGrid className="w-5 h-5" />
                        <span className="font-bold">Descubrir</span>
                    </button>
                    <button
                        onClick={() => setActiveTab('news')}
                        className={`flex items-center gap-2 py-4 border-b-2 transition-colors ${activeTab === 'news' ? 'border-indigo-500 text-indigo-400' : 'border-transparent text-gray-400 hover:text-white'}`}
                    >
                        <Newspaper className="w-5 h-5" />
                        <span className="font-bold">Novedades</span>
                    </button>
                </div>
            </div>

            {/* Content Tabs */}
            <div className="pb-20 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                {activeTab === 'discovery' ? (
                    <div className="space-y-8 animate-fade-in">
                        <Carousel
                            title="🔥 Tendencias en Listopic"
                            lists={topLists}
                            loading={topLoading}
                        />

                        <UserCarousel
                            title="✨ Creadores Destacados"
                            users={topUsers as any}
                            loading={usersLoading}
                        />

                        <Carousel
                            title="🆕 Recién Agregadas"
                            lists={recentLists}
                            loading={recentLoading}
                        />
                    </div>
                ) : (
                    <div className="animate-fade-in">
                        <h2 className="text-2xl font-bold text-white mb-6">Últimas Reseñas</h2>

                        {reviewsLoading ? (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {[...Array(6)].map((_, i) => (
                                    <div key={i} className="h-48 bg-[#151b2e] rounded-xl animate-pulse border border-white/5"></div>
                                ))}
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {newReviews.map(review => (
                                    <ReviewCard key={review.id} review={review} />
                                ))}
                                {newReviews.length === 0 && (
                                    <p className="text-gray-500 col-span-full text-center py-12">No hay novedades recientes.</p>
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

