import React, { useState, useMemo, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { useFilters } from '../context/FilterContext';
import { useLists } from '../hooks/useLists';
import { useUsers } from '../hooks/useUsers';
import { useReviews } from '../hooks/useReviews';
import { ReviewCard } from '../components/ReviewCard';
import { ReviewCarouselItem } from '../components/ReviewCarouselItem';
import { CardCarousel } from '../components/CardCarousel';
import { MapView } from '../components/MapView';
import { Map as MapIcon, ChevronDown, Heart, MapPin, List as ListIcon, MessageCircle, Layers, Users } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useLocation } from '../hooks/useLocation';
import { collection, query, getDocs, limit } from 'firebase/firestore';
import { db } from '../firebase';

/* 
    HOMEPAGE (Legacy Screenshot Match + Functional Logic: Categories & Range)
*/

export const HomePage: React.FC = () => {
    const { user } = useAuth();
    const { location, calculateDistance, requestLocation } = useLocation();
    const navigate = useNavigate();

    // UI State
    const [activeTab, setActiveTab] = useState<'explore' | 'news'>('explore');
    const [activeFilter, setActiveFilter] = useState('Todo'); // Category Filter

    // Global Distance Range State
    const { range, toggleRange, getRangeLabel } = useFilters();

    const [isMapOpen, setIsMapOpen] = useState(false);

    // Following Logic
    const [followingIds, setFollowingIds] = useState<string[]>([]);
    useEffect(() => {
        if (!user) return;
        const fetchFollowing = async () => {
            const q = query(collection(db, 'users', user.uid, 'following'));
            const snap = await getDocs(q);
            setFollowingIds(snap.docs.map(d => d.id));
        };
        fetchFollowing();
    }, [user]);

    // Infinite Scroll
    const [visibleCount, setVisibleCount] = useState(4);
    const loadMoreRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                setVisibleCount(prev => prev + 5);
            }
        }, { threshold: 0.5 });

        if (loadMoreRef.current) observer.observe(loadMoreRef.current);
        return () => observer.disconnect();
    }, [activeTab, visibleCount]); // Re-attach when count changes/renders

    // Reset count when tab/filter changes
    useEffect(() => {
        setVisibleCount(4);
    }, [activeTab, activeFilter]);

    // --- DATA FETCHING (Dynamic based on Tab) ---
    // Explore -> Top Rated/Trending; News -> Following
    const listSort = activeTab === 'explore' ? 'top_rated' : 'recent'; // Lists still use 'recent' for news

    const reviewSortParam = useMemo(() => {
        return activeTab === 'explore'
            ? { type: 'trending' as const, limit: 100 } // Fetch more for geo-filtering
            : { type: 'following' as const, followingIds, limit: 50 }; // Fetch more following
    }, [activeTab, followingIds]);

    const { lists, loading: loadingLists } = useLists(listSort);
    const { reviews, loading: loadingReviews } = useReviews(reviewSortParam);
    const { users: topUsers, loading: loadingUsers } = useUsers();

    // --- FILTERING LOGIC ---

    // 1. Helper: Check Category (User Request: Hmm/Woow/Yujuui are categories)
    const checkCategory = (item: any) => {
        if (activeFilter === 'Todo') return true;

        const catId = item.categoryId || item.category || '';
        const filterNorm = activeFilter.toLowerCase().replace(/[^a-z0-9]/g, '');
        const catNorm = String(catId).toLowerCase().replace(/[^a-z0-9]/g, '');

        if (catNorm.includes(filterNorm)) return true;

        if (item.availableTags && Array.isArray(item.availableTags)) {
            if (item.availableTags.some((t: string) => t.toLowerCase().includes(filterNorm))) return true;
        }

        if (item.listCategory || item.category) {
            const itemCat = String(item.listCategory || item.category).toLowerCase().replace(/[^a-z0-9]/g, '');
            if (itemCat.includes(filterNorm)) return true;
        }

        return false;
    };

    // 2. Helper: Check Distance
    const checkDistance = (lat?: number, lng?: number) => {
        if (!range || !location || !lat || !lng) return true;
        const dist = calculateDistance(lat, lng);
        if (dist === null) return true;
        return dist <= range;
    };

    // 3. Derived & Filtered Lists
    const filteredLists = useMemo(() => {
        return lists.filter(l => {
            const matchesCategory = checkCategory(l);
            const matchesDist = checkDistance(l.lat, l.lng);
            return matchesCategory && matchesDist;
        });
    }, [lists, activeFilter, range, location]);

    // 4. Derived & Filtered Items (Reviews)
    // We need the FULL list for calcs, not just the sliced one for display
    const reviewsInRange = useMemo(() => {
        return reviews.filter(r => {
            const matchesCategory = checkCategory(r);
            const lat = (r as any).placeLat || (r as any).lat;
            const lng = (r as any).placeLng || (r as any).lng;
            const matchesDist = checkDistance(lat, lng);
            return matchesCategory && matchesDist;
        });
    }, [reviews, activeFilter, range, location]);

    const filteredItems = useMemo(() => {
        const base = [...reviewsInRange];

        if (activeTab === 'news') {
            // Sort by Date Descending
            return base.sort((a, b) => {
                const dateA = a.createdAt?.toMillis ? a.createdAt.toMillis() : (a.createdAt?.seconds ? a.createdAt.seconds * 1000 : 0);
                const dateB = b.createdAt?.toMillis ? b.createdAt.toMillis() : (b.createdAt?.seconds ? b.createdAt.seconds * 1000 : 0);
                return dateB - dateA;
            });
        }

        // "Mejor en Listopic" (Best Rated items/reviews in range)
        return base
            .sort((a, b) => (b.placeAverageRating || b.overallRating || 0) - (a.placeAverageRating || a.overallRating || 0))
            .slice(0, 15);
    }, [reviewsInRange, activeTab]);

    // 4b. Carousel Reviews (Specific Logic: Last 2 Months + Top Liked + Filtered by Range/Cat)
    const carouselReviews = useMemo(() => {
        // "Reseñas que gustan" (Trending/Liked in range)
        return reviewsInRange
            .sort((a, b) => (b.reactionCounts?.like || 0) - (a.reactionCounts?.like || 0))
            .slice(0, 15);
    }, [reviewsInRange]);

    // 4c. Recent Reviews (Strictly by Date + In Range)
    const recentReviewsInRange = useMemo(() => {
        return [...reviewsInRange].sort((a, b) => {
            const dateA = a.createdAt?.toMillis ? a.createdAt.toMillis() : (a.createdAt?.seconds ? a.createdAt.seconds * 1000 : 0);
            const dateB = b.createdAt?.toMillis ? b.createdAt.toMillis() : (b.createdAt?.seconds ? b.createdAt.seconds * 1000 : 0);
            return dateB - dateA;
        }).slice(0, 15);
    }, [reviewsInRange]);



    // --- MAP DATA ENRICHMENT ---
    // Fetch actual places from 'places' collection to populate Map beyond just Feed items
    const [extraPlaces, setExtraPlaces] = useState<any[]>([]);
    const [placesLimit, setPlacesLimit] = useState(20); // Start small for speed

    useEffect(() => {
        // Upgrade to full fetch after initial render (Background Loading)
        const timer = setTimeout(() => {
            setPlacesLimit(100);
        }, 2000); // Wait 2s to allow main content to settle
        return () => clearTimeout(timer);
    }, []);

    useEffect(() => {
        const fetchExtraPlaces = async () => {
            try {
                // Fetch top rated and recent places to ensure map is populated
                // Note: Real geo-querying would be better, but for now we fetch a healthy batch
                const q = query(collection(db, 'places'), limit(placesLimit));
                const snap = await getDocs(q);

                const mapped = snap.docs.map(d => {
                    const data = d.data();
                    const lat = data.location?.latitude || data.coordinates?.latitude || data.lat;
                    const lng = data.location?.longitude || data.coordinates?.longitude || data.lng;
                    return {
                        id: d.id,
                        placeId: d.id,
                        name: data.name,
                        address: data.address || data.formatted_address,
                        photoUrl: data.mainImageUrl || data.photoUrl,
                        rating: data.averageRating || data.googleRating || 0,
                        reviewsCount: data.reviewsCount || 0,
                        lat, lng,
                        items: [] // No specific items for these unless we fetch subcollections
                    };
                }).filter(p => p.lat && p.lng && p.reviewsCount > 0); // Only places with location AND reviews

                setExtraPlaces(mapped);
            } catch (e) {
                console.error("Error fetching map places:", e);
            }
        };

        if (activeTab === 'explore') {
            fetchExtraPlaces();
        }
    }, [activeTab, placesLimit]);

    // 5. Derived Places (Unique from Reviews -> Filtered) + Extra Places
    const filteredPlaces = useMemo(() => {
        const uniquePlaces = new Map();

        // 1. Add places from Reviews (High priority - have rich item data)
        reviewsInRange.forEach(r => {
            if (r.placeId) {
                if (uniquePlaces.has(r.placeId)) {
                    const existing = uniquePlaces.get(r.placeId);
                    existing.reviewsCount = (existing.reviewsCount || 0) + 1;
                    if (!existing.photoUrl && (r.placeMainImage || r.photoUrl)) {
                        existing.photoUrl = r.placeMainImage || r.photoUrl;
                    }
                    uniquePlaces.set(r.placeId, existing);
                } else {
                    const lat = (r as any).placeLat;
                    const lng = (r as any).placeLng;
                    uniquePlaces.set(r.placeId, {
                        id: r.placeId,
                        placeId: r.placeId,
                        name: r.placeName || r.itemName,
                        address: r.placeAddress,
                        photoUrl: r.placeMainImage || r.photoUrl,
                        rating: r.placeAverageRating || r.overallRating,
                        reviewsCount: 1,
                        lat, lng,
                        items: [] // Can populate if needed
                    });
                }
            }
        });

        // 2. Add Extra Places (if not already present)
        extraPlaces.forEach(p => {
            if (!uniquePlaces.has(p.id)) {
                // Check distance filter for these too!
                if (checkDistance(p.lat, p.lng)) {
                    uniquePlaces.set(p.id, p);
                }
            }
        });

        // Sort: "Los lugares de más nota a menos."
        return Array.from(uniquePlaces.values()).sort((a, b) => (b.rating || 0) - (a.rating || 0));
    }, [reviewsInRange, extraPlaces, range, location, activeFilter]);

    // 6. Derived Users (Synthesized from content IN RANGE)
    // "Así aparecerán usuarios, ordenados de más resñas dentro de ese rango a menos."
    const activeUsersInRange = useMemo(() => {
        const userStats = new Map<string, { count: number, user: any }>();

        // Agregate counts from REVIEWS visible in current range
        reviewsInRange.forEach(r => {
            const uid = r.userId || r.authorId;
            if (uid) {
                if (!userStats.has(uid)) {
                    // Try to find full metadata from topUsers if available, else build minimal
                    const meta = topUsers.find(u => u.uid === uid) || {
                        uid,
                        displayName: r.authorName || 'Usuario',
                        photoUrl: r.authorPhoto,
                        username: 'user',
                        followersCount: 0 // We don't use this for sorting anymore
                    };
                    userStats.set(uid, { count: 0, user: meta });
                }

                const entry = userStats.get(uid)!;
                entry.count++;
                // If we found a photo here and didn't have one, update it
                if (!entry.user.photoUrl && r.authorPhoto) {
                    entry.user.photoUrl = r.authorPhoto;
                }
            }
        });

        // Convert map to array, filter > 0, sort by count desc
        return Array.from(userStats.values())
            .filter(item => item.count > 0)
            .sort((a, b) => b.count - a.count)
            .map(item => ({
                ...item.user,
                reviewsInRangeCount: item.count // Attach the specific count
            }));

    }, [reviewsInRange, topUsers]);

    // 7. Lists with Range Stats
    const listsWithRangeStats = useMemo(() => {
        // Map lists to attach dynamic review count based on reviewsInRange
        return filteredLists.map(list => {
            // If Range is NULL (Infinite), use the static total count from DB to be accurate
            // regardless of how many reviews we have loaded in memory.
            if (range === null) {
                return {
                    ...list,
                    reviewsInRangeCount: list.reviewCount || 0
                };
            }

            // Otherwise, calculate based on loaded reviews (best effort for specific range)
            const count = reviewsInRange.filter(r => r.listId === list.id).length;
            return {
                ...list,
                reviewsInRangeCount: count
            };
        });
    }, [filteredLists, reviewsInRange, range]);


    const handleToggleRange = () => {
        if (!location) {
            requestLocation();
        }
        toggleRange();
    };

    return (
        <div className="min-h-screen bg-[#0b1021] pb-20 font-sans">
            <div className="pt-24 px-4 pb-6">

                {/* Hero Section (Clean) */}
                <div className="max-w-4xl mx-auto mb-8 text-center pt-4">
                    <h1 className="text-5xl md:text-7xl font-black tracking-tighter mb-3 select-none">
                        <span className="bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 via-indigo-500 to-purple-500 drop-shadow-[0_0_25px_rgba(99,102,241,0.4)]">
                            LISTOPIC
                        </span>
                    </h1>
                    <p className="text-lg md:text-xl text-gray-400 font-light tracking-wide max-w-xl mx-auto">
                        Donde tus ideas cobran <span className="text-indigo-400 font-bold">vida</span> y el mundo las <span className="text-purple-400 font-bold">descubre</span>.
                    </p>
                </div>

                {/* Navigation Pills */}
                <div className="flex justify-center mt-8 gap-4">
                    <div className="inline-flex bg-[#151b2e] p-1 rounded-full border border-white/10">
                        <button
                            onClick={() => setActiveTab('explore')}
                            className={`px-6 py-2 rounded-full text-sm font-bold transition-all ${activeTab === 'explore'
                                ? 'bg-gradient-to-r from-indigo-500 to-purple-500 text-white shadow-lg'
                                : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Explorar
                        </button>
                        <button
                            onClick={() => setActiveTab('news')}
                            className={`px-6 py-2 rounded-full text-sm font-bold transition-all ${activeTab === 'news'
                                ? 'bg-gradient-to-r from-indigo-500 to-purple-500 text-white shadow-lg'
                                : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            Novedades
                        </button>
                    </div>
                </div>

                {/* Filter Chips (Categories) */}
                <div className="flex flex-wrap justify-between items-center mt-8 gap-4">
                    <div className="flex-1"></div>


                </div>


                {/* Map Collapsible */}
                {activeTab === 'explore' && (
                    <div className="max-w-7xl mx-auto mb-8">
                        <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden transition-all duration-300">
                            <div className="w-full p-3 flex items-center justify-between text-gray-300 bg-[#1e2538]/50">
                                <button
                                    onClick={() => setIsMapOpen(!isMapOpen)}
                                    className="flex items-center gap-2 hover:text-white transition-colors flex-1 text-left"
                                >
                                    <MapIcon className="w-5 h-5 text-gray-400" />
                                    <span className="font-bold text-sm">Mapa</span>
                                </button>

                                <div className="flex items-center gap-3">
                                    <button
                                        onClick={(e) => { e.stopPropagation(); handleToggleRange(); }}
                                        className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all border shrink-0 flex items-center gap-1.5 ${range !== null
                                            ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg'
                                            : 'bg-[#0b1021] border-white/10 text-gray-400 hover:text-white hover:border-white/30'
                                            }`}
                                    >
                                        <MapPin className="w-3 h-3" />
                                        {getRangeLabel()}
                                    </button>

                                    <button
                                        onClick={() => setIsMapOpen(!isMapOpen)}
                                        className="flex items-center gap-2 text-xs font-bold text-gray-500 hover:text-white transition-colors"
                                    >
                                        {isMapOpen ? 'Ocultar' : 'Ver Mapa'}
                                        <ChevronDown className={`w-4 h-4 transition-transform duration-300 ${isMapOpen ? 'rotate-180' : ''}`} />
                                    </button>
                                </div>
                            </div>

                            <div className={`grid transition-[grid-template-rows] duration-300 ease-in-out ${isMapOpen ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'}`}>
                                <div className="overflow-hidden min-h-0">
                                    <div className="h-[400px] border-t border-white/10 relative">
                                        <MapView items={filteredPlaces} mode="global" range={range} />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                <div className="max-w-[95%] mx-auto space-y-1">


                    {activeTab === 'explore' && (<>
                        {/* 1. Listas */
                        }
                        {/* 1. Listas */}
                        <CardCarousel
                            title={activeTab === 'explore' ? "Listas con más reseñas" : "Listas Recientes"}
                            viewAllLink={`/search?type=lists&sort=${activeTab === 'explore' ? 'most_reviewed' : 'latest'}`}
                            items={activeTab === 'explore'
                                ? listsWithRangeStats.sort((a, b) => (b.reviewsInRangeCount ?? b.reviewCount ?? 0) - (a.reviewsInRangeCount ?? a.reviewCount ?? 0)).slice(0, 10)
                                : filteredLists}
                            loading={loadingLists}
                            renderItem={(list: any, index: number) => (
                                <Link to={`/list/${list.id}`} className="block relative group h-40 md:h-48 rounded-md overflow-hidden transition-all duration-300 transform hover:scale-105 hover:z-10 origin-center">
                                    {(list.mainImageUrl || list.photoUrl) ? (
                                        <div className="absolute inset-0">
                                            <img src={list.mainImageUrl || list.photoUrl} alt={list.name} className="w-full h-full object-cover" />
                                            <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/90 to-transparent" />
                                        </div>
                                    ) : (
                                        <div className="w-full h-full bg-zinc-800" />
                                    )}

                                    <div className="absolute top-2 right-2 px-1.5 py-0.5 rounded bg-black/60 text-[9px] font-bold text-white uppercase tracking-wider backdrop-blur-sm" title="Total de lugares en la lista">
                                        {list.itemCount}
                                    </div>
                                    <div className="absolute top-2 left-2 w-5 h-5 bg-red-600 rounded-full flex items-center justify-center text-[10px] font-bold text-white shadow-sm">
                                        #{index + 1}
                                    </div>

                                    <div className="absolute bottom-0 left-0 right-0 p-3">
                                        <h3 className="text-white font-bold text-sm leading-tight mb-1 drop-shadow-sm line-clamp-1">{list.name}</h3>

                                        {/* Stats Row: Reviews, Followers */}
                                        <div className="flex items-center gap-4 opacity-90 text-xs text-gray-300 font-medium">
                                            <div className="flex items-center gap-1.5" title="Reseñas dentro de tu rango de distancia">
                                                <MessageCircle className="w-3.5 h-3.5 text-indigo-400" />
                                                <span>{list.reviewsInRangeCount !== undefined ? list.reviewsInRangeCount : (list.reviewCount || 0)}</span>
                                            </div>
                                            <div className="flex items-center gap-1.5" title="Seguidores de la lista">
                                                <Users className="w-3.5 h-3.5 text-rose-400" />
                                                <span>{list.followersCount || 0}</span>
                                            </div>
                                        </div>
                                    </div>
                                </Link>
                            )}
                        />

                        {/* 2. Items */}
                        <CardCarousel
                            title={activeTab === 'explore' ? "Mejor en Listopic" : "Últimos Items"}
                            viewAllLink={`/search?type=items&sort=${activeTab === 'explore' ? 'top_rated' : 'latest'}`}
                            items={filteredItems} // filteredItems are likely top rated in 'explore' mode already via useReviews('trending')
                            loading={loadingReviews}
                            renderItem={(item: any) => (
                                <ReviewCarouselItem review={item} variant="item" />
                            )}
                        />

                        {/* 3. NEW: Reseñas Recientes (Strictly by Date) */}
                        <CardCarousel
                            title="Reseñas recientes"
                            viewAllLink="/search?type=items&sort=latest"
                            items={recentReviewsInRange}
                            loading={loadingReviews}
                            renderItem={(item: any) => (
                                <ReviewCarouselItem review={item} variant="review" />
                            )}
                        />

                        {/* 3. Usuarios activos */}
                        <CardCarousel
                            title="Usuarios activos"
                            viewAllLink="/search?type=users"
                            items={activeUsersInRange}
                            loading={loadingUsers} // Technically we are deriving this from reviews now, but loadingUsers is still a fine proxy or we could use loadingReviews
                            itemClassName="w-auto mr-3"
                            renderItem={(user: any) => (
                                <Link to={`/profile/${user.uid}`} className="flex flex-col items-center gap-1 group p-2 rounded-md hover:bg-white/5 transition-colors w-24 md:w-32 shrink-0">
                                    <div className="relative w-16 h-16 md:w-20 md:h-20">
                                        <img src={user.photoUrl || `https://ui-avatars.com/api/?name=${user.displayName}`} alt="User" className="w-full h-full rounded-full object-cover border-2 border-transparent group-hover:border-white transition-all" />
                                    </div>
                                    <div className="text-center w-full">
                                        <h4 className="text-white font-bold text-xs truncate w-full">{user.displayName}</h4>
                                        <p className="text-gray-500 text-[10px] truncate">@{user.username || 'user'}</p>
                                        <p className="text-[9px] text-indigo-400 font-medium mt-0.5">
                                            {user.reviewsInRangeCount ?? 0} Reseñas
                                        </p>
                                    </div>
                                </Link>
                            )}
                        />

                        {/* 4. Lugares top */}
                        <CardCarousel
                            title={activeTab === 'explore' ? "Lugares top" : "Nuevos Lugares"}
                            viewAllLink={`/search?type=places&sort=${activeTab === 'explore' ? 'rating' : 'latest'}`}
                            items={filteredPlaces}
                            loading={loadingReviews}
                            renderItem={(place: any) => (
                                <Link to={`/place/${place.id}`} className="block relative group h-40 md:h-48 rounded-md overflow-hidden transition-all duration-300 transform hover:scale-105 hover:z-10 bg-zinc-900">
                                    {place.photoUrl ? (
                                        <div className="absolute inset-0">
                                            <img src={place.photoUrl} alt={place.name} className="w-full h-full object-cover" />
                                            <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-black/80 to-transparent" />
                                        </div>
                                    ) : (
                                        <div className="w-full h-full bg-blue-900/20" />
                                    )}

                                    <div className="absolute top-2 right-2 bg-teal-600 px-1.5 py-0.5 rounded text-[10px] font-bold text-white shadow-sm">
                                        {place.rating?.toFixed(1) || 9.5}
                                    </div>

                                    <div className="absolute bottom-0 left-0 right-0 p-3">
                                        <h3 className="text-white font-bold text-sm leading-tight mb-1 truncate">{place.name}</h3>
                                        <p className="text-gray-300 text-[10px] flex items-center gap-1 opacity-80">
                                            <MapPin className="w-3 h-3" /> {place.address?.split(',')[0]}
                                        </p>
                                    </div>
                                </Link>
                            )}
                        />


                    </>)}


                    {/* 5. Resenas / Feed */}
                    {activeTab === 'news' ? (
                        <div className="max-w-2xl mx-auto mt-12 pb-20">
                            {filteredItems.length === 0 ? (
                                <div className="text-center text-gray-500 py-10 border border-white/5 rounded-xl bg-white/5 mx-4">
                                    <p className="font-bold text-white mb-2">Tu feed está tranquilo</p>
                                    <p className="text-sm">No hay actividad reciente de personas que sigues.</p>
                                    <p className="text-xs mt-4 text-indigo-400">¡Explora y sigue a usuarios para ver sus reseñas aquí!</p>
                                </div>
                            ) : (
                                <div className="space-y-8">
                                    {filteredItems.slice(0, visibleCount).map((review: any) => (
                                        <ReviewCard key={review.id} review={review} />
                                    ))}
                                    {visibleCount < filteredItems.length && (
                                        <div ref={loadMoreRef} className="py-8 flex justify-center">
                                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    ) : (

                        <CardCarousel
                            title="Reseñas que gustan"
                            viewAllLink="/search?type=items&sort=top_liked"
                            items={carouselReviews}
                            loading={loadingReviews}
                            itemClassName="w-auto"
                            renderItem={
                                (review: any) => (
                                    <ReviewCarouselItem review={review} />
                                )}
                        />
                    )}

                </div>
            </div>
        </div >
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, Link, useLocation as useRouterLocation } from 'react-router-dom';
import { Map as MapIcon, List as ListIcon, Plus, Heart, ArrowDownWideNarrow, Clock, Search, ChevronDown, MapPin, Store, Lock, Share2, ChevronRight, Edit3, ArrowLeft } from 'lucide-react';
import { useListDetails } from '../hooks/useListDetails';
import { ListItemCard } from '../components/ListItemCard';
import { MapView } from '../components/MapView';
import { AddReviewForm } from '../components/AddReviewForm';
import { FilterModal } from '../components/FilterModal';
import { ShareListModal } from '../components/ShareListModal';
import { SublistsModal } from '../components/SublistsModal';
import { useAuth } from '../context/AuthContext';
import { useFilters } from '../context/FilterContext';
import { useLike } from '../hooks/useLike';
import { useLocation } from '../hooks/useLocation';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase';

export interface FilterState {
    minRating: number;
    hasPhoto: boolean;
    visited: boolean;
    criteriaMin: Record<string, number>;
}

export const ListPage: React.FC = () => {
    const { listId } = useParams<{ listId: string }>();
    const routerLocation = useRouterLocation();
    const [sortMode, setSortMode] = useState<'rating' | 'newest' | 'oldest' | 'count'>('rating');
    const { list, reviews, sublists, loading, error } = useListDetails(listId);
    const { user } = useAuth();
    const { location, calculateDistance, requestLocation } = useLocation();

    const canAddReview = useMemo(() => {
        if (!user || !list) return false;
        if (list.userId === user.uid) return true;
        if (list.editors?.includes(user.uid)) return true;
        if (list.isPublic && (list as any).publicAccess === 'writer') return true;
        if (list.userId === user.uid) return true;
        if (list.editors?.includes(user.uid)) return true;
        if (list.isPublic) return true; // Open to public (authenticated)
        return false;
    }, [user, list]);

    const [filters, setFilters] = useState<FilterState>({
        minRating: 0,
        hasPhoto: false,
        visited: false,
        criteriaMin: {}
    });
    const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');
    const [groupingMode, setGroupingMode] = useState<'place' | 'dish'>('dish');

    // Check for editId param
    const queryParams = new URLSearchParams(routerLocation.search);
    const editId = queryParams.get('editId');

    const [isAddModalOpen, setIsAddModalOpen] = useState(!!editId);
    const [editingReviewId, setEditingReviewId] = useState<string | undefined>(editId || undefined);

    // Update state if URL changes (e.g. navigation back/forward)
    React.useEffect(() => {
        const q = new URLSearchParams(routerLocation.search);
        const Eid = q.get('editId');
        if (Eid) {
            setEditingReviewId(Eid);
            setIsAddModalOpen(true);
        }
    }, [routerLocation.search]);

    const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
    const [isMapOpen, setIsMapOpen] = useState(false);
    const [isShareModalOpen, setIsShareModalOpen] = useState(false);
    const [isSublistsModalOpen, setIsSublistsModalOpen] = useState(false);


    // Range State from Context
    const { range, toggleRange, getRangeLabel } = useFilters();

    const handleToggleRange = () => {
        if (!location) {
            requestLocation();
        }
        toggleRange();
    };

    // Ensure location is requested if a range is active, to prevent showing ALL items by default
    useEffect(() => {
        if (range !== null && !location) {
            requestLocation();
        }
    }, [range, location]);

    // list.likes might be undefined initially, defaulting to 0
    const { isLiked, likeCount, toggleLike } = useLike(listId || '', list?.likes || 0);

    // Filter & Search State
    const [searchQuery, setSearchQuery] = useState('');

    // Parent List Name (for Sublists)
    const [parentListName, setParentListName] = useState<string | null>(null);
    useEffect(() => {
        const fetchParentName = async () => {
            if (list?.parentListId) {
                try {
                    const snap = await getDoc(doc(db, 'lists', list.parentListId));
                    if (snap.exists()) {
                        setParentListName(snap.data().name);
                    }
                } catch (e) {
                    console.error("Error fetching parent list name", e);
                }
            }
        };
        fetchParentName();
    }, [list?.parentListId]);


    // --- Aggregation Logic (Ranked List View & Map Data) ---
    const groupedItems = useMemo(() => {
        if (!reviews.length) return [];

        const groups: Record<string, {
            id: string;
            name: string;
            placeId?: string;
            placeName?: string;
            placeCity?: string;
            placeAddress?: string;
            photoUrl?: string;
            totalRating: number;
            count: number;
            criteriaSums: Record<string, number>;
            lat?: number;
            lng?: number;
            latestReviewAt: number; // Timestamp for sorting
            userHasReviewed: boolean;
            items: { name: string; score: number }[];
            photoMaxLikes: number;
            maxScore: number; // Track max score for the pin
            allTags: string[]; // For consensus calculation
            tags: string[]; // Final consensus tags
        }> = {};

        reviews.forEach(review => {
            let key = review.placeId || (review.itemName ? review.itemName.trim().toLowerCase() : 'unknown');

            // Grouping Mode Logic
            if (groupingMode === 'dish') {
                key = review.placeId
                    ? `${review.placeId}_${(review.itemName || '').trim().toLowerCase()}`
                    : (review.itemName || '').trim().toLowerCase();
            }

            if (!groups[key]) {
                const itemName = review.itemName ? review.itemName : (review.placeName || 'Item sin nombre');
                groups[key] = {
                    id: key,
                    name: groupingMode === 'dish' ? itemName : (review.placeName || itemName),
                    placeId: review.placeId,
                    placeName: review.placeName,
                    placeCity: review.placeCity,
                    placeAddress: review.placeAddress,
                    photoUrl: review.photoUrl,
                    totalRating: 0,
                    count: 0,
                    criteriaSums: {},
                    latestReviewAt: 0,
                    userHasReviewed: false,
                    items: [],
                    photoMaxLikes: -1,
                    maxScore: 0,
                    allTags: [],
                    tags: []
                };
            }

            const g = groups[key];
            g.totalRating += review.overallRating || 0;
            g.count += 1;

            if ((review.overallRating || 0) > g.maxScore) {
                g.maxScore = review.overallRating || 0;
            }

            if (user && (review.userId === user.uid || review.authorId === user.uid)) {
                g.userHasReviewed = true;
            }

            g.items.push({
                name: review.itemName || 'Item',
                score: review.overallRating || 0
            });

            // Handle Review Time for sorting
            const createdAt = review.createdAt as any;
            let reviewTime = 0;
            if (createdAt?.toMillis) {
                reviewTime = createdAt.toMillis();
            } else if (createdAt instanceof Date) {
                reviewTime = createdAt.getTime();
            } else if (createdAt) {
                reviewTime = new Date(createdAt).getTime();
            }
            if (reviewTime > g.latestReviewAt) {
                g.latestReviewAt = reviewTime;
            }

            // Handle Photo
            const currentLikes = review.reactionCounts?.like || 0;
            if (review.photoUrl || review.placeMainImage) {
                if (currentLikes > g.photoMaxLikes) {
                    g.photoMaxLikes = currentLikes;
                    g.photoUrl = review.photoUrl || review.placeMainImage;
                }
            }

            // Handle Criteria
            if (review.scores) {
                Object.entries(review.scores).forEach(([k, v]) => {
                    g.criteriaSums[k] = (g.criteriaSums[k] || 0) + v;
                });
            }

            // Handle Tags
            if (review.tags && Array.isArray(review.tags)) {
                g.allTags.push(...review.tags);
            }

            if ((!g.lat || !g.lng) && review.lat && review.lng) {
                g.lat = review.lat;
                g.lng = review.lng;
            }
        });

        // Finalize Groups (Averages + Tags Consensus)
        return Object.values(groups).map(g => {
            const criteriaAverages: Record<string, number> = {};
            const allowedCriteria = list?.criteriaDefinition ? Object.keys(list.criteriaDefinition) : null;

            Object.keys(g.criteriaSums).forEach(k => {
                if (allowedCriteria && !allowedCriteria.includes(k)) return;
                criteriaAverages[k] = g.criteriaSums[k] / g.count;
            });

            // 50% Rule for Tags
            const tagCounts: Record<string, number> = {};
            g.allTags.forEach(t => { tagCounts[t] = (tagCounts[t] || 0) + 1; });
            const minThreshold = Math.ceil(g.count / 2);
            /* Logic: "Al menos en la mitad". So >= g.count / 2.
               Math.ceil(20/2) = 10. 15/20 >= 10 -> OK. 2/20 >= 10 -> No.
               Math.ceil(1/2) = 1. 1/1 >= 1 -> OK.
            */
            const consensusTags = Object.entries(tagCounts)
                .filter(([_, count]) => count >= minThreshold)
                .map(([tag]) => tag).sort();

            return {
                ...g,
                avgRating: g.totalRating / g.count,
                reviewCount: g.count,
                items: g.items.sort((a, b) => b.score - a.score),
                criteriaAverages,
                criteriaDefinition: list?.criteriaDefinition,
                tags: consensusTags // Use calculated tags
            };
        }).sort((a, b) => {
            if (sortMode === 'rating') {
                if (b.avgRating !== a.avgRating) return b.avgRating - a.avgRating;
                return b.reviewCount - a.reviewCount;
            }
            if (sortMode === 'count') {
                return b.reviewCount - a.reviewCount;
            }
            if (sortMode === 'newest' || sortMode === 'oldest') {
                const diff = b.latestReviewAt - a.latestReviewAt;
                return sortMode === 'newest' ? diff : -diff;
            }
            return 0;
        });
    }, [reviews, list, groupingMode, sortMode, user]);

    // Unique Tags for Filter UI
    const availableGroupTags = useMemo(() => {
        const set = new Set<string>();
        groupedItems.forEach(g => g.tags.forEach(t => set.add(t)));
        return Array.from(set).sort();
    }, [groupedItems]);

    const [selectedTags, setSelectedTags] = useState<string[]>([]);

    // Filter Items
    // Filter Items by Tag
    const filteredByTagItems = useMemo(() => {
        if (selectedTags.length === 0) return groupedItems;
        return groupedItems.filter(item => item.tags.some(t => selectedTags.includes(t)));
    }, [groupedItems, selectedTags]);



    // Map Specific Data - Always grouped by Place, always has Items list
    const mapItems = useMemo(() => {
        if (!reviews.length) return [];
        const placeGroups: Record<string, any> = {};

        reviews.forEach(review => {
            if (!review.placeId) return; // Skip items without placeId for map

            if (!placeGroups[review.placeId]) {
                placeGroups[review.placeId] = {
                    id: review.placeId,
                    placeId: review.placeId,
                    name: review.placeName || review.itemName,
                    lat: review.lat,
                    lng: review.lng,
                    photoUrl: review.placeMainImage || review.photoUrl,
                    maxScore: 0,
                    items: [],
                    reviewsCount: 0
                };
            }

            const g = placeGroups[review.placeId];
            // Accumulate Items
            g.items.push({ name: review.itemName, score: review.overallRating });
            g.reviewsCount++;

            if (review.overallRating > g.maxScore) {
                g.maxScore = review.overallRating;
            }

            // Ensure coords
            if ((!g.lat || !g.lng) && review.lat && review.lng) {
                g.lat = review.lat;
                g.lng = review.lng;
            }

            // Ensure photo (naive)
            if (!g.photoUrl && (review.placeMainImage || review.photoUrl)) {
                g.photoUrl = review.placeMainImage || review.photoUrl;
            }
        });

        // Format for MapView
        return Object.values(placeGroups).map(g => ({
            ...g,
            rating: g.maxScore, // Override rating for Pin Color with Max Score
            items: g.items.sort((a: any, b: any) => b.score - a.score) // Sort items descending
        }));
    }, [reviews]);

    // --- Filtering Logic ---
    // --- Filtering Logic ---
    const filteredItemsAll = useMemo(() => {
        let result = filteredByTagItems;

        // 1. Apply Smart Filters
        if (filters.minRating > 0) {
            result = result.filter(item => item.avgRating >= filters.minRating);
        }
        if (filters.hasPhoto) {
            result = result.filter(item => !!item.photoUrl);
        }
        if (filters.visited) {
            result = result.filter(item => item.userHasReviewed);
        }
        if (Object.keys(filters.criteriaMin).length > 0) {
            result = result.filter(item => {
                return Object.entries(filters.criteriaMin).every(([critKey, minScore]) => {
                    const score = item.criteriaAverages?.[critKey] || 0;
                    return score >= minScore;
                });
            });
        }

        // 2. Apply Search
        if (searchQuery) {
            const lowerQ = searchQuery.toLowerCase();
            result = result.filter(item =>
                item.name.toLowerCase().includes(lowerQ) ||
                (item.placeName && item.placeName.toLowerCase().includes(lowerQ))
            );
        }

        // 3. Apply Distance Range
        if (range !== null && location) {
            result = result.filter(item => {
                if (!item.lat || !item.lng) return false;
                const dist = calculateDistance(item.lat, item.lng);
                return dist !== null && dist <= range;
            });
        } else if (range !== null && !location) {
            // If range is active but no location, maybe show nothing or keep all?
            // Usually keeping all is confusing if user wants filtering. 
            // But usually requestLocation should have triggered.
            // We'll optimistically keep them or filter if we strictly want radius.
            // Let's filter nothing until location is found (user should see prompt).
        }

        return result;
    }, [filteredByTagItems, searchQuery, filters, range, location]);

    const filteredMapItems = useMemo(() => {
        // Filter mapItems based on the SAME criteria as the list (or at least search/range)
        // Since mapItems are aggregated differently, we might need to filter differently.
        // Simplest approach: If mapItem's placeID is present in ANY of the filteredItemsAll, keep it?
        // Or re-apply filters (Search, Range, Rating).

        let result = mapItems;

        if (filters.minRating > 0) {
            // Check if maxScore meets it? Or average? Assuming Max Score for now as it's the pin rating.
            result = result.filter(item => item.maxScore >= filters.minRating);
        }

        if (filters.hasPhoto) {
            result = result.filter(item => !!item.photoUrl);
        }

        if (searchQuery) {
            const lowerQ = searchQuery.toLowerCase();
            result = result.filter(item =>
                item.name.toLowerCase().includes(lowerQ)
            ); // Map items are places, so searching by name is usually enough. Items names are also in the 'items' array if we wanted deep search.
        }

        if (range !== null && location) {
            result = result.filter(item => {
                if (!item.lat || !item.lng) return false;
                const dist = calculateDistance(item.lat, item.lng);
                return dist !== null && dist <= range;
            });
        }

        return result;
    }, [mapItems, searchQuery, filters, range, location]);

    // Pagination
    const PAGE_SIZE = 24;
    const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);

    const filteredItems = useMemo(() => {
        return filteredItemsAll.slice(0, visibleCount);
    }, [filteredItemsAll, visibleCount]);

    const handleLoadMore = () => {
        setVisibleCount(prev => prev + PAGE_SIZE);
    };

    if (loading) {
        return (
            <div className="min-h-screen pt-24 px-4 max-w-4xl mx-auto">
                <div className="h-8 w-1/3 bg-gray-800 rounded animate-pulse mb-4"></div>
                <div className="h-4 w-2/3 bg-gray-800 rounded animate-pulse mb-8"></div>
                <div className="space-y-4">
                    {[1, 2, 3].map(i => (
                        <div key={i} className="h-48 bg-gray-800 rounded-xl animate-pulse"></div>
                    ))}
                </div>
            </div>
        );
    }

    if (error || !list) {
        if (error === 'private') {
            return (
                <div className="min-h-screen pt-40 px-4 text-center">
                    <div className="bg-[#151b2e] border border-white/10 rounded-2xl p-8 max-w-md mx-auto">
                        <div className="w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4">
                            <Lock className="w-8 h-8 text-gray-400" />
                        </div>
                        <h2 className="text-2xl font-bold text-white mb-2">Lista Privada</h2>
                        <p className="text-gray-400 mb-6">
                            Esta lista es privada y no tienes permisos para verla.
                        </p>
                        <Link to="/search" className="inline-flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-xl transition-colors">
                            <Search className="w-4 h-4" />
                            Explorar otras listas
                        </Link>
                    </div>
                </div>
            );
        }

        return (
            <div className="min-h-screen pt-24 px-4 text-center">
                <h2 className="text-2xl font-bold text-red-400 mb-2">Error</h2>
                <p className="text-gray-400">{error || "Lista no encontrada"}</p>
                <Link to="/search" className="mt-4 inline-block text-indigo-400 hover:text-indigo-300">
                    Volver al buscador
                </Link>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#0b1021] pb-20 transition-colors duration-300">
            {/* Hero Section */}
            {/* Hero Section */}
            <div className={`relative w-full ${list.mainImageUrl || list.photoUrl ? 'h-[40vh] min-h-[300px]' : 'h-[30vh] min-h-[250px]'} transition-all duration-700 overflow-hidden group`}>
                <div className="absolute inset-0 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-black/40 z-10" />

                {/* Background Image & Overlay */}
                {(list.mainImageUrl || list.photoUrl) ? (
                    <img
                        src={list.mainImageUrl || list.photoUrl}
                        alt={list.name}
                        className="w-full h-full object-cover opacity-80 transition-transform duration-700 group-hover:scale-105"
                    />
                ) : (
                    <div className="absolute inset-0 bg-gradient-to-br from-indigo-900/40 via-[#0b1021] to-[#0b1021]">
                        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
                    </div>
                )}

                <div className="absolute inset-0 flex flex-col justify-end p-4 sm:p-8 z-10 max-w-7xl mx-auto w-full">
                    <div className="flex flex-col md:flex-row gap-6 md:items-end md:justify-between">
                        {/* Left Column: Title & Author */}
                        <div className="flex-1 space-y-4">
                            <div>
                                {list.parentListId && (
                                    <Link to={`/list/${list.parentListId}`} className="inline-flex items-center gap-1 text-indigo-300 hover:text-white text-xs font-bold uppercase tracking-wider mb-2 transition-colors">
                                        <ArrowLeft className="w-4 h-4" />
                                        Volver a {parentListName || 'Lista Principal'}
                                    </Link>
                                )}
                                <h1 className="text-3xl sm:text-4xl md:text-6xl font-display font-bold text-white mb-2 leading-tight shadow-sm text-shadow-lg">
                                    {list.name}
                                </h1>
                                {list.description && (
                                    <p className="text-gray-300 text-sm sm:text-base max-w-2xl line-clamp-2 md:line-clamp-3 leading-relaxed drop-shadow-md">
                                        {list.description}
                                    </p>
                                )}
                            </div>

                            <div className="flex flex-wrap items-center gap-4">
                                {
                                    /* Author Badge - Only for Sublists */
                                }
                                {list.parentListId && (
                                    <Link to={`/profile/${list.userId}`} className="flex items-center gap-2 bg-black/30 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10 hover:bg-black/50 transition-colors group/author">
                                        <div className="w-5 h-5 rounded-full bg-indigo-500 overflow-hidden flex items-center justify-center text-[10px] text-white font-bold border border-white/20">
                                            {list.authorName?.[0] ? list.authorName[0].toUpperCase() : '?'}
                                        </div>
                                        <span className="text-sm font-medium text-white/90 group-hover/author:text-white">
                                            {list.authorName || 'Usuario'}
                                        </span>
                                    </Link>
                                )}
                                <div className="flex items-center gap-1.5 bg-black/30 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10 text-pink-500 font-bold text-sm">
                                    <Heart className={`w-3.5 h-3.5 ${user && (list as any).isLiked ? 'fill-current' : ''}`} />
                                    <span>{likeCount}</span>
                                </div>
                            </div>
                        </div>

                        {/* Right Column: Status Badges & Actions */}
                        <div className="flex flex-col gap-3 items-end w-full md:w-auto">
                            {/* Badges Row - Moved to Right */}
                            <div className="flex flex-wrap items-center gap-2">
                                {/* Type Badge */}
                                <span className={`px-2.5 py-0.5 rounded-md border text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm ${list.parentListId ? 'bg-purple-500/10 border-purple-500/20 text-purple-400' : 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400'}`}>
                                    {list.parentListId ? 'Sublista' : 'Lista'}
                                </span>

                                {list.isPublic ? (
                                    <span className="px-2.5 py-0.5 rounded-md bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                        Pública
                                    </span>
                                ) : (
                                    <span className="px-2.5 py-0.5 rounded-md bg-red-500/10 border border-red-500/20 text-red-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm flex items-center gap-1">
                                        <Lock className="w-3 h-3" /> Privada
                                    </span>
                                )}

                                {/* Role Bubbles */}
                                {list.parentListId && user?.uid === list.userId && (
                                    <span className="px-2.5 py-0.5 rounded-md bg-amber-500/10 border border-amber-500/20 text-amber-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                        Propietario
                                    </span>
                                )}
                                {list.parentListId && !user && list.isPublic && (
                                    <span className="px-2.5 py-0.5 rounded-md bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                        Visitante
                                    </span>
                                )}
                                {(list.parentListId || (list.editors && list.editors.includes(user?.uid || ''))) && user && user.uid !== list.userId && (
                                    <>
                                        {list.editors?.includes(user?.uid) ? (
                                            <span className="px-2.5 py-0.5 rounded-md bg-purple-500/10 border border-purple-500/20 text-purple-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                                Editor
                                            </span>
                                        ) : (list as any).publicAccess === 'writer' ? (
                                            <span className="px-2.5 py-0.5 rounded-md bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                                Colaborador
                                            </span>
                                        ) : (
                                            <span className="px-2.5 py-0.5 rounded-md bg-blue-500/10 border border-blue-500/20 text-blue-400 text-[10px] sm:text-xs font-bold uppercase tracking-wider backdrop-blur-sm">
                                                Lector
                                            </span>
                                        )}
                                    </>
                                )}
                            </div>

                            {/* Action Buttons Row */}
                            <div className="flex items-center gap-2">
                                {user && list.userId === user.uid && (
                                    <Link
                                        to={`/list/${list.id}/edit`}
                                        className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-bold rounded-xl shadow-lg shadow-indigo-500/20 flex items-center gap-2 transition-all"
                                    >
                                        <Edit3 className="w-4 h-4" />
                                        <span className="hidden sm:inline">Editar</span>
                                    </Link>
                                )}

                                <button
                                    onClick={() => setIsShareModalOpen(true)}
                                    className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white text-sm font-bold rounded-xl border border-white/10 backdrop-blur-md flex items-center gap-2 transition-all"
                                >
                                    <Share2 className="w-4 h-4" />
                                    <span className="hidden sm:inline">Compartir</span>
                                </button>

                                {/* Like/Follow Button */}
                                {user && list.userId !== user.uid && (
                                    <button
                                        onClick={toggleLike}
                                        className={`px-4 py-2 text-sm font-bold rounded-xl border flex items-center gap-2 transition-all ${isLiked
                                            ? 'bg-transparent border-white/20 text-white hover:border-pink-500 hover:text-pink-500'
                                            : 'bg-indigo-600 border-indigo-600 text-white hover:bg-indigo-500'
                                            }`}
                                    >
                                        {isLiked ? (
                                            <>
                                                <Heart className="w-4 h-4 fill-current" />
                                                <span className="hidden sm:inline">Guardada</span>
                                            </>
                                        ) : (
                                            <>
                                                <Heart className="w-4 h-4" />
                                                <span className="hidden sm:inline">Guardar</span>
                                            </>
                                        )}
                                    </button>
                                )}

                                {/* Sublists Button (Only for Main Lists) */}
                                {!list.parentListId && (
                                    <button
                                        onClick={() => setIsSublistsModalOpen(true)}
                                        className="px-4 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-300 border border-indigo-500/20 text-sm font-bold rounded-xl backdrop-blur-md flex items-center gap-2 transition-all hover:scale-105 shadow-lg shadow-indigo-500/10"
                                    >
                                        <ListIcon className="w-4 h-4" />
                                        <span>Sublistas</span>
                                        {sublists && sublists.length > 0 && (
                                            <span className="bg-indigo-500/20 px-1.5 py-0.5 rounded text-[10px] ml-1 border border-indigo-500/30 text-indigo-200">
                                                {sublists.length}
                                            </span>
                                        )}
                                    </button>
                                )}

                                {/* Add Review Button */}
                                {canAddReview && (
                                    <button
                                        onClick={() => setIsAddModalOpen(true)}
                                        className="px-4 py-2 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white text-sm font-bold rounded-xl shadow-lg shadow-emerald-500/20 flex items-center gap-2 hover:scale-105 transition-all ml-2"
                                    >
                                        <Plus className="w-4 h-4" />
                                        <span>Añadir Reseña</span>
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Map Collapsible */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 pt-6">
                <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden transition-all duration-300">
                    <div className="w-full p-3 flex items-center justify-between text-gray-300 bg-[#1e2538]/50">
                        <button
                            onClick={() => setIsMapOpen(!isMapOpen)}
                            className="flex items-center gap-2 hover:text-white transition-colors flex-1"
                        >
                            <MapIcon className="w-5 h-5 text-gray-400" />
                            <span className="font-bold text-sm">Mapa de la Lista</span>
                        </button>

                        <div className="flex items-center gap-3">
                            <button
                                onClick={handleToggleRange}
                                className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all border shrink-0 flex items-center gap-1.5 ${range !== null
                                    ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg'
                                    : 'bg-[#0b1021] border-white/10 text-gray-400 hover:text-white hover:border-white/30'
                                    }`}
                            >
                                <MapPin className="w-3 h-3" />
                                {getRangeLabel()}
                            </button>

                            <button
                                onClick={() => setIsMapOpen(!isMapOpen)}
                                className="flex items-center gap-2 text-xs font-bold text-gray-500 hover:text-white transition-colors"
                            >
                                {isMapOpen ? 'Ocultar' : 'Ver Mapa'}
                                <ChevronDown className={`w-4 h-4 transition-transform duration-300 ${isMapOpen ? 'rotate-180' : ''}`} />
                            </button>
                        </div>
                    </div>

                    <div className={`transition-all duration-500 ease-in-out ${isMapOpen ? 'max-h-[600px] opacity-100' : 'max-h-0 opacity-0'}`}>
                        <div className="h-[400px] w-full relative z-0">
                            {isMapOpen && <MapView items={filteredMapItems} mode="list" range={range} />}
                        </div>
                    </div>
                </div>
            </div>

            {/* Sublists Viewer - Moved to Header */}


            {/* Content List */}
            <main className="max-w-4xl mx-auto px-4 sm:px-6 pt-8">

                {/* Modern Toolbar */}
                <div className="sticky top-20 z-30 mb-8 mx-auto max-w-4xl">
                    <div className="bg-[#151b2e]/80 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl p-2 flex flex-col sm:flex-row items-center justify-between gap-3 transition-all duration-300 hover:border-white/20">

                        {/* Search & Count */}
                        <div className="flex items-center flex-1 w-full gap-3 px-2">
                            <div className="bg-white/5 text-xs px-2.5 py-1 rounded-full text-indigo-300 font-bold border border-white/5 flex-shrink-0">
                                {filteredItems.length}
                            </div>
                            <div className="h-4 w-px bg-white/10 mx-1 hidden sm:block"></div>
                            <div className="relative flex-1 group/search">
                                <Search className="absolute left-0 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 group-focus-within/search:text-indigo-400 transition-colors" />
                                <input
                                    type="text"
                                    placeholder="Buscar en esta lista..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full bg-transparent border-none p-0 pl-7 text-sm text-white placeholder:text-gray-600 focus:ring-0 transition-colors"
                                />
                            </div>
                        </div>

                        {/* Actions Island */}
                        <div className="flex items-center gap-2 w-full sm:w-auto justify-end border-t sm:border-t-0 border-white/5 pt-2 sm:pt-0">

                            {/* Filter */}
                            <button
                                onClick={() => setIsFilterModalOpen(true)}
                                className="h-9 w-9 flex items-center justify-center rounded-xl bg-white/5 hover:bg-white/10 border border-white/5 text-gray-400 hover:text-white transition-all active:scale-95"
                                title="Filtros"
                            >
                                <ArrowDownWideNarrow className="w-4 h-4 rotate-180" />
                            </button>

                            <div className="h-4 w-px bg-white/10 mx-1"></div>

                            {/* Grouping Toggle */}
                            <button
                                onClick={() => setGroupingMode(prev => prev === 'place' ? 'dish' : 'place')}
                                className={`h-9 w-9 flex items-center justify-center rounded-xl border transition-all ${groupingMode === 'place' ? 'bg-indigo-500/20 border-indigo-500/30 text-indigo-400 shadow-[0_0_10px_rgba(99,102,241,0.2)]' : 'bg-white/5 border-white/5 text-gray-400 hover:text-white'}`}
                                title={groupingMode === 'place' ? "Agrupado por Lugar" : "Ver Platos Sueltos"}
                            >
                                <Store className="w-4 h-4" />
                            </button>

                            <div className="h-4 w-px bg-white/10 mx-1"></div>

                            {/* View Toggle */}
                            <div className="flex bg-black/20 rounded-xl p-0.5 border border-white/5">
                                <button
                                    onClick={() => setViewMode('list')}
                                    className={`h-8 w-8 flex items-center justify-center rounded-lg transition-all ${viewMode === 'list' ? 'bg-indigo-500/20 text-indigo-400 shadow-inner' : 'text-gray-500 hover:text-gray-300'}`}
                                >
                                    <ListIcon className="w-3.5 h-3.5" />
                                </button>
                                <button
                                    onClick={() => setViewMode('grid')}
                                    className={`h-8 w-8 flex items-center justify-center rounded-lg transition-all ${viewMode === 'grid' ? 'bg-indigo-500/20 text-indigo-400 shadow-inner' : 'text-gray-500 hover:text-gray-300'}`}
                                >
                                    <div className="w-3.5 h-3.5 grid grid-cols-2 gap-0.5 opacity-80">
                                        <div className="bg-current rounded-[0.5px]"></div>
                                        <div className="bg-current rounded-[0.5px]"></div>
                                        <div className="bg-current rounded-[0.5px]"></div>
                                        <div className="bg-current rounded-[0.5px]"></div>
                                    </div>
                                </button>
                            </div>

                            {/* Add Actions */}
                            {canAddReview && (
                                <button
                                    onClick={() => setIsAddModalOpen(true)}
                                    className="ml-2 h-9 px-4 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white text-xs font-bold rounded-xl shadow-lg shadow-indigo-500/20 flex items-center gap-2 hover:scale-105 transition-all"
                                >
                                    <Plus className="w-3.5 h-3.5" />
                                    <span className="hidden sm:inline">Añadir</span>
                                </button>
                            )}
                        </div>
                    </div>
                </div>

                <div className="animate-fade-in">
                    {filteredItems.length > 0 ? (
                        <>
                            <div className={viewMode === 'grid' ? "grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" : "flex flex-col rounded-xl overflow-hidden border border-[var(--border-color)] divide-y divide-[var(--border-color)]"}>
                                {filteredItems.map((item, idx) => (
                                    <ListItemCard
                                        key={item.id}
                                        item={item}
                                        rank={idx + 1}
                                        isGrid={viewMode === 'grid'}
                                        groupingMode={groupingMode}
                                        listId={listId}
                                    />
                                ))}
                            </div>

                            {/* Load More Button */}
                            {visibleCount < filteredItemsAll.length && (
                                <div className="mt-8 text-center">
                                    <button
                                        onClick={handleLoadMore}
                                        className="px-6 py-2 bg-[#151b2e] hover:bg-[#1e2538] border border-white/10 rounded-full text-indigo-400 hover:text-indigo-300 font-medium transition-colors shadow-lg"
                                    >
                                        Cargar más ({filteredItemsAll.length - visibleCount} restantes)
                                    </button>
                                </div>
                            )}
                        </>
                    ) : (
                        <div className="text-center py-16 bg-[#151b2e]/30 rounded-2xl border border-dashed border-white/5">
                            <p className="text-gray-400 mb-4 text-lg">
                                {searchQuery ? 'No hay resultados para tu búsqueda.' : 'Esta lista está vacía o no hay elementos cerca.'}
                            </p>
                            {canAddReview && !searchQuery && (
                                <button
                                    onClick={() => setIsAddModalOpen(true)}
                                    className="text-indigo-400 hover:text-indigo-300 font-bold hover:underline"
                                >
                                    ¡Añade la primera reseña!
                                </button>
                            )}
                        </div>
                    )}
                </div>
            </main>

            {/* Add Modal */}
            {
                isAddModalOpen && listId && (
                    <AddReviewForm
                        listId={listId}
                        editReviewId={editingReviewId}
                        lockList={true} // Always lock list on ListPage
                        onClose={() => {
                            setIsAddModalOpen(false);
                            setEditingReviewId(undefined);
                            // Clear param without reload
                            window.history.replaceState({}, '', `/list/${listId}`);
                        }}
                        onSuccess={() => window.location.reload()}
                    />
                )
            }

            {/* Share Modal */}
            {
                isShareModalOpen && list && user && (
                    <ShareListModal
                        isOpen={isShareModalOpen}
                        onClose={() => setIsShareModalOpen(false)}
                        listId={listId!}
                        listName={list.name}
                        currentGuests={list.guests || []}
                        currentEditors={list.editors || []}
                        ownerId={list.userId}
                        onUpdate={() => {
                            // No reload needed for UI, but if we want to refresh 'list' data in background we can.
                            // For now, we rely on local Modal state updates.
                            // window.location.reload() 
                        }}
                    />
                )
            }

            {/* Sublists Modal (Only for Main Lists) */}
            {
                isSublistsModalOpen && sublists && !list.parentListId && (
                    <SublistsModal
                        isOpen={isSublistsModalOpen}
                        onClose={() => setIsSublistsModalOpen(false)}
                        sublists={sublists}
                        listId={list.id}
                        listName={list.name}
                        parentCriteria={list.criteriaDefinition}
                        parentTags={list.availableTags}
                    />
                )
            }

            <FilterModal
                isOpen={isFilterModalOpen}
                onClose={() => setIsFilterModalOpen(false)}
                filters={filters}
                setFilters={setFilters}
                criteriaDefinition={list?.criteriaDefinition}
                sortMode={sortMode}
                setSortMode={setSortMode}
                availableTags={availableGroupTags}
                selectedTags={selectedTags}
                setSelectedTags={setSelectedTags}
            />
        </div >
    );
};

import React, { useState, useMemo } from 'react';
import { useLists } from '../hooks/useLists';
import { useLocation } from '../hooks/useLocation';
import { ListCard } from '../components/ListCard';
import { Search, MapPin, Filter } from 'lucide-react';

export const ListView: React.FC = () => {
    const { lists, loading, error } = useLists();
    const { location, calculateDistance } = useLocation();

    // Filters state
    const [searchTerm, setSearchTerm] = useState('');
    const [maxDistance, setMaxDistance] = useState<number>(50); // km
    const [enableLocationFilter, setEnableLocationFilter] = useState(false);

    const [selectedTag, setSelectedTag] = useState<string | null>(null);

    // Derived state: Unique Tags from available lists
    const uniqueTags = useMemo(() => {
        if (!lists) return [];
        const tags = new Set<string>();
        lists.forEach(list => {
            list.availableTags?.forEach((tag: string) => {
                if (tag) tags.add(tag);
            });
        });
        return Array.from(tags).sort();
    }, [lists]);

    // Derived state: Filter lists
    const filteredLists = useMemo(() => {
        if (!lists) return [];

        return lists.filter(list => {
            // Text Search
            const matchesSearch = list.name.toLowerCase().includes(searchTerm.toLowerCase());
            if (!matchesSearch) return false;

            // Tag Filter
            if (selectedTag && (!list.availableTags || !list.availableTags.includes(selectedTag))) {
                return false;
            }

            // Location Filter
            if (enableLocationFilter && location) {
                // Check if list has location data
                if (list.lat === undefined || list.lng === undefined) return false;

                const dist = calculateDistance(list.lat, list.lng);
                return dist !== null && dist <= maxDistance;
            }

            return true;
        });
    }, [lists, searchTerm, enableLocationFilter, maxDistance, location, selectedTag]);

    return (
        <div className="min-h-screen pt-20 pb-10 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-white mb-2">Explorar Listas</h1>
                    <p className="text-gray-400">Descubre las mejores colecciones de la comunidad.</p>
                </div>

                {/* Search & Filter Bar */}
                <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                    <div className="relative group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 group-focus-within:text-indigo-400 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar listas..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="bg-[#151b2e] border border-white/10 rounded-lg pl-10 pr-4 py-2 text-white text-sm focus:outline-none focus:border-indigo-500/50 w-full sm:w-64 transition-all"
                        />
                    </div>

                    <button
                        onClick={() => setEnableLocationFilter(!enableLocationFilter)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg border text-sm font-medium transition-all ${enableLocationFilter ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-[#151b2e] border-white/10 text-gray-400 hover:border-white/20'}`}
                    >
                        <MapPin className="w-4 h-4" />
                        <span>Cerca de mí</span>
                    </button>
                </div>
            </div>

            {/* Tags Scrollbar */}
            {!loading && uniqueTags.length > 0 && (
                <div className="mb-6 flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                    <button
                        onClick={() => setSelectedTag(null)}
                        className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors whitespace-nowrap
                            ${!selectedTag ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-[#151b2e] border-white/10 text-gray-400 hover:border-white/20'}`}
                    >
                        Todos
                    </button>
                    {uniqueTags.map(tag => (
                        <button
                            key={tag}
                            onClick={() => setSelectedTag(tag === selectedTag ? null : tag)} // Toggle
                            className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors whitespace-nowrap
                                ${selectedTag === tag ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-[#151b2e] border-white/10 text-gray-400 hover:border-white/20'}`}
                        >
                            #{tag}
                        </button>
                    ))}
                </div>
            )}

            {/* Range Slider (donditional) */}
            {enableLocationFilter && (
                <div className="mb-8 p-4 bg-[#151b2e] rounded-xl border border-white/10 animate-fade-in-down">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm text-gray-400 flex items-center gap-2">
                            <Filter className="w-3 h-3" /> Radio de búsqueda
                        </span>
                        <span className="text-indigo-400 font-bold text-sm">{maxDistance} km</span>
                    </div>
                    <input
                        type="range"
                        min="1"
                        max="200"
                        value={maxDistance}
                        onChange={(e) => setMaxDistance(Number(e.target.value))}
                        className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                    />
                    {!location && (
                        <p className="text-xs text-red-400 mt-2">
                            ⚠️ Necesitamos tu ubicación para filtrar por distancia.
                        </p>
                    )}
                </div>
            )}

            {/* Results Grid */}
            {loading ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                    {[1, 2, 3, 4, 5, 6].map(i => (
                        <div key={i} className="h-64 bg-[#151b2e] rounded-xl animate-pulse border border-white/5"></div>
                    ))}
                </div>
            ) : error ? (
                <div className="bg-red-500/10 border border-red-500/20 text-red-200 p-4 rounded-lg text-center">
                    Error al cargar listas: {error}
                </div>
            ) : (
                <>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredLists.map(list => (
                            <ListCard key={list.id} list={list} />
                        ))}
                    </div>
                    {filteredLists.length === 0 && (
                        <div className="text-center py-20">
                            <div className="w-16 h-16 bg-[#151b2e] rounded-full flex items-center justify-center mx-auto mb-4 text-gray-600">
                                <Search className="w-8 h-8" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">No se encontraron resultados</h3>
                            <p className="text-gray-400">Intenta ajustar los filtros de búsqueda.</p>
                        </div>
                    )}
                </>
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { GoogleAuthProvider, signInWithPopup, signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { auth } from '../firebase';
import { Mail, Lock, User, Loader2 } from 'lucide-react';

export const LoginPage: React.FC = () => {
    const navigate = useNavigate();
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    // Auth State
    const [isRegistering, setIsRegistering] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState(''); // For registration

    const handleGoogleLogin = async () => {
        setLoading(true);
        setError(null);
        try {
            const provider = new GoogleAuthProvider();
            await signInWithPopup(auth, provider);
            navigate('/');
        } catch (err: any) {
            console.error(err);
            setError("Error al iniciar sesión con Google. Inténtalo de nuevo.");
            setLoading(false);
        }
    };

    const handleEmailAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        try {
            if (isRegistering) {
                // Register
                const userCredential = await createUserWithEmailAndPassword(auth, email, password);
                if (name) {
                    await updateProfile(userCredential.user, {
                        displayName: name
                    });
                }
            } else {
                // Login
                await signInWithEmailAndPassword(auth, email, password);
            }
            navigate('/');
        } catch (err: any) {
            console.error(err);
            let msg = "Error de autenticación.";
            if (err.code === 'auth/wrong-password') msg = "Contraseña incorrecta.";
            if (err.code === 'auth/user-not-found') msg = "Usuario no encontrado.";
            if (err.code === 'auth/email-already-in-use') msg = "El correo ya está registrado.";
            if (err.code === 'auth/weak-password') msg = "La contraseña es muy débil (min 6 caracteres).";
            if (err.code === 'auth/invalid-email') msg = "Correo inválido.";
            setError(msg);
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-[#0b1021] flex items-center justify-center p-4">
            <div className="bg-[#151b2e] border border-white/10 rounded-2xl p-8 max-w-md w-full shadow-2xl">
                <div className="text-center mb-6">
                    <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-cyan-500 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl font-bold text-white shadow-lg shadow-indigo-500/20">
                        L
                    </div>
                    <h1 className="text-2xl font-bold text-white mb-2">
                        {isRegistering ? 'Crear Cuenta' : 'Bienvenido de nuevo'}
                    </h1>
                    <p className="text-gray-400 text-sm">
                        {isRegistering ? 'Únete a la comunidad de Listopic' : 'Accede a tus listas y guardados'}
                    </p>
                </div>

                {error && (
                    <div className="bg-red-500/10 border border-red-500/20 text-red-200 p-3 rounded-lg text-sm mb-6 text-center animate-pulse">
                        {error}
                    </div>
                )}

                <form onSubmit={handleEmailAuth} className="space-y-4 mb-6">
                    {isRegistering && (
                        <div className="relative">
                            <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                            <input
                                type="text"
                                placeholder="Nombre completo"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-[#0b1021] border border-white/10 rounded-xl px-10 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-indigo-500 transition-colors"
                                required={isRegistering}
                            />
                        </div>
                    )}

                    <div className="relative">
                        <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                        <input
                            type="email"
                            placeholder="Correo electrónico"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full bg-[#0b1021] border border-white/10 rounded-xl px-10 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-indigo-500 transition-colors"
                            required
                        />
                    </div>

                    <div className="relative">
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" />
                        <input
                            type="password"
                            placeholder="Contraseña"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full bg-[#0b1021] border border-white/10 rounded-xl px-10 py-3 text-white placeholder-gray-500 focus:outline-none focus:border-indigo-500 transition-colors"
                            required
                            minLength={6}
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3 px-4 rounded-xl shadow-lg shadow-indigo-600/20 transition-all hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                        {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                        {isRegistering ? 'Registrarse' : 'Iniciar Sesión'}
                    </button>
                </form>

                <div className="relative mb-6">
                    <div className="absolute inset-0 flex items-center">
                        <div className="w-full border-t border-white/10"></div>
                    </div>
                    <div className="relative flex justify-center text-xs uppercase">
                        <span className="bg-[#151b2e] px-2 text-gray-500">O continuar con</span>
                    </div>
                </div>

                <button
                    onClick={handleGoogleLogin}
                    disabled={loading}
                    className="w-full flex items-center justify-center gap-3 bg-white text-gray-900 font-bold py-3 px-4 rounded-xl hover:bg-gray-100 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <svg className="w-5 h-5" viewBox="0 0 24 24">
                        <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                        <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                        <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.84z" fill="#FBBC05" />
                        <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                    </svg>
                    <span>Google</span>
                </button>

                <div className="mt-6 text-center">
                    <button
                        onClick={() => setIsRegistering(!isRegistering)}
                        className="text-indigo-400 hover:text-indigo-300 text-sm font-medium hover:underline transition-colors"
                    >
                        {isRegistering ? '¿Ya tienes cuenta? Inicia sesión' : '¿No tienes cuenta? Regístrate'}
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, Link, useLocation } from 'react-router-dom';
import {
    MapPin, MessageSquare, List as ListIcon, Share2,
    Bookmark, Heart, Smartphone, Globe, Accessibility, Utensils, ShoppingBag, Bike, Clock, Coffee, Wine, Moon, Star, Plus, X, AlertTriangle, Image as ImageIcon, ZoomIn
} from 'lucide-react';
import { ShareModal } from '../components/ShareModal';
import { SaveToArchiveModal } from '../components/SaveToArchiveModal';
import { usePlaceDetails } from '../hooks/usePlaceDetails';
import { ReviewCard } from '../components/ReviewCard';
import { MapView } from '../components/MapView';
import { useAuth } from '../context/AuthContext';
import { doc, getDoc, setDoc, deleteDoc, updateDoc, increment, serverTimestamp, collection, query, where, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { AddReviewForm } from '../components/AddReviewForm';
import { ReportModal } from '../components/ReportModal';
import { Lightbox } from '../components/Lightbox';

import { ListSelector } from '../components/ListSelector';

export const PlacePage: React.FC = () => {
    const { placeId } = useParams<{ placeId: string }>();
    const { place, loading, error, refresh } = usePlaceDetails(placeId);
    const { user } = useAuth();
    const location = useLocation();
    const searchParams = new URLSearchParams(location.search);
    const fromListId = searchParams.get('listId');

    const [activeTab, setActiveTab] = useState<'reviews' | 'lists' | 'dishes' | 'photos'>('reviews');
    const [isLightboxOpen, setIsLightboxOpen] = useState(false);
    const [lightboxIndex, setLightboxIndex] = useState(0);
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isFollowed, setIsFollowed] = useState(false);
    const [isShareModalOpen, setIsShareModalOpen] = useState(false);
    const [followLoading, setFollowLoading] = useState(false);
    const [showReportModal, setShowReportModal] = useState(false);

    // Review Creation State
    const [isFlowOpen, setIsFlowOpen] = useState(false);
    const [selectedListId, setSelectedListId] = useState<string | null>(null);
    const [selectedDishName, setSelectedDishName] = useState<string | null>(null);
    const [editingReviewId, setEditingReviewId] = useState<string | null>(null);

    // Infinite Scroll State
    const [visibleCount, setVisibleCount] = useState(4);
    const loadMoreRef = React.useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                setVisibleCount(prev => prev + 5);
            }
        }, { threshold: 0.1 });

        if (loadMoreRef.current) observer.observe(loadMoreRef.current);
        return () => observer.disconnect();
    }, [activeTab, visibleCount]);

    // Compute suggested list IDs where this place is already present
    const suggestedListIds = useMemo(() => {
        if (!place?.relatedLists) return [];
        return place.relatedLists.map(l => l.id);
    }, [place?.relatedLists]);

    const handleEditReview = (review: any) => {
        setEditingReviewId(review.id);
        setIsFlowOpen(true);
    };

    const [reactionConfig, setReactionConfig] = useState<{ like?: string; dislike?: string } | null>(null);

    // Fetch Category Configuration for Reactions
    useEffect(() => {
        if (!place?.category) return;
        import('../services/CategoryService').then(({ CategoryService }) => {
            CategoryService.getCategory(place.category!).then(cat => {
                if (cat?.defaultCriteria?.rangos) {
                    setReactionConfig(cat.defaultCriteria.rangos);
                }
            });
        });
    }, [place?.category]);

    // ... (rest of the file remains similar until render)


    // Check if place is followed
    useEffect(() => {
        if (!user || !placeId) return;
        const checkFollow = async () => {
            try {
                const docRef = doc(db, 'users', user.uid, 'followingPlaces', placeId);
                const snap = await getDoc(docRef);
                setIsFollowed(snap.exists());
            } catch (e) {
                console.warn("Check follow error", e);
            }
        };
        checkFollow();
    }, [user, placeId]);

    const handleFollowToggle = async () => {
        if (!user || !placeId) return; // Prompt login if needed

        // Optimistic UI
        const prevState = isFollowed;
        setIsFollowed(!prevState);
        setFollowLoading(true);

        try {
            const followingPlaceRef = doc(db, 'users', user.uid, 'followingPlaces', placeId);

            // Backend Trigger 'onPlaceFollowingWrite' in 'social.js' handles:
            // 1. Updating user.followingPlacesCount
            // 2. Updating place.followersCount (and ensuring place doc exists)

            if (prevState) {
                // Unfollow (Trigger delete)
                await deleteDoc(followingPlaceRef);
            } else {
                // Follow (Trigger create)
                await setDoc(followingPlaceRef, {
                    placeId,
                    followedAt: serverTimestamp(),
                    placeName: place?.name || '',
                    placeAddress: place?.address || '',
                    placePhoto: place?.photoUrl || ''
                });
            }
        } catch (error) {
            console.error("Follow place error:", error);
            setIsFollowed(prevState); // Revert
        } finally {
            setFollowLoading(false);
        }
    };

    // --- Dishes Aggregation (Menu Mode: Platos) ---
    const dishes = useMemo(() => {
        if (!place?.reviews) return [];

        const dishMap: Record<string, { total: number; count: number; name: string; photos: string[]; listId?: string }> = {};

        place.reviews.forEach(r => {
            if (!r.itemName) return;
            const name = r.itemName.trim();
            const key = name.toLowerCase();

            if (!dishMap[key]) {
                dishMap[key] = { total: 0, count: 0, name: name, photos: [], listId: r.listId };
            }
            dishMap[key].total += r.overallRating;
            dishMap[key].count += 1;
            if (r.photoUrl) dishMap[key].photos.push(r.photoUrl);
            // Update listId fallback if missing
            if (!dishMap[key].listId && r.listId) dishMap[key].listId = r.listId;
        });

        return Object.values(dishMap).map(d => ({
            name: d.name,
            avg: d.total / d.count,
            count: d.count,
            photo: d.photos[0],
            listId: d.listId
        })).sort((a, b) => b.avg - a.avg);
    }, [place?.reviews]);


    // Aggregate Photos for Gallery
    const galleryPhotos = useMemo(() => {
        if (!place) return [];
        const set = new Set<string>();

        // 1. Place Photos
        const placeAny = place as any;
        if (placeAny.photos && Array.isArray(placeAny.photos)) {
            placeAny.photos.forEach((p: string) => p && set.add(p));
        } else if (place.photoUrl) {
            set.add(place.photoUrl);
        }

        // 2. Review Photos
        if (place.reviews) {
            place.reviews.forEach(r => {
                if (r.photoUrl) set.add(r.photoUrl);
            });
        }

        return Array.from(set);
    }, [place]);



    // Helper for Price Level
    const renderPriceLevel = (level?: number) => {
        if (!level && level !== 0) return null;
        // Map 0-4 to € symbols. If string e.g 'PRICE_LEVEL_EXPENSIVE', logic needed. 
        // Assuming number 0-4 or similar.
        const count = typeof level === 'number' ? level : 2;
        return (
            <div className="flex text-emerald-400 font-bold" title="Nivel de precio">
                {[...Array(5)].map((_, i) => (
                    <span key={i} className={i < count ? 'opacity-100' : 'opacity-30 text-gray-500'}>€</span>
                ))}
            </div>
        );
    };

    if (loading) {
        return (
            <div className="min-h-screen pt-32 px-4 flex justify-center bg-[#0b1021]">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
            </div>
        );
    }

    if (error || !place) {
        return (
            <div className="min-h-screen pt-32 px-4 text-center bg-[#0b1021]">
                <h2 className="text-2xl font-bold text-red-400">Lugar no encontrado</h2>
                <Link to="/search" className="text-indigo-400 mt-4 inline-block hover:underline">
                    Volver a buscar
                </Link>
            </div>
        );
    }


    // Dynamic Color for Score

    const handleShareClick = () => {
        setIsShareModalOpen(true);
    };

    return (
        <div className="min-h-screen bg-[#0b1021] pb-20">
            {/* Hero */}
            <div className="relative h-[40vh] min-h-[300px] w-full overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-black/40 z-10" />

                {place.photoUrl ? (
                    <img src={place.photoUrl} alt={place.name} className="w-full h-full object-cover opacity-80 group-hover:scale-105 transition-transform duration-1000" />
                ) : (
                    <div className="w-full h-full bg-gradient-to-br from-indigo-900 to-gray-900 flex items-center justify-center">
                        <MapPin className="w-20 h-20 text-white/20" />
                    </div>
                )}

                <div className="absolute bottom-0 left-0 w-full p-4 sm:p-8 z-20 bg-gradient-to-t from-[#0b1021] via-[#0b1021]/60 to-transparent pt-20">
                    <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-end md:justify-between gap-6">

                        {/* Title & Info */}
                        <div className="flex-1">
                            <h1 className="text-3xl sm:text-4xl md:text-6xl font-display font-bold text-white mb-2 shadow-sm text-shadow-lg leading-tight line-clamp-2">
                                {place.name}
                            </h1>
                            {place.address && (
                                <p className="text-gray-200 flex items-center gap-2 text-sm sm:text-lg max-w-2xl font-light line-clamp-1">
                                    <MapPin className="w-4 h-4 text-indigo-400 shrink-0" />
                                    {place.address}
                                </p>
                            )}
                        </div>

                        {/* Ratings & Awards Row */}
                        <div className="flex flex-col items-start md:items-end gap-3">
                            <div className="flex flex-wrap items-center gap-2">
                                {/* Listopic Rating */}
                                <div className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-bold border backdrop-blur-md ${place.avgScore >= 7
                                    ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-400'
                                    : 'bg-indigo-500/20 border-indigo-500/30 text-indigo-400'
                                    }`}>
                                    <Star className="w-4 h-4 fill-current" />
                                    <span>{place.avgScore.toFixed(1)}</span>
                                </div>

                                {/* Google Rating */}
                                {place.googleRating && (
                                    <div className="flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-bold bg-white/10 border border-white/10 text-white backdrop-blur-md">
                                        <svg viewBox="0 0 24 24" className="w-4 h-4 fill-current text-white" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .533 5.333.533 12S5.867 24 12.48 24c3.44 0 6.053-1.147 8.16-3.293 2.133-2.133 2.827-5.28 2.827-7.893 0-.693-.053-1.52-.16-2.16h-10.827z" />
                                        </svg>
                                        <span>{place.googleRating.toFixed(1)}</span>
                                        {place.googleUserRatingCount && (
                                            <span className="text-xs text-gray-400 font-normal ml-0.5 opacity-70">({place.googleUserRatingCount})</span>
                                        )}
                                    </div>
                                )}

                                {
                                    /* Awards removed */
                                }

                                {/* Add Review Button (New) */}
                                <button
                                    onClick={() => {
                                        if (fromListId) {
                                            setSelectedListId(fromListId);
                                            setIsFlowOpen(true);
                                        } else {
                                            setSelectedListId(null);
                                            setIsFlowOpen(true);
                                        }
                                    }}
                                    className="px-4 py-2 bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-400 hover:to-teal-400 text-white text-sm font-bold rounded-xl shadow-lg shadow-emerald-500/20 flex items-center gap-2 hover:scale-105 transition-all ml-2"
                                >
                                    <Plus className="w-4 h-4" />
                                    <span>Añadir Reseña</span>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content: Flex Col on Mobile (Order control), Grid on Desktop */}
            <main className="max-w-7xl mx-auto px-4 sm:px-6 pt-4 sm:pt-8 flex flex-col lg:grid lg:grid-cols-12 gap-8">

                {/* Sidebar (Right on Desktop, Top on Mobile) */}
                {/* Order-1 on Mobile -> Renders FIRST. lg:order-last -> Renders RIGHT. */}
                <div className="order-1 lg:col-span-4 lg:order-last space-y-4 sm:space-y-6">

                    {/* 1. Actions Row */}
                    <div className="bg-[#151b2e] p-3 rounded-xl border border-white/10 grid grid-cols-4 gap-2 sm:gap-3">
                        <button
                            onClick={() => setIsSaveModalOpen(true)}
                            className="flex flex-col items-center justify-center p-2 rounded-xl border border-white/5 bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white transition-all"
                        >
                            <Bookmark className="w-5 h-5 mb-1 text-indigo-400" />
                            <span className="text-[10px] sm:text-xs font-bold uppercase tracking-wider">Guardar</span>
                        </button>
                        <button
                            onClick={handleFollowToggle}
                            disabled={followLoading}
                            className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all ${isFollowed ? 'bg-pink-500/20 border-pink-500 text-pink-400' : 'bg-white/5 border-white/5 text-gray-400 hover:bg-white/10 hover:text-white'} ${followLoading ? 'opacity-50 cursor-wait' : ''}`}
                        >
                            <Heart className={`w-5 h-5 mb-1 ${isFollowed ? 'fill-current' : ''}`} />
                            <span className="text-[10px] sm:text-xs font-bold uppercase tracking-wider">{isFollowed ? 'Seguido' : 'Seguir'}</span>
                        </button>
                        <button
                            onClick={handleShareClick}
                            className="flex flex-col items-center justify-center p-2 rounded-xl border border-white/5 bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white transition-all active:scale-95 active:bg-indigo-500/20 active:border-indigo-500/50"
                        >
                            <Share2 className="w-5 h-5 mb-1 text-indigo-400" />
                            <span className="text-[10px] sm:text-xs font-bold uppercase tracking-wider">Compartir</span>
                        </button>
                        <button
                            onClick={() => setShowReportModal(true)}
                            className="flex flex-col items-center justify-center p-2 rounded-xl border border-white/5 bg-white/5 text-gray-400 hover:bg-red-500/10 hover:text-red-400 transition-all group/report"
                        >
                            <AlertTriangle className="w-5 h-5 mb-1 text-red-500/50 group-hover/report:text-red-500 transition-colors" />
                            <span className="text-[10px] sm:text-xs font-bold uppercase tracking-wider">Reportar</span>
                        </button>
                    </div>

                    {/* 2. Map */}
                    {place.coords && (
                        <div className="bg-[#151b2e] rounded-xl overflow-hidden border border-white/10 shadow-lg relative group">
                            <div className="absolute top-3 right-3 z-10">
                                <a
                                    href={place.googleMapsUri || `https://www.google.com/maps/search/?api=1&query=${place.coords.lat},${place.coords.lng}`}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="px-3 py-1.5 bg-black/50 backdrop-blur-md rounded-lg text-white text-xs font-bold flex items-center gap-2 hover:bg-indigo-600 transition-colors border border-white/10"
                                >
                                    <MapPin className="w-3 h-3" />
                                    Abrir en Google Maps
                                </a>
                            </div>
                            <div className="h-48 sm:h-64 relative z-0">
                                <MapView items={[{ ...place.reviews[0], lat: place.coords.lat, lng: place.coords.lng }]} />
                            </div>
                        </div>
                    )}

                    {/* 3. Detailed Info (New Rich Data) */}
                    <div className="bg-[#151b2e] p-5 rounded-xl border border-white/10 space-y-4">
                        <h3 className="font-bold text-white border-b border-white/5 pb-2 text-sm uppercase tracking-wider">Detalles</h3>

                        {/* Price & Features Grid */}
                        <div className="grid grid-cols-2 gap-4 pb-4 border-b border-white/5">
                            {place.priceLevel !== undefined && (
                                <div>
                                    <span className="text-xs text-gray-500 block mb-1">Precio</span>
                                    {renderPriceLevel(place.priceLevel)}
                                </div>
                            )}

                            {place.accessibility && (
                                <div className="col-span-2 sm:col-span-1">
                                    <span className="text-xs text-gray-500 block mb-1">Accesibilidad</span>
                                    <div className="space-y-1">
                                        {place.accessibility.wheelchairAccessibleEntrance && (
                                            <div className="flex items-center gap-2 text-indigo-400 font-medium text-xs">
                                                <Accessibility className="w-4 h-4" />
                                                <span>Entrada adaptada</span>
                                            </div>
                                        )}
                                        {place.accessibility.wheelchairAccessibleRestroom && (
                                            <div className="flex items-center gap-2 text-indigo-400 font-medium text-xs">
                                                <Accessibility className="w-4 h-4" />
                                                <span>Baño adaptado</span>
                                            </div>
                                        )}
                                        {!place.accessibility.wheelchairAccessibleEntrance && !place.accessibility.wheelchairAccessibleRestroom && (
                                            <span className="text-gray-400 text-xs">-</span>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Options Chips */}
                        <div className="flex flex-wrap gap-2">
                            {place.options?.delivery && (
                                <span className="px-3 py-1 bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Bike className="w-3 h-3" /> Delivery
                                </span>
                            )}
                            {place.options?.takeout && (
                                <span className="px-3 py-1 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <ShoppingBag className="w-3 h-3" /> Takeaway
                                </span>
                            )}
                            {place.options?.dineIn && (
                                <span className="px-3 py-1 bg-purple-500/10 text-purple-400 border border-purple-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Utensils className="w-3 h-3" /> Restaurante
                                </span>
                            )}
                            {place.options?.reservable && (
                                <span className="px-3 py-1 bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Clock className="w-3 h-3" /> Reservas
                                </span>
                            )}
                            {place.options?.servesBreakfast && (
                                <span className="px-3 py-1 bg-yellow-500/10 text-yellow-400 border border-yellow-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Coffee className="w-3 h-3" /> Desayuno
                                </span>
                            )}
                            {place.options?.servesLunch && (
                                <span className="px-3 py-1 bg-orange-500/10 text-orange-400 border border-orange-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Utensils className="w-3 h-3" /> Comida
                                </span>
                            )}
                            {place.options?.servesDinner && (
                                <span className="px-3 py-1 bg-slate-500/10 text-slate-300 border border-slate-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Moon className="w-3 h-3" /> Cena
                                </span>
                            )}
                            {(place.options?.servesBeer || place.options?.servesWine) && (
                                <span className="px-3 py-1 bg-red-500/10 text-red-400 border border-red-500/20 rounded-full text-xs font-bold flex items-center gap-1">
                                    <Wine className="w-3 h-3" /> Alcohol
                                </span>
                            )}
                        </div>

                        {/* Contact Buttons */}
                        <div className="flex flex-col gap-3 pt-2">
                            {place.website && (
                                <a
                                    href={place.website}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="flex items-center justify-center gap-2 w-full p-3 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-sm transition-all shadow-lg shadow-indigo-500/20 group"
                                >
                                    <Globe className="w-4 h-4 group-hover:scale-110 transition-transform" />
                                    Visitar Sitio Web
                                </a>
                            )}
                            {place.phone && (
                                <a
                                    href={`tel:${place.phone}`}
                                    className="flex items-center justify-center gap-2 w-full p-3 rounded-xl bg-white/5 hover:bg-white/10 text-gray-300 hover:text-white font-bold text-sm transition-all border border-white/10 group"
                                >
                                    <Smartphone className="w-4 h-4 group-hover:scale-110 transition-transform" />
                                    Llamar ({place.phone})
                                </a>
                            )}
                        </div>
                    </div>
                </div>

                {/* Left: Content (Tabs) */}
                {/* Order-2 on Mobile -> Renders SECOND. lg:order-first -> Renders LEFT. */}
                <div className="order-2 lg:col-span-8 lg:order-first">
                    {/* Tabs */}
                    <div className="flex gap-4 sm:gap-8 border-b border-white/10 mb-6 overflow-x-auto scrollbar-hide px-1">
                        <button
                            onClick={() => setActiveTab('reviews')}
                            className={`pb-3 px-2 text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap border-b-2 ${activeTab === 'reviews'
                                ? 'border-indigo-500 text-indigo-400'
                                : 'border-transparent text-gray-400 hover:text-white'
                                }`}
                        >
                            <MessageSquare className="w-4 h-4" /> Opiniones ({place.reviews.length})
                        </button>
                        <button
                            onClick={() => setActiveTab('dishes')}
                            className={`pb-3 px-2 text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap border-b-2 ${activeTab === 'dishes'
                                ? 'border-indigo-500 text-indigo-400'
                                : 'border-transparent text-gray-400 hover:text-white'
                                }`}
                        >
                            <ListIcon className="w-4 h-4" /> La Carta ({dishes.length || 0})
                        </button>
                        <button
                            onClick={() => setActiveTab('lists')}
                            className={`pb-3 px-2 text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap border-b-2 ${activeTab === 'lists'
                                ? 'border-indigo-500 text-indigo-400'
                                : 'border-transparent text-gray-400 hover:text-white'
                                }`}
                        >
                            <Bookmark className="w-4 h-4" /> Listas ({place.relatedLists?.length || 0})
                        </button>
                        <button
                            onClick={() => setActiveTab('photos')}
                            className={`pb-3 px-2 text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap border-b-2 ${activeTab === 'photos'
                                ? 'border-indigo-500 text-indigo-400'
                                : 'border-transparent text-gray-400 hover:text-white'
                                }`}
                        >
                            <ImageIcon className="w-4 h-4" /> Fotos ({galleryPhotos.length})
                        </button>
                    </div>



                    {activeTab === 'reviews' && (
                        <div className="grid grid-cols-1 gap-6 animate-fade-in">
                            {place.reviews.slice(0, visibleCount).map(review => (
                                <ReviewCard
                                    key={review.id}
                                    review={review}
                                    reactionConfig={reactionConfig || undefined}
                                    onEdit={handleEditReview}
                                />
                            ))}
                            {visibleCount < place.reviews.length && (
                                <div ref={loadMoreRef} className="py-4 flex justify-center">
                                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'dishes' && (
                        <div className="animate-fade-in bg-[#151b2e] rounded-2xl border border-white/10 p-6 sm:p-8">
                            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                <ListIcon className="w-5 h-5 text-indigo-400" />
                                Platos Destacados
                            </h3>

                            {dishes && dishes.length > 0 ? (
                                <div className="space-y-4">
                                    {dishes.map((dish, idx) => (
                                        <div key={idx} className="flex items-center justify-between p-3 rounded-xl bg-white/5 hover:bg-white/10 transition-colors group">
                                            <Link
                                                to={`/group/${placeId}/${encodeURIComponent(dish.name)}`}
                                                className="flex items-center gap-4 flex-1 min-w-0"
                                            >
                                                <div className="w-12 h-12 rounded-lg bg-gray-800 overflow-hidden shrink-0">
                                                    {dish.photo ? (
                                                        <img src={dish.photo} alt={dish.name} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <div className="w-full h-full flex items-center justify-center text-gray-600 font-bold text-xs">
                                                            IMG
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="min-w-0">
                                                    <h4 className="font-bold text-white group-hover:text-indigo-400 transition-colors truncate">{dish.name}</h4>
                                                    <div className="flex items-center gap-2 text-xs text-gray-400">
                                                        <span className="font-bold text-emerald-400">{dish.avg.toFixed(1)}</span>
                                                        <span>• {dish.count} opiniones</span>
                                                    </div>
                                                </div>
                                            </Link>

                                            <button
                                                onClick={() => {
                                                    if (dish.listId) {
                                                        setSelectedListId(dish.listId);
                                                        setSelectedDishName(dish.name);
                                                        setIsFlowOpen(true);
                                                    } else {
                                                        alert("No se pudo identificar la lista asociada a este plato.");
                                                    }
                                                }}
                                                className="px-3 py-1.5 rounded-full bg-indigo-600 text-white text-xs font-bold hover:bg-indigo-500 transition-colors shadow-lg shadow-indigo-500/20"
                                            >
                                                Valorar
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <div className="text-center py-10 text-gray-500">
                                    No hay suficientes datos para mostrar la carta.
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'lists' && (
                        <div className="space-y-8 animate-fade-in">
                            {(() => {
                                const mainLists = place.relatedLists?.filter(l => !l.parentListId) || [];
                                const subLists = place.relatedLists?.filter(l => !!l.parentListId) || [];

                                if (mainLists.length === 0 && subLists.length === 0) {
                                    return (
                                        <div className="py-10 text-center text-gray-500 border border-dashed border-white/10 rounded-xl">
                                            Este lugar aún no ha sido añadido a otras listas públicas.
                                        </div>
                                    );
                                }

                                return (
                                    <>
                                        {mainLists.length > 0 && (
                                            <div>
                                                <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                                                    <ListIcon className="w-5 h-5 text-indigo-400" />
                                                    Listas ({mainLists.length})
                                                </h3>
                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                    {mainLists.map((list: any) => (
                                                        <Link key={list.id} to={`/list/${list.id}`} className="block group">
                                                            <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden hover:border-indigo-500/50 transition-all h-full flex flex-col">
                                                                <div className="h-32 bg-gray-800 relative">
                                                                    {list.photoUrl ? (
                                                                        <img src={list.photoUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                                                                    ) : (
                                                                        <div className="w-full h-full flex items-center justify-center bg-gray-800">
                                                                            <ListIcon className="w-10 h-10 text-gray-600" />
                                                                        </div>
                                                                    )}
                                                                </div>
                                                                <div className="p-4 flex-1 flex flex-col justify-between">
                                                                    <div>
                                                                        <h3 className="text-white font-bold text-lg mb-1 truncate">{list.name}</h3>
                                                                        <p className="text-gray-500 text-xs line-clamp-2">{list.description}</p>
                                                                    </div>
                                                                    <div className="mt-4 pt-2 border-t border-white/5 flex items-center justify-between">
                                                                        {/* Hiding Author as requested */}
                                                                        <span className="text-xs text-indigo-400 font-medium group-hover:underline">Ver Lista</span>
                                                                        <span className="text-xs text-gray-500">{list.itemCount || 0} lugares</span>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </Link>
                                                    ))}
                                                </div>
                                            </div>
                                        )}

                                        {subLists.length > 0 && (
                                            <div>
                                                <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                                                    <div className="p-1 bg-purple-500/20 rounded text-purple-400"><ListIcon className="w-4 h-4" /></div>
                                                    Sublistas ({subLists.length})
                                                </h3>
                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                    {subLists.map((list: any) => (
                                                        <Link key={list.id} to={`/list/${list.id}`} className="block group">
                                                            <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden hover:border-purple-500/50 transition-all h-full flex flex-col relative">
                                                                <div className="h-32 bg-gray-800 relative">
                                                                    {list.photoUrl ? (
                                                                        <img src={list.photoUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                                                                    ) : (
                                                                        <div className="w-full h-full flex items-center justify-center bg-gray-800">
                                                                            <ListIcon className="w-10 h-10 text-gray-600" />
                                                                        </div>
                                                                    )}
                                                                    <div className="absolute top-2 right-2 p-1 bg-black/50 rounded backdrop-blur-md">
                                                                        <span className="text-[10px] font-bold uppercase tracking-wider text-purple-400 bg-purple-500/10 px-2 py-0.5 rounded">Sublista</span>
                                                                    </div>
                                                                </div>
                                                                <div className="p-4 flex-1 flex flex-col justify-between">
                                                                    <div>
                                                                        <h3 className="text-white font-bold text-lg mb-1 truncate">{list.name}</h3>
                                                                        <p className="text-gray-500 text-xs line-clamp-2">{list.description}</p>
                                                                    </div>
                                                                    <div className="mt-4 pt-2 border-t border-white/5 flex items-center justify-between">
                                                                        {/* Hiding Author */}
                                                                        <span className="text-xs text-purple-400 font-medium group-hover:underline">Ver Sublista</span>
                                                                        <span className="text-xs text-gray-500">{list.itemCount || 0} lugares</span>
                                                                    </div>
                                                                </div>
                                                            </div>
                                                        </Link>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </>
                                );
                            })()}
                        </div>
                    )}

                    {activeTab === 'photos' && (
                        <div className="animate-fade-in">
                            {galleryPhotos.length > 0 ? (
                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                                    {galleryPhotos.map((photo, idx) => (
                                        <div
                                            key={idx}
                                            onClick={() => {
                                                setLightboxIndex(idx);
                                                setIsLightboxOpen(true);
                                            }}
                                            className="aspect-square rounded-xl overflow-hidden bg-gray-800 cursor-pointer group relative border border-white/5 hover:border-indigo-500/50 transition-all"
                                        >
                                            <img src={photo} alt="Lugar" className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                                            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                                                <div className="bg-black/50 backdrop-blur-sm p-2 rounded-full text-white">
                                                    <ZoomIn className="w-5 h-5" />
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <div className="py-16 text-center bg-[#151b2e] rounded-xl border border-dashed border-white/10">
                                    <ImageIcon className="w-12 h-12 text-gray-600 mx-auto mb-3" />
                                    <h3 className="text-white font-bold">Sin fotos</h3>
                                    <p className="text-gray-500 text-sm">Aún no hay fotos de este lugar.</p>
                                </div>
                            )}
                        </div>
                    )}

                    <Lightbox
                        isOpen={isLightboxOpen}
                        onClose={() => setIsLightboxOpen(false)}
                        images={galleryPhotos}
                        initialIndex={lightboxIndex}
                    />
                </div>
            </main >

            <SaveToArchiveModal
                isOpen={isSaveModalOpen}
                onClose={() => setIsSaveModalOpen(false)}
                item={{
                    itemId: place.placeId,
                    type: 'place',
                    name: place.name,
                    subtitle: place.address,
                    route: `/place/${place.placeId}`,
                    photoUrl: place.photoUrl || undefined
                }}
            />

            {/* Review Creation Flow */}
            {/* Direct access to Form - internal list selection if needed */}
            {
                isFlowOpen && (
                    <AddReviewForm
                        listId={selectedListId}
                        onListChange={setSelectedListId}
                        prefillPlaceId={place.placeId}
                        prefillItemName={selectedDishName || undefined}
                        editReviewId={editingReviewId || undefined}
                        lockList={!!selectedListId}
                        onClose={() => {
                            setIsFlowOpen(false);
                            setSelectedListId(null);
                            setSelectedDishName(null);
                            setEditingReviewId(null);
                        }}
                        onSuccess={() => {
                            setIsFlowOpen(false);
                            setSelectedListId(null);
                            setSelectedDishName(null);
                            // Maybe refresh reviews? Realtime updates handle it.
                            if (refresh) refresh();
                        }}
                        suggestedListIds={suggestedListIds}
                    />
                )
            }
            {/* Share Modal */}
            <ShareModal
                isOpen={isShareModalOpen}
                onClose={() => setIsShareModalOpen(false)}
                title={`Compartir ${place.name}`}
                place={place}
            />

            <ReportModal
                isOpen={showReportModal}
                onClose={() => setShowReportModal(false)}
                targetId={place.placeId}
                targetName={place.name}
                targetType="place"
            />
        </div >
    );
};

import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useUserProfile } from '../hooks/useUserProfile';
import { useLists } from '../hooks/useLists';
import { useReviews } from '../hooks/useReviews';
import { useFilters } from '../context/FilterContext'; // Import Filter Context
import { Settings, Calendar, Users as UsersIcon, List as ListIcon, Star, UserPlus, UserCheck, MessageCircle, Power, MapPin as MapPinIcon, Bug, Flag, MoreVertical, Loader2 } from 'lucide-react';
import { ReportModal } from '../components/ReportModal';
import { doc, setDoc, deleteDoc, getDoc, updateDoc, increment } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { db, auth, storage } from '../firebase';
import { signOut } from 'firebase/auth';
import { ReviewCard } from '../components/ReviewCard';
import { AddReviewForm } from '../components/AddReviewForm';
import { ChatService } from '../services/ChatService';
import { FollowingSection } from '../components/profile/FollowingSection';
import { BadgeDisplay } from '../components/profile/BadgeDisplay';
import { collection, query, where, getDocs, limit, documentId, FieldPath } from 'firebase/firestore';

// Helper Component for List Cards
const ListGrid = ({ lists, emptyMessage, isSublist = false }: { lists: any[], emptyMessage: string, isSublist?: boolean }) => {
    if (lists.length === 0) {
        return (
            <div className="py-8 text-center border border-dashed border-white/5 rounded-xl bg-white/5">
                <p className="text-gray-500 text-sm">{emptyMessage}</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {lists.map(list => (
                <Link key={list.id} to={`/list/${list.id}`} className="block group">
                    <div className="bg-[#151b2e] border border-white/10 rounded-xl overflow-hidden hover:border-indigo-500/50 transition-all h-full flex flex-col relative">
                        <div className="h-32 bg-gray-800 relative">
                            {list.photoUrl ? (
                                <img src={list.photoUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center bg-gray-800">
                                    <ListIcon className="w-10 h-10 text-gray-600" />
                                </div>
                            )}
                            {isSublist && (
                                <div className="absolute top-2 left-2 bg-indigo-600/90 px-2 py-0.5 rounded text-[10px] font-bold text-white uppercase tracking-wider">
                                    Sublista
                                </div>
                            )}
                            {!list.isPublic && (
                                <div className="absolute top-2 right-2 bg-red-500/90 px-2 py-0.5 rounded text-[10px] font-bold text-white uppercase tracking-wider flex items-center gap-1">
                                    Privada
                                </div>
                            )}
                        </div>
                        <div className="p-4 flex-1 flex flex-col">
                            <h3 className="text-white font-bold text-lg mb-1 truncate">{list.name}</h3>
                            <p className="text-gray-500 text-xs mb-3 flex-1 line-clamp-2">{list.description}</p>
                            <div className="flex justify-between items-center text-xs text-gray-400 mt-2 pt-2 border-t border-white/5">
                                <span>{list.itemCount || 0} lugares</span>
                                {list.ownerName && <span className="text-indigo-400">de {list.ownerName}</span>}
                            </div>
                        </div>
                    </div>
                </Link>
            ))}
        </div>
    );
};

export const ProfilePage: React.FC = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const { userId: paramUserId } = useParams<{ userId: string }>();
    const [activeTab, setActiveTab] = useState<'lists' | 'reviews' | 'following'>('reviews');
    const [isFollowing, setIsFollowing] = useState(false);
    const [followLoading, setFollowLoading] = useState(false);
    const [isEditing, setIsEditing] = useState(false);
    const [editRange, setEditRange] = useState<string>('50'); // Default to 50 if undefined
    const [uploading, setUploading] = useState(false);
    const [dragActive, setDragActive] = useState(false);
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [showReportModal, setShowReportModal] = useState(false);
    const [isFlowOpen, setIsFlowOpen] = useState(false);
    const [editingReviewId, setEditingReviewId] = useState<string | null>(null);
    const [editingListId, setEditingListId] = useState<string | null>(null);

    const handleEditReview = (review: any) => {
        setEditingReviewId(review.id);
        setEditingListId(review.listId || null);
        setIsFlowOpen(true);
    };

    // Determine target user ID
    const targetUserId = paramUserId || user?.uid;
    const isOwnProfile = user?.uid === targetUserId;

    // Hooks
    const { profile, loading: loadingProfile, error: errorProfile } = useUserProfile(targetUserId);
    const { lists: ownedLists, loading: loadingLists } = useLists('recent', targetUserId, isOwnProfile); // Pass isOwnProfile to include private
    const { reviews: fetchedReviews, loading: loadingReviews, refresh: refreshReviews, fetchMore, hasMore, loadingMore } = useReviews({ type: 'recent', userId: targetUserId });
    const [localReviews, setLocalReviews] = useState<any[]>([]);

    // Infinite Scroll Effect (Must be after useReviews)
    const loadMoreRef = React.useRef<HTMLDivElement>(null);
    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting && hasMore && !loadingMore) {
                fetchMore();
            }
        }, { threshold: 0.1 });

        if (loadMoreRef.current) observer.observe(loadMoreRef.current);
        return () => observer.disconnect();
    }, [hasMore, loadingMore, activeTab]);

    // Additional List States
    const [guestLists, setGuestLists] = useState<any[]>([]);
    const [followedLists, setFollowedLists] = useState<any[]>([]);
    const [loadingExtraLists, setLoadingExtraLists] = useState(false);

    // Derived Lists
    const mainCreatedLists = ownedLists.filter(l => !l.parentListId);
    const subCreatedLists = ownedLists.filter(l => !!l.parentListId);

    const mainFollowedLists = followedLists.filter(l => !l.parentListId);
    const subFollowedLists = followedLists.filter(l => !!l.parentListId);

    // Fetch Guest & Followed Lists
    useEffect(() => {
        if (!targetUserId) return;

        const fetchExtra = async () => {
            setLoadingExtraLists(true);
            try {
                // 1. Guest Lists (Where I am an editor)
                // Note: 'editors' array-contains query
                // FIX: Only fetch guest lists if viewing own profile to avoid permission errors (can't query private lists of others)
                // or ensure we rely on Algolia for complex search. For now, strict check.
                let validGuest: any[] = [];
                if (isOwnProfile) {
                    try {
                        const qGuest = query(collection(db, 'lists'), where('editors', 'array-contains', targetUserId), limit(20));
                        const snapGuest = await getDocs(qGuest);
                        validGuest = snapGuest.docs.map(d => ({ id: d.id, ...d.data() }));
                    } catch (e: any) {
                        console.warn("Guest lists query failed (likely missing index or permission)", e);
                        // Don't crash, just empty
                    }
                } else {
                    // If viewing someone else, we can ONLY see public lists where they are editor
                    // Note: This requires composite index: editors (array) + isPublic (asc/desc)
                    try {
                        const qGuest = query(
                            collection(db, 'lists'),
                            where('editors', 'array-contains', targetUserId),
                            where('isPublic', '==', true),
                            limit(20)
                        );
                        const snapGuest = await getDocs(qGuest);
                        validGuest = snapGuest.docs.map(d => ({ id: d.id, ...d.data() }));
                    } catch (e: any) {
                        // Index might be missing for this composite query, fail gracefully
                        console.warn("Guest lists (public) query failed", e);
                    }
                }
                setGuestLists(validGuest);

                // 2. Followed Lists (From 'followingLists' subcollection)
                const qFollowed = query(collection(db, 'users', targetUserId, 'followingLists'));
                const snapFollowed = await getDocs(qFollowed);

                if (!snapFollowed.empty) {
                    const followedIds = snapFollowed.docs.map(d => d.id);
                    // Fetch full details for the first 20 to check isPublic/parentListId
                    // Firestore 'in' query supports max 10/30 depending on version. 10 safe.
                    // We'll batch or just fetch individual if few.
                    const chunks = [];
                    for (let i = 0; i < followedIds.length; i += 10) {
                        chunks.push(followedIds.slice(i, i + 10));
                    }

                    let allFollowedDetails: any[] = [];
                    for (const chunk of chunks) {
                        try {
                            // Only fetch PUBLIC lists to avoid permission errors.
                            // If a user follows a private list, it won't be shown here, which is standard behavior
                            // unless we implement a specific 'sharedWithMe' check.
                            const qDetails = query(
                                collection(db, 'lists'),
                                where(documentId(), 'in', chunk),
                                where('isPublic', '==', true)
                            );
                            const capsShot = await getDocs(qDetails);
                            allFollowedDetails.push(...capsShot.docs.map(d => ({ id: d.id, ...d.data() })));
                        } catch (chunkError) {
                            console.warn("Error fetching chunk of lists", chunkError);
                        }
                    }

                    // Filter Privacy
                    // If viewing another profile, only show their followed lists if those lists are PUBLIC.
                    // Private lists followed by someone else shouldn't be exposed details unless viewer has access.
                    // We'll stick to isPublic == true.
                    // Also filter out any that failed to fetch (deleted).
                    const validFollowed = allFollowedDetails.filter(l => l.isPublic || (user && (l.userId === user.uid || l.editors?.includes(user.uid))));
                    setFollowedLists(validFollowed);
                } else {
                    setFollowedLists([]);
                }

            } catch (e) {
                console.error("Error fetching extra lists", e);
            } finally {
                setLoadingExtraLists(false);
            }
        };

        fetchExtra();
    }, [targetUserId, isOwnProfile, user]);

    useEffect(() => {
        if (fetchedReviews) {
            setLocalReviews(fetchedReviews);
        }
    }, [fetchedReviews]);

    const handleDeleteReview = (id: string) => {
        setLocalReviews(prev => prev.filter(r => r.id !== id));
    };

    // Check Follow Status
    useEffect(() => {
        if (!user || isOwnProfile || !targetUserId) return;

        const checkFollow = async () => {
            const docRef = doc(db, 'users', user.uid, 'following', targetUserId);
            const snap = await getDoc(docRef);
            setIsFollowing(snap.exists());
        };
        checkFollow();
    }, [user, targetUserId, isOwnProfile]);

    useEffect(() => {
        if (profile?.defaultDistanceKm) {
            setEditRange(String(profile.defaultDistanceKm));
        }
    }, [profile]);

    // Image Upload Handlers
    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const processFile = async (file: File) => {
        if (!user) return;
        if (!file.type.startsWith('image/')) {
            alert("Solo se permiten archivos de imagen");
            return;
        }
        if (file.size > 5 * 1024 * 1024) { // 5MB limit
            alert("La imagen no debe superar los 5MB");
            return;
        }

        setUploading(true);
        try {
            const storageRef = ref(storage, `profile_images/${user.uid}/${Date.now()}_${file.name}`);
            await uploadBytes(storageRef, file);
            const downloadURL = await getDownloadURL(storageRef);

            await setDoc(doc(db, 'users', user.uid), {
                photoUrl: downloadURL
            }, { merge: true });

            // Reload to show changes (simple approach)
            window.location.reload();
        } catch (error) {
            console.error("Error uploading image:", error);
            alert("Error al subir la imagen");
        } finally {
            setUploading(false);
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            processFile(e.dataTransfer.files[0]);
        }
    };

    const { setRange } = useFilters(); // Get setRange from context

    const savePreferences = async () => {
        if (!user) return;
        try {
            const val = parseInt(editRange);
            const newRange = isNaN(val) ? 50 : (val >= 999999 ? null : val);

            await setDoc(doc(db, 'users', user.uid), {
                defaultDistanceKm: isNaN(val) ? 50 : val
            }, { merge: true });

            // Update session too if generic
            // And CRUCIALLY update the context immediately so the UI reflects it without reload
            sessionStorage.removeItem('sessionRange');
            setRange(newRange);

            setIsEditing(false);
        } catch (err) {
            console.error("Error saving preferences:", err);
            alert("Error al guardar preferencias");
        }
    };

    const handleMessage = async () => {
        if (!user || !targetUserId) return;
        try {
            const chatId = await ChatService.createPrivateChat(user.uid, targetUserId);
            navigate(`/chats/${chatId}`);
        } catch (error) {
            console.error("Error creating chat:", error);
        }
    };

    const handleFollowToggle = async () => {
        if (!user || !targetUserId) return;
        setFollowLoading(true);
        try {
            const followingRef = doc(db, 'users', user.uid, 'following', targetUserId);
            // We do NOT write to the target user's 'followers' collection nor update their counts client-side.
            // This is now handled by the backend trigger 'onUserFollowingWrite' in 'functions/modules/social.js'
            // to ensure security and consistency.

            if (isFollowing) {
                // 1. Unfollow (Trigger delete)
                await deleteDoc(followingRef);
                setIsFollowing(false);
            } else {
                // 1. Follow (Trigger create)
                await setDoc(followingRef, {
                    uid: targetUserId,
                    followedAt: new Date(),
                    // Optional: Store snapshot for optimistic feed rendering
                    displayName: profile?.displayName || profile?.username,
                    photoUrl: profile?.photoUrl
                });
                setIsFollowing(true);
            }
        } catch (error) {
            console.error("Follow error:", error);
            alert("Error al seguir/dejar de seguir. Inténtalo de nuevo.");
            setIsFollowing(!isFollowing); // Revert optimistic UI if failed
        } finally {
            setFollowLoading(false);
        }
    };

    if (!targetUserId) {
        return (
            <div className="min-h-screen pt-40 px-4 text-center text-gray-400">
                Debes iniciar sesión para ver tu perfil.
            </div>
        );
    }

    if (loadingProfile) {
        return (
            <div className="min-h-screen pt-32 text-center text-gray-500">
                Cargando perfil...
            </div>
        );
    }

    if (errorProfile || !profile) {
        return (
            <div className="min-h-screen pt-40 px-4 text-center">
                <div className="text-2xl text-white font-bold mb-4">Perfil no encontrado</div>
                <p className="text-gray-400">El usuario que buscas no existe o ha sido eliminado.</p>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#0b1021] pb-20">
            {/* Header / Banner */}
            <div className={`h-64 relative bg-gradient-to-b from-indigo-900/40 to-[#0b1021] ${profile.photoUrl ? 'bg-cover bg-center' : ''}`} style={profile.photoUrl ? { backgroundImage: `linear-gradient(to bottom, rgba(11,16,33,0.3), #0b1021), url(${profile.photoUrl})` } : {}}>
                <div className="absolute inset-0 bg-[#0b1021]/60 blur-xl"></div>
                <div className="absolute inset-0 bg-[#0b1021]/60 blur-xl"></div>
                {/* Removed top-right buttons from here */}
            </div>

            <div className="max-w-5xl mx-auto px-4 sm:px-6 relative -mt-32 z-10">
                {/* TOP SECTION: Avatar + Identity + Desktop Actions */}
                <div className="flex flex-row items-end gap-4 md:gap-8 mb-6">
                    {/* Avatar (Left) */}
                    <div className="group relative shrink-0">
                        <div className="w-24 h-24 sm:w-32 sm:h-32 md:w-40 md:h-40 rounded-full bg-[#0b1021] p-1.5 md:p-2">
                            <div className="w-full h-full rounded-full bg-gray-700 overflow-hidden border-4 border-[#151b2e] shadow-2xl relative">
                                <img
                                    src={profile.photoUrl || `https://ui-avatars.com/api/?name=${profile.displayName || profile.username || 'User'}`}
                                    alt={profile.username}
                                    className="w-full h-full object-cover"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Identity (Right of Avatar) */}
                    <div className="flex-1 min-w-0 pb-1 md:pb-4 flex flex-col justify-end">
                        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                            <div>
                                <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold text-white leading-tight flex flex-col md:flex-row md:items-end gap-1 md:gap-3">
                                    <span className="truncate">{profile.displayName || profile.username || 'Usuario'}</span>
                                    {profile.username && <span className="text-base sm:text-lg text-indigo-400 font-normal truncate">@{profile.username}</span>}
                                </h1>
                            </div>

                            {/* DESKTOP ACTIONS */}
                            <div className="hidden md:flex items-center gap-3">
                                {isOwnProfile ? (
                                    <div className="flex items-center gap-2">
                                        {((Array.isArray(profile.userType) && profile.userType.includes('jefe')) || profile.userType === 'jefe') && (
                                            <Link to="/developer" className="p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-indigo-400 hover:bg-indigo-500/10 transition-colors">
                                                <Bug className="w-5 h-5" />
                                            </Link>
                                        )}
                                        <button onClick={() => setIsEditing(!isEditing)} className="p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-300 hover:text-white hover:bg-white/10 transition-colors">
                                            <Settings className="w-5 h-5" />
                                        </button>
                                        <button onClick={async () => { await signOut(auth); navigate('/login'); }} className="p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-300 hover:text-red-400 hover:bg-red-500/10 transition-colors">
                                            <Power className="w-5 h-5" />
                                        </button>
                                    </div>
                                ) : (
                                    <>
                                        <button
                                            onClick={handleFollowToggle}
                                            disabled={followLoading}
                                            className={`px-6 py-2.5 rounded-xl font-bold transition-all flex items-center justify-center gap-2 shadow-lg ${isFollowing
                                                ? 'bg-[#151b2e] border border-white/20 text-white hover:border-red-500 hover:text-red-500'
                                                : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-500/20'
                                                }`}
                                        >
                                            {isFollowing ? <><UserCheck className="w-4 h-4" /> Siguiendo</> : <><UserPlus className="w-4 h-4" /> Seguir</>}
                                        </button>
                                        <button
                                            onClick={handleMessage}
                                            className="px-4 py-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-white hover:bg-white/10 transition-colors shadow-lg"
                                        >
                                            <MessageCircle className="w-5 h-5" />
                                        </button>

                                        <div className="relative">
                                            <button
                                                onClick={() => setIsMenuOpen(!isMenuOpen)}
                                                className="px-3 py-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-400 hover:text-white hover:bg-white/10 transition-colors"
                                            >
                                                <MoreVertical className="w-5 h-5" />
                                            </button>
                                            {isMenuOpen && (
                                                <div className="absolute right-0 mt-2 w-48 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl py-1 overflow-hidden animate-fade-in z-50 origin-top-right">
                                                    <button
                                                        onClick={() => { setIsMenuOpen(false); setShowReportModal(true); }}
                                                        className="w-full text-left px-4 py-2.5 text-sm text-gray-300 hover:bg-white/5 hover:text-white flex items-center gap-2 transition-colors"
                                                    >
                                                        <Flag className="w-4 h-4" /> Reportar
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* BIO + MOBILE ACTIONS + STATS */}
                <div className="space-y-6 md:space-y-8">
                    {/* Bio */}
                    {profile.bio && (
                        <p className="text-gray-400 text-sm max-w-2xl leading-relaxed">
                            {profile.bio}
                        </p>
                    )}

                    {/* MOBILE ACTIONS */}
                    <div className="md:hidden flex items-center gap-3">
                        {isOwnProfile ? (
                            <div className="flex items-center gap-2 w-full">
                                {((Array.isArray(profile.userType) && profile.userType.includes('jefe')) || profile.userType === 'jefe') && (
                                    <Link to="/developer" className="p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-indigo-400">
                                        <Bug className="w-5 h-5" />
                                    </Link>
                                )}
                                <button onClick={() => setIsEditing(!isEditing)} className="flex-1 p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-300 text-sm font-bold">
                                    Editar Perfil
                                </button>
                                <button onClick={async () => { await signOut(auth); navigate('/login'); }} className="p-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-300 text-red-400">
                                    <Power className="w-5 h-5" />
                                </button>
                            </div>
                        ) : (
                            <div className="flex items-center gap-2 w-full">
                                <button
                                    onClick={handleFollowToggle}
                                    disabled={followLoading}
                                    className={`flex-1 px-4 py-2.5 rounded-xl font-bold transition-all flex items-center justify-center gap-2 shadow-lg ${isFollowing
                                        ? 'bg-[#151b2e] border border-white/20 text-white'
                                        : 'bg-indigo-600 text-white'
                                        }`}
                                >
                                    {isFollowing ? 'Siguiendo' : 'Seguir'}
                                </button>
                                <button
                                    onClick={handleMessage}
                                    className="px-4 py-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-white shadow-lg"
                                >
                                    <MessageCircle className="w-5 h-5" />
                                </button>
                                <div className="relative">
                                    <button
                                        onClick={() => setIsMenuOpen(!isMenuOpen)}
                                        className="px-3 py-2.5 rounded-xl bg-[#151b2e] border border-white/10 text-gray-400"
                                    >
                                        <MoreVertical className="w-5 h-5" />
                                    </button>
                                    {isMenuOpen && (
                                        <div className="absolute right-0 mt-2 w-48 bg-[#151b2e] border border-white/10 rounded-xl shadow-2xl py-1 z-50">
                                            <button
                                                onClick={() => { setIsMenuOpen(false); setShowReportModal(true); }}
                                                className="w-full text-left px-4 py-2.5 text-sm text-gray-300 flex items-center gap-2"
                                            >
                                                <Flag className="w-4 h-4" /> Reportar
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* DASHBOARD CARD: STATS + LEVEL */}
                    <div className="bg-[#151b2e] border border-white/5 rounded-2xl p-4 md:p-6 mb-6">
                        {/* Stats Grid */}
                        <div className="grid grid-cols-4 gap-2 md:gap-8 mb-4 md:mb-6">
                            {[
                                { label: 'Seguidores', value: profile.followersCount || 0 },
                                { label: 'Reseñas', value: profile.reviewsCount || 0 },
                                { label: 'Usuarios', value: profile.followingUsersCount || profile.followingCount || 0, icon: UsersIcon },
                                { label: 'Listas', value: profile.followingListsCount || 0, icon: ListIcon }
                            ].map((stat, i) => (
                                <div key={i} className="flex flex-col items-center justify-center p-2 rounded-xl bg-white/5 md:bg-transparent md:p-0">
                                    <span className="text-white font-bold text-lg md:text-2xl mb-1">{stat.value}</span>
                                    <span className="text-[9px] md:text-xs text-gray-400 uppercase tracking-wider text-center flex flex-col md:flex-row items-center gap-1">
                                        {stat.icon && <stat.icon className="w-3 h-3 md:w-4 md:h-4 mb-0.5 md:mb-0" />}
                                        {stat.label}
                                    </span>
                                </div>
                            ))}
                        </div>

                        {/* Level Bar (Full Width in Card) */}
                        {(() => {
                            const xp = profile.xp || 0;
                            const level = Math.floor(Math.sqrt(xp / 50)) + 1;
                            const nextLevelXp = 50 * Math.pow(level, 2);
                            const currentLevelBaseXp = 50 * Math.pow(level - 1, 2);
                            const progress = Math.min(100, Math.max(0, ((xp - currentLevelBaseXp) / (nextLevelXp - currentLevelBaseXp)) * 100));

                            return (
                                <div className="flex items-center gap-3 relative">
                                    <div className="w-10 h-10 shrink-0 rounded-full bg-gradient-to-br from-amber-400 to-orange-600 flex items-center justify-center font-bold text-white text-sm shadow-lg border border-[#151b2e] z-10">
                                        {level}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-end mb-1.5">
                                            <span className="text-[10px] font-bold text-gray-400 tracking-wider">NIVEL {level}</span>
                                            <span className="text-[10px] text-amber-500 font-mono font-bold">{Math.floor(xp)} / {nextLevelXp} XP</span>
                                        </div>
                                        <div className="h-1.5 bg-gray-800 rounded-full overflow-hidden">
                                            <div className="h-full bg-gradient-to-r from-amber-400 to-orange-500 shadow-[0_0_10px_rgba(245,158,11,0.5)]" style={{ width: `${progress}%` }} />
                                        </div>
                                    </div>
                                </div>
                            );
                        })()}
                    </div>

                    {/* BADGES SECTION */}
                    {profile.badges && profile.badges.length > 0 && (
                        <div className="pt-2">
                            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                <Star className="w-3 h-3 text-amber-500" /> Medallas
                            </h3>
                            <BadgeDisplay earnedBadgeIds={profile.badges?.map((b: any) => typeof b === 'string' ? b : b.id) || []} />
                        </div>
                    )}

                    {profile.createdAt && (
                        <div className="flex items-center gap-2 text-xs text-gray-500">
                            <Calendar className="w-3 h-3" />
                            Miembro desde {new Date((profile.createdAt as any).seconds * 1000).getFullYear()}
                        </div>
                    )}
                </div>


                {/* Preferences Form */}
                {isEditing && isOwnProfile && (
                    <div className="bg-[#151b2e] border border-white/10 rounded-xl p-6 mb-8 animate-fade-in space-y-6">

                        {/* Avatar Settings */}
                        <div>
                            <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                                <UsersIcon className="w-4 h-4 text-indigo-400" /> Avatar
                            </h3>
                            <div className="flex flex-col gap-4">
                                <div className="flex gap-4">
                                    {/* Google Option */}
                                    <button
                                        onClick={async () => {
                                            if (!user?.photoURL) return;
                                            try {
                                                await setDoc(doc(db, 'users', user!.uid), {
                                                    photoUrl: user!.photoURL
                                                }, { merge: true });
                                                // Force reload profile by relying on useUserProfile effect or optimistic update
                                                // Ideally we'd have a refresh function from the hook, but let's just wait for real-time listener or effect
                                                window.location.reload();
                                            } catch (e) {
                                                console.error("Error setting Google photo", e);
                                            }
                                        }}
                                        className={`flex-1 p-3 rounded-xl border flex flex-col items-center gap-2 transition-all ${profile.photoUrl === user?.photoURL
                                            ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500'
                                            : 'bg-black/20 border-white/10 hover:border-white/30'
                                            }`}
                                    >
                                        <div className="w-10 h-10 rounded-full overflow-hidden border border-white/10">
                                            {user?.photoURL ? (
                                                <img src={user.photoURL} alt="Google" className="w-full h-full object-cover" />
                                            ) : (
                                                <div className="w-full h-full bg-gray-700"></div>
                                            )}
                                        </div>
                                        <span className="text-xs font-bold text-gray-300">Google</span>
                                    </button>

                                    {/* Custom Option / Drag & Drop Zone */}
                                    <div
                                        className={`flex-1 p-3 rounded-xl border flex flex-col items-center gap-2 transition-all relative overflow-hidden group ${profile.photoUrl !== user?.photoURL
                                            ? 'bg-indigo-600/20 border-indigo-500 ring-1 ring-indigo-500'
                                            : 'bg-black/20 border-white/10 hover:border-white/30'
                                            } ${dragActive ? 'border-dashed border-indigo-400 bg-indigo-500/10' : ''}`}
                                        onDragEnter={handleDrag}
                                        onDragLeave={handleDrag}
                                        onDragOver={handleDrag}
                                        onDrop={handleDrop}
                                        onClick={() => document.getElementById('file-upload')?.click()}
                                    >
                                        <input
                                            type="file"
                                            id="file-upload"
                                            className="hidden"
                                            accept="image/*"
                                            onChange={(e) => e.target.files && e.target.files[0] && processFile(e.target.files[0])}
                                        />

                                        {uploading ? (
                                            <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-10">
                                                <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>
                                            </div>
                                        ) : null}

                                        <div className="w-10 h-10 rounded-full overflow-hidden border border-white/10 grayscale group-hover:grayscale-0 transition-all">
                                            <img src={profile.photoUrl || `https://ui-avatars.com/api/?name=${profile.displayName}`} alt="Custom" className="w-full h-full object-cover" />
                                        </div>
                                        <span className="text-xs font-bold text-gray-300">
                                            {dragActive ? 'Suelta aquí' : 'Personal'}
                                        </span>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-gray-400 text-xs uppercase font-bold">O arrastra tu imagen aquí</label>
                                    <p className="text-[10px] text-gray-500">
                                        Haz clic en "Personal" o arrastra una imagen para subirla. Máx 5MB.
                                    </p>
                                </div>
                            </div>
                        </div>

                        {/* Search Preferences */}
                        <div>
                            <h3 className="text-white font-bold mb-4 flex items-center gap-2">
                                <Settings className="w-4 h-4 text-indigo-400" /> Preferencias de Búsqueda
                            </h3>
                            <div className="flex flex-col gap-2 max-w-xs">
                                <label className="text-gray-400 text-xs uppercase font-bold">Rango de distancia por defecto</label>
                                <div className="flex items-center gap-3">
                                    <select
                                        value={editRange}
                                        onChange={(e) => setEditRange(e.target.value)}
                                        className="bg-black/20 border border-white/10 rounded-lg text-white px-3 py-2 outline-none focus:border-indigo-500 w-full"
                                    >
                                        <option value="1">1 km</option>
                                        <option value="2">2 km</option>
                                        <option value="5">5 km</option>
                                        <option value="10">10 km</option>
                                        <option value="50">50 km</option>
                                        <option value="100">100 km</option>
                                        <option value="500">500 km</option>
                                        <option value="999999">Sin límite</option>
                                    </select>
                                </div>
                                <p className="text-[10px] text-gray-500 mt-1">Este rango se aplicará automáticamente cuando inicies nueva sesión.</p>
                                <button
                                    onClick={savePreferences}
                                    className="mt-2 w-full py-2 bg-white/10 hover:bg-white/20 text-white text-xs font-bold rounded-lg"
                                >
                                    Guardar Preferencias
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Tabs Navigation */}
                <div className="flex gap-8 border-b border-white/10 mb-8 overflow-x-auto">
                    <button
                        onClick={() => setActiveTab('reviews')}
                        className={`pb-4 px-2 font-bold text-sm flex items-center gap-2 transition-colors relative ${activeTab === 'reviews' ? 'text-indigo-400' : 'text-gray-400 hover:text-white'
                            }`}
                    >
                        <Star className="w-4 h-4" /> Reseñas ({localReviews.length})
                        {activeTab === 'reviews' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-500 rounded-full" />}
                    </button>
                    <button
                        onClick={() => setActiveTab('lists')}
                        className={`pb-4 px-2 font-bold text-sm flex items-center gap-2 transition-colors relative ${activeTab === 'lists' ? 'text-indigo-400' : 'text-gray-400 hover:text-white'
                            }`}
                    >
                        <ListIcon className="w-4 h-4" /> Listas ({ownedLists.length + guestLists.length + followedLists.length})
                        {activeTab === 'lists' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-500 rounded-full" />}
                    </button>
                    <button
                        onClick={() => setActiveTab('following')}
                        className={`pb-4 px-2 font-bold text-sm flex items-center gap-2 transition-colors relative ${activeTab === 'following' ? 'text-indigo-400' : 'text-gray-400 hover:text-white'
                            }`}
                    >
                        <UserCheck className="w-4 h-4" /> Siguiendo ({profile.followingCount || 0})
                        {activeTab === 'following' && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-indigo-500 rounded-full" />}
                    </button>
                </div>

                {/* Tab Content */}
                <div className="min-h-[300px]">
                    {activeTab === 'reviews' && (
                        <>
                            {loadingReviews ? (
                                <div className="py-20 text-center text-gray-500">Cargando reseñas...</div>
                            ) : localReviews.length === 0 ? (
                                <div className="py-20 text-center border-2 border-dashed border-white/5 rounded-xl">
                                    <p className="text-gray-500">No hay reseñas recientes.</p>
                                </div>
                            ) : (
                                <div className="space-y-8">
                                    <div className="grid grid-cols-1 gap-8">
                                        {localReviews.map(review => (
                                            <ReviewCard key={review.id} review={review} onDelete={handleDeleteReview} onEdit={handleEditReview} />
                                        ))}
                                    </div>

                                    {/* Infinite Scroll Trigger */}
                                    {hasMore && (
                                        <div ref={loadMoreRef} className="flex justify-center pt-8 pb-4">
                                            {loadingMore ? (
                                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
                                            ) : (
                                                <div className="h-4 w-full" /> // Invisible trigger
                                            )}
                                        </div>
                                    )}
                                </div>
                            )}
                        </>
                    )}

                    {activeTab === 'lists' && (
                        <>
                            {loadingLists || loadingExtraLists ? (
                                <div className="py-20 text-center text-gray-500">Cargando listas...</div>
                            ) : (
                                <div className="space-y-16">

                                    {/* 1. Created Lists */}
                                    <section>
                                        <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                            <span className="w-1.5 h-6 bg-indigo-500 rounded-full"></span>
                                            Listas Creadas
                                        </h3>
                                        <ListGrid
                                            lists={mainCreatedLists}
                                            emptyMessage="No hay listas públicas creadas aún."
                                        />
                                    </section>

                                    {/* 2. Created Sublists */}
                                    {subCreatedLists.length > 0 && (
                                        <section>
                                            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                                <span className="w-1.5 h-6 bg-purple-500 rounded-full"></span>
                                                Sublistas Creadas
                                            </h3>
                                            <ListGrid
                                                lists={subCreatedLists}
                                                emptyMessage="No hay sublistas."
                                                isSublist={true}
                                            />
                                        </section>
                                    )}

                                    {/* 3. Guest Lists */}
                                    {guestLists.length > 0 && (
                                        <section>
                                            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                                <span className="w-1.5 h-6 bg-amber-500 rounded-full"></span>
                                                Listas como Invitado / Editor
                                            </h3>
                                            <ListGrid
                                                lists={guestLists}
                                                emptyMessage="No participas en ninguna lista."
                                            />
                                        </section>
                                    )}

                                    {/* 4. Followed Lists */}
                                    {mainFollowedLists.length > 0 && (
                                        <section>
                                            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                                <span className="w-1.5 h-6 bg-emerald-500 rounded-full"></span>
                                                Listas Seguidas
                                            </h3>
                                            <ListGrid
                                                lists={mainFollowedLists}
                                                emptyMessage="No sigues ninguna lista."
                                            />
                                        </section>
                                    )}

                                    {/* 5. Followed Sublists */}
                                    {subFollowedLists.length > 0 && (
                                        <section>
                                            <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                                <span className="w-1.5 h-6 bg-teal-500 rounded-full"></span>
                                                Sublistas Seguidas
                                            </h3>
                                            <ListGrid
                                                lists={subFollowedLists}
                                                emptyMessage="No sigues ninguna sublista."
                                                isSublist={true}
                                            />
                                        </section>
                                    )}
                                </div>
                            )}
                        </>
                    )}

                    {activeTab === 'following' && (
                        <FollowingSection targetUserId={targetUserId} />
                    )}
                </div>
            </div>


            <ReportModal
                isOpen={showReportModal}
                onClose={() => setShowReportModal(false)}
                targetId={targetUserId!}
                targetName={profile.displayName || profile.username || 'Usuario'}
                targetType="user"
                itemName="Perfil de Usuario"
            />
            {isFlowOpen && (
                <AddReviewForm
                    listId={editingListId}
                    editReviewId={editingReviewId || undefined}
                    onClose={() => {
                        setIsFlowOpen(false);
                        setEditingReviewId(null);
                        setEditingListId(null);
                    }}
                    onSuccess={() => {
                        refreshReviews();
                        setIsFlowOpen(false);
                        setEditingReviewId(null);
                        setEditingListId(null);
                    }}
                />
            )}
        </div >
    );
};

